  const settingsSaveRef = useRef(false);

  useEffect(() => {
    const load = async () => {
      try {
        const all = await loadAllEntityRows({ entity: SettingsEntity, sort: null, label: "Metal Settings catalog" });
        const relevant = (all || []).filter((row) => ACTIVE_KEYS.has(row.setting_name));
        const map = Object.fromEntries(relevant.map((row) => [row.setting_name, row.setting_value ?? ""]));
        setRows(relevant);
        setValues(map);
        setOriginal(map);
      } catch (e) {
        setError(e.message || "Could not load Metal settings.");
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  const patch = (key, value) => setValues((prev) => ({ ...prev, [key]: String(value) }));
  const dirtyCount = rows.filter((row) => String(values[row.setting_name] ?? "") !== String(original[row.setting_name] ?? "")).length;

  // #83 — stage every managed key back to the calculator's documented fallback.
  const handleResetDefaults = () => {
    setValues((prev) => resetValuesToDefaults(prev, METAL_SETTINGS_DEFAULTS, [...ACTIVE_KEYS]));
    setMessage("Defaults staged — click Save to persist them.");
  };

  const save = async () => {
    if (settingsSaveRef.current) return;
    settingsSaveRef.current = true;
    setSaving(true);
    setError("");
    setMessage("");
    try {
      const result = await saveSettingsRowsSafely({
        SettingsEntity,
        rows,
        values,
        originalValues: original,
      });
      setRows(result.rows);
      setOriginal(result.snapshot);
      setMessage(result.changedCount ? `Saved ${result.changedCount} Metal setting${result.changedCount === 1 ? "" : "s"}.` : "No Metal settings changed.");
    } catch (e) {
      setError(e.message || "Could not save Metal settings. Admin permission may be required.");
    } finally {
      settingsSaveRef.current = false;
      setSaving(false);
    }
  };

  if (loading) return <div className="p-10 text-center text-gray-400">Loading Metal settings…</div>;

  return (
    <div className="min-h-full bg-gray-50">
