// #488 — per-user display preferences that live in the workspace-prefs blob
// (UserWorkspacePreferences.preferences). Currently: the viewer's timezone,
// which estimator surfaces honor when rendering dates/timestamps.
function MyDisplayPrefsCard() {
  const { prefs, updatePrefs, saving } = useWorkspacePreferences();
  const savedTz = String(prefs?.locale?.timezone || "");
  const [value, setValue] = useState(savedTz);
  const [error, setError] = useState("");
  const [savedFlash, setSavedFlash] = useState(false);
  useEffect(() => { setValue(savedTz); }, [savedTz]);

  const resolved = resolveUserTimeZone(prefs, "");
  const save = () => {
    const v = String(value || "").trim();
    setError("");
    if (v && !isValidTimeZone(v)) {
      setError(`"${v}" is not a valid IANA timezone — try e.g. America/New_York, America/Chicago, America/Denver, America/Los_Angeles.`);
      return;
    }
    updatePrefs("locale.timezone", v);
    setSavedFlash(true);
    window.setTimeout(() => setSavedFlash(false), 2500);
  };

  return (
    <div className="bg-white px-4 py-4 border-t-4 border-sky-300">
      <div className="flex items-center gap-2">
        <Clock className="w-4 h-4 text-red-500" />
        <div className="text-xs font-bold tracking-wide text-gray-600">MY DISPLAY PREFERENCES</div>
      </div>
      <p className="mt-1 text-[11px] text-gray-500">
        Per-user preferences that follow your account across devices. The timezone is honored on due-date and audit/activity timestamp displays.
      </p>
      {error && <div className="mt-2 border border-red-200 bg-red-50 px-3 py-2 text-[10px] text-red-700">{error}</div>}
      {savedFlash && <div className="mt-2 border border-emerald-200 bg-emerald-50 px-3 py-2 text-[10px] text-emerald-800">Preference saved{resolved ? ` — dates will display in ${resolved}` : " — dates will display in your browser timezone"}.</div>}
      <div className="mt-3 flex items-end gap-2">
        <label className="text-[10px] font-bold tracking-wide text-gray-500">
          MY TIMEZONE (IANA)
          <input
            value={value}
            onChange={(event) => setValue(event.target.value)}
            onKeyDown={(event) => { if (event.key === "Enter") save(); }}
            placeholder="blank = browser local"
            list="ccs-tz-options"
            className="mt-1 h-[32px] w-56 rounded border border-gray-300 px-2 text-[11px] font-normal text-gray-800"
          />
          <datalist id="ccs-tz-options">
            <option value="America/New_York" />
            <option value="America/Chicago" />
            <option value="America/Denver" />
            <option value="America/Los_Angeles" />
            <option value="America/Phoenix" />
            <option value="America/Anchorage" />
            <option value="Pacific/Honolulu" />
            <option value="UTC" />
          </datalist>
        </label>
        <button
          type="button"
          onClick={save}
          disabled={saving}
          className="h-[32px] px-3 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 disabled:opacity-40 inline-flex items-center gap-1.5"
        >
          {saving ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Save className="w-3.5 h-3.5" />}
          {saving ? "Saving…" : "Save"}
        </button>
      </div>
      <p className="mt-1.5 text-[9px] text-gray-400">Company-wide fallback is set on Quote Defaults → Display timezone. Your pick wins when both are set.</p>
    </div>
  );
}

const QUOTE_APPROVAL_THRESHOLD_KEY = "quote_approval_threshold";
const DEFAULT_QUOTE_APPROVAL_THRESHOLD = 5000;

function thresholdValue(record) {
  const raw = record?.setting_value;
  const parsed = Number(raw?.threshold ?? raw?.value ?? raw);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : DEFAULT_QUOTE_APPROVAL_THRESHOLD;
}

function QuoteApprovalCard() {
  const canManage = getSessionUser()?.role === "admin";
  const [loading, setLoading] = useState(true);
  const [settingRecord, setSettingRecord] = useState(null);
  const [threshold, setThreshold] = useState(String(DEFAULT_QUOTE_APPROVAL_THRESHOLD));
  const [users, setUsers] = useState([]);
  const [savingThreshold, setSavingThreshold] = useState(false);
  const [togglingUserId, setTogglingUserId] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const load = async () => {
    setLoading(true);
    setError("");
    try {
      const record = await loadSingleGlobalSetting({
        entity: staffEntities.GlobalSettings,
        settingKey: QUOTE_APPROVAL_THRESHOLD_KEY,
        label: "Quote approval threshold",
      });
      setSettingRecord(record);
      setThreshold(String(thresholdValue(record)));
      if (canManage) {
        const rows = await listAuthorizedUsersAdmin({ sessionToken: getSessionToken() });
        setUsers(Array.isArray(rows) ? rows : []);
      } else {
        setUsers([]);
      }
    } catch (err) {
      setError(err?.message || "Quote approval settings could not be loaded.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const saveThreshold = async () => {
    const next = Number(threshold);
    if (!Number.isFinite(next) || next < 0) {
      setError("Enter a valid non-negative dollar threshold.");
      return;
    }
    setSavingThreshold(true);
    setMessage("");
    setError("");
    try {
      const response = await base44.functions.invoke("manageQuoteApprovalSettings", {
        session_token: getSessionToken(),
        action: "save_threshold",
        threshold: next,
        expected_id: settingRecord?.id || "",
        expected_updated_date: settingRecord?.updated_date || "",
      });
      const data = response?.data || response;
      if (data?.error) throw new Error(data.error);
      if (!data?.success) throw new Error("Quote approval threshold could not be verified after saving.");
      setSettingRecord(data.record || null);
      setThreshold(String(data.threshold ?? next));
      setMessage("Quote approval threshold saved.");
    } catch (err) {
      setError(err?.response?.data?.error || err?.data?.error || err?.message || "Quote approval threshold could not be saved.");
    } finally {
      setSavingThreshold(false);
    }
  };

  const toggleApprover = async (user, next) => {
    if (togglingUserId || !user?.id) return;
    setTogglingUserId(user.id);
    setMessage("");
    setError("");
    try {
      const saved = await updateAuthorizedUserAdmin({
        record: user,
        nextFields: { can_approve_quotes: next },
        sessionToken: getSessionToken(),
      });
      const confirmed = saved?.can_approve_quotes === true;
      setUsers((prev) => prev.map((row) => (row.id === user.id ? { ...row, can_approve_quotes: confirmed } : row)));
    } catch (err) {
      setError(err?.message || "Quote approver access could not be changed.");
    } finally {
      setTogglingUserId("");
    }
  };

  return (
    <div className="bg-white px-4 py-4 border-t-4 border-lime-300">
      <div className="flex items-center gap-2">
        <ShieldCheck className="w-4 h-4 text-red-500" />
        <div className="text-xs font-bold tracking-wide text-gray-600">QUOTE APPROVAL</div>
      </div>
      <p className="mt-1 text-[11px] text-gray-500">
        Quotes above this total need a recorded manager approval before they can be marked sent. Approvers may approve quotes, including their own.
      </p>

      {message && <div className="mt-2 border border-emerald-200 bg-emerald-50 px-3 py-2 text-[10px] text-emerald-800">{message}</div>}
      {error && <div className="mt-2 border border-red-200 bg-red-50 px-3 py-2 text-[10px] text-red-700">{error}</div>}

      {loading ? (
        <div className="mt-3 text-[11px] text-gray-400 flex items-center gap-2"><Loader2 className="w-3.5 h-3.5 animate-spin" /> Loading quote approval settings…</div>
      ) : (
        <>
          <div className="mt-3 flex items-end gap-2">
            <label className="text-[10px] font-bold tracking-wide text-gray-500">
              APPROVAL THRESHOLD ($)
              <input
                type="number"
                min="0"
                step="0.01"
                value={threshold}
                disabled={!canManage || savingThreshold}
                onChange={(event) => setThreshold(event.target.value)}
                className="mt-1 h-[32px] w-40 rounded border border-gray-300 px-2 text-[11px] font-normal text-gray-800 disabled:opacity-50"
              />
            </label>
            <button
              type="button"
              onClick={saveThreshold}
              disabled={!canManage || savingThreshold}
              title={canManage ? "Save the quote approval threshold" : "Only an administrator can change the quote approval threshold."}
              className="h-[32px] px-3 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 disabled:opacity-40 inline-flex items-center gap-1.5"
            >
              {savingThreshold ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Save className="w-3.5 h-3.5" />}
              {savingThreshold ? "Saving…" : "Save"}
            </button>
          </div>

          <div className="mt-4">
            <div className="text-[10px] font-bold tracking-wide text-gray-500 mb-1.5">QUOTE APPROVERS</div>
            {!canManage && (
              <div className="border border-amber-200 bg-amber-50 px-3 py-2 text-[10px] text-amber-800">
                Only an administrator can view and change which users may approve quotes.
              </div>
            )}
            {canManage && users.length === 0 && (
              <div className="text-[10px] text-gray-400">No authorized users found.</div>
            )}
            {canManage && users.length > 0 && (
              <div className="divide-y divide-gray-100 border border-gray-200 rounded">
                {users.map((user) => (
                  <label key={user.id} className="flex items-center justify-between gap-3 px-3 py-2 text-[11px] text-gray-700">
                    <span className="min-w-0">
                      <span className="font-semibold text-gray-800">{user.full_name || user.email}</span>
                      {user.full_name && <span className="ml-2 text-gray-400">{user.email}</span>}
                      {user.role === "admin" && <span className="ml-2 text-[9px] font-bold tracking-wide text-gray-400">ADMIN</span>}
                    </span>
                    <span className="flex items-center gap-2 shrink-0">
                      {togglingUserId === user.id && <Loader2 className="w-3.5 h-3.5 animate-spin text-gray-400" />}
                      <input
                        type="checkbox"
                        checked={user.can_approve_quotes === true}
                        disabled={togglingUserId === user.id}
                        onChange={(event) => toggleApprover(user, event.target.checked)}
                        className="w-3.5 h-3.5 accent-red-600"
                      />
                    </span>
                  </label>
                ))}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

import { useState, useEffect, useRef, useMemo } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { ArrowUpDown, Calculator, History, Plus, Search } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import EstimateCard from "@/components/estimator/EstimateCard";
import NewEstimateDialog from "@/components/estimator/NewEstimateDialog";
import { runHistoricalBuilderBackfill } from "@/components/estimator/builder/historicalBackfill";
import { runLegacyBomReconcile } from "@/components/estimator/builder/legacyBomReconcile";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { ListSkeleton } from "@/components/ui/list-skeleton";
import { quoteExpirationDate } from "@/components/estimator/quoteLifecycle";
import { staffEntities } from "@/components/staff/staffEntities";
import { isFleetCoolingDown } from "@/components/fleet/fleetInvoke";
import { useAuth } from "@/components/auth/EmailGate";
import { estimateMatchesSearch, pushRecentSearch, readRecentSearches, useEstimateDeepLink } from "@/components/estimator/deepLinks";

const STATUSES = [
  { key: "", label: "All" },
  { key: "draft", label: "In Draft" },
  { key: "calculated", label: "Calculated" },
  { key: "sent", label: "Awaiting Approval" },
  { key: "approved", label: "Approved" },
  { key: "archived", label: "Archived" },
  { key: "cancelled", label: "Cancelled" },
  { key: "sync_issues", label: "Sync Issues" },
];

const SORTS = [
  { key: "newest", label: "Newest" },
  { key: "oldest", label: "Oldest" },
  { key: "value_desc", label: "$ high → low" },
  { key: "expiring", label: "Expiring first" },
];

const money0 = (n) => `$${Number(n || 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}`;
const compact = (n) => (n >= 1000 ? `$${Math.round(n / 1000)}k` : money0(n));

function expiryOf(e) {
  const validDays = e.quote_valid_days ?? e.valid_days;
  if ((e.status || "draft") !== "sent" || !e.quote_issue_date || !validDays) return null;
  return quoteExpirationDate(e.quote_issue_date, validDays) || null;
}

export default function Estimator() {
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const status = searchParams.get("status") || "";
  const sort = searchParams.get("sort") || "newest";
  const [estimates, setEstimates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");
  const [search, setSearch] = useState(() => searchParams.get("q") || "");
  const [showNew, setShowNew] = useState(
    new URLSearchParams(window.location.search).get("new") === "1"
  );
  const backfillStartedRef = useRef(false);
  // #302 — /Estimator?estimate=<id> forwards to the estimate detail.
  useEstimateDeepLink();
  // #313 — last-5 searches per user, dropdown under the search input.
  const { currentUser } = useAuth();
  const userEmail = currentUser?.email || "";
  const [recentOpen, setRecentOpen] = useState(false);
  const [recentSearches, setRecentSearches] = useState(() => readRecentSearches("estimator", userEmail));
  const commitRecentSearch = (v) => setRecentSearches(pushRecentSearch("estimator", userEmail, v));

  const load = async () => {
    try {
      const rows = await loadAllEntityRows({
        entity: staffEntities.AllInOneEstimate,
        sort: "-created_date",
        label: "Estimates",
      });
      setEstimates(rows);

      // The migration writes a server-side completion sentinel and is
      // resumable — once a full run finishes, this browser never runs it
      // again, and background tabs / open 429 breakers never start it.
      const bomDone = (() => { try { return Boolean(localStorage.getItem("ccs.bomMigration.done.v1")); } catch { return false; } })();
      if (!backfillStartedRef.current && !bomDone && !document.hidden && !isFleetCoolingDown()) {
        backfillStartedRef.current = true;
        runHistoricalBuilderBackfill({ seedEstimates: rows })
          .then(async (result) => {
            if (result?.estimates?.length) setEstimates(result.estimates);
            await runLegacyBomReconcile();
            try { localStorage.setItem("ccs.bomMigration.done.v1", new Date().toISOString()); } catch {}
          })
          .catch((error) => {
            // Historical conversion/reconciliation must never block normal estimating.
            // Each migration writes its completion marker last, so the next admin
            // visit can resume safely if either pass is interrupted.
            console.error("Historical Product/BOM migration paused:", error);
          });
      }
    } catch (error) {
      console.error("Estimates could not be loaded:", error);
      setLoadError(error?.message || "Estimates could not be loaded.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const setParam = (key, value) => {
    const next = new URLSearchParams(searchParams);
    if (value) next.set(key, value);
    else next.delete(key);
    setSearchParams(next, { replace: true });
  };

  // Trashed estimates never appear in queue counts or lists — they are only
  // reachable through the Trash chip on Estimate Queues.
  // K-05 (item 485): admin sees every estimate; non-admin sales sees only
  // their own (`salesperson` stores full_name || email — the same value the
  // Step-1 dropdown writes).
  const scopedEstimates = useMemo(() => {
    const visible = estimates.filter((e) => e?.deleted !== true);
    if (!currentUser || currentUser.role === "admin") return visible;
    const mine = new Set(
      [String(currentUser.full_name || "").trim().toLowerCase(),
       String(currentUser.email || "").trim().toLowerCase()].filter(Boolean)
    );
    return visible.filter((e) => mine.has(String(e?.salesperson || "").trim().toLowerCase()));
  }, [estimates, currentUser]);
  const liveEstimates = scopedEstimates;

  const buckets = useMemo(() => {
    const by = {};
    for (const s of STATUSES) by[s.key] = { count: 0, total: 0 };
    for (const e of liveEstimates) {
      const bucketKey = e.pipeline_sync_pending === true ? "sync_issues" : (e.status || "draft");
      if (by[bucketKey]) { by[bucketKey].count += 1; by[bucketKey].total += Number(e.quote_total || e.total_cost || 0); }
      by[""].count += 1;
      by[""].total += Number(e.quote_total || e.total_cost || 0);
    }
    return by;
  }, [liveEstimates]);

  const term = search.trim().toLowerCase();
  const filtered = useMemo(() => {
    let list = status === "sync_issues"
      ? liveEstimates.filter((e) => e.pipeline_sync_pending === true)
      : status
        ? liveEstimates.filter((e) => (e.status || "draft") === status)
        : liveEstimates;
    // #301 — global estimate search: header fields + notes + line items.
    if (term) {
      list = list.filter((e) => estimateMatchesSearch(e, term));
    }
    const val = (e) => Number(e.quote_total || e.total_cost || 0);
    const exp = (e) => expiryOf(e) || "9999-12-31";
    const sorted = [...list];
    if (sort === "oldest") sorted.sort((a, b) => String(a.created_date).localeCompare(String(b.created_date)));
    else if (sort === "value_desc") sorted.sort((a, b) => val(b) - val(a));
    else if (sort === "expiring") sorted.sort((a, b) => exp(a).localeCompare(exp(b)));
    else sorted.sort((a, b) => String(b.created_date).localeCompare(String(a.created_date)));
    return sorted;
  }, [liveEstimates, status, term, sort]);

  const visibleTotal = filtered.reduce((s, e) => s + Number(e.quote_total || e.total_cost || 0), 0);

  // Incremental render-window (#404): large estimate lists render the first
  // PAGE cards and grow on "Show more" — resets whenever the filters change.
  const CARD_PAGE = 24;
  const [visibleCount, setVisibleCount] = useState(CARD_PAGE);
  useEffect(() => { setVisibleCount(CARD_PAGE); }, [status, term, sort]);

  return (
    <div className="clay-scope min-h-full bg-gradient-to-br from-rose-50 to-orange-50">
      <div className="max-w-6xl mx-auto p-4 sm:p-6">
        <div className="clay-card p-4 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
          <div className="flex items-center gap-3">
            <div
              className="w-11 h-11 rounded-2xl flex items-center justify-center flex-shrink-0"
              style={{
                background: 'linear-gradient(135deg, #FEE2E2 0%, #FECACA 100%)',
                boxShadow: 'inset 2px 2px 6px rgba(255,255,255,0.7), inset -2px -2px 6px rgba(0,0,0,0.08)',
              }}
            >
              <Calculator className="w-6 h-6 text-red-600" aria-hidden="true" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-gray-800">Estimator</h1>
              <p className="text-sm text-gray-500">Build and price multi-section sign estimates</p>
            </div>
          </div>
          <Button onClick={() => navigate("/NewAllInOneEstimate")} className="clay-button border-2 border-red-300 bg-red-50 hover:bg-red-100 text-red-700 font-bold">
            <Plus className="w-4 h-4" aria-hidden="true" /> New Estimate
          </Button>
        </div>

        <div className="flex flex-wrap items-center gap-2 mb-4" role="tablist" aria-label="Estimate status filter"
          onKeyDown={(e) => {
            if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(e.key)) return;
            const tabs = [...e.currentTarget.querySelectorAll('button[role="tab"]')];
            const i = tabs.indexOf(document.activeElement);
            if (i < 0) return;
            e.preventDefault();
            const next = e.key === "Home" ? tabs[0] : e.key === "End" ? tabs[tabs.length - 1] : tabs[(i + (e.key === "ArrowRight" ? 1 : -1) + tabs.length) % tabs.length];
            next?.focus();
          }}>
          {STATUSES.map((s) => {
            const b = buckets[s.key] || { count: 0, total: 0 };
            return (
              <button
                key={s.key || "all"}
                type="button"
                role="tab"
                aria-selected={status === s.key}
                onClick={() => setParam("status", s.key)}
                className={`px-3 py-1.5 rounded-full text-xs font-semibold border ${
                  status === s.key
                    ? "bg-red-600 text-white border-red-600"
                    : "bg-white/70 text-gray-600 border-gray-200 hover:border-red-300"
                }`}
                title={`${b.count} · ${money0(b.total)}`}
              >
                {s.label}
                <span className={`ml-1.5 ${status === s.key ? "text-red-100" : "text-gray-400"}`}>
                  {b.count}{b.total > 0 ? ` · ${compact(b.total)}` : ""}
                </span>
              </button>
            );
          })}
        </div>

        <div className="flex flex-wrap items-center gap-2 mb-5">
          {currentUser && currentUser.role !== "admin" && (
            <span className="rounded-full bg-red-50 border border-red-200 px-3 py-1 text-xs font-semibold text-red-700" title="Item 485: non-admin sales staff see only their own estimates. Admins see all.">
              My estimates
            </span>
          )}
          <div className="relative flex-1 min-w-48">
            <Search className="w-4 h-4 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" aria-hidden="true" />
            <Input
              value={search}
              aria-label="Search estimates"
              onChange={(e) => { setSearch(e.target.value); setParam("q", e.target.value); }}
              onFocus={() => { setRecentSearches(readRecentSearches("estimator", userEmail)); setRecentOpen(true); }}
              onBlur={() => { commitRecentSearch(search); window.setTimeout(() => setRecentOpen(false), 150); }}
              onKeyDown={(e) => {
                if (e.key === "Enter") { commitRecentSearch(search); setRecentOpen(false); }
                else if (e.key === "Escape") setRecentOpen(false);
              }}
              placeholder="Search by description, client, estimate number, notes or products"
              className="pl-9 clay-card border-none h-11"
            />
            {recentOpen && recentSearches.length > 0 && (
              <div className="absolute left-0 right-0 top-full z-30 mt-1 overflow-hidden rounded-lg border border-gray-200 bg-white shadow-lg">
                <div className="flex items-center gap-1.5 px-3 pt-2 text-[9px] font-bold uppercase tracking-wide text-gray-400">
                  <History className="h-3 w-3" aria-hidden="true" /> Recent searches
                </div>
                {recentSearches.map((recent) => (
                  <button
                    key={recent}
                    type="button"
                    onMouseDown={(e) => { e.preventDefault(); setSearch(recent); setParam("q", recent); commitRecentSearch(recent); setRecentOpen(false); }}
                    className="block w-full px-3 py-1.5 text-left text-xs text-gray-700 hover:bg-red-50"
                  >
                    {recent}
                  </button>
                ))}
              </div>
            )}
          </div>
          <div className="flex items-center gap-1.5">
            <ArrowUpDown className="h-3.5 w-3.5 text-gray-400" aria-hidden="true" />
            <select
              aria-label="Sort estimates"
              value={sort}
              onChange={(e) => setParam("sort", e.target.value === "newest" ? "" : e.target.value)}
              className="clay-card border-none h-11 px-2 text-xs font-semibold text-gray-600 outline-none"
            >
              {SORTS.map((s) => <option key={s.key} value={s.key}>{s.label}</option>)}
            </select>
          </div>
          <span className="text-xs text-gray-400">
            {filtered.length} estimate{filtered.length === 1 ? "" : "s"} · {compact(visibleTotal)}
          </span>
        </div>

        {loading ? (
          <ListSkeleton rows={6} />
        ) : loadError ? (
          <div className="clay-card text-center py-16" role="alert">
            <p className="text-red-600 font-medium">{loadError}</p>
          </div>
        ) : filtered.length === 0 ? (
          <div className="clay-card text-center py-16">
            <Calculator className="w-8 h-8 text-red-300 mx-auto mb-3" aria-hidden="true" />
            <p className="text-gray-600 font-medium">
              {liveEstimates.length === 0 ? "No estimates yet" : "No estimates match your search"}
            </p>
            {liveEstimates.length === 0 && (
              <p className="text-sm text-gray-400 mt-1">Create your first estimate to get started.</p>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            {filtered.slice(0, visibleCount).map((estimate) => (
              <EstimateCard key={estimate.id} estimate={estimate} />
            ))}
          </div>
        )}
        {visibleCount < filtered.length && (
          <div className="flex justify-center mt-4">
            <button
              type="button"
              onClick={() => setVisibleCount((c) => c + CARD_PAGE)}
              className="h-[30px] px-3 rounded border border-gray-300 bg-white text-[10px] font-bold text-gray-600 hover:bg-gray-50"
            >
              Show {Math.min(CARD_PAGE, filtered.length - visibleCount)} more ({filtered.length - visibleCount} remaining)
            </button>
          </div>
        )}
      </div>

      <NewEstimateDialog
        open={showNew}
        onClose={() => setShowNew(false)}
        onCreated={(estimate) => {
          setEstimates((prev) => [estimate, ...prev]);
          setShowNew(false);
        }}
      />
    </div>
  );
}

// Vinyl Estimator — tabbed estimator with multiple vinyl workflows + installation.
// Tabs: Project Info → Vinyl Workflows → Installation → Travel & Crew → Summary
// Each workflow has its own vinyl + machines + parts + roll layout, so different
// materials never get nested onto the same physical roll.

import { useEffect, useMemo, useState, useCallback, useRef } from "react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import {
  VinylProject, VinylInventory, VinylMachine,
  Settings, ChannelLetterInstallEquipment,
} from "@/api/gatedEntities";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { ArrowLeft, Droplets, Loader2, FileText, Layers, HardHat, Calculator, Plus, MapPin, Settings as SettingsIcon, ChevronsUpDown, ChevronsDownUp, BookmarkPlus, ClipboardPaste, UploadCloud, AlertTriangle, TrendingUp } from "lucide-react";
import CustomerPricingTab from "@/components/markup/CustomerPricingTab";
import { categorizeVinylProject } from "@/components/markup/projectCategorizer";
import { calculateSavedCustomerPricing } from "@/components/markup/savedCustomerPricing";
import { recordBuilderSave } from "@/components/estimator/builder/builderService";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { preflightBuilderSourceMutation, updateBuilderSourceProject } from "@/components/estimator/builder/sourceProjectPersistence";
import { ensureIdempotentEntityCreate, newCreationRequestKey } from "@/components/estimator/idempotentEntityCreate";
import ModuleActionBar from "@/components/estimator/moduleShared/ModuleActionBar";
import ModuleTemplateDialog from "@/components/estimator/moduleShared/ModuleTemplateDialog";
import { saveModuleProjectCopy } from "@/components/estimator/moduleShared/moduleProjectActions";
import AddressAutocomplete from "@/components/channelLetterInstall/AddressAutocomplete";
import EquipmentSelector from "@/components/channelLetterInstall/EquipmentSelector";
import PersonnelSelector from "@/components/channelLetterInstall/PersonnelSelector";
import TravelCostCard from "@/components/channelLetterInstall/TravelCostCard";

import VinylWorkflowCard from "@/components/vinylEstimator/VinylWorkflowCard";
import VinylProjectSummaryCard from "@/components/vinylEstimator/VinylProjectSummaryCard";
import VinylBulkImportDialog from "@/components/vinylEstimator/VinylBulkImportDialog";
import VinylPartsLibraryDialog from "@/components/vinylEstimator/VinylPartsLibraryDialog";
import VinylArtworkUploadDialog from "@/components/vinylEstimator/VinylArtworkUploadDialog";
import VinylMoveToWorkflowMenu from "@/components/vinylEstimator/VinylMoveToWorkflowMenu";
import {
  blankVinylProject, blankWorkflow, migrateProject, rollupVinylProject,
} from "@/components/vinylEstimator/vinylProjectHelpers";
