// DXF/SVG dimension extraction (#92): reads the file text and pulls a
// bounding box -- DXF $EXTMIN/$EXTMAX headers, or an SVG width/height/viewBox --
// returning inches so a laser part can prefill length/width from a vector file.
async function extractLaserDims(file) {
  try {
    const text = await file.text();
    const lines = String(text).split(/[\r\n]+/);
    const readPair = (marker) => {
      const idx = lines.findIndex((l) => String(l).trim() === marker);
      if (idx < 0) return null;
      let x = NaN, y = NaN;
      for (let j = idx + 1; j < Math.min(idx + 14, lines.length); j += 1) {
        const code = String(lines[j]).trim();
        if (code === "10") x = parseFloat(lines[j + 1]);
        else if (code === "20") y = parseFloat(lines[j + 1]);
        if (Number.isFinite(x) && Number.isFinite(y)) return { x, y };
      }
      return null;
    };
    const extMin = readPair("$EXTMIN");
    const extMax = readPair("$EXTMAX");
    const metric = lines.some((l, i) => String(l).trim() === "$MEASUREMENT" && String(lines[i + 2] || "").trim() === "1");
    const insUnitsMM = lines.some((l, i) => String(l).trim() === "$INSUNITS" && String(lines[i + 2] || "").trim() === "4");
    const toIn = (metric || insUnitsMM) ? 1 / 25.4 : 1;
    if (extMin && extMax && extMax.x > extMin.x) {
      const w = (extMax.x - extMin.x) * toIn;
      const h = Math.abs(extMax.y - extMin.y) * toIn;
      return { w: +w.toFixed(2), h: +h.toFixed(2) };
    }
    const vb = /viewBox=["']([\d\.\s-]+)["']/.exec(text);
    const sW = /width=["']([\d\.]+)/.exec(text), sH = /height=["']([\d\.]+)/.exec(text);
    if (Number.isFinite(parseFloat(sW?.[1])) && Number.isFinite(parseFloat(sH?.[1]))) return { w: parseFloat(sW[1]), h: parseFloat(sH[1]) };
    if (vb) { const p = vb[1].trim().split(/\s+/).map(Number); if (p.length === 4 && p[2] > 0 && p[3] > 0) return { w: +p[2].toFixed(2), h: +p[3].toFixed(2) }; }
  } catch {}
  return null;
}

  const addItem = () => {

    setTimeout(() => document.querySelector(`input[data-item-desc="${(project.items || []).length}"]`)?.focus(), 60);
    const newItem = {
      builder_item_id: newBuilderItemId("laser-item"),
      item_type: "panel",
      description: "",
      material_type: "Acrylic",
      material_thickness: "1/4",
      quantity: 1,
      length: 24,
      width: 12,
      letter_height: 12,
      num_letters: 10,
      engrave_area_sqin: 0,
      total_cut_length_inches: 0,
      cut_speed_ipm: 20,
      engrave_speed_sqipm: 5,
      machine_time_hours: 0,
      handling_time_hours: 0,
      machine_cost: 0,
      labor_cost: 0
    };
    setProject((prev) => ({ ...prev, items: [...prev.items, newItem] }));
  };

  // File attach + dimension extraction (#92): upload the part's vector file,
  // store its URL on the item, and prefill length/width from a DXF/SVG bbox.
  const attachFileToItem = async (index, file) => {
    if (!file) return;
    try {
      const up = await base44.integrations.Core.UploadFile({ file });
      const url = up?.file_url || "";
      if (url) updateItem(index, "file_url", url);
      const dims = await extractLaserDims(file);
      if (dims && (dims.w > 0 || dims.h > 0)) {
        updateItem(index, "length", dims.w);
        updateItem(index, "width", dims.h);
        window.alert(`Attached file — extracted ${dims.w}" × ${dims.h}" into length/width.`);
      } else {
        window.alert("File attached (no readable dimensions — length/width left as entered).");
      }
    } catch (e) { window.alert(e?.message || "Attach failed."); }
  };

  const removeItem = (index) => {
    if (!window.confirm("Remove this item?")) return;
    setProject((prev) => ({
      ...prev,
      items: prev.items.filter((_, i) => i !== index)
    }));
  };

  const updateItem = (index, field, value) => {
    setProject((prev) => ({
      ...prev,
      items: prev.items.map((item, i) => {
        if (i !== index) return item;
        const updated = { ...item, [field]: value };

        // Auto-calculate based on item type
        if (field === 'item_type' || field === 'material_type' || field === 'material_thickness' ||
        field === 'length' || field === 'width' || field === 'letter_height' ||
        field === 'num_letters' || field === 'quantity' || field === 'engrave_area_sqin') {

          const perimFactor = parseFloat(globalSettings.laser_letter_perimeter_factor) || 3.5;

          // Reset total_cut_length_inches first to ensure correct recalculation
          updated.total_cut_length_inches = 0;

          if (updated.item_type === 'panel' || updated.item_type === 'engrave_and_cut') {
            const perimeterInches = 2 * (updated.length + updated.width);
            updated.total_cut_length_inches = perimeterInches * updated.quantity;
          } 

          if ((updated.item_type === 'engraving' || updated.item_type === 'engrave_and_cut') && (field === 'length' || field === 'width' || field === 'item_type')) {
            updated.engrave_area_sqin = updated.length * updated.width;
          }

          if (updated.item_type === 'lettering') {
            const perimeterPerLetter = updated.letter_height * perimFactor;
            updated.total_cut_length_inches = perimeterPerLetter * updated.num_letters * updated.quantity;
          }
          // For 'engraving', total_cut_length_inches remains 0.

          // Get cut speed from settings based on thickness
          // (String() guards: absent material/thickness used to throw here —
          // now it resolves a nonexistent setting key → the same `||default`
          // result, and the field is flagged where it's actually consumed.)
          const thicknessKey = `cut_speed_${String(updated.material_thickness ?? "").replace('/', '_')}`;
          const baseSpeed = parseFloat(globalSettings[thicknessKey]) || 20;

          // Apply material multiplier
          const materialMultiplier = parseFloat(globalSettings[`${String(updated.material_type ?? "").toLowerCase()}_cut_multiplier`]) || 1.0;
          updated.cut_speed_ipm = baseSpeed * materialMultiplier;

          // Get engraving speed from settings
          const engraveBaseSpeed = parseFloat(globalSettings.laser_engrave_speed_sqipm) || 5;
          const engraveMultiplier = parseFloat(globalSettings[`${String(updated.material_type ?? "").toLowerCase()}_engrave_multiplier`]) || 1.0;
          updated.engrave_speed_sqipm = engraveBaseSpeed * engraveMultiplier;
        }

        return updated;
      })
    }));
  };

  // Pricing-availability: one strict calc pass shared by the banner, the
  // totals panels, the per-field diagnostics, and the save guard. The ported
  // math is byte-identical to the old inline calculation on clean input;
  // flagged inputs hold derived numbers at null — never a leaked NaN or a
  // laundered $0. Raw project/item state is never mutated by the calc.
  const priced = useMemo(() => calcLaserPricing(project, globalSettings), [project, globalSettings]);
  const calculated = priced.calc;
  const allIssues = priced.issues || [];
  // Any settings-side unavailability → stronger save message; any issue at
  // all blocks the save — unavailable pricing is never written as $0/NaN.
  const catalogBlocked = allIssues.some((i) => i.kind === "laser_catalog");
  const pricingBlocked = allIssues.length > 0;
  const pricingUnavailable = !!calculated?.pricingUnavailable;
  const itemIssues = (index) => allIssues.filter((i) => i.itemIndex === index);
  const itemIssuesId = (index) => `laser-item-${index}-issues`;
  const itemFieldFlag = (field, index) => hasIssueFor(allIssues, field, index) || undefined;
  const itemFieldDesc = (field, index) => (hasIssueFor(allIssues, field, index) ? itemIssuesId(index) : undefined);
  const projectFieldFlag = (field) => hasIssueFor(allIssues, field) || undefined;
  const projectFieldDesc = (field) => (hasIssueFor(allIssues, field) ? "laser-pricing-issues" : undefined);

  // Display model: live totals while finite; under held pricing the
  // acknowledged snapshot persisted on the record (never a fabricated $0).
  const displayTotals = {
    total_machine_cost: Number.isFinite(calculated?.total_machine_cost)
      ? calculated.total_machine_cost : savedTotals.total_machine_cost,
    total_labor_cost: Number.isFinite(calculated?.total_labor_cost)
      ? calculated.total_labor_cost : savedTotals.total_labor_cost,
    total_supplies_cost: Number.isFinite(calculated?.total_supplies_cost)
      ? calculated.total_supplies_cost : savedTotals.total_supplies_cost,
  };
  const displayTotalCost = laserSumOrNull(
    displayTotals.total_machine_cost, displayTotals.total_supplies_cost, displayTotals.total_labor_cost);
  // Rows the calc actually priced (length-matched); held rows carry nulled
  // derived numbers so displays degrade to "—"/saved, not stale math.
  const displayItems = Array.isArray(calculated?.items) && calculated.items.length === (project.items || []).length
    ? calculated.items
    : (project.items || []);

  // Ctrl+S / Cmd+S saves the section without leaving the editor.
  useEffect(() => {
    const handler = (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "s") {
        e.preventDefault();
        if (!isSaving) saveProject();
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [isSaving]);
  // Block accidental navigation while a save is in flight.
  useEffect(() => {
    if (!isSaving) return undefined;
    const warn = (e) => { e.preventDefault(); e.returnValue = ""; };
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [isSaving]);
  const saveProject = async () => {
    // Pricing-availability gate first — a held estimate never writes, so
    // malformed/unusable inputs can never launder into persisted $0/NaN
    // totals (this also covers the estimate handoff via recordBuilderSave).
    if (pricingBlocked) {
      setSaveError(catalogBlocked
        ? "Save paused: a Laser Settings value is missing or unusable — update it in Laser Settings, then save."
        : "Save paused: fix the flagged pricing values before saving — unavailable pricing is never written as $0.");
      return;
    }
    setSaveError("");
    if (!project.project_name || !(estimateContext?.client_name || project.client_name)) {
      alert('Please fill in project name and client name');
      return;
    }

    if (project.items.length === 0) {
      alert('Please add at least one item to the project');
      return;
    }

    setIsSaving(true);
    try {
      // `calculated` is the shared pricing result — all finite under a clean
      // (unblocked) pass, so persisted totals are real numbers.
      const totalCost = calculated.total_machine_cost + calculated.total_supplies_cost + calculated.total_labor_cost;
      const pricingProject = {
        ...project,
        client_name: estimateContext?.client_name || project.client_name,
        customer_id: estimateContext?.customer_id || project.customer_id,
        estimate_number: estimateContext?.estimate_number || project.estimate_number,
        items: calculated.items,
        total_machine_cost: calculated.total_machine_cost,
        total_supplies_cost: calculated.total_supplies_cost,
        total_labor_cost: calculated.total_labor_cost,
      };
      const customerPricing = await calculateSavedCustomerPricing({
        project: pricingProject,
        categorize: categorizeLaserProject,
        tierNumber: project.customer_pricing?.tier_number,
      });
      const dataToSave = {
        ...pricingProject,
        customer_pricing: customerPricing || project.customer_pricing,
        total_cost: totalCost,
        status: 'calculated'
      };

      let saved;
      const activeProjectId = persistedProjectIdRef.current || editId || "";
      if (activeProjectId) {
        saved = await updateBuilderSourceProject({
          entity: LaserProject,
          sourceId: activeProjectId,
          expectedUpdatedAt: project.updated_date,
          data: dataToSave,
          estimateId,
          label: "Laser project",
        });
      } else {
        await preflightBuilderSourceMutation({ estimateId });
        const signature = JSON.stringify(dataToSave);
        if (createAttemptRef.current.signature !== signature) {
          createAttemptRef.current = {
            signature,
            key: newCreationRequestKey("laser_project"),
          };
        }
        saved = await ensureIdempotentEntityCreate({
          entity: LaserProject,
          keyField: "creation_request_key",
          key: createAttemptRef.current.key,
          data: dataToSave,
          label: "Laser project",
