  hasIssueFor,
} from "@/components/estimator/cnc/cncPricingAvailability";

const imperialSizes = ["1/16", "1/8", "3/16", "1/4", "3/8", "1/2", "5/8", "3/4", "7/8", "1", "1-1/4", "1-1/2", "2", "2-1/2", "3", "3-1/2", "4"];
const materials = ["Acrylic", "Wood", "MDF", "Plywood", "PVC", "HDPE", "Aluminum", "Corian"];
const MATERIAL_THICKNESS_PRESETS = {
  Acrylic: ["1/8", "1/4", "3/8", "1/2"],
  Wood: ["1/2", "3/4", "1", "1-1/2"],
  MDF: ["1/4", "1/2", "3/4", "1"],
  Plywood: ["1/4", "1/2", "3/4", "1"],
  PVC: ["1/4", "1/2", "3/4", "1"],
  HDPE: ["1/4", "1/2", "3/4", "1"],
  Aluminum: ["1/16", "1/8", "3/16", "1/4"],
  Corian: ["1/4", "1/2", "3/4"],
};

const escHtml = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

// Pricing-availability display helpers. A non-finite live value is either the
// saved acknowledged snapshot (shown plainly) or genuinely unsaved
// ("Not saved") — never an invented $0. "—" marks a held derived field.
const moneyCell = (v) => hasCncCostSnapshot(v)
  ? `$${v.toFixed(2)}`
  : <span className="text-amber-700 font-medium">Not saved</span>;
const heldMoney = (v) => (Number.isFinite(v) ? `$${v.toFixed(2)}` : "—");
const heldNum = (v, digits = 1, suffix = "") => (Number.isFinite(v) ? `${v.toFixed(digits)}${suffix}` : "—");

export default function CNCEstimator({ embedded = false, embeddedProjectId = null, embeddedEstimateId = null, onClose, onSaved }) {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  // Embedded All-In-One context wins over standalone query parameters.
  const editId = embeddedProjectId || searchParams.get("edit") || searchParams.get("id");
  const estimateId = embeddedEstimateId || searchParams.get("estimateId");
  const [isEditing, setIsEditing] = useState(false);
  const [project, setProject] = useState({
    project_name: "",
    client_name: "",
    items: [],
    machine_rate_per_hour: 75,
    labor_rate: 45,
    setup_time_percentage: 20, // New field
    fixed_setup_hours: 0, // New field
    notes: ""
  });
  const [globalSettings, setGlobalSettings] = useState({});
  const [estimateContext, setEstimateContext] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [loadError, setLoadError] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const [saveError, setSaveError] = useState("");
  const [activeTab, setActiveTab] = useState("project");
  const persistedProjectIdRef = useRef(editId || "");
  const createAttemptRef = useRef({ signature: "", key: "" });
  const copyAttemptRef = useRef({ signature: "", key: "" });
  const [templateMode, setTemplateMode] = useState(null);

  useEffect(() => {
    persistedProjectIdRef.current = editId || "";
    createAttemptRef.current = { signature: "", key: "" };
    copyAttemptRef.current = { signature: "", key: "" };
    loadPrerequisites();

  }, [editId, estimateId]);

  const loadPrerequisites = async () => {
    setIsLoading(true);
    setLoadError("");
    try {
      const [settingsData, existing, estimate] = await Promise.all([
        loadAllEntityRows({ entity: Settings, sort: "created_date", label: "Estimator Settings" }),
        editId ? CNCProject.get(editId) : Promise.resolve(null),
        estimateId ? staffEntities.AllInOneEstimate.get(estimateId) : Promise.resolve(null),
      ]);
      const settingsObj = {};
      (settingsData || []).forEach(s => { settingsObj[s.setting_name] = s.setting_value; });
      setGlobalSettings(settingsObj);
      setEstimateContext(estimate || null);

      // Strict settings seed: absent rows fall back to the documented module
      // defaults by design; a recorded-but-unusable value lands as null so the
      // project-field scan flags it instead of silently resurrecting a default
      // (remote `parseFloat(x) || dflt` laundered both "abc" and authored 0).
      const strictSeed = (key, dflt) => cncSettingRecorded(settingsObj, key)
        ? cncSettingNumber(settingsObj, key)
        : dflt;
      const sourceDefaults = {
        machine_rate_per_hour: strictSeed("cnc_machine_rate", 75),
        labor_rate: strictSeed("cnc_labor_rate", 45),
        setup_time_percentage: strictSeed("cnc_setup_time_percentage", 20),
        fixed_setup_hours: strictSeed("min_cnc_setup_hours", 0),
        notes: settingsObj.default_notes_template || "",
      };

      if (existing) {
        // CCS creates the section record before the embedded editor opens. Missing
        // CNC-specific values get the same Settings defaults as a source "new" estimate.
        setProject(prev => ({
          ...prev,
          ...sourceDefaults,
          ...existing,
          client_name: estimate?.client_name || existing.client_name || prev.client_name,
          customer_id: estimate?.customer_id || existing.customer_id,
          estimate_number: estimate?.estimate_number || existing.estimate_number,
          items: seedBuilderItemIds(existing.items || []),
          machine_rate_per_hour: existing.machine_rate_per_hour ?? sourceDefaults.machine_rate_per_hour,
          labor_rate: existing.labor_rate ?? sourceDefaults.labor_rate,
          setup_time_percentage: existing.setup_time_percentage ?? sourceDefaults.setup_time_percentage,
          fixed_setup_hours: existing.fixed_setup_hours ?? sourceDefaults.fixed_setup_hours,
        }));
        setIsEditing(true);
      } else {
        setProject(prev => ({
          ...prev,
          ...sourceDefaults,
          client_name: estimate?.client_name || prev.client_name,
          customer_id: estimate?.customer_id,
          estimate_number: estimate?.estimate_number,
        }));
      }
    } catch (error) {
      console.error('Error loading prerequisites:', error);
      setLoadError(error?.message || "CNC Builder prerequisites could not be verified.");
    }
    setIsLoading(false);
  };

  const addItem = () => {
    setTimeout(() => document.querySelector(`input[data-item-desc="${(project.items || []).length}"]`)?.focus(), 60);
    setProject(prev => ({
      ...prev,
      items: [...prev.items, {
        builder_item_id: newBuilderItemId("cnc-item"),
        item_type: "panel",
        description: "",
        material_type: "Wood",
        material_thickness: "3/4",
        quantity: 1,
        length: 0,
        width: 0,
        letter_height: 0,
        num_letters: 0,
        carve_area_sqin: 0,
        carve_depth: 0.125,
        cut_speed_ipm: 50,
        carve_speed_sqipm: 10,
        machine_time_hours: 0,
        setup_time_hours: 0,
        machine_cost: 0,
        labor_cost: 0,
        force_enhanced: false,
        cutter_diameter_in: 0,
        smallest_detail_in: 0,
        workholding_method: "",
        creates_loose_pieces: false,
      }]
    }));
  };

  const removeItem = (index) => {
    if (!window.confirm("Remove this item?")) return;
    setProject(prev => ({ ...prev, items: prev.items.filter((_, i) => i !== index) }));
  };

  const updateItem = (index, field, value) => {
    setProject(prev => {
      const newItems = [...prev.items];
      let item = { ...newItems[index], [field]: value };

      // For lettering items, "Number of Letters" IS the quantity â€” keep qty=1
      // so the per-item math (which multiplies by quantity) doesn't double-count.
      if (field === 'item_type' && value === 'lettering') {
        item.quantity = 1;
      }
      if (item.item_type === 'lettering') {
        item.quantity = 1;
      }

      // Auto-set cut speed based on thickness for CNC. Strict: an absent
      // setting uses the documented 50 ipm default; a recorded-but-unusable
      // value lands null so the item scan flags it (remote silently wrote 50).
      if (field === 'material_thickness') {
        const speedSettingKey = `cnc_cut_speed_${value.replace('/', '_').replace('-', '_')}`;
        item.cut_speed_ipm = cncSettingRecorded(globalSettings, speedSettingKey)
          ? cncSettingNumber(globalSettings, speedSettingKey)
          : 50;
      }

      // Calculate cut length based on item type
      const letterPerimFactor = parseFloat(globalSettings.cnc_letter_perimeter_factor) || 3.5;

      let cutLength = 0;
      if (item.item_type === 'panel') {
        cutLength = (item.length + item.width) * 2;
      } else if (item.item_type === 'lettering') {
        cutLength = item.letter_height * letterPerimFactor * item.num_letters;
      }

      // Machine Time calculation
      const materialCutMultiplierKey = `${item.material_type.toLowerCase()}_cnc_cut_multiplier`;
      const cutMultiplier = parseFloat(globalSettings[materialCutMultiplierKey]) || 1.0;
      const cutTimeMinutes = cutLength > 0 && item.cut_speed_ipm > 0 
        ? (cutLength / item.cut_speed_ipm) * cutMultiplier : 0;

      const carveTimeMinutes = item.carve_area_sqin > 0 && item.carve_speed_sqipm > 0 
        ? item.carve_area_sqin / item.carve_speed_sqipm : 0;

      const machineTimeHours = ((cutTimeMinutes + carveTimeMinutes) * item.quantity) / 60;
      item.machine_time_hours = machineTimeHours;

      // Setup time calculation - use project's setup_time_percentage
      const setupTimePercentage = prev.setup_time_percentage; 
      const setupTimeHours = machineTimeHours * (setupTimePercentage / 100);
      item.setup_time_hours = setupTimeHours;

      // Costs
      item.machine_cost = machineTimeHours * prev.machine_rate_per_hour;
      item.labor_cost = setupTimeHours * prev.labor_rate;

      newItems[index] = { ...item };
      return { ...prev, items: newItems };
    });
  };

  // Pricing-availability: one strict derived pass shared by the banner, the
  // totals panel, the per-field diagnostics, the save guard, and the exports.
  // Totals re-derive from the CURRENT raw inputs every render — the remote
  // reprice-staleness defect (project-rate edits left stored item snapshots
  // stale) cannot persist stale totals as current.
  const priced = useMemo(() => calcCncPricing(project, globalSettings), [project, globalSettings]);
  const pricedItems = priced.items;
  const allIssues = priced.issues;
  // Any settings-side unavailability → stronger save message; any issue at
  // all blocks the save — unavailable pricing is never written as $0.
  const catalogBlocked = allIssues.some((i) => i.kind === "cnc_catalog");
  const pricingBlocked = allIssues.length > 0;
  const pricingUnavailable = priced.held;
  const itemIssues = (index) => allIssues.filter((i) => i.itemIndex === index);

  // calculateTotals keeps its remote shape ({ totalMachine, totalLabor,
  // totalSetupHours, dynamicLaborFromItems, fixedSetupCost, minLaborHours,
  // minimumDynamicLaborAdjustment }) but returns the derived pass — identical
  // values on the valid path; null fields when pricing is held (callers guard).
  const calculateTotals = () => priced.totals;

  // Ctrl+S / Cmd+S saves the section without leaving the editor.
  useEffect(() => {
    const handler = (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "s") {
        e.preventDefault();
        if (!isSaving) saveProject();
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [isSaving]);
  // Block accidental navigation while a save is in flight.
  useEffect(() => {
    if (!isSaving) return undefined;
    const warn = (e) => { e.preventDefault(); e.returnValue = ""; };
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [isSaving]);
  const saveProject = async () => {
    // Pricing-availability guard: a malformed or unavailable pricing input
    // must never be persisted as $0 or an inferred default. Block the write
    // (recordBuilderSave included) and point the user at the flagged values.
    if (pricingBlocked) {
      setSaveError(catalogBlocked
        ? "Save paused: a CNC Settings value is missing or unusable — update it in CNC Settings, then save."
        : "Save paused: fix the flagged pricing values before saving — unavailable pricing is never written as $0.");
      return;
    }
    if (!project.project_name || !(estimateContext?.client_name || project.client_name)) {
      alert('Please fill in project name and client name');
      return;
    }

    setIsSaving(true);
    setSaveError("");
    try {
      const totals = calculateTotals();
      const totalCost = totals.totalMachine + totals.totalLabor;
      const pricingProject = {
        ...project,
        // Persist the derived-fresh item costs so the acknowledged snapshot is
        // always current pricing (reprice-on-save; never a stale snapshot).
        items: pricedItems,
        client_name: estimateContext?.client_name || project.client_name,
        customer_id: estimateContext?.customer_id || project.customer_id,
        estimate_number: estimateContext?.estimate_number || project.estimate_number,
        total_machine_cost: totals.totalMachine,
        total_labor_cost: totals.totalLabor,
      };
      const customerPricing = await calculateSavedCustomerPricing({
        project: pricingProject,
        categorize: categorizeCNCProject,
        tierNumber: project.customer_pricing?.tier_number,
      });
      const finalProject = {
        ...pricingProject,
        customer_pricing: customerPricing || project.customer_pricing,
        total_cost: totalCost,
        status: 'calculated',
      };

      let saved;
      const activeProjectId = persistedProjectIdRef.current || editId || "";
      if (activeProjectId) {
        saved = await updateBuilderSourceProject({
          entity: CNCProject,
          sourceId: activeProjectId,
          expectedUpdatedAt: project.updated_date,
          data: finalProject,
