  const id = embeddedProjectId || params.get("id") || params.get("edit");
  const estimateId = embeddedEstimateId || params.get("estimateId");

  const [project, setProject] = useState(null);
  const [materials, setMaterials] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");
  const [saving, setSaving] = useState(false);
  const [templateMode, setTemplateMode] = useState(null);
  const saveRef = useRef(null);
  const copyAttemptRef = useRef({ signature: "", key: "" });
  const navigate = useNavigate();

  useEffect(() => {
    copyAttemptRef.current = { signature: "", key: "" };
    const load = async () => {
      setLoading(true);
      setLoadError("");
      try {
        const [p, legacyMats, foundationMats] = await Promise.all([
          id ? staffEntities.BrickStoneProject.get(id) : Promise.resolve(null),
          // Legacy entity is optional compatibility data; the modern Foundation
          // inventory below is the authoritative masonry catalog and is strict.
          loadAllEntityRows({ entity: staffEntities.BrickStoneInventory, sort: "material_name", label: "Legacy Brick & Stone inventory" }).catch(() => []),
          loadAllEntityRows({ entity: staffEntities.FoundationInventory, sort: "material_name", label: "Foundation masonry inventory" }),
        ]);

      // The committed SignEstimate Pro repo defined BrickStoneInventory but never
      // shipped a Brick estimator implementation or any BrickStoneInventory data.
      // Modern Master Inventory stores masonry units in FoundationInventory. Use
      // those rows as the primary catalog while keeping the legacy entity readable
      // for compatibility if an older record is ever encountered.
      const modernMats = (foundationMats || [])
        .filter((row) =>
          row.show_in_foundation !== false && (
            row.material_type === "brick_stone" ||
            (row.material_type === "wall_material" && ["brick", "stone", "cinderblock"].includes(row.wall_material_subtype))
          )
        )
        .map((row) => ({
          ...row,
          length: row.material_type === "brick_stone" ? row.brick_length_inches : row.wall_unit_length_inches,
          width: row.material_type === "brick_stone" ? row.brick_width_inches : row.wall_unit_width_inches,
          height: row.material_type === "brick_stone" ? row.brick_height_inches : row.wall_unit_height_inches,
          _inventory_entity: "FoundationInventory",
        }));
      const legacyNormalized = (legacyMats || []).map((row) => ({
        ...row,
        _inventory_entity: "BrickStoneInventory",
      }));

        setProject(p);
        setMaterials([...modernMats, ...legacyNormalized]);
      } catch (error) {
        console.error("Brick & Stone prerequisites could not be loaded:", error);
        setLoadError(error?.message || "Brick & Stone Builder prerequisites could not be verified.");
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [id]);

  const material = useMemo(
    () => materials.find((m) => m.id === project?.selected_material_id),
    [materials, project]
  );
  // Pricing-availability: one strict calc pass shared by the banner, the
  // totals panel, the per-field diagnostics, and every save path.
  const priced = useMemo(
    () => (project ? calcBrickStoneAvailability(project, material) : null),
    [project, material]
  );
  const totals = priced?.calc || null;
  const allIssues = priced?.issues || [];
  // A catalog-side hold (the selected material record) gets the stronger
  // save message; any issue at all blocks every write path.
  const catalogBlocked = allIssues.some((i) => i.kind === "brick_catalog");
  const pricingBlocked = allIssues.length > 0;

  // Ctrl+S / Cmd+S saves the section without leaving the editor.
  useEffect(() => {
    const handler = (e) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "s") {
        e.preventDefault();
        if (!saving) saveRef.current?.();
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [saving]);
  // Block accidental navigation while a save is in flight.
  useEffect(() => {
    if (!saving) return undefined;
    const warn = (e) => { e.preventDefault(); e.returnValue = ""; };
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [saving]);

  if (loading) return <div className="p-10 text-center text-gray-400">Loading section…</div>;
  if (loadError) return <div className="p-10 text-center text-red-700 bg-red-50 border border-red-200 rounded">Brick & Stone Builder unavailable. Required project data or the primary masonry catalog could not be verified. {loadError}</div>;
  if (!project) return <div className="p-10 text-center text-gray-500">Section not found.</div>;

  const patch = (changes) => setProject((prev) => ({ ...prev, ...changes }));

  const handleSave = async () => {
    // Pricing-availability guard: a malformed or unavailable pricing input
    // must never be persisted as $0 or an inferred default. Block the write
    // and point the user at the flagged values.
    if (pricingBlocked) {
      window.alert(catalogBlocked
        ? "Save paused: the selected material record is missing or unusable — fix it in the masonry catalog, then save."
        : "Save paused: fix the flagged pricing values before saving — unavailable pricing is never written as $0.");
      return;
    }
    if (!(Number(totals?.calculated_surface_area) > 0)) {
      window.alert("Wall area must be greater than zero before this section can be saved. Check the wall dimensions and material selection.");
      return;
    }
    setSaving(true);
    try {
      const pricingProject = {
        ...project,
        material_cost: totals.material_cost,
        mortar_cost: totals.mortar_cost,
        labor_cost: totals.labor_cost,
        subtotal: totals.subtotal,
      };
      const customerPricing = project.customer_pricing?.applied === true
        ? await calculateSavedCustomerPricing({
            project: pricingProject,
            categorize: categorizeBrickStoneProject,
            tierNumber: project.customer_pricing?.tier_number,
          })
        : project.customer_pricing;
      const dataToSave = {
        project_name: project.project_name,
        notes: project.notes,
        status: "calculated",
        selected_material_id: project.selected_material_id,
        material_name: project.material_name,
        material_dimensions: project.material_dimensions,
        bricks_along_length: project.bricks_along_length,
        bricks_along_width: project.bricks_along_width,
        courses_high: project.courses_high,
        layers: project.layers,
        mortar_gap: project.mortar_gap,
        waste_factor: project.waste_factor,
        mortar_bag_cost: project.mortar_bag_cost,
        bricks_per_hour: project.bricks_per_hour,
        labor_rate_per_hour: project.labor_rate_per_hour,
        markup_percent: project.markup_percent,
        base_length: totals.derived_length,
        base_width: totals.derived_width,
        base_height: totals.derived_height,
        calculated_bricks: totals.calculated_bricks,
        calculated_surface_area: totals.calculated_surface_area,
        mortar_bags_needed: totals.mortar_bags_needed,
        material_cost: totals.material_cost,
        mortar_cost: totals.mortar_cost,
        labor_hours: totals.labor_hours,
        labor_cost: totals.labor_cost,
        subtotal: totals.subtotal,
        markup_amount: totals.markup_amount,
        total_cost: totals.total_cost,
        customer_pricing: customerPricing,
      };
      const savedProject = await updateBuilderSourceProject({
        entity: staffEntities.BrickStoneProject,
        sourceId: project.id,
        expectedUpdatedAt: project.updated_date,
        data: dataToSave,
        estimateId,
        label: "Brick & Stone project",
      });
      if (savedProject?.updated_date) {
        setProject((prev) => ({ ...prev, updated_date: savedProject.updated_date }));
      }

      if (estimateId) {
        await recordBuilderSave({
          estimateId,
          line: { project_id: project.id, module_key: "brick_stone" },
          sourceProject: savedProject,
          liveTotal: totals.total_cost,
        });
      }
      onSaved?.();
    } catch (e) {
      console.error(e); alert("Save failed: " + e.message);
    } finally {
      setSaving(false);
    }
  };
  saveRef.current = handleSave;

  // #78 — clone the current save payload into a brand-new Brick & Stone project.
  const handleSaveAsCopy = async () => {
    // Same availability gate as the save path — a copy must never clone $0 or
    // inferred pricing into a new record (the mop-up guard gap).
    if (pricingBlocked) {
      window.alert(catalogBlocked
        ? "Save paused: the selected material record is missing or unusable — fix it in the masonry catalog, then save a copy."
        : "Save paused: fix the flagged pricing values before saving a copy — unavailable pricing is never written as $0.");
      return;
    }
    if (!(Number(totals?.calculated_surface_area) > 0)) {
      window.alert("Wall area must be greater than zero before this section can be copied. Check the wall dimensions and material selection.");
      return;
    }
    setSaving(true);
    try {
      const copy = await saveModuleProjectCopy({
        entity: staffEntities.BrickStoneProject,
        payload: {
          project_name: project.project_name,
          client_name: project.client_name,
          customer_id: project.customer_id,
          estimate_number: project.estimate_number,
          hyperlink: project.hyperlink,
          notes: project.notes,
          status: "calculated",
          selected_material_id: project.selected_material_id,
          material_name: project.material_name,
          material_dimensions: project.material_dimensions,
          bricks_along_length: project.bricks_along_length,
          bricks_along_width: project.bricks_along_width,
          courses_high: project.courses_high,
          layers: project.layers,
          mortar_gap: project.mortar_gap,
          waste_factor: project.waste_factor,
          mortar_bag_cost: project.mortar_bag_cost,
          bricks_per_hour: project.bricks_per_hour,
          labor_rate_per_hour: project.labor_rate_per_hour,
          markup_percent: project.markup_percent,
          base_length: totals.derived_length,
          base_width: totals.derived_width,
          base_height: totals.derived_height,
          calculated_bricks: totals.calculated_bricks,
          calculated_surface_area: totals.calculated_surface_area,
          mortar_bags_needed: totals.mortar_bags_needed,
          material_cost: totals.material_cost,
          mortar_cost: totals.mortar_cost,
          labor_hours: totals.labor_hours,
          labor_cost: totals.labor_cost,
          subtotal: totals.subtotal,
          markup_amount: totals.markup_amount,
          total_cost: totals.total_cost,
          customer_pricing: project.customer_pricing,
        },
        attemptRef: copyAttemptRef,
        keyPrefix: "brick_stone_project_copy",
        baseName: project.project_name || "Brick & Stone",
        label: "Brick & Stone project copy",
      });
      if (embedded) onSaved?.();
      else navigate(`/BrickStoneEstimator?id=${copy.id}`);
    } catch (e) {
      console.error(e); alert("Save copy failed: " + e.message);
    } finally {
      setSaving(false);
    }
  };

  // #79 — template payload = the editable masonry setup a user would reuse.
  const buildBrickStoneTemplateData = (p) => ({
    selected_material_id: p.selected_material_id,
    material_name: p.material_name,
    material_dimensions: p.material_dimensions,
    bricks_along_length: p.bricks_along_length,
    bricks_along_width: p.bricks_along_width,
    courses_high: p.courses_high,
    layers: p.layers,
    mortar_gap: p.mortar_gap,
    waste_factor: p.waste_factor,
    mortar_bag_cost: p.mortar_bag_cost,
    bricks_per_hour: p.bricks_per_hour,
    labor_rate_per_hour: p.labor_rate_per_hour,
    markup_percent: p.markup_percent,
    notes: p.notes,
  });

  return (
    <div className="clay-scope min-h-full bg-gradient-to-br from-rose-50 to-orange-50">
      <div className="max-w-6xl mx-auto p-4 sm:p-6">
        <div className="flex items-center justify-between gap-4 mb-5">
          {embedded ? (
            <button
              type="button"
              onClick={onClose}
              className="flex items-center gap-1 text-sm text-gray-600 hover:text-red-600"
            >
              <ArrowLeft className="w-4 h-4" /> Back to products
            </button>
          ) : (
            <Link
              to={estimateId ? `/EstimateDetail?id=${estimateId}` : "/Estimator"}
              className="flex items-center gap-1 text-sm text-gray-600 hover:text-red-600"
            >
              <ArrowLeft className="w-4 h-4" /> Back to estimate
            </Link>
          )}
          {project?.updated_date && (<div className="mt-1 text-[10px] text-gray-400">Last saved {new Date(project.updated_date).toLocaleString()}</div>)}
          <Button onClick={handleSave} disabled={saving || !project.selected_material_id} className="clay-button border-2 border-red-300 bg-red-50 hover:bg-red-100 text-red-700 font-bold">
            <Save className="w-4 h-4" /> {saving ? "Saving…" : "Save Section"}
          </Button>
          <ModuleActionBar
            onTemplates={() => setTemplateMode("load")}
            onSaveAsTemplate={() => setTemplateMode("save")}
            onSaveAsCopy={handleSaveAsCopy}
            estimateId={estimateId}
            saving={saving}
          />
        </div>

        <div className="mb-4">
          <h1 className="text-2xl font-bold text-gray-900">Brick &amp; Stone</h1>
          <p className="text-sm text-gray-500">{project.client_name}</p>
        </div>

        {/* Pricing-availability banner — visible on every state so a blocked
            save always shows why. */}
        {allIssues.length > 0 && (
          <div
            role="status"
            id="brick-pricing-issues"
            className="mb-4 flex items-start gap-2 text-xs text-amber-900 bg-amber-50 border border-amber-300 rounded-xl px-3 py-2"
          >
            <AlertTriangle className="w-4 h-4 mt-0.5 flex-shrink-0 text-amber-600" />
            <div className="min-w-0">
              <div className="font-semibold">
                Pricing unavailable — {allIssues.length} value{allIssues.length === 1 ? "" : "s"} need{allIssues.length === 1 ? "s" : ""} attention before this section can be priced or saved.
              </div>
              <ul className="mt-1 space-y-0.5 list-disc list-inside">
                {allIssues.slice(0, 5).map((it, i) => <li key={i}>{it.message}</li>)}
                {allIssues.length > 5 && <li>…and {allIssues.length - 5} more</li>}
              </ul>
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">
          <div className="lg:col-span-2 space-y-4">
            <div className="bg-white rounded-xl border border-gray-200 p-4">
              <label className="text-xs text-gray-500">
                Section name
                <Input
                  value={project.project_name || ""}
                  onChange={(e) => patch({ project_name: e.target.value })}
                />
              </label>
            </div>

            <BrickGeometryPanel
              project={project}
              materials={materials}
              derived={totals}
              issues={allIssues}
              onChange={patch}
            />

            {materials.length === 0 && (
              <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 text-xs text-amber-700">
                No masonry materials in the catalog yet.{" "}
                <Link to="/FoundationCatalog" className="font-semibold underline hover:text-amber-900">
                  Add brick or stone in the foundation catalog →
                </Link>
              </div>
            )}
          </div>

          <div>
            <BrickTotals
              project={project}
              totals={totals}
              issues={allIssues}
              onChange={(changes) => patch({
                ...changes,
                ...(Object.prototype.hasOwnProperty.call(changes, "markup_percent")
                  ? { customer_pricing: { ...(project.customer_pricing || {}), applied: false } }
                  : {}),
              })}
            />
          </div>
        </div>

        <div className="mt-5">
          <CustomerPricingTab
            project={{
              ...project,
              material_cost: totals.material_cost,
              mortar_cost: totals.mortar_cost,
              labor_cost: totals.labor_cost,
              subtotal: totals.subtotal,
            }}
            categorize={categorizeBrickStoneProject}
            accentColor="red"
            onApplyTier={(tier) => patch({
              customer_pricing: { ...(project.customer_pricing || {}), applied: true, tier_number: tier },
            })}
          />
        </div>

        <ModuleTemplateDialog
          open={!!templateMode}
          mode={templateMode}
          onClose={() => setTemplateMode(null)}
          project={project}
          onApply={(data) => patch(data)}
          moduleKey="brick_stone"
          title="Brick & Stone"
          buildTemplateData={buildBrickStoneTemplateData}
          describeTemplate={(t) => (t.project_data?.material_name || "Saved wall setup")}
        />
      </div>
    </div>
  );
}

import { useState, useEffect, useRef } from "react";
import { useSearchParams, Link } from "react-router-dom";
import { staffEntities } from "@/components/staff/staffEntities";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Plus, Trash2, Upload, ArrowLeft, ListChecks } from "lucide-react";
import { recordBuilderSave } from "@/components/estimator/builder/builderService";
import { preflightBuilderSourceMutation } from "@/components/estimator/builder/sourceProjectPersistence";

const num = (v, d = 0) => { const n = parseFloat(v); return Number.isFinite(n) ? n : d; };
const newItem = () => ({ description: "", quantity: 1, item_total_cost: 0, item_type: "fabrication", unit: "item" });
const ITEM_TYPES = ["fabrication", "material", "labor", "equipment", "shipping", "other"];
const sumTotal = (items) => (items || []).reduce((s, i) => s + num(i.item_total_cost), 0);

export default function CustomItemsEstimator({ embeddedProjectId, embeddedEstimateId, onSaved } = {}) {
  const [searchParams] = useSearchParams();
  const editId = embeddedProjectId || searchParams.get("edit") || searchParams.get("id");
  const estimateId = embeddedEstimateId || searchParams.get("estimateId");
  const [project, setProject] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const csvRef = useRef(null);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        const proj = editId ? await staffEntities.CustomItemsProject.get(editId) : null;
        if (cancelled) return;
        setProject(proj || { project_name: "Custom items", client_name: "", items: [newItem()], total_cost: 0 });
        setLoading(false);
      } catch (e) { if (!cancelled) { setError(e?.message || "Could not load project."); setLoading(false); } }
    };
    load();
    return () => { cancelled = true; };
  }, [editId]);

  const updateItem = (i, field, value) => setProject((p) => {
    const items = p.items.map((it, j) => j === i ? { ...it, [field]: value } : it);
    return { ...p, items, total_cost: sumTotal(items) };
  });
  const addItem = () => setProject((p) => ({ ...p, items: [...(p.items || []), newItem()] }));
  const removeItem = (i) => setProject((p) => { const items = p.items.filter((_, j) => j !== i); return { ...p, items, total_cost: sumTotal(items) }; });

  const importCsv = async (file) => {
    if (!file) return;
    try {
      const text = await file.text();
      const lines = text.split(/[\n\r]+/).map((l) => l.trim()).filter(Boolean).slice(0, 200);
      const rows = [];
      for (const line of lines) {
        const [desc, qty, cost, type] = line.split(",").map((s) => s.trim());
        if (!desc || desc.toLowerCase() === "description") continue;
        rows.push({ description: desc, quantity: num(qty, 1), item_total_cost: num(cost), item_type: type || "fabrication", unit: "item" });
      }
      if (!rows.length) throw new Error("No item rows — expected `description, quantity, item_total_cost` per line.");
      setProject((p) => { const items = [...(p.items || []), ...rows]; return { ...p, items, total_cost: sumTotal(items) }; });
      window.alert(`Imported ${rows.length} line item(s).`);
    } catch (e) { window.alert(e?.message || "CSV import failed."); }
    finally { if (csvRef.current) csvRef.current.value = ""; }
  };

  const saveProject = async () => {
    setSaving(true);
    try {
      const payload = { ...project, total_cost: sumTotal(project.items) };
      let saved;
      if (project.id) {
        const fresh = await staffEntities.CustomItemsProject.get(project.id);
        if (fresh?.updated_date && fresh.updated_date !== project.updated_date) throw new Error("This section changed — reload before saving.");
        saved = await staffEntities.CustomItemsProject.update(project.id, payload);
      } else {
        await preflightBuilderSourceMutation?.({ estimateId }).catch(() => {});
        saved = await staffEntities.CustomItemsProject.create(payload);
      }
      setProject(saved || payload);
      if (estimateId) await recordBuilderSave?.({ estimateId, projectId: saved?.id || project.id }).catch(() => {});
      onSaved?.(saved);
      window.alert("Section saved.");
    } catch (e) { window.alert(e?.message || "Save failed."); }
    finally { setSaving(false); }
  };

  if (loading) return <div className="p-10 text-center text-[12px] text-gray-400">Loading custom items…</div>;
  if (error) return <div className="p-10 text-center text-[12px] text-red-600">{error}</div>;
  if (!project) return null;

  return (
    <div className="mx-auto max-w-4xl px-4 py-5">
      <div className="flex items-center gap-3 mb-4">
        <Link to="/Estimator"><Button variant="outline" className="h-[30px] text-[11px]"><ArrowLeft className="w-3.5 h-3.5 mr-1" /> Estimator</Button></Link>
        <div className="w-9 h-9 rounded bg-violet-50 text-violet-700 flex items-center justify-center"><ListChecks className="w-5 h-5" /></div>
        <div className="min-w-0 flex-1">
          <h1 className="text-[18px] font-bold text-gray-900">Custom line items</h1>
          <p className="text-[10px] text-gray-500">A flat list of priced items — hand-entered or CSV-imported. Feeds the section total via `extractManualItems`.</p>
        </div>
        <button type="button" onClick={() => csvRef.current?.click()} className="h-[30px] px-2.5 rounded border border-emerald-300 bg-emerald-50 text-[10px] font-bold text-emerald-700 hover:bg-emerald-100 inline-flex items-center gap-1"><Upload className="w-3 h-3" /> Import CSV</button>
        <input ref={csvRef} type="file" accept=".csv,text/csv" className="hidden" onChange={(e) => importCsv(e.target.files?.[0])} />
        <Button onClick={saveProject} disabled={saving} className="h-[30px] text-[11px]">{saving ? "Saving…" : "Save section"}</Button>
      </div>
      <div className="bg-white border border-gray-200 rounded-md">
        <div className="px-4 py-2 border-b border-gray-200 grid grid-cols-2 gap-3">
          <div><Label className="text-[9px]">Section name</Label><Input value={project.project_name || ""} onChange={(e) => setProject((p) => ({ ...p, project_name: e.target.value }))} className="h-[30px] text-[11px] mt-0.5" /></div>
          <div><Label className="text-[9px]">Client</Label><Input value={project.client_name || ""} onChange={(e) => setProject((p) => ({ ...p, client_name: e.target.value }))} className="h-[30px] text-[11px] mt-0.5" /></div>
        </div>
        <div className="divide-y divide-gray-100">
          {(project.items || []).map((item, i) => (
            <div key={i} className="px-4 py-2.5 grid grid-cols-12 items-end gap-2">
              <div className="col-span-5"><Label className="text-[9px]">Description</Label><Input value={item.description || ""} onChange={(e) => updateItem(i, "description", e.target.value)} className="h-[28px] text-[11px] mt-0.5" /></div>
              <div className="col-span-2"><Label className="text-[9px]">Qty</Label><Input type="number" min="0" value={item.quantity ?? 1} onChange={(e) => updateItem(i, "quantity", num(e.target.value, 1))} className="h-[28px] text-[11px] mt-0.5" /></div>
              <div className="col-span-2"><Label className="text-[9px]">Cost (extended)</Label><Input type="number" min="0" step="0.01" value={item.item_total_cost ?? 0} onChange={(e) => updateItem(i, "item_total_cost", num(e.target.value))} className="h-[28px] text-[11px] mt-0.5" /></div>
              <div className="col-span-2"><Label className="text-[9px]">Type</Label>
                <Select value={item.item_type || "fabrication"} onValueChange={(v) => updateItem(i, "item_type", v)}>
                  <SelectTrigger className="h-[28px] text-[11px] mt-0.5"><SelectValue /></SelectTrigger>
                  <SelectContent>{ITEM_TYPES.map((t) => <SelectItem key={t} value={t}>{t}</SelectItem>)}</SelectContent>
                </Select>
              </div>
              <button type="button" onClick={() => removeItem(i)} className="col-span-1 justify-self-end text-red-400 hover:text-red-600"><Trash2 className="w-4 h-4" /></button>
            </div>
          ))}
        </div>
        <div className="px-4 py-2.5 border-t border-gray-200 flex items-center justify-between">
          <button type="button" onClick={addItem} className="h-[28px] px-2.5 rounded border border-gray-300 bg-white text-[10px] font-bold text-gray-700 hover:bg-gray-50 inline-flex items-center gap-1"><Plus className="w-3 h-3" /> Add item</button>
          <div className="text-[12px] font-bold text-gray-900">Section total: ${sumTotal(project.items).toLocaleString(undefined, { maximumFractionDigits: 2 })}</div>
        </div>
      </div>
    </div>
  );
}

