import { Layers, X, AlertCircle } from "lucide-react";
import { ChannelLetterInstallInventory } from "@/api/gatedEntities";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import BackerFabPanel from "./BackerFabPanel";
import { channelDraftValue } from "./channelLetterPricingAvailability";

const fmt = (v) => (Number.isFinite(v) ? `$${v.toFixed(2)}` : "—");

/**
 * BackerSection — renders inside a Dimensional Letters purchase row
 * when backer_enabled is true. Lets the user pick:
 *  - Backer material (from DimensionalLetterMaterial)
 *  - Standoff (from ChannelLetterInstallInventory where applies_to_list includes "backer")
 *  - # of standoffs
 *  - Build Backer Fab Cost (opens BackerFabModal)
 */
export default function BackerSection({ purchase, onUpdate, onDisable }) {
  const [standoffs, setStandoffs] = useState([]);

  useEffect(() => {
    (async () => {
      try {
        const inv = await loadAllEntityRows({ entity: ChannelLetterInstallInventory, sort: "sort_order", label: "Backer standoff inventory" });
        const filtered = (inv || []).filter(i => {
          const list = Array.isArray(i.applies_to_list) ? i.applies_to_list : [];
          return list.includes("backer");
        });
        setStandoffs(filtered);
      } catch (e) {
        console.error("BackerSection load failed", e);
      }
    })();
  }, []);

  const fab = purchase.backer_fab_config;
  const standoffPicked = standoffs.find(s => s.id === purchase.backer_standoff_inventory_id);
  const standoffUnitCost = standoffPicked ? (parseFloat(standoffPicked.cost_per_letter) || parseFloat(standoffPicked.cost_flat) || 0) : 0;
  const standoffTotalCost = standoffUnitCost * (parseFloat(purchase.backer_standoff_qty) || 0);

  return (
    <div className="border-2 border-orange-200 bg-orange-50/40 rounded-xl p-4 space-y-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Layers className="w-4 h-4 text-orange-600" />
          <span className="text-sm font-semibold text-orange-900">Backer Panel Configuration</span>
          <Badge className="bg-orange-200 text-orange-900 border-orange-300 text-[10px]">SWITCHES PRICING SCHEDULE</Badge>
        </div>
        <Button variant="ghost" size="sm" onClick={() => { if (confirm("Remove the backer panel and its configuration?")) onDisable(); }} className="h-7 text-xs text-orange-700 hover:bg-orange-100">
          <X className="w-3 h-3 mr-1" /> Remove Backer
        </Button>
      </div>

      {/* Standoff picker — backer material + W/H are configured in the inline panel below */}
      <div className="grid md:grid-cols-2 gap-3">
        <div>
          <Label className="text-xs">Standoff Type</Label>
          <Select
            value={purchase.backer_standoff_inventory_id || ""}
            onValueChange={(v) => onUpdate({ backer_standoff_inventory_id: v })}
          >
            <SelectTrigger className="h-9 mt-1 bg-white">
              <SelectValue placeholder="Pick a standoff..." />
            </SelectTrigger>
            <SelectContent>
              {standoffs.length === 0 && <SelectItem value="__none" disabled>No backer standoffs in inventory</SelectItem>}
              {standoffs.map(s => (
                <SelectItem key={s.id} value={s.id}>{s.item_name} — {fmt(parseFloat(s.cost_per_letter) || parseFloat(s.cost_flat) || 0)}/ea</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div>
          <Label className="text-xs">Qty of Standoffs (per letter)</Label>
          <Input
            type="number" min="0" step="1"
            value={purchase.backer_standoff_qty ?? 0}
            onChange={(e) => onUpdate({ backer_standoff_qty: channelDraftValue(e.target.value) })}
            className="h-9 mt-1 bg-white"
          />
        </div>
      </div>

      {standoffs.length === 0 && (
        <div className="bg-amber-50 border border-amber-200 rounded-md p-2 flex items-start gap-2">
          <AlertCircle className="w-3.5 h-3.5 text-amber-600 flex-shrink-0 mt-0.5" />
          <p className="text-[11px] text-amber-800">
            No standoffs yet. Add them in <strong>Channel Letter Install Inventory → Materials → Backer</strong> group.
          </p>
        </div>
      )}

      {/* Inline Backer Fab panel (replaces the popup) */}
      <div className="border-t border-orange-200 pt-3">
        <BackerFabPanel purchase={purchase} onUpdate={onUpdate} />
      </div>

      {/* Mini rollup */}
      <div className="bg-white rounded-lg border border-orange-200 p-2.5 grid grid-cols-3 gap-2 text-xs">
        <div>
          <div className="text-[10px] uppercase tracking-wider text-slate-500">Backer Fab × Qty</div>
          <div className="font-semibold tabular-nums text-slate-900">{fmt((fab?.unit_total_cost || 0) * (parseFloat(purchase.qty) || 0))}</div>
        </div>
        <div>
          <div className="text-[10px] uppercase tracking-wider text-slate-500">Standoffs ({purchase.backer_standoff_qty || 0})</div>
          <div className="font-semibold tabular-nums text-slate-900">{fmt(standoffTotalCost)}</div>
          <div className="text-[10px] text-slate-400">Per install line</div>
        </div>
        <div>
          <div className="text-[10px] uppercase tracking-wider text-slate-500">Pricing Schedule</div>
          <Badge className="bg-orange-100 text-orange-800 border-orange-200 text-[10px]">w/ Backer</Badge>
        </div>
      </div>

    </div>
  );
}

import React, { useState } from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Sun, Home } from "lucide-react";
import AutoGrowNotes from "./AutoGrowNotes";
import { HEIGHT_BUCKETS, qualifiedKey, qualifiedNotesKey } from "./installSizeRates";

// One size's editor card. Holds:
//   - large Interior/Exterior pill toggle (very noticeable)
//   - Height bucket dropdown (0-12, 12-20, 20-30, 30+ ft)
//   - the drill/prep/(elec) inputs for the currently-selected (env, height) tuple
//
// Each combination edits its own setting key:
//   `${drillPrefix}${sizeKey}__${env}__${heightBucket}` etc.
export default function BaseTimesSizeCard({
  sizeKey,
  sizeLabel,
  sizeRange,
  drillPrefix,
  prepPrefix,
  elecPrefix,
  includeElectrical,
  settings,
  updateSetting,
  isLocked,
}) {
  const [env, setEnv] = useState("exterior");
  const [heightBucket, setHeightBucket] = useState("h0_12");

  const drillName = qualifiedKey(drillPrefix, sizeKey, env, heightBucket);
  const prepName  = qualifiedKey(prepPrefix,  sizeKey, env, heightBucket);
  const elecName  = elecPrefix ? qualifiedKey(elecPrefix, sizeKey, env, heightBucket) : null;

  const drillVal = parseFloat(settings[drillName]) || 0;
  const prepVal  = parseFloat(settings[prepName]) || 0;
  const elecVal  = elecName ? (parseFloat(settings[elecName]) || 0) : 0;
  const total    = drillVal + prepVal + elecVal;

  const renderField = (name, label) => {
    if (!name) return null;
    const value = settings[name];
    const notesName = qualifiedNotesKey(
      name.startsWith(drillPrefix) ? drillPrefix
      : name.startsWith(prepPrefix) ? prepPrefix
      : elecPrefix,
      sizeKey, env, heightBucket
    );
    const notesValue = settings[notesName];
    return (
      <div>
        <div className="flex items-baseline justify-between mb-1">
          <Label htmlFor={name} className="text-xs font-medium text-slate-700">{label}</Label>
          <span className="text-[10px] uppercase tracking-wider text-slate-400 font-medium">min</span>
        </div>
        <div className="flex items-start gap-2">
          <Input
            type="number"
            step="1"
            id={name}
            value={value ?? ""}
            onChange={(e) => updateSetting(name, e.target.value)}
            disabled={isLocked}
            className="h-9 w-14 flex-shrink-0 bg-white border-slate-200 focus:border-slate-400 focus:ring-0 text-sm tabular-nums font-medium px-1.5 text-center"
            min="0"
          />
          <AutoGrowNotes
            value={notesValue}
            onChange={(v) => updateSetting(notesName, v)}
            disabled={isLocked}
            className="flex-1 min-w-0"
            minHeightPx={36}
          />
        </div>
      </div>
    );
  };

  const envIsExterior = env === "exterior";

  return (
    <div className="border border-slate-200 rounded-xl p-4 bg-slate-50/40 hover:bg-slate-50 transition-colors space-y-3">
      <div className="flex items-baseline justify-between">
        <div>
          <div className="text-sm font-semibold text-slate-900">{sizeLabel}</div>
          <div className="text-[11px] text-slate-500">{sizeRange}</div>
        </div>
        <div className="text-right">
          <div className="text-[10px] uppercase tracking-wider text-slate-400">Total / letter</div>
          <div className="text-sm font-bold text-slate-900 tabular-nums">{total} min</div>
        </div>
      </div>

      {/* LARGE Interior/Exterior slider toggle — very noticeable */}
      <button
        type="button"
        role="switch"
        aria-checked={envIsExterior}
        onClick={() => setEnv(envIsExterior ? "interior" : "exterior")}
        disabled={isLocked}
        className={`relative w-full h-11 rounded-xl border-2 transition-all overflow-hidden shadow-sm ${
          envIsExterior
            ? "bg-gradient-to-r from-blue-50 to-sky-50 border-blue-300"
            : "bg-gradient-to-r from-amber-50 to-orange-50 border-amber-300"
        } ${isLocked ? "opacity-60 cursor-not-allowed" : "cursor-pointer hover:shadow"}`}
      >
        {/* Sliding pill */}
        <div
          className={`absolute top-1 bottom-1 w-[calc(50%-4px)] rounded-lg shadow-md transition-all duration-300 ease-out ${
            envIsExterior
              ? "left-1 bg-gradient-to-br from-blue-500 to-blue-600"
              : "left-[calc(50%+3px)] bg-gradient-to-br from-amber-500 to-orange-500"
          }`}
        />
        {/* Labels */}
        <div className="relative grid grid-cols-2 h-full">
          <div className={`flex items-center justify-center gap-1.5 text-xs font-semibold transition-colors ${envIsExterior ? "text-white" : "text-blue-700"}`}>
            <Sun className="w-3.5 h-3.5" />
            Exterior
          </div>
          <div className={`flex items-center justify-center gap-1.5 text-xs font-semibold transition-colors ${!envIsExterior ? "text-white" : "text-amber-700"}`}>
            <Home className="w-3.5 h-3.5" />
            Interior
          </div>
        </div>
      </button>

      {/* Height bucket selector */}
      <div>
        <Label className="text-[10px] uppercase tracking-wider text-slate-500 font-medium">Installation Height</Label>
        <div className="grid grid-cols-4 gap-1 mt-1">
          {HEIGHT_BUCKETS.map(hb => (
            <button type="button"
              key={hb.key}
              type="button"
              onClick={() => setHeightBucket(hb.key)}
              disabled={isLocked}
              className={`text-[10px] py-1.5 px-1 rounded-md border transition-all font-medium ${
                heightBucket === hb.key
                  ? "border-slate-700 bg-slate-900 text-white shadow-sm"
                  : "border-slate-200 bg-white text-slate-600 hover:border-slate-400"
              } ${isLocked ? "opacity-60 cursor-not-allowed" : "cursor-pointer"}`}
            >
              {hb.label}
            </button>
          ))}
        </div>
      </div>

      {/* The actual minute inputs for the currently-selected (env, height) tuple */}
      <div className="space-y-2 pt-1">
        {renderField(drillName, "Drill Pattern / Drill Time")}
        {renderField(prepName, "Installation / Prep Time")}
        {includeElectrical && renderField(elecName, "Electrical Hookup")}
      </div>

      <div className="text-[10px] text-slate-400 italic leading-tight pt-1 border-t border-slate-200">
        Editing: <span className="font-semibold text-slate-600">{envIsExterior ? "Exterior" : "Interior"}</span> · <span className="font-semibold text-slate-600">{HEIGHT_BUCKETS.find(h => h.key === heightBucket)?.label}</span>
      </div>
    </div>
  );
}

import { useMemo, useState, useEffect } from "react";
import { ChannelLetterInstallEquipment } from "@/api/gatedEntities";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { AlertTriangle, CheckCircle2 } from "lucide-react";
import {
  ResponsiveContainer,
  ComposedChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ReferenceLine,
  ReferenceDot,
  Legend,
} from "recharts";

// Computes the maximum horizontal parking distance (boom pivot → building
// face) at which a boom can still reach a given building height.
// The boom's working envelope is approximated as a circle of radius
// horizontal_boom_reach centered on the boom pivot. The pivot sits
// (total_boom_height) above the ground. So at building height `h`, the
// reachable horizontal distance from the pivot is:
//     sqrt( H_reach^2 - (h - pivot_height)^2 )
// Subtract half the deployed truck width because the pivot is centered on
// the truck while the truck side touches the building.
function reachAt(equipment, buildingHeight) {
  const H = Number(equipment.horizontal_boom_reach_feet) || 0;
  const totalBoom = Number(equipment.total_boom_height_feet) || Number(equipment.max_height_feet) || 0;
  const safety = Number(equipment.vertical_reach_safety_margin_feet) || 0;
  const truckWidth = Number(equipment.deployed_truck_width_feet) || 0;
  if (H <= 0 || totalBoom <= 0) return null;

  // The boom can reach UP to (totalBoom - safety) and DOWN to (- some amount)
  // We model the pivot at ~truck-deck height; for simplicity treat the pivot
  // as at ground level with a max vertical reach of (totalBoom - safety).
  const maxVertical = totalBoom - safety;
  if (buildingHeight > maxVertical) return 0; // out of vertical range
  // Horizontal reach from pivot at this height (circular envelope)
  const horiz = Math.sqrt(Math.max(0, H * H - Math.pow(buildingHeight - 0, 2)));
  // Subtract half the truck width — boom pivot is centered on the carriage
  const usable = horiz - truckWidth / 2;
  return Math.max(0, usable);
}

const COLORS = ["#7c3aed", "#0ea5e9", "#f59e0b", "#10b981", "#ef4444", "#ec4899", "#6366f1"];

export default function BoomLiftReachChart({ installationHeightFeet }) {
  const [allEquipment, setAllEquipment] = useState([]);
  const [selectedId, setSelectedId] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    (async () => {
      setLoading(true);
      try {
        const list = await loadAllEntityRows({ entity: ChannelLetterInstallEquipment, sort: "sort_order", label: "Boom lift equipment" });
        const booms = list.filter(
          (e) => (e.equipment_type === "boom_lift" || e.equipment_type === "boom_truck") && e.is_active !== false
        );
        setAllEquipment(booms);
        // Auto-select the smallest boom whose max height ≥ install height,
        // otherwise just the first one.
        const h = Number(installationHeightFeet) || 0;
        const sorted = [...booms].sort(
          (a, b) => (Number(a.max_height_feet) || 0) - (Number(b.max_height_feet) || 0)
        );
        const best = sorted.find((b) => (Number(b.max_height_feet) || 0) >= h) || sorted[0];
        if (best) setSelectedId(best.id);
      } catch (e) {
        console.error("BoomLiftReachChart load error:", e);
      }
      setLoading(false);
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const selected = useMemo(
    () => allEquipment.find((e) => e.id === selectedId),
    [allEquipment, selectedId]
  );

  const chartData = useMemo(() => {
    if (!selected) return [];
    const H = Number(selected.horizontal_boom_reach_feet) || 0;
    const totalBoom = Number(selected.total_boom_height_feet) || Number(selected.max_height_feet) || 0;
    const safety = Number(selected.vertical_reach_safety_margin_feet) || 0;
    const maxVertical = Math.max(totalBoom - safety, 0);
    const upperBound = Math.max(maxVertical, Number(installationHeightFeet) || 0, 30);
    const steps = 60;
    const data = [];
    for (let i = 0; i <= steps; i++) {
      const height = (upperBound / steps) * i;
      const dist = reachAt(selected, height);
      data.push({
        building_height: +height.toFixed(1),
        parking_distance: dist == null ? null : +dist.toFixed(2),
      });
    }
    return data;
  }, [selected, installationHeightFeet]);

  const targetReach = useMemo(() => {
    if (!selected) return null;
    return reachAt(selected, Number(installationHeightFeet) || 0);
  }, [selected, installationHeightFeet]);

  const isReachable = targetReach != null && targetReach > 0;
  const maxVerticalReach = selected
    ? (Number(selected.total_boom_height_feet) || Number(selected.max_height_feet) || 0) -
      (Number(selected.vertical_reach_safety_margin_feet) || 0)
    : 0;

  if (loading) {
    return <div className="text-xs text-slate-500 py-6 text-center">Loading boom lift data…</div>;
  }

  if (allEquipment.length === 0) {
    return (
      <div className="text-xs text-slate-600 bg-amber-50 border border-amber-200 rounded p-3 leading-relaxed">
        No boom lifts or boom trucks in your equipment inventory yet. Add one in{" "}
        <span className="font-semibold">Channel Letter Inventory → Equipment</span> with{" "}
        <span className="font-semibold">Horizontal Boom Reach</span>,{" "}
        <span className="font-semibold">Total Boom Height</span>, and{" "}
        <span className="font-semibold">Deployed Truck Width</span> to enable this chart.
      </div>
    );
  }

  const hasFullData =
    selected &&
    Number(selected.horizontal_boom_reach_feet) > 0 &&
    (Number(selected.total_boom_height_feet) > 0 || Number(selected.max_height_feet) > 0);

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2 flex-wrap">
        <span className="text-xs font-semibold text-slate-700">Boom Lift / Truck:</span>
        <Select value={selectedId} onValueChange={setSelectedId}>
          <SelectTrigger className="h-8 w-[280px] text-xs">
            <SelectValue placeholder="Choose a boom lift or truck" />
          </SelectTrigger>
          <SelectContent>
            {allEquipment.map((e) => (
              <SelectItem key={e.id} value={e.id} className="text-xs">
                {e.equipment_name} — {e.max_height_feet || 0}ft max
                {e.equipment_type === "boom_truck" ? " (Truck)" : ""}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {!hasFullData ? (
        <div className="text-xs text-amber-800 bg-amber-50 border border-amber-200 rounded p-2 leading-relaxed">
          <AlertTriangle className="w-3.5 h-3.5 inline mr-1" />
          This boom lift is missing reach data. Edit it in the Equipment inventory and add{" "}
          <span className="font-semibold">Horizontal Boom Reach</span> and{" "}
          <span className="font-semibold">Total Boom Height</span>.
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-3">
          {/* LEFT column — specs, status, explanation */}
          <div className="space-y-2 min-w-0">
            {/* Quick spec strip */}
            <div className="grid grid-cols-2 gap-1.5 text-[10px]">
              <div className="bg-slate-50 border border-slate-200 rounded px-2 py-1">
                <div className="text-slate-500">Horiz Reach</div>
                <div className="font-semibold text-slate-800">{selected.horizontal_boom_reach_feet || 0} ft</div>
              </div>
              <div className="bg-slate-50 border border-slate-200 rounded px-2 py-1">
                <div className="text-slate-500">Max Vert (w/ safety)</div>
                <div className="font-semibold text-slate-800">{maxVerticalReach.toFixed(0)} ft</div>
              </div>
              <div className="bg-slate-50 border border-slate-200 rounded px-2 py-1">
                <div className="text-slate-500">Truck Width</div>
                <div className="font-semibold text-slate-800">{selected.deployed_truck_width_feet || 0} ft</div>
              </div>
              <div className="bg-slate-50 border border-slate-200 rounded px-2 py-1">
                <div className="text-slate-500">Safety Margin</div>
                <div className="font-semibold text-slate-800">{selected.vertical_reach_safety_margin_feet || 0} ft</div>
              </div>
            </div>

            {/* Status badge for current install height */}
            {isReachable ? (
              <div className="text-xs bg-emerald-50 border border-emerald-200 text-emerald-800 rounded px-2.5 py-1.5 flex items-center gap-2">
                <CheckCircle2 className="w-3.5 h-3.5 shrink-0" />
                <span>
                  At <strong>{Number(installationHeightFeet) || 0} ft</strong> install height, this boom can park up to{" "}
                  <strong>{targetReach.toFixed(1)} ft</strong> away from the building face.
                </span>
              </div>
            ) : (
              <div className="text-xs bg-red-50 border border-red-200 text-red-800 rounded px-2.5 py-1.5 flex items-center gap-2">
                <AlertTriangle className="w-3.5 h-3.5 shrink-0" />
                <span>
                  This boom can't safely reach <strong>{Number(installationHeightFeet) || 0} ft</strong>. Choose a larger lift or
                  check vertical safety margin.
                </span>
              </div>
            )}

            <p className="text-[10px] text-slate-400 leading-snug">
              The shaded area is where the boom can position its platform to touch the building face. Below the curve = OK;
              above = the boom physically can't get the worker that high while parked that far out. Half the truck width is
              subtracted because the boom pivot sits in the middle of the carriage.
            </p>
          </div>

          {/* RIGHT column — chart */}
          <div className="bg-white border border-slate-200 rounded-lg p-2 min-w-0">
            <ResponsiveContainer width="100%" height={220}>
              <ComposedChart data={chartData} margin={{ top: 8, right: 16, left: 8, bottom: 36 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  dataKey="building_height"
                  type="number"
                  domain={[0, "dataMax"]}
                  tick={{ fontSize: 10, fill: "#64748b" }}
                  label={{ value: "Building Height (ft)", position: "insideBottom", offset: -20, fontSize: 11, fill: "#475569" }}
                />
                <YAxis
                  tick={{ fontSize: 10, fill: "#64748b" }}
                  label={{ value: "Parking Dist (ft)", angle: -90, position: "insideLeft", offset: 14, fontSize: 11, fill: "#475569", style: { textAnchor: "middle" } }}
                />
                <Tooltip
                  contentStyle={{ fontSize: 11, padding: "4px 8px", borderRadius: 6 }}
                  formatter={(v) => (v == null ? "out of reach" : `${v} ft`)}
                  labelFormatter={(v) => `Building height: ${v} ft`}
                />
                <Legend wrapperStyle={{ fontSize: 10, paddingTop: 4 }} verticalAlign="top" height={20} />
                <Area
                  type="monotone"
                  dataKey="parking_distance"
                  name="Reachable zone"
                  stroke={COLORS[0]}
                  fill={COLORS[0]}
                  fillOpacity={0.15}
                  strokeWidth={2}
                />
                <ReferenceLine
                  x={Number(installationHeightFeet) || 0}
                  stroke="#ef4444"
                  strokeDasharray="4 4"
                  label={{ value: "Install Ht", fontSize: 10, fill: "#ef4444", position: "top" }}
                />
                {isReachable && (
                  <ReferenceDot
                    x={Number(installationHeightFeet) || 0}
                    y={targetReach}
                    r={5}
                    fill="#ef4444"
                    stroke="#fff"
                    strokeWidth={2}
                  />
                )}
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}
    </div>
  );
}

