export default function InstallLineItem({ item, index, inventory, settings = {}, onUpdate, onRemove, onDuplicate, compact = false, issues = [] }) {
  const [expanded, setExpanded] = useState(!compact);
  const [advancedOpen, setAdvancedOpen] = useState(false);
  const isRaceway = item.installation_type === "raceway";

  // Pricing diagnostics — per-field aria-invalid + inline message. Item-level
  // issues carry index = item index; material issues on this item use
  // different field names (unit_cost/quantity) so they never collide here.
  const fieldIssues = (field) => issuesForField(issues, field, null, index);
  const invalidCls = (field) => (fieldIssues(field).length ? "border-red-500" : "");
  const ariaFor = (field) => (fieldIssues(field).length
    ? { "aria-invalid": true, "aria-describedby": `cli-${index}-${field}-issue` }
    : {});
  const FieldIssue = ({ field }) => {
    const fi = fieldIssues(field);
    if (!fi.length) return null;
    return (
      <p id={`cli-${index}-${field}-issue`} className="text-[10px] text-red-600 mt-0.5" role="alert">
        {fi[0].message}
      </p>
    );
  };

  // Count active "advanced" toggles to show on the collapsed header
  const activeConditionsCount = [
    item.thick_hollow_walls, item.parapet, item.poor_electrical_access,
    item.escort_required, item.badging_checkin, item.after_hours_weekend,
    item.set_hours_installation, item.poor_site_access
  ].filter(Boolean).length;

  // Sync expanded state when parent toggles compact mode globally
  useEffect(() => {
    setExpanded(!compact);
  }, [compact]);

  const update = (patch) => onUpdate({ ...item, ...patch });

  const wallMat = WALL_MATERIAL_MAP[item.wall_material];

  const conditionBadges = [];
  if (wallMat) conditionBadges.push({ label: wallMat.label, color: "bg-purple-50 text-purple-700 border-purple-200" });
  if (item.thick_hollow_walls) conditionBadges.push({ label: "Thick Walls", color: "bg-orange-50 text-orange-700 border-orange-200" });
  if (item.parapet) conditionBadges.push({ label: "Parapet", color: "bg-red-50 text-red-700 border-red-200" });
  if (item.poor_electrical_access) conditionBadges.push({ label: "Poor Electrical", color: "bg-yellow-50 text-yellow-800 border-yellow-200" });
  if (item.escort_required) conditionBadges.push({ label: "Escort Req'd", color: "bg-sky-50 text-sky-700 border-sky-200" });
  if (item.badging_checkin) conditionBadges.push({ label: "Badging/Check-in", color: "bg-indigo-50 text-indigo-700 border-indigo-200" });
  if (item.after_hours_weekend) conditionBadges.push({ label: "After-Hours", color: "bg-violet-50 text-violet-700 border-violet-200" });
  if (item.set_hours_installation) conditionBadges.push({ label: "Set-Hours", color: "bg-teal-50 text-teal-700 border-teal-200" });
  if (item.poor_site_access) conditionBadges.push({ label: "Poor Site Access", color: "bg-rose-50 text-rose-700 border-rose-200" });

  return (
    <Card className="border border-slate-200 shadow-sm overflow-hidden">
      {/* Header */}
      <div className="flex items-center gap-2 px-4 py-3 bg-slate-50 border-b border-slate-100 flex-wrap">
        <button type="button" onClick={() => setExpanded(e => !e)} className="text-slate-500 hover:text-slate-900">
          {expanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
        </button>
        <span className="text-xs font-semibold text-slate-500 w-6">#{index + 1}</span>
        <Input
          value={item.description || ""}
          onChange={(e) => update({ description: e.target.value })}
          placeholder={`${TYPE_LABELS[item.installation_type]} — describe this line...`}
          className="h-8 text-sm flex-1 bg-white min-w-[160px]"
          onClick={(e) => e.stopPropagation()}
        />
        <Badge variant="outline" className={`capitalize ${TYPE_BADGE_COLOR[item.installation_type]}`}>
          {TYPE_LABELS[item.installation_type]}
        </Badge>
        {item.__held && (
          <Badge variant="outline" className="text-[10px] text-amber-700 border-amber-300 bg-amber-50">
            Saved value — not repriced
          </Badge>
        )}
        {conditionBadges.map((b, i) => (
          <Badge key={i} variant="outline" className={`text-[10px] ${b.color}`}>
            {b.label}
          </Badge>
        ))}
        <Badge variant="outline" className="bg-slate-100 text-slate-700 font-semibold tabular-nums">
          {fmt(item.item_total_cost)}
        </Badge>
        <Button variant="ghost" size="sm" onClick={onDuplicate} className="h-7 w-7 p-0 text-slate-500 hover:bg-slate-200" title="Duplicate">
          <Copy className="w-3.5 h-3.5" />
        </Button>
        <Button variant="ghost" size="sm" onClick={onRemove} className="h-7 w-7 p-0 text-red-500 hover:bg-red-50" title="Remove">
          <Trash2 className="w-3.5 h-3.5" />
        </Button>
      </div>

      {/* Cost breakdown bar — always visible */}
      <div className="px-4 py-2 border-b border-slate-100 bg-white">
        <CostBreakdownBar
          labor={item.labor_cost || 0}
          materials={item.materials_cost || 0}
        />
      </div>

      {expanded && (
        <CardContent className="p-4 space-y-4">
          {/* Quick summary */}
          <div className="text-xs text-slate-500">
            {isRaceway
              ? `${item.qty_letters} letters · ${item.raceway_length_feet} ft raceway · ${item.installation_height_feet} ft high`
              : `${item.qty_letters} letters · ${item.installation_height_feet} ft high`
            }
          </div>

          {/* Interior / Exterior override — defaults to project setting */}
          <div className="bg-slate-50 rounded-lg p-3 border border-slate-200">
            <div className="flex items-center gap-2 mb-2">
              <Label className="text-xs font-semibold text-slate-700">Installation Environment</Label>
              <span className="text-[10px] text-slate-400">(overrides project default for this line item)</span>
            </div>
            <div className="grid grid-cols-3 gap-1 max-w-md">
              {[
                { value: "", label: "Project Default" },
                { value: "exterior", label: "Exterior" },
                { value: "interior", label: "Interior" },
              ].map(opt => {
                const active = (item.install_environment || "") === opt.value;
                return (
                  <button type="button"
                    key={opt.value || "default"}
                    onClick={() => update({ install_environment: opt.value || undefined })}
                    className={`text-xs px-2 py-1.5 rounded-md border transition-all ${
                      active
                        ? "border-purple-500 bg-purple-50 text-purple-900 font-semibold shadow-sm"
                        : "border-slate-200 bg-white text-slate-600 hover:border-slate-300"
                    }`}
                  >
                    {opt.label}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Qty Letters + Installation Height — at the very top */}
          <div className="grid md:grid-cols-2 gap-4 bg-slate-50 rounded-lg p-3 border border-slate-200">
            <div>
              <Label className="text-xs font-semibold text-slate-700">Qty Letters</Label>
              <Input
                type="number"
                value={item.qty_letters}
                onFocus={(e) => e.target.select()}
                onChange={(e) => update({ qty_letters: channelDraftValue(e.target.value) })}
                className={`h-9 mt-1.5 ${invalidCls("qty_letters")}`}
                {...ariaFor("qty_letters")}
              />
              <FieldIssue field="qty_letters" />
              {isRaceway && (
                <div className="mt-3">
                  <Label className="text-xs font-semibold text-slate-700">Raceway Length (ft)</Label>
                  <Input
                    type="number"
                    value={item.raceway_length_feet}
                    onFocus={(e) => e.target.select()}
                    onChange={(e) => update({ raceway_length_feet: channelDraftValue(e.target.value) })}
                    className={`h-9 mt-1.5 ${invalidCls("raceway_length_feet")}`}
                    {...ariaFor("raceway_length_feet")}
                  />
                  <FieldIssue field="raceway_length_feet" />
                </div>
              )}
            </div>
            <div>
              <Label className="text-xs font-semibold text-slate-700">Installation Height (ft)</Label>
              <div className="mt-1.5">
                <InstallHeightSlider
                  value={item.installation_height_feet}
                  onChange={(v) => update({ installation_height_feet: v })}
                />
              </div>
            </div>
          </div>

          {/* Install Type Picker */}
          <div>
            <Label className="text-xs text-slate-600">Installation Type</Label>
            <div className="mt-1.5">
              <InstallTypePicker value={item.installation_type} onChange={(v) => update({ installation_type: v })} />
            </div>
          </div>

          {/* Letter Size Picker (not for raceway) */}
          {!isRaceway && (
            <div>
              <Label className="text-xs text-slate-600">Letter Size</Label>
              <div className="mt-1.5">
                <LetterSizePicker value={item.letter_size} onChange={(v) => update({ letter_size: v })} />
              </div>
            </div>
          )}

          {/* Wall material + Site conditions */}
          <div className="space-y-3 border-t pt-3">
            <div className="flex items-center gap-2 text-xs font-semibold text-slate-700">
              <Sliders className="w-3.5 h-3.5" />
              Wall & Site Conditions
              {activeConditionsCount > 0 && (
                <Badge variant="outline" className="bg-purple-100 text-purple-800 border-purple-200 text-[10px] h-4 px-1.5">
                  {activeConditionsCount} active
                </Badge>
              )}
            </div>
            <div>
              <Label className="text-xs text-slate-600">Wall Material <span className="text-slate-400 font-normal">(what we're installing into)</span></Label>
              <div className="mt-1.5">
                <WallMaterialPicker value={item.wall_material || "eifs"} onChange={(v) => update({ wall_material: v })} />
              </div>
            </div>
            <div>
              <Label className="text-xs text-slate-600">Site Conditions <span className="text-slate-400 font-normal">(toggle if applicable)</span></Label>
              <div className="mt-1.5">
                <ConditionPicker
                  settings={settings}
                  values={{
                    thick_hollow_walls: item.thick_hollow_walls,
                    parapet: item.parapet,
                    parapet_electrical_routing: item.parapet_electrical_routing || "roof",
                    poor_electrical_access: item.poor_electrical_access,
                    poor_electrical_severity: item.poor_electrical_severity || 1,
                    escort_required: item.escort_required,
                    badging_checkin: item.badging_checkin,
                    after_hours_weekend: item.after_hours_weekend,
                    set_hours_installation: item.set_hours_installation,
                    poor_site_access: item.poor_site_access,
                    poor_site_access_severity: item.poor_site_access_severity || 1,
                  }}
                  onChange={(v) => update(v)}
                />
              </div>
            </div>
          </div>

          {/* Materials */}
          <div className="border-t pt-3">
            <MaterialsList item={item} itemIndex={index} inventory={inventory} onChange={(materials) => update({ materials })} issues={issues} />
          </div>

          {/* Per-item summary strip */}
          <div className="border-t pt-3 grid grid-cols-3 gap-3 text-xs">
            <div className="bg-slate-50 rounded p-2">
              <div className="text-slate-500">Labor</div>
              <div className="font-semibold tabular-nums">
                {Number.isFinite(item.labor_hours) ? item.labor_hours.toFixed(2) : "—"} hrs · {fmt(item.labor_cost)}
              </div>
            </div>
            <div className="bg-slate-50 rounded p-2">
              <div className="text-slate-500">Materials</div>
              <div className="font-semibold tabular-nums">{fmt(item.materials_cost)}</div>
            </div>
            <div className="bg-purple-50 rounded p-2 border border-purple-100">
              <div className="text-purple-700">Item Total</div>
              <div className="font-bold text-purple-900 tabular-nums">{fmt(item.item_total_cost)}</div>
            </div>
          </div>
        </CardContent>
      )}
    </Card>
  );
}

import React from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Save, Copy, FileDown, Calculator, TrendingUp } from "lucide-react";
// Note: Markup % control intentionally removed — all markups are managed on the Customer Pricing tab.
import CostBreakdownBar from "./CostBreakdownBar";

// Held/blank values render an em-dash instead of laundering into $0.00.
const fmt = (v) => (Number.isFinite(v) ? `$${v.toFixed(2)}` : "—");

export default function InstallSummaryCard({
  project, onUpdate, onSave, isSaving, isEditing, onCopySummary, onExportCSV
}) {
  const itemsCount = (project.items || []).length;
  // Keep possibly-null values — a held group must show "—", never $0.00.
  const labor = project.labor_cost;
  // When a crew is assigned, personnel pricing replaces the flat-rate labor in the subtotal
  const laborViaCrew = !!project.labor_priced_via_personnel;
  const laborInSubtotal = laborViaCrew ? 0 : labor;
  const materials = project.total_materials_cost;
  const equipment = project.total_equipment_cost;
  const personnel = project.total_personnel_cost;
  const travel = project.total_travel_cost;
  const letters = project.total_letters_cost;
  const subtotal = project.subtotal;
  const total = project.total_cost;
  const showSeg = (v) => v === null || (Number.isFinite(v) && v > 0);

  const segments = [
    { label: "Labor",      value: laborInSubtotal, color: "bg-purple-400" },
    { label: "Materials",  value: materials, color: "bg-emerald-400" },
    { label: "Equipment",  value: equipment, color: "bg-amber-400" },
    { label: "Personnel",  value: personnel, color: "bg-sky-400" },
    { label: "Travel",     value: travel,    color: "bg-orange-400" },
    { label: "Letters",    value: letters,   color: "bg-pink-400" },
  ].map(s => ({ ...s, value: Number.isFinite(s.value) ? s.value : 0 }));

  return (
    <Card className="border-0 shadow-xl sticky top-8 overflow-hidden bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 text-white">
      {/* Header */}
      <div className="px-5 pt-5 pb-4 bg-gradient-to-br from-purple-600/30 to-transparent">
        <div className="flex items-center gap-2 mb-1">
          <div className="w-8 h-8 rounded-lg bg-white/10 backdrop-blur flex items-center justify-center">
            <Calculator className="w-4 h-4 text-purple-200" />
          </div>
          <div>
            <div className="text-sm font-semibold tracking-wide">Estimate Summary</div>
            <div className="text-[11px] text-slate-300">
              {itemsCount} item{itemsCount !== 1 ? "s" : ""}
              {(project.letter_purchases || []).length > 0 && ` · ${(project.letter_purchases).length} letter line${(project.letter_purchases).length !== 1 ? "s" : ""}`}
            </div>
          </div>
        </div>
      </div>

      <CardContent className="space-y-4 pt-2 pb-5 px-5">
        {project.__held && (
          <p className="text-[11px] text-amber-300 bg-amber-500/10 border border-amber-400/30 rounded-md px-2.5 py-1.5">
            Saved amounts (not current pricing) — fix the flagged values to reprice.
          </p>
        )}
        {/* Cost rollup rows */}
        <div className="space-y-1.5 text-sm">
          {!laborViaCrew && (
            <Row label={`Labor (${Number.isFinite(project.labor_hours) ? project.labor_hours.toFixed(2) : "—"} hrs)`} value={labor} dot="bg-purple-400" />
          )}
          <Row label="Materials" value={materials} dot="bg-emerald-400" />
          {showSeg(equipment) && (
            <Row label={`Equipment (${(project.selected_equipment || []).length})`} value={equipment} dot="bg-amber-400" />
          )}
          {showSeg(personnel) && (
            <Row
              label={laborViaCrew
                ? `Crew Labor (${(project.personnel || []).length} crew · ${Number.isFinite(project.labor_hours) ? project.labor_hours.toFixed(2) : "—"} hrs)`
                : `Personnel (${(project.personnel || []).length})`}
              value={personnel}
              dot="bg-sky-400"
            />
          )}
          {showSeg(travel) && (
            <Row label={`Travel (${(parseFloat(project.travel_miles_round_trip) || 0).toFixed(1)} mi)`} value={travel} dot="bg-orange-400" />
          )}
          {showSeg(letters) && (
            <Row label={`Letters (${(project.letter_purchases || []).length})`} value={letters} dot="bg-pink-400" />
          )}
          <div className="flex justify-between border-t border-white/10 pt-2 mt-2">
            <span className="text-slate-300">Subtotal</span>
            <span className="font-semibold tabular-nums">{fmt(subtotal)}</span>
          </div>
        </div>

        {/* Breakdown bar */}
        {Number.isFinite(subtotal) && subtotal > 0 && (
          <div className="bg-white/5 rounded-lg p-3 space-y-2 border border-white/5">
            <div className="flex items-center justify-between text-[10px] uppercase tracking-wider text-slate-400">
              <span className="flex items-center gap-1">
                <TrendingUp className="w-3 h-3" /> Where the money goes
              </span>
            </div>
            <CostBreakdownBar segments={segments} />
          </div>
        )}

        {/* Total — markups live in the Customer Pricing tab */}
        <div className="bg-gradient-to-br from-purple-600 to-purple-800 rounded-xl px-4 py-3 shadow-lg border border-purple-400/30">
          <div className="text-[10px] text-purple-100 uppercase tracking-widest font-semibold">Subtotal (Before Markup)</div>
          <div className="text-3xl font-bold tabular-nums leading-tight">{fmt(Number.isFinite(subtotal) ? subtotal : total)}</div>
          <div className="text-[10px] text-purple-200 mt-0.5">
            See <span className="font-semibold">Customer Pricing</span> tab for tier-based pricing.
          </div>
        </div>

        {/* Actions */}
        <div className="space-y-2 pt-1">
          {project?.updated_date && (<div className="mt-1 text-[10px] text-gray-400">Last saved {new Date(project.updated_date).toLocaleString()}</div>)}
          <Button
            onClick={onSave}
            disabled={isSaving}
            className="w-full bg-green-500 hover:bg-green-600 text-white h-11 shadow-md"
          >
            <Save className="w-4 h-4 mr-2" />
            {isSaving ? "Saving..." : isEditing ? "Update Estimate" : "Save Estimate"}
          </Button>
          <div className="grid grid-cols-2 gap-2">
            <Button
              variant="outline"
              onClick={onCopySummary}
              className="h-9 text-xs bg-white/5 border-white/20 text-white hover:bg-white/10 hover:text-white"
            >
              <Copy className="w-3.5 h-3.5 mr-1" /> Copy
            </Button>
            <Button
              variant="outline"
              onClick={onExportCSV}
              className="h-9 text-xs bg-white/5 border-white/20 text-white hover:bg-white/10 hover:text-white"
            >
              <FileDown className="w-3.5 h-3.5 mr-1" /> CSV
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

const Row = ({ label, value, dot }) => (
  <div className="flex justify-between items-center">
    <span className="text-slate-300 flex items-center gap-2">
      <span className={`w-1.5 h-1.5 rounded-full ${dot}`} />
      {label}
    </span>
    <span className="font-medium tabular-nums">{fmt(value)}</span>
  </div>
);

