import React from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Link } from "react-router-dom";
import { createPageUrl } from "@/utils";
import { Plus, Type, Truck, Receipt, Info, Settings, Sparkles, ChevronDown, ArrowUp } from "lucide-react";
import LetterPurchaseRow from "./LetterPurchaseRow";
import AIScopeWriterModal from "./AIScopeWriterModal";
import { emptyLetterPurchase, LETTER_TYPE_LABELS, groupPurchasesBySet, newSetId } from "./lettersCalculator";
import { channelDraftValue, channelNumber, issuesForField } from "./channelLetterPricingAvailability";
import { Layers } from "lucide-react";

// Held/blank values render an em-dash instead of laundering into $0.00.
const fmt = (v) => (Number.isFinite(v) ? `$${v.toFixed(2)}` : "—");

const QUICK_ADD = [
  { type: "channel_raceway_mounted", label: "+ Raceway Mounted Letters", color: "bg-indigo-50 hover:bg-indigo-100 text-indigo-700 border-indigo-200" },
  { type: "channel_flush_mounted", label: "+ Flush Mounted Letters", color: "bg-purple-50 hover:bg-purple-100 text-purple-700 border-purple-200" },
  { type: "channel_halo_lit", label: "+ Halo-Lit Letters", color: "bg-pink-50 hover:bg-pink-100 text-pink-700 border-pink-200" },
  { type: "capsule_logo_pillbox", label: "+ Capsule / Logo", color: "bg-amber-50 hover:bg-amber-100 text-amber-700 border-amber-200" },
  { type: "dimensional_letters", label: "+ Dimensional Letters", color: "bg-emerald-50 hover:bg-emerald-100 text-emerald-700 border-emerald-200" },
];

export default function LettersPurchaseTab({ project, settings, onUpdateProject, incompleteDimensionalIds = [], issues = [] }) {
  const purchases = project.letter_purchases || [];
  const [aiOpen, setAiOpen] = React.useState(false);
  const [feesOpen, setFeesOpen] = React.useState(false);
  const incompleteSet = React.useMemo(() => new Set(incompleteDimensionalIds || []), [incompleteDimensionalIds]);

  const addPurchase = (type) => {
    const p = emptyLetterPurchase(type);
    onUpdateProject({ letter_purchases: [...purchases, p] });
  };

  // True when at least one dimensional letters row is on this project
  const hasDimensional = purchases.some(p => p.letter_type === "dimensional_letters");

  // Delivery / Shipping does NOT apply to dimensional lettering (fabricated in-house).
  // Hide the fee + rollup row when every letter product on the project is dimensional.
  const onlyDimensional = purchases.length > 0 && purchases.every(p => p.letter_type === "dimensional_letters");

  // Enable a backer on the first dimensional row that doesn't already have one
  const addBackerToFirstDimensional = () => {
    const idx = purchases.findIndex(p => p.letter_type === "dimensional_letters" && !p.backer_enabled);
    if (idx === -1) return; // all dimensional rows already have a backer
    const arr = [...purchases];
    arr[idx] = { ...arr[idx], backer_enabled: true };
    onUpdateProject({ letter_purchases: arr });
  };
  const allDimensionalHaveBacker = hasDimensional && purchases
    .filter(p => p.letter_type === "dimensional_letters")
    .every(p => p.backer_enabled);

  const applyAIPurchases = (aiPurchases, mode = "append") => {
    const newOnes = aiPurchases.map((ai) => {
      const base = emptyLetterPurchase(ai.letter_type || "channel_flush_mounted");
      return {
        ...base,
        description: ai.description || base.description,
        qty: parseFloat(ai.qty) || 0,
        size_value: parseFloat(ai.size_value) || 0,
        install_height_feet: parseFloat(ai.install_height_feet) || base.install_height_feet || 12,
        wall_material: ai.wall_material || base.wall_material || "eifs",
      };
    });
    onUpdateProject({
      letter_purchases: mode === "replace" ? newOnes : [...purchases, ...newOnes],
    });
  };

  const updatePurchase = (idx, next) => {
    const arr = [...purchases];
    arr[idx] = next;
    onUpdateProject({ letter_purchases: arr });
  };

  const removePurchase = (idx) => {
    if (!confirm("Remove this letter row?")) return;
    const arr = [...purchases];
    arr.splice(idx, 1);
    onUpdateProject({ letter_purchases: arr });
  };

  const duplicatePurchase = (idx) => {
    const arr = [...purchases];
    const copy = JSON.parse(JSON.stringify(arr[idx]));
    copy.id = `lp_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
    // A duplicated row should NOT clone set membership — that would create orphan/duplicate children
    copy.set_id = undefined;
    copy.set_parent_id = undefined;
    arr.splice(idx + 1, 0, copy);
    onUpdateProject({ letter_purchases: arr });
  };

  // Add a CHILD purchase that inherits install_height_feet & wall_material from the parent.
  // If the parent doesn't yet have a set_id, give it one and insert the new child right after it.
  const addToSet = (parent, childType) => {
    const arr = [...purchases];
    const parentIdx = arr.findIndex(p => p.id === parent.id);
    if (parentIdx === -1) return;

    const sid = parent.set_id || newSetId();
    if (!parent.set_id) {
      arr[parentIdx] = { ...arr[parentIdx], set_id: sid };
    }

    const child = emptyLetterPurchase(childType);
    child.set_id = sid;
    child.set_parent_id = parent.id;
    // Inherit location-style fields from the parent
    child.install_height_feet = parent.install_height_feet;
    child.wall_material = parent.wall_material || "eifs";

    // Insert immediately after the parent (and after any existing children of that parent)
    let insertAt = parentIdx + 1;
    while (insertAt < arr.length && arr[insertAt].set_parent_id === parent.id) insertAt++;
    arr.splice(insertAt, 0, child);
    onUpdateProject({ letter_purchases: arr });
  };

  // When a parent in a set changes install_height_feet or wall_material, propagate to children.
  // This keeps "inherit from parent" semantics live in the UI.
  const updatePurchaseWithSetSync = (idx, next) => {
    const arr = [...purchases];
    const prev = arr[idx];
    arr[idx] = next;

    const heightChanged = (prev.install_height_feet || 0) !== (next.install_height_feet || 0);
    const wallChanged = (prev.wall_material || "") !== (next.wall_material || "");
    if (next.set_id && !next.set_parent_id && (heightChanged || wallChanged)) {
      // It's a parent — propagate to its children
      for (let i = 0; i < arr.length; i++) {
        if (arr[i].set_parent_id === next.id) {
          arr[i] = {
            ...arr[i],
            install_height_feet: next.install_height_feet,
            wall_material: next.wall_material || "eifs",
          };
        }
      }
    }
    onUpdateProject({ letter_purchases: arr });
  };

  // Removing a parent should remove its children too
  const removePurchaseWithSetCleanup = (idx) => {
    const target = purchases[idx];
    if (!target) return;
    const ids = new Set([target.id]);
    // If this is a parent, also remove all its children
    purchases.forEach(p => { if (p.set_parent_id === target.id) ids.add(p.id); });
    if (!confirm(ids.size > 1
      ? `Remove this row and its ${ids.size - 1} linked set item${ids.size - 1 === 1 ? "" : "s"}?`
      : "Remove this letter row?")) return;
    onUpdateProject({ letter_purchases: purchases.filter(p => !ids.has(p.id)) });
  };

  // Null-propagating: a held row makes the subtotal unavailable, not $0.
  const purchasesTotal = purchases.reduce((s, p) => {
    if (s === null || p.__held) return null;
    const v = channelNumber(p.total_cost);
    return v === null ? null : s + v;
  }, 0);

  // Aggregate dimensional-letter cost breakdown across all dimensional rows.
  // Pulls Material / Cutting (CNC or Laser) / Paint / Backer totals from each row's fab_config.
  const dimensionalBreakdown = React.useMemo(() => {
    const acc = { material: 0, cnc: 0, laser: 0, paint: 0, backer: 0 };
    let hasAny = false;
    for (const p of purchases) {
      if (p.letter_type !== "dimensional_letters") continue;
      const fc = p.fab_config;
      if (!fc) continue;
      const qty = parseFloat(p.qty) || 0;
      if (qty <= 0) continue;
      hasAny = true;
      acc.material += (parseFloat(fc.unit_material_cost) || 0) * qty;
      const cutCostTotal = (parseFloat(fc.unit_cut_cost) || 0) * qty;
      if (fc.cutting_method === "laser") acc.laser += cutCostTotal;
      else acc.cnc += cutCostTotal;
      acc.paint += (parseFloat(fc.unit_paint_cost) || 0) * qty;
      if (p.backer_enabled && p.backer_fab_config?.unit_total_cost) {
        acc.backer += (parseFloat(p.backer_fab_config.unit_total_cost) || 0) * qty;
      }
    }
    return { ...acc, hasAny };
  }, [purchases]);

  return (
    <div className="space-y-3">
      {/* Intro / quick-add */}
      <Card className="bg-gradient-to-br from-purple-50 to-indigo-50 border-purple-200">
        <CardContent className="p-4 space-y-3">
          <div className="flex items-start gap-3">
            <div className="w-10 h-10 rounded-xl bg-purple-600 flex items-center justify-center flex-shrink-0">
              <Type className="w-5 h-5 text-white" />
            </div>
            <div className="flex-1">
              <h3 className="font-semibold text-slate-900">Letters & Logos — Fabricate or Purchase</h3>
              <p className="text-xs text-slate-600">
                Build up the cost of the signage itself — letters, logos, and dimensional pieces you either
                fabricate in-house or purchase from a vendor (separate from installation labor).
                Each line auto-creates a matching item on the Installation tab.
              </p>
            </div>
            <div className="flex gap-2">
              <Button
                onClick={() => setAiOpen(true)}
                size="sm"
                className="bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 text-white shadow-sm"
              >
                <Sparkles className="w-3.5 h-3.5 mr-1.5" /> AI Scope Writer
              </Button>
              <Link to={createPageUrl("EstimatorSettings")}>
                <Button variant="outline" size="sm" className="bg-white">
                  <Settings className="w-3.5 h-3.5 mr-1.5" /> Letter Pricing
                </Button>
              </Link>
            </div>
          </div>
          <div id="clp-add-letter-row" className="flex flex-wrap gap-2 pt-1">
            {QUICK_ADD.map(qa => (
              <button type="button"
                key={qa.type}
                onClick={() => addPurchase(qa.type)}
                className={`px-3 py-1.5 rounded-lg border text-xs font-medium transition-colors ${qa.color}`}
              >
                {qa.label}
              </button>
            ))}
            {/* Backer Panel — only visible when there's a Dimensional Letters row */}
            {hasDimensional && (
              <button type="button"
                onClick={addBackerToFirstDimensional}
                disabled={allDimensionalHaveBacker}
                title={allDimensionalHaveBacker ? "All Dimensional Letter rows already have a backer" : "Add a backer panel to the first Dimensional Letter row"}
                className={`px-3 py-1.5 rounded-lg border text-xs font-medium transition-colors ${
                  allDimensionalHaveBacker
                    ? "bg-slate-100 text-slate-400 border-slate-200 cursor-not-allowed"
                    : "bg-orange-50 hover:bg-orange-100 text-orange-700 border-orange-200"
                }`}
              >
                + Backer Panel
              </button>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Purchase rows */}
      {purchases.length === 0 ? (
        <Card className="border-2 border-dashed border-slate-300 bg-white/50">
          <CardContent className="p-10 text-center text-slate-500">
            <div className="flex items-end justify-center gap-2 mb-3 h-12 text-purple-500">
              <ArrowUp className="w-6 h-6 animate-bounce" style={{ animationDelay: "0ms" }} />
              <ArrowUp className="w-7 h-7 animate-bounce" style={{ animationDelay: "120ms" }} />
              <ArrowUp className="w-8 h-8 animate-bounce" style={{ animationDelay: "240ms" }} />
              <ArrowUp className="w-7 h-7 animate-bounce" style={{ animationDelay: "120ms" }} />
              <ArrowUp className="w-6 h-6 animate-bounce" style={{ animationDelay: "0ms" }} />
            </div>
            <p className="mb-1 font-semibold text-slate-700">Add Product</p>
            <p className="text-xs">Use the quick-add buttons above to choose a letter type.</p>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-2">
          {groupPurchasesBySet(purchases).map((group, gi) => {
            if (group.kind === "solo") {
              const p = group.purchase;
              const idx = purchases.findIndex(x => x.id === p.id);
              return (
                <div key={p.id || gi} id={idx === 0 ? "clp-letter-purchase-row" : undefined}>
                  <LetterPurchaseRow
                    index={idx}
                    purchase={p}
                    settings={settings}
                    onUpdate={(next) => updatePurchaseWithSetSync(idx, next)}
                    onRemove={() => removePurchaseWithSetCleanup(idx)}
                    onDuplicate={() => duplicatePurchase(idx)}
                    onAddToSet={addToSet}
                    fabHighlight={incompleteSet.has(p.id)}
                    issues={issues}
                  />
                </div>
              );
            }
            // Set group
            const { parent, children } = group;
            const parentIdx = purchases.findIndex(x => x.id === parent.id);
            const setSize = 1 + children.length;
            const setMembers = [parent, ...children];
            const setTotal = setMembers.some(m => m.__held) ? null
              : setMembers.reduce((s, m) => s + (channelNumber(m.total_cost) ?? 0), 0);
            return (
              <div key={parent.id || gi} className="space-y-2 bg-purple-50/40 rounded-2xl p-2 border border-purple-100">
                <LetterPurchaseRow
                  index={parentIdx}
                  purchase={parent}
                  settings={settings}
                  onUpdate={(next) => updatePurchaseWithSetSync(parentIdx, next)}
                  onRemove={() => removePurchaseWithSetCleanup(parentIdx)}
                  onDuplicate={() => duplicatePurchase(parentIdx)}
                  onAddToSet={addToSet}
                  fabHighlight={incompleteSet.has(parent.id)}
                  setRole="parent"
                  setSize={setSize}
                  issues={issues}
                />
                {children.map((c, ci) => {
                  const cidx = purchases.findIndex(x => x.id === c.id);
                  return (
                    <LetterPurchaseRow
                      key={c.id}
                      index={cidx}
                      purchase={c}
                      settings={settings}
                      onUpdate={(next) => updatePurchase(cidx, next)}
                      onRemove={() => removePurchase(cidx)}
                      onDuplicate={() => duplicatePurchase(cidx)}
                      fabHighlight={incompleteSet.has(c.id)}
                      setRole="child"
                      setSize={setSize}
                      setIndex={ci + 1}
                      issues={issues}
                    />
                  );
                })}
                <div className="flex items-center justify-end gap-3 pr-2 pt-1">
                  <span className="text-[11px] text-purple-700 flex items-center gap-1">
                    <Layers className="w-3 h-3" /> Set total ({setSize} items)
                  </span>
                  <span className="text-base font-bold tabular-nums text-purple-900">
                    {fmt(setTotal)}
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Project-level fees — Advanced Settings */}
      <Card id="clp-letter-fees" className="bg-white border-0 shadow-sm overflow-hidden">
        <button
          type="button"
          onClick={() => setFeesOpen(o => !o)}
          className="w-full flex items-center justify-between px-6 py-4 hover:bg-slate-50 transition-colors"
        >
          <div className="flex items-center gap-2">
            <Settings className="w-4 h-4 text-slate-500" />
            <span className="text-base font-semibold text-slate-900">Advanced Settings — Project Fees</span>
          </div>
          <ChevronDown className={`w-4 h-4 text-slate-500 transition-transform ${feesOpen ? "rotate-180" : ""}`} />
        </button>
        {feesOpen && (
          <CardContent className="border-t border-slate-100 pt-4">
            <div className="mb-4 flex items-start gap-2 p-3 bg-blue-50 border border-blue-200 rounded-lg">
              <Info className="w-4 h-4 text-blue-600 flex-shrink-0 mt-0.5" />
              <p className="text-xs text-blue-900">
                These fees are prefilled based on the defaults configured by your admin in the
                {" "}<Link to={createPageUrl("EstimatorSettings")} className="font-semibold underline">Settings page</Link>.
                Override them here for this estimate only.
              </p>
            </div>
            {onlyDimensional && (
              <div className="mb-3 flex items-start gap-2 p-2.5 bg-emerald-50 border border-emerald-200 rounded-lg">
                <Info className="w-4 h-4 text-emerald-600 flex-shrink-0 mt-0.5" />
                <p className="text-xs text-emerald-900">
                  Delivery / Shipping doesn't apply to dimensional lettering (fabricated in-house), so it's hidden for this estimate.
                </p>
              </div>
            )}
            <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
              {!onlyDimensional && (
                <FeeInput
                  icon={Truck}
                  label="Delivery / Shipping"
                  field="letters_delivery_fee"
                  issues={issues}
                  value={project.letters_delivery_fee}
                  onChange={(v) => onUpdateProject({ letters_delivery_fee: v })}
                />
              )}
              <FeeInput
                icon={Receipt}
                label="Other"
                field="letters_other_fee"
                issues={issues}
                value={project.letters_other_fee}
                onChange={(v) => onUpdateProject({ letters_other_fee: v })}
              />
            </div>
          </CardContent>
        )}
      </Card>

      {/* Rollup */}
      <Card className="bg-gradient-to-r from-slate-900 to-slate-800 text-white border-0">
        <CardContent className="p-4 space-y-2">
          {project.__held && (
            <p className="text-[11px] text-amber-300">
              Saved amounts (not current pricing) — fix the flagged values to reprice.
            </p>
          )}
          {/* Dimensional letter cost breakdown — Material / CNC / Laser / Paint / Backer */}
          {dimensionalBreakdown.hasAny && (
            <div className="bg-white/5 rounded-lg p-3 mb-1 space-y-1 border border-white/10">
              <p className="text-[10px] uppercase tracking-wider text-slate-400 font-semibold mb-1">
                Dimensional Letter Breakdown
              </p>
              {dimensionalBreakdown.material > 0 && (
                <BreakdownRow label="Material (sheet)" value={dimensionalBreakdown.material} />
              )}
              {dimensionalBreakdown.cnc > 0 && (
                <BreakdownRow label="CNC Routing" value={dimensionalBreakdown.cnc} />
              )}
              {dimensionalBreakdown.laser > 0 && (
                <BreakdownRow label="Laser Cutting" value={dimensionalBreakdown.laser} />
              )}
              {dimensionalBreakdown.paint > 0 && (
                <BreakdownRow label="Paint" value={dimensionalBreakdown.paint} />
              )}
              {dimensionalBreakdown.backer > 0 && (
                <BreakdownRow label="Backer Panel" value={dimensionalBreakdown.backer} />
              )}
            </div>
          )}
          <div className="flex justify-between text-sm">
            <span className="text-slate-300">Letters Subtotal</span>
            <span className="tabular-nums font-medium">{fmt(purchasesTotal)}</span>
          </div>
          {!onlyDimensional && (parseFloat(project.letters_delivery_fee) || 0) > 0 && (
            <RollupRow label="Delivery / Shipping" value={project.letters_delivery_fee} />
          )}
          {(parseFloat(project.letters_other_fee) || 0) > 0 && (
            <RollupRow label="Other" value={project.letters_other_fee} />
          )}
          <div className="border-t border-white/20 pt-2 flex justify-between">
            <span className="text-slate-300 text-sm">Subtotal w/ Fees</span>
            <span className="tabular-nums font-medium">{fmt(project.letters_subtotal)}</span>
          </div>
          {(parseFloat(project.letters_markup_percent) || 0) > 0 && (
            <div className="flex justify-between text-xs text-slate-400">
              <span>Markup ({parseFloat(project.letters_markup_percent).toFixed(1)}%)</span>
              <span className="tabular-nums">
                {fmt(Number.isFinite(project.total_letters_cost) && Number.isFinite(project.letters_subtotal)
                  ? project.total_letters_cost - project.letters_subtotal
                  : null)}
              </span>
            </div>
          )}
          <div className="border-t-2 border-white/30 pt-2 flex justify-between items-center">
            <span className="text-lg font-bold">Total Letters Cost</span>
            <span className="text-2xl font-bold tabular-nums">{fmt(project.total_letters_cost)}</span>
          </div>
        </CardContent>
      </Card>

      <div className="text-[11px] text-slate-500 flex items-start gap-1.5 px-1">
        <Info className="w-3.5 h-3.5 flex-shrink-0 mt-0.5" />
        <span>
          Letter pricing pulls from your Channel Letter Settings page. Click "Letter Pricing" above to adjust.
          The total above is added to the project Grand Total on the Summary tab.
        </span>
      </div>

      <AIScopeWriterModal open={aiOpen} onClose={() => setAiOpen(false)} onApply={applyAIPurchases} />
    </div>
  );
}

const FeeInput = ({ icon: Icon, label, value, onChange, field, issues = [] }) => {
  const fi = issuesForField(issues, field);
  const invalid = fi.length > 0;
  const id = `clp-fee-${field}`;
  return (
    <div>
      <Label className="text-xs flex items-center gap-1" htmlFor={id}>
        <Icon className="w-3 h-3 text-slate-500" />
        {label}
      </Label>
      <div className="relative mt-1">
        <span className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-400 text-sm">$</span>
        <Input
          id={id}
          type="number"
          min="0"
          step="0.01"
          value={value ?? ""}
          onChange={(e) => onChange(channelDraftValue(e.target.value))}
          className={`h-9 pl-6 ${invalid ? "border-red-500" : ""}`}
          aria-invalid={invalid || undefined}
          aria-describedby={invalid ? `${id}-issue` : undefined}
        />
      </div>
      {invalid && (
        <p id={`${id}-issue`} className="text-[10px] text-red-600 mt-0.5" role="alert">{fi[0].message}</p>
      )}
    </div>
  );
};

const RollupRow = ({ label, value }) => (
  <div className="flex justify-between text-xs text-slate-400">
    <span>{label}</span>
    <span className="tabular-nums">{fmt(value)}</span>
  </div>
);

const BreakdownRow = ({ label, value }) => (
  <div className="flex justify-between text-xs">
    <span className="text-slate-300">{label}</span>
    <span className="tabular-nums text-slate-100 font-medium">{fmt(value)}</span>
  </div>
);

import React, { useState, useRef, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import {
  Trash2, ChevronDown, ChevronRight, Zap, Copy, History, Clock,
  Type, Ruler, MoveHorizontal, Hash, Activity, AlertCircle,
} from "lucide-react";
import AppliesToMultiSelect from "./AppliesToMultiSelect";
import QuantityTiersEditor from "./QuantityTiersEditor";
import {
  CRITERIA_OPTIONS, CRITERIA_MAP,
  APPLIES_TO_LABEL, summarizeCost,
} from "./materialsConstants";
import { formatRelative, isStale } from "./materialsHelpers";

const SIZE_FIELDS = [
  { key: "cost_extra_small", label: "XS", sub: '2"-8"' },
  { key: "cost_small", label: "S", sub: '8"-12"' },
  { key: "cost_medium", label: "M", sub: '12"-24"' },
  { key: "cost_large", label: "L", sub: '24"-48"' },
  { key: "cost_extra_large", label: "XL", sub: '48"-60"' },
  { key: "cost_extra_extra_large", label: "XXL", sub: '60"+' },
];

const ICON_MAP = { Type, Ruler, MoveHorizontal, Hash };

export default function MaterialItemCard({
  item, isDirty, isNew, defaultExpanded,
  selected, onSelectChange,
  usageCount = 0,
  readOnly = false,
  onChange, onRemove, onDuplicate, onCollapse, onViewHistory,
}) {
  const [expanded, setExpanded] = useState(!!defaultExpanded || !!isNew);
  const wasExpanded = useRef(expanded);

  // Auto-save trigger when a card collapses while dirty
  useEffect(() => {
    if (wasExpanded.current && !expanded && isDirty && !readOnly) {
      onCollapse && onCollapse();
    }
    wasExpanded.current = expanded;
  }, [expanded, isDirty, readOnly, onCollapse]);

  const update = (patch) => { if (!readOnly) onChange(patch); };
  const crit = CRITERIA_MAP[item.pricing_mode];
  const CritIcon = ICON_MAP[crit?.icon] || Type;
  const appliesList = Array.isArray(item.applies_to_list) && item.applies_to_list.length > 0
    ? item.applies_to_list
    : (item.applies_to && item.applies_to !== "all" ? [item.applies_to] : []);

  const stale = isStale(item.updated_date);

  return (
    <div className={`bg-white border rounded-xl overflow-hidden transition-shadow ${
      selected ? "border-purple-400 ring-2 ring-purple-100"
        : isDirty ? "border-amber-300 shadow-sm ring-1 ring-amber-100"
        : "border-slate-200"
    }`}>
      {/* Header */}
      <div className="flex items-center gap-3 px-4 py-3 hover:bg-slate-50">
        {!readOnly && (
          <Checkbox
            checked={selected}
            onCheckedChange={(c) => onSelectChange(!!c)}
            onClick={(e) => e.stopPropagation()}
            className="flex-shrink-0"
          />
        )}

        <button
          type="button"
          className="text-slate-400 hover:text-slate-700 flex-shrink-0"
          onClick={() => setExpanded(x => !x)}
        >
          {expanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
        </button>

        <div className="flex-1 min-w-0 cursor-pointer" onClick={() => setExpanded(x => !x)}>
          <div className="flex items-center gap-2 flex-wrap">
            <span className="font-semibold text-slate-900 truncate">
              {item.item_name || <span className="text-slate-400 italic">Unnamed item</span>}
            </span>
            {crit && (
              <Badge variant="outline" className={`text-[10px] gap-1 ${crit.color}`}>
                <CritIcon className="w-2.5 h-2.5" />
                {crit.short}
              </Badge>
            )}
            {item.is_default && (
              <Badge variant="outline" className="text-[10px] bg-green-50 text-green-700 border-green-200 gap-1">
                <Zap className="w-2.5 h-2.5" /> Auto
              </Badge>
            )}
            {usageCount > 0 && (
              <Badge variant="outline" className="text-[10px] bg-slate-50 text-slate-700 border-slate-200 gap-1">
                <Activity className="w-2.5 h-2.5" />
                Used in {usageCount} project{usageCount !== 1 ? "s" : ""}
              </Badge>
            )}
            {isDirty && (
              <Badge variant="outline" className="text-[10px] bg-amber-50 text-amber-700 border-amber-200">
                Unsaved
              </Badge>
            )}
            {isNew && (
              <Badge variant="outline" className="text-[10px] bg-blue-50 text-blue-700 border-blue-200">
                New
              </Badge>
            )}
            {stale && !isNew && (
              <Badge variant="outline" className="text-[10px] bg-orange-50 text-orange-700 border-orange-200 gap-1">
                <AlertCircle className="w-2.5 h-2.5" /> Review pricing
              </Badge>
            )}
          </div>
          <div className="flex items-center gap-3 mt-1 text-xs text-slate-500 flex-wrap">
            <span className="font-medium text-slate-700">{summarizeCost(item)}</span>
            {appliesList.length > 0 ? (
              <span className="truncate">
                Applies to: {appliesList.map(v => APPLIES_TO_LABEL[v] || v).join(", ")}
              </span>
            ) : (
              <span>Applies to: All types</span>
            )}
            {item.updated_date && (
              <span className="flex items-center gap-1">
                <Clock className="w-3 h-3" />
                Updated {formatRelative(item.updated_date)}
              </span>
            )}
          </div>
        </div>

        <div className="flex items-center gap-1 flex-shrink-0">
          {item.id && (
            <Button
              size="sm" variant="ghost"
              onClick={(e) => { e.stopPropagation(); onViewHistory(); }}
              className="text-slate-500 hover:bg-slate-100 h-8 w-8 p-0"
              title="View price history"
            >
              <History className="w-4 h-4" />
            </Button>
          )}
          {!readOnly && (
            <Button
              size="sm" variant="ghost"
              onClick={(e) => { e.stopPropagation(); onDuplicate(); }}
              className="text-slate-500 hover:bg-slate-100 h-8 w-8 p-0"
              title="Duplicate item"
            >
              <Copy className="w-4 h-4" />
            </Button>
          )}
          {!readOnly && (
            <Button
              size="sm" variant="ghost"
              onClick={(e) => { e.stopPropagation(); onRemove(); }}
              className="text-red-500 hover:bg-red-50 h-8 w-8 p-0"
              title="Delete item"
            >
              <Trash2 className="w-4 h-4" />
            </Button>
          )}
        </div>
      </div>

      {/* Expanded body */}
      {expanded && (
        <div className="border-t border-slate-200 px-4 py-4 bg-slate-50/40 space-y-5">
          <section>
            <h5 className="text-[11px] font-semibold uppercase tracking-wide text-slate-500 mb-2">Identity</h5>
            <div className="grid md:grid-cols-12 gap-3">
              <div className="md:col-span-9">
                <Label className="text-xs">Item Name</Label>
                <Input
                  value={item.item_name}
                  onChange={(e) => update({ item_name: e.target.value })}
                  placeholder="e.g. 1/4 inch threaded studs"
                  disabled={readOnly}
                  className="h-9 mt-1"
                />
              </div>
              <div className="md:col-span-3">
                <Label className="text-xs">Unit</Label>
                <Input
                  value={item.unit || ""}
                  onChange={(e) => update({ unit: e.target.value })}
                  placeholder="ea, ft, box"
                  disabled={readOnly}
                  className="h-9 mt-1"
                />
              </div>
            </div>
          </section>

          <section>
            <h5 className="text-[11px] font-semibold uppercase tracking-wide text-slate-500 mb-2">Applicability</h5>
            <div className="grid md:grid-cols-12 gap-3 items-start">
              <div className="md:col-span-6">
                <Label className="text-xs">Applies To (Installation Types)</Label>
                <AppliesToMultiSelect
                  value={appliesList}
                  onChange={(list) => update({
                    applies_to_list: list,
                    applies_to: list.length === 0 ? "all" : list[0],
                  })}
                />
                <p className="text-[10px] text-slate-500 mt-1">
                  Leave empty to apply to all installation types.
                </p>
              </div>
              <div className="md:col-span-6 flex items-center gap-2 pt-5">
                <Checkbox
                  id={`auto-${item.id || "new"}`}
                  checked={item.is_default}
                  onCheckedChange={(c) => update({ is_default: !!c })}
                  disabled={readOnly}
                />
                <Label htmlFor={`auto-${item.id || "new"}`} className="text-sm cursor-pointer flex-1">
                  <div className="font-medium">Auto-attach to new line items</div>
                  <div className="text-[11px] text-slate-500">
                    When enabled, this material is automatically added to matching line items.
                  </div>
                </Label>
              </div>
            </div>
          </section>

          <section>
            <h5 className="text-[11px] font-semibold uppercase tracking-wide text-slate-500 mb-2">Pricing</h5>
            <div className="grid md:grid-cols-12 gap-3">
              <div className="md:col-span-4">
                <Label className="text-xs">Pricing Method</Label>
                <Select value={item.pricing_mode} onValueChange={(v) => update({ pricing_mode: v })} disabled={readOnly}>
                  <SelectTrigger className="h-9 mt-1"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {CRITERIA_OPTIONS.map(c => (
                      <SelectItem key={c.value} value={c.value}>{c.label}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="md:col-span-8">
                {item.pricing_mode === "per_letter_flat" && (
                  <div>
                    <Label className="text-xs">Cost per Letter ($)</Label>
                    <Input
                      type="number" step="0.01" value={item.cost_per_letter}
                      onFocus={e => e.target.select()}
                      onChange={(e) => update({ cost_per_letter: parseFloat(e.target.value) || 0 })}
                      disabled={readOnly}
                      className="h-9 mt-1 max-w-[200px]"
                    />
                  </div>
                )}

                {item.pricing_mode === "per_letter_by_size" && (
                  <div>
                    <Label className="text-xs">Cost per Letter by Size ($)</Label>
                    <div className="grid grid-cols-3 md:grid-cols-6 gap-2 mt-1">
                      {SIZE_FIELDS.map(s => (
                        <div key={s.key}>
                          <div className="text-[10px] text-slate-500 mb-0.5">
                            <span className="font-semibold">{s.label}</span> <span className="opacity-70">{s.sub}</span>
                          </div>
                          <Input
                            type="number" step="0.01" value={item[s.key]}
                            onFocus={e => e.target.select()}
                            onChange={(e) => update({ [s.key]: parseFloat(e.target.value) || 0 })}
                            disabled={readOnly}
                            className="h-9 text-sm"
                          />
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {item.pricing_mode === "per_raceway_foot" && (
                  <div>
                    <Label className="text-xs">Cost per Linear Foot of Raceway ($)</Label>
                    <Input
                      type="number" step="0.01" value={item.cost_per_foot}
                      onFocus={e => e.target.select()}
                      onChange={(e) => update({ cost_per_foot: parseFloat(e.target.value) || 0 })}
                      disabled={readOnly}
                      className="h-9 mt-1 max-w-[200px]"
                    />
                  </div>
                )}

                {item.pricing_mode === "per_project_flat" && (
                  <div>
                    <Label className="text-xs">Flat Cost per Sign ($)</Label>
                    <Input
                      type="number" step="0.01" value={item.cost_flat}
                      onFocus={e => e.target.select()}
                      onChange={(e) => update({ cost_flat: parseFloat(e.target.value) || 0 })}
                      disabled={readOnly}
                      className="h-9 mt-1 max-w-[200px]"
                    />
                  </div>
                )}
              </div>
            </div>

            <div className="mt-3">
              <QuantityTiersEditor
                tiers={item.quantity_tiers}
                onChange={(tiers) => update({ quantity_tiers: tiers })}
                disabled={readOnly}
              />
            </div>
          </section>

          <section>
            <h5 className="text-[11px] font-semibold uppercase tracking-wide text-slate-500 mb-2">Details</h5>
            <div className="grid md:grid-cols-12 gap-3">
              <div className="md:col-span-4">
                <Label className="text-xs">Supplier</Label>
                <Input
                  value={item.supplier || ""}
                  onChange={(e) => update({ supplier: e.target.value })}
                  placeholder="Vendor name"
                  disabled={readOnly}
                  className="h-9 mt-1"
                />
              </div>
              <div className="md:col-span-8">
                <Label className="text-xs">Notes</Label>
                <Input
                  value={item.notes || ""}
                  onChange={(e) => update({ notes: e.target.value })}
                  placeholder="Internal notes, SKU, alt sources..."
                  disabled={readOnly}
                  className="h-9 mt-1"
                />
              </div>
            </div>
          </section>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useMemo, useCallback } from "react";
import { ChannelLetterInstallInventory, ChannelLetterInstallation } from "@/api/gatedEntities";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { User } from "@/api/entities";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { Plus, Save, Search, Package2, X, Lock } from "lucide-react";
import MaterialItemCard from "./MaterialItemCard";
import BulkActionsBar from "./BulkActionsBar";
import BulkPriceAdjustDialog from "./BulkPriceAdjustDialog";
import PriceHistoryDialog from "./PriceHistoryDialog";
import { APPLIES_TO_GROUPS, ALL_INSTALL_TYPES, emptyMaterialItem } from "./materialsConstants";
import {
  extractPriceSnapshot, buildPriceHistoryUpdate,
  countInventoryUsage, adjustItemPricing,
} from "./materialsHelpers";

const APPLIES_TO_FILTER = [
  { value: "any", label: "All Groups" },
  ...APPLIES_TO_GROUPS,
];

// Resolve which "applies to" groups an item belongs to.
// Items with no specific applies_to_list (or legacy "all") show in EVERY type section.
const groupsForItem = (it) => {
  const list = Array.isArray(it.applies_to_list) && it.applies_to_list.length > 0
    ? it.applies_to_list
    : (it.applies_to && it.applies_to !== "all" ? [it.applies_to] : []);
  return list.length > 0 ? list : ALL_INSTALL_TYPES;
};

export default function MaterialsInventoryTab() {
  const [items, setItems] = useState([]);
  const [savedSnapshots, setSavedSnapshots] = useState({}); // id -> last saved price snapshot
  const [usageCounts, setUsageCounts] = useState({});
  const [currentUser, setCurrentUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  // Filters
  const [search, setSearch] = useState("");
  const [appliesFilter, setAppliesFilter] = useState("any");

  // State tracking
  const [dirtyIds, setDirtyIds] = useState(new Set());
  const [selectedKeys, setSelectedKeys] = useState(new Set());

  // Dialogs
  const [historyItem, setHistoryItem] = useState(null);
  const [showAdjustDialog, setShowAdjustDialog] = useState(false);

  const isAdmin = currentUser?.role === "admin";
  const readOnly = currentUser && !isAdmin;

  const keyFor = (it) => it.id || it._localKey;

  const load = useCallback(async () => {
    setLoading(true);
    const [data, user, projects] = await Promise.all([
      loadAllEntityRows({ entity: ChannelLetterInstallInventory, sort: "sort_order", label: "Channel Letter installation inventory" }),
      User.me().catch(() => null),
      loadAllEntityRows({ entity: ChannelLetterInstallation, sort: "created_date", label: "Channel Letter projects" }).catch(() => []),
    ]);
    setItems(data);
    setCurrentUser(user);
    setUsageCounts(countInventoryUsage(projects));
    // Snapshot current pricing on load (baseline for change detection)
    const snaps = {};
    for (const it of data) {
      if (it.id) snaps[it.id] = extractPriceSnapshot(it);
    }
    setSavedSnapshots(snaps);
    setDirtyIds(new Set());
    setSelectedKeys(new Set());
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const markDirty = (idx) => {
    setDirtyIds(prev => {
      const next = new Set(prev);
      next.add(idx);
      return next;
    });
  };

  const update = (idx, patch) => {
    if (readOnly) return;
    const next = [...items];
    next[idx] = { ...next[idx], ...patch };
    setItems(next);
    markDirty(idx);
  };

  const addItem = () => {
    if (readOnly) return;
    const newItem = { ...emptyMaterialItem(), _new: true, _localKey: `new-${Date.now()}` };
    const next = [...items, newItem];
    setItems(next);
    markDirty(next.length - 1);
  };

  const duplicateItem = (idx) => {
    if (readOnly) return;
    const original = items[idx];
    const { id, _new, _localKey, price_history, ...rest } = original;
    const copy = {
      ...rest,
      item_name: `${original.item_name || "Item"} (Copy)`,
      _new: true,
      _localKey: `new-${Date.now()}`,
      price_history: [],
    };
    const next = [...items, copy];
    setItems(next);
    markDirty(next.length - 1);
  };

  const removeItem = async (idx) => {
    if (readOnly) return;
    const item = items[idx];
    if (item.id) {
      if (!confirm(`Delete "${item.item_name || "this item"}"?`)) return;
      try {
        await ChannelLetterInstallInventory.delete(item.id);
      } catch (e) {
        console.error("Delete failed:", e);
        alert("Delete failed: " + (e.message || "unknown error"));
        return;
      }
    }
    const next = [...items];
    next.splice(idx, 1);
    setItems(next);
    // re-index dirty set
    const newDirty = new Set();
    dirtyIds.forEach(i => {
      if (i < idx) newDirty.add(i);
      else if (i > idx) newDirty.add(i - 1);
    });
    setDirtyIds(newDirty);
    // remove from selection
    const newSel = new Set(selectedKeys);
    newSel.delete(keyFor(item));
    setSelectedKeys(newSel);
  };

  const saveOne = async (idx) => {
    if (readOnly) return;
    try {
      const it = items[idx];
      const { _new, _localKey, id, ...payload } = it;
      // Append price history if pricing changed
      const prevSnap = id ? savedSnapshots[id] : null;
      const updatedHistory = buildPriceHistoryUpdate(payload, prevSnap, currentUser?.email);
      if (updatedHistory) payload.price_history = updatedHistory;

      let saved;
      if (id) saved = await ChannelLetterInstallInventory.update(id, payload);
      else saved = await ChannelLetterInstallInventory.create(payload);

      // Update local row with returned id and clear dirty flag
      setItems(prev => {
        const next = [...prev];
        next[idx] = { ...saved };
        return next;
      });
      setSavedSnapshots(prev => ({
        ...prev,
        [saved.id]: extractPriceSnapshot(saved),
      }));
      setDirtyIds(prev => {
        const next = new Set(prev);
        next.delete(idx);
        return next;
      });
    } catch (e) {
      console.error("Save failed:", e);
      alert("Save failed: " + (e.message || "unknown error"));
    }
  };

  const saveAll = async () => {
    if (readOnly) return;
    setSaving(true);
    const toSave = [...dirtyIds];
    for (const idx of toSave) {
      // eslint-disable-next-line no-await-in-loop
      await saveOne(idx);
    }
    setSaving(false);
  };

  // Bulk actions ----------------------------------------------------
  const toggleSelect = (it, on) => {
    const k = keyFor(it);
    setSelectedKeys(prev => {
      const next = new Set(prev);
      if (on) next.add(k); else next.delete(k);
      return next;
    });
  };

  const selectedIndices = useMemo(() => {
    const idxs = [];
    items.forEach((it, idx) => {
      if (selectedKeys.has(keyFor(it))) idxs.push(idx);
    });
    return idxs;
  }, [items, selectedKeys]);

  const clearSelection = () => setSelectedKeys(new Set());

  const bulkDuplicate = () => {
    if (readOnly || selectedIndices.length === 0) return;
    let next = [...items];
    const newDirty = new Set(dirtyIds);
    for (const idx of selectedIndices) {
      const original = next[idx];
      const { id, _new, _localKey, price_history, ...rest } = original;
      next.push({
        ...rest,
        item_name: `${original.item_name || "Item"} (Copy)`,
        _new: true,
        _localKey: `new-${Date.now()}-${idx}`,
        price_history: [],
      });
      newDirty.add(next.length - 1);
    }
    setItems(next);
    setDirtyIds(newDirty);
    clearSelection();
  };

  const bulkDelete = async () => {
    if (readOnly || selectedIndices.length === 0) return;
    if (!confirm(`Delete ${selectedIndices.length} item(s)? This cannot be undone.`)) return;
    const idsToDelete = selectedIndices.map(i => items[i].id).filter(Boolean);
    try {
      await Promise.all(idsToDelete.map(id => ChannelLetterInstallInventory.delete(id)));
    } catch (e) {
      console.error("Bulk delete failed:", e);
      alert("Delete failed: " + (e.message || "unknown error"));
      return;
    }
    // Rebuild items array
    const next = items.filter((_, idx) => !selectedIndices.includes(idx));
    setItems(next);
    setDirtyIds(new Set());
    clearSelection();
  };

  const bulkToggleAuto = (value) => {
    if (readOnly || selectedIndices.length === 0) return;
    const next = [...items];
    const newDirty = new Set(dirtyIds);
    for (const idx of selectedIndices) {
      next[idx] = { ...next[idx], is_default: value };
      newDirty.add(idx);
    }
    setItems(next);
    setDirtyIds(newDirty);
  };

  const bulkAdjustPrices = (percent) => {
    if (readOnly || selectedIndices.length === 0) return;
    const next = [...items];
    const newDirty = new Set(dirtyIds);
    for (const idx of selectedIndices) {
      const patch = adjustItemPricing(next[idx], percent);
      next[idx] = { ...next[idx], ...patch };
      newDirty.add(idx);
    }
    setItems(next);
    setDirtyIds(newDirty);
  };

  // Auto-save when a card is collapsed
  const handleCardCollapse = (idx) => {
    if (dirtyIds.has(idx) && !readOnly) {
      saveOne(idx);
    }
  };

  // Filtering -------------------------------------------------------
  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    return items
      .map((it, idx) => ({ it, idx }))
      .filter(({ it }) => {
        if (appliesFilter !== "any") {
          const groups = groupsForItem(it);
          if (!groups.includes(appliesFilter)) return false;
        }
        if (q) {
          const haystack = `${it.item_name || ""} ${it.supplier || ""} ${it.notes || ""}`.toLowerCase();
          if (!haystack.includes(q)) return false;
        }
        return true;
      });
  }, [items, search, appliesFilter]);

  // Group items by APPLIES_TO_GROUPS — items can appear in multiple groups.
  const grouped = useMemo(() => {
    const map = new Map();
    for (const { it, idx } of filtered) {
      const groups = groupsForItem(it);
      for (const g of groups) {
        if (!map.has(g)) map.set(g, []);
        map.get(g).push({ it, idx });
      }
    }
    return APPLIES_TO_GROUPS
      .map(g => ({ group: g, rows: map.get(g.value) || [] }))
      .filter(g => g.rows.length > 0);
  }, [filtered]);

  const hasFilters = search || appliesFilter !== "any";
  const clearFilters = () => { setSearch(""); setAppliesFilter("any"); };

  // Count unique filtered items (filtered may contain duplicates if regrouped)
  const uniqueFiltered = useMemo(() => {
    const seen = new Set();
    const out = [];
    for (const row of filtered) {
      const k = keyFor(row.it);
      if (seen.has(k)) continue;
      seen.add(k);
      out.push(row);
    }
    return out;
  }, [filtered]);

  const allFilteredSelected = uniqueFiltered.length > 0 && uniqueFiltered.every(({ it }) => selectedKeys.has(keyFor(it)));
  const toggleSelectAll = (on) => {
    const next = new Set(selectedKeys);
    for (const { it } of uniqueFiltered) {
      if (on) next.add(keyFor(it));
      else next.delete(keyFor(it));
    }
    setSelectedKeys(next);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20 text-slate-500">
        <div className="w-6 h-6 border-2 border-slate-300 border-t-purple-600 rounded-full animate-spin mr-3" />
        Loading materials...
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {readOnly && (
        <div className="bg-amber-50 border border-amber-200 rounded-xl p-3 flex items-center gap-2 text-sm text-amber-800">
          <Lock className="w-4 h-4" />
          <span>
            <strong>View-only mode.</strong> Only administrators can edit the materials inventory.
          </span>
        </div>
      )}

      {/* Sticky toolbar */}
      <div className="sticky top-0 z-30 bg-slate-50 -mx-2 px-2 pt-2 pb-1">
        <div className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm">
          <div className="flex flex-wrap items-center gap-3">
            <div className="flex-1 min-w-[200px] relative">
              <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <Input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search by name, supplier, or notes..."
                className="pl-9 h-10"
              />
            </div>

            <Select value={appliesFilter} onValueChange={setAppliesFilter}>
              <SelectTrigger className="h-10 w-[220px]">
                <SelectValue placeholder="All Groups" />
              </SelectTrigger>
              <SelectContent>
                {APPLIES_TO_FILTER.map(o => (
                  <SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>
                ))}
              </SelectContent>
            </Select>

            {hasFilters && (
              <Button variant="ghost" size="sm" onClick={clearFilters} className="text-slate-500">
                <X className="w-3.5 h-3.5 mr-1" /> Clear
              </Button>
            )}

            {!readOnly && (
              <div className="ml-auto flex items-center gap-2">
                <Button onClick={addItem} variant="outline" className="h-10">
                  <Plus className="w-4 h-4 mr-1" /> Add Material
                </Button>
                <Button
                  onClick={saveAll}
                  disabled={saving || dirtyIds.size === 0}
                  className="bg-purple-600 hover:bg-purple-700 text-white h-10"
                >
                  <Save className="w-4 h-4 mr-1" />
                  {saving ? "Saving..." : dirtyIds.size > 0 ? `Save ${dirtyIds.size} Change${dirtyIds.size !== 1 ? "s" : ""}` : "Saved"}
                </Button>
              </div>
            )}
          </div>

          <div className="flex items-center gap-3 mt-3 text-xs text-slate-500">
            {uniqueFiltered.length > 0 && !readOnly && (
              <label className="flex items-center gap-1.5 cursor-pointer">
                <Checkbox
                  checked={allFilteredSelected}
                  onCheckedChange={(c) => toggleSelectAll(!!c)}
                />
                <span>Select all visible</span>
              </label>
            )}
            <span><strong className="text-slate-700">{items.length}</strong> total materials</span>
            {hasFilters && (
              <span>· Showing <strong className="text-slate-700">{uniqueFiltered.length}</strong> filtered</span>
            )}
            {dirtyIds.size > 0 && (
              <Badge variant="outline" className="bg-amber-50 text-amber-700 border-amber-200 text-[10px]">
                {dirtyIds.size} unsaved — auto-saves when card is collapsed
              </Badge>
            )}
          </div>
        </div>

        <div className="mt-2">
          <BulkActionsBar
            selectedCount={selectedIndices.length}
            onClear={clearSelection}
            onDuplicate={bulkDuplicate}
            onDelete={bulkDelete}
            onToggleAuto={bulkToggleAuto}
            onAdjustPrices={() => setShowAdjustDialog(true)}
            disabled={readOnly}
          />
        </div>
      </div>

      {/* Content */}
      {items.length === 0 ? (
        <div className="bg-white border border-dashed border-slate-300 rounded-xl py-16 text-center">
          <Package2 className="w-12 h-12 text-slate-300 mx-auto mb-3" />
          <h3 className="font-semibold text-slate-700 mb-1">No materials yet</h3>
          <p className="text-sm text-slate-500 mb-4">
            Add your first material to start building your installation inventory.
          </p>
          {!readOnly && (
            <Button onClick={addItem} className="bg-purple-600 hover:bg-purple-700 text-white">
              <Plus className="w-4 h-4 mr-1" /> Add Your First Material
            </Button>
          )}
        </div>
      ) : uniqueFiltered.length === 0 ? (
        <div className="bg-white border border-slate-200 rounded-xl py-12 text-center">
          <p className="text-slate-500 mb-3">No materials match your filters.</p>
          <Button variant="outline" onClick={clearFilters}>
            <X className="w-3.5 h-3.5 mr-1" /> Clear Filters
          </Button>
        </div>
      ) : (
        <div className="space-y-6">
          {grouped.map(({ group, rows }) => (
            <div key={group.value}>
              <div className="flex items-center gap-2 mb-2 px-1">
                <Badge variant="outline" className={`${group.color} text-xs`}>
                  {group.label}
                </Badge>
                <span className="text-xs text-slate-400">
                  {rows.length} item{rows.length !== 1 ? "s" : ""}
                </span>
              </div>
              <div className="space-y-2">
                {rows.map(({ it, idx }) => (
                  <MaterialItemCard
                    key={`${group.value}-${keyFor(it)}`}
                    item={it}
                    isDirty={dirtyIds.has(idx)}
                    isNew={!!it._new}
                    defaultExpanded={!!it._new}
                    selected={selectedKeys.has(keyFor(it))}
                    onSelectChange={(on) => toggleSelect(it, on)}
                    usageCount={it.id ? (usageCounts[it.id] || 0) : 0}
                    readOnly={readOnly}
                    onChange={(patch) => update(idx, patch)}
                    onRemove={() => removeItem(idx)}
                    onDuplicate={() => duplicateItem(idx)}
                    onCollapse={() => handleCardCollapse(idx)}
                    onViewHistory={() => setHistoryItem(it)}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      )}

      <PriceHistoryDialog
        open={!!historyItem}
        onOpenChange={(o) => !o && setHistoryItem(null)}
        item={historyItem}
      />

      <BulkPriceAdjustDialog
        open={showAdjustDialog}
        onOpenChange={setShowAdjustDialog}
        selectedCount={selectedIndices.length}
        onApply={bulkAdjustPrices}
      />
    </div>
  );
}

import React, { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Plus, Trash2, Package, Loader2, ImageIcon } from "lucide-react";
import { materialFromInventory } from "./installCalculator";
import { channelDraftValue, channelNumber, issuesForField } from "./channelLetterPricingAvailability";
import { GenerateImage } from "@/api/integrations";

// Held/blank values render an em-dash instead of laundering into $0.00.
const fmt = (v) => (Number.isFinite(v) ? `$${v.toFixed(2)}` : "—");

export default function MaterialsList({ item, itemIndex = null, inventory, onChange, issues = [] }) {
  const materials = item.materials || [];
  const [generatingIdx, setGeneratingIdx] = useState(null);
  // Material issues carry index = install-item index, itemIndex = material index.
  const matIssues = (field, mi) => issuesForField(issues, field, mi, itemIndex);
  const matInvalid = (field, mi) => matIssues(field, mi).length > 0;

  // Build options of inventory items applicable to this line
  const eligibleInventory = (inventory || []).filter(inv => {
    if (inv.applies_to === "all") return true;
    return inv.applies_to === item.installation_type;
  });

  const addMaterial = (invId) => {
    const inv = inventory.find(i => i.id === invId);
    if (!inv) return;
    if (materials.some(m => m.inventory_item_id === invId)) return;
    const newMat = materialFromInventory(inv, item);
    // pull image from inventory if it exists
    if (inv.image_url) newMat.image_url = inv.image_url;
    onChange([...materials, newMat]);
  };

  const addCustomMaterial = () => {
    onChange([
      ...materials,
      {
        inventory_item_id: null,
        item_name: "Custom item",
        pricing_mode: "custom",
        unit_cost: 0,
        quantity: 1,
        total_cost: 0,
        is_custom: true,
        image_url: "",
      },
    ]);
  };

  const removeMaterial = (idx) => {
    if (!confirm(`Remove "${materials[idx]?.item_name || "this material"}"?`)) return;
    const next = [...materials];
    next.splice(idx, 1);
    onChange(next);
  };

  const updateMaterial = (idx, patch) => {
    const next = [...materials];
    next[idx] = { ...next[idx], ...patch };
    // Null-propagating: a blank/malformed input makes the row total
    // unavailable instead of laundering it to $0.
    const u = channelNumber(next[idx].unit_cost);
    const q = channelNumber(next[idx].quantity);
    next[idx].total_cost = (u === null || q === null) ? null : u * q;
    onChange(next);
  };

  const generateImageForMaterial = async (idx) => {
    const mat = materials[idx];
    const name = (mat.item_name || "").trim();
    if (!name || name === "Custom item") {
      alert("Please name the material first.");
      return;
    }
    setGeneratingIdx(idx);
    try {
      const res = await GenerateImage({
        prompt: `Photograph of "${name}" — a signage installation material or hardware item used by professional sign installers. Product is centered in the frame, full item clearly visible, neutral light background, professional product photography, sharp focus, no people, no text overlay.`,
      });
      if (res?.url) {
        updateMaterial(idx, { image_url: res.url });
      }
    } catch (e) {
      console.error("Image generation failed:", e);
      alert("Image generation failed: " + (e.message || "unknown error"));
    }
    setGeneratingIdx(null);
  };

  const totalMaterials = materials.reduce((s, m) => {
    if (s === null) return null;
    const v = channelNumber(m.total_cost);
    return v === null ? null : s + v;
  }, 0);

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Package className="w-4 h-4 text-slate-500" />
          <span className="text-sm font-medium text-slate-700">Materials</span>
          <span className="text-xs text-slate-400">({materials.length})</span>
        </div>
        <div className="flex items-center gap-2">
          <Select value="" onValueChange={addMaterial}>
            <SelectTrigger className="h-8 text-xs w-auto min-w-[160px]">
              <SelectValue placeholder="+ Add material..." />
            </SelectTrigger>
            <SelectContent>
              {eligibleInventory.length === 0 ? (
                <div className="px-2 py-1.5 text-xs text-slate-500">No inventory items match this install type</div>
              ) : eligibleInventory.map(inv => (
                <SelectItem
                  key={inv.id}
                  value={inv.id}
                  disabled={materials.some(m => m.inventory_item_id === inv.id)}
                >
                  {inv.item_name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={addCustomMaterial}
            className="h-8 text-xs"
          >
            <Plus className="w-3 h-3 mr-1" /> Custom
          </Button>
        </div>
      </div>

      {materials.length === 0 ? (
        <div className="text-xs text-slate-400 italic px-2 py-3 text-center border border-dashed border-slate-200 rounded">
          No materials added. Use the dropdown to add from inventory.
        </div>
      ) : (
        <div className="border border-slate-200 rounded-lg overflow-hidden">
          <table className="w-full text-xs">
            <thead className="bg-slate-50 text-slate-600">
              <tr>
                <th className="text-left px-2 py-1.5 font-medium w-12">Img</th>
                <th className="text-left px-2 py-1.5 font-medium">Item</th>
                <th className="text-right px-2 py-1.5 font-medium w-20">Unit $</th>
                <th className="text-right px-2 py-1.5 font-medium w-16">Qty</th>
                <th className="text-right px-2 py-1.5 font-medium w-20">Total</th>
                <th className="w-8"></th>
              </tr>
            </thead>
            <tbody>
              {materials.map((m, idx) => (
                <tr key={idx} className="border-t border-slate-100">
                  <td className="px-2 py-1">
                    {m.image_url ? (
                      <img
                        src={m.image_url}
                        alt={m.item_name}
                        className="w-10 h-10 object-contain rounded border border-slate-200 bg-white"
                      />
                    ) : (
                      <button
                        type="button"
                        onClick={() => generateImageForMaterial(idx)}
                        disabled={generatingIdx === idx}
                        title="Generate image with AI"
                        className="w-10 h-10 rounded border border-dashed border-slate-300 flex items-center justify-center text-slate-400 hover:bg-slate-50 hover:text-purple-600 disabled:opacity-50"
                      >
                        {generatingIdx === idx ? (
                          <Loader2 className="w-4 h-4 animate-spin" />
                        ) : (
                          <ImageIcon className="w-4 h-4" />
                        )}
                      </button>
                    )}
                  </td>
