// Vinyl & Graphics cost engine.
// Each item: width_inches, height_inches, quantity, vinyl_id, laminate_id, apply_print,
// labor_hours_each. Material is priced from the roll: pieces are nested across the roll
// width, so the billed material is (linear feet of roll used) x (roll cost per linear foot).

const num = (v, d = 0) => (Number.isFinite(Number(v)) ? Number(v) : d);

export function rollCostPerSqft(vinyl) {
  if (!vinyl) return 0;
  if (vinyl.pricing_mode === "per_sqft") return num(vinyl.cost_per_sqft);
  const widthFt = num(vinyl.roll_width_inches, 24) / 12;
  if (vinyl.pricing_mode === "per_linear_foot") {
    return widthFt > 0 ? num(vinyl.cost_per_linear_foot) / widthFt : 0;
  }
  const lengthFt = num(vinyl.roll_length_yards, 50) * 3;
  const area = widthFt * lengthFt;
  return area > 0 ? num(vinyl.cost_per_roll) / area : 0;
}

function materialForItem(item, vinyl) {
  const w = num(item.width_inches);
  const h = num(item.height_inches);
  const qty = num(item.quantity, 1);
  if (!w || !h || !qty) return { sqft: 0, cost: 0 };

  const rollWidth = num(vinyl?.roll_width_inches, 48);
  // Best orientation: how many fit across the roll width.
  const acrossA = Math.floor(rollWidth / w) || 0;
  const acrossB = Math.floor(rollWidth / h) || 0;
  const optionA = acrossA ? Math.ceil(qty / acrossA) * h : Infinity;
  const optionB = acrossB ? Math.ceil(qty / acrossB) * w : Infinity;
  const runInches = Math.min(optionA, optionB);

  const waste = 1 + num(vinyl?.waste_factor_percent, 15) / 100;
  const usedSqft = Number.isFinite(runInches)
    ? (runInches * rollWidth) / 144
    : ((w * h * qty) / 144) * 1.3;
  const sqft = usedSqft * waste;
  return { sqft, cost: sqft * rollCostPerSqft(vinyl) };
}

export function calcVinylProject(project, inventory) {
  const byId = new Map((inventory || []).map((v) => [v.id, v]));
  const printRate = num(project.print_cost_per_sqft, 1.5);
  const laborRate = num(project.labor_rate_per_hour, 65);

  const items = (project.items || []).map((raw) => {
    const item = { ...raw };
    const vinyl = byId.get(item.vinyl_id);
    const laminate = item.laminate_id ? byId.get(item.laminate_id) : null;

    const vinylPart = materialForItem(item, vinyl);
    const lamPart = laminate ? materialForItem(item, laminate) : { sqft: 0, cost: 0 };

    item.vinyl_sqft = vinylPart.sqft;
    item.vinyl_cost = vinylPart.cost;
    item.laminate_sqft = lamPart.sqft;
    item.laminate_cost = lamPart.cost;
    item.print_sqft = item.apply_print ? vinylPart.sqft : 0;
    item.print_cost = item.print_sqft * printRate;
    item.labor_hours = num(item.labor_hours_each) * num(item.quantity, 1);
    item.labor_cost = item.labor_hours * laborRate;
    item.item_total_cost =
      item.vinyl_cost + item.laminate_cost + item.print_cost + item.labor_cost + num(item.extra_cost);
    return item;
  });

  const sum = (fn) => items.reduce((a, i) => a + num(fn(i)), 0);

  const total_vinyl_cost = sum((i) => i.vinyl_cost);
  const total_laminate_cost = sum((i) => i.laminate_cost);
  const total_ink_cost = sum((i) => i.print_cost);
  const labor_cost = sum((i) => i.labor_cost);
  const materials = total_vinyl_cost + total_laminate_cost;
  const total_supplies_cost = (materials * num(project.supplies_percent_of_materials, 5)) / 100;

  const subtotal =
    materials + total_ink_cost + labor_cost + total_supplies_cost + num(project.extra_supplies_cost);
  const markup_amount = (subtotal * num(project.markup_percent)) / 100;

  return {
    items,
    totals: {
      total_vinyl_sqft: sum((i) => i.vinyl_sqft),
      total_laminate_sqft: sum((i) => i.laminate_sqft),
      total_print_sqft: sum((i) => i.print_sqft),
      total_vinyl_cost,
      total_laminate_cost,
      total_ink_cost,
      total_supplies_cost,
      labor_hours: sum((i) => i.labor_hours),
      labor_cost,
      subtotal,
      markup_amount,
      total_cost: subtotal + markup_amount,
    },
  };
}

// Vinyl sell-price engine wire (F-23b) — module-side glue.
//
// The shared wire (base44/shared/vinylPricingWire.ts) is intentionally
// import-free; this file is the composition root that injects the real engine
// functions and merges caller-supplied registries with the record-embedded
// engine context. Wired into customerPricing.sourceProjectEconomics for
// module_key "vinyl" — when no vinyl line carries pricing-engine config the
// resolution is a passthrough and the module sell price is returned verbatim
// (zero regression).
//
// Registry context (`pricingContext`) is OPTIONAL today: config embedded on
// the record/items (item pricing fields, engine_pricing blocks, embedded
// templates/tier rules) resolves without any entity reads. Callers that have
// PricingTierMatrix / PricingTemplate / GlobalPricingTier / MarkupTier rows
// loaded may pass them as { tierRules|tier_rules, templates, tiers,
// customerTier|customer_tier, defaultMarkupPct|default_markup_pct, now } to
// unlock registry-backed tier/template references.

import { pricePart, matrixRowsToRules } from "../../../../base44/shared/pricingEngine.ts";
import { resolveTemplatePrice, templatePartDescriptor } from "../../../../base44/shared/pricingTemplateModel.ts";
import {
  resolveVinylSellPricing,
  vinylConfigScan,
  vinylPricingContextOf,
} from "../../../../base44/shared/vinylPricingWire.ts";

const ENGINE = Object.freeze({ pricePart, resolveTemplatePrice, templatePartDescriptor });

/**
 * Full resolution — engine-priced sell for config-carrying vinyl lines.
 * Never throws: malformed input/config degrades to a passthrough result.
 *
 * @param {object} record       VinylProject-like record
 * @param {object} opts
 * @param {number} opts.baselineSell  module sell price (record.total_cost)
 * @param {number} [opts.internalCost] module internal cost (record.subtotal)
 * @param {object} [opts.pricingContext] caller-loaded registries (optional)
 * @param {*}      [opts.now]    effective-window override (tests)
 * @returns {object} resolveVinylSellPricing result ({applied, customer_price,
 *          passthrough, lines, chain, warnings, ...})
 */
export function resolveVinylEngineSell(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  try {
    const caller = pricingContext && typeof pricingContext === "object" ? { ...pricingContext } : {};
    // Normalize caller chart rows through the engine's entity adapter so
    // PricingTierMatrix spellings (unit_breaks aliases, status windows) resolve
    // exactly like the pricing admin path.
    const rawRules = caller.tierRules ?? caller.tier_rules ?? caller.tier_matrix;
    if (Array.isArray(rawRules) && rawRules.length) {
      caller.tierRules = matrixRowsToRules(rawRules, { now: caller.now ?? now });
    }
    const context = vinylPricingContextOf(record, caller);
    return resolveVinylSellPricing({ record, baselineSell, internalCost, context, engine: ENGINE, now });
  } catch {
    // The sell-price seam must never break estimate rendering — a malformed
    // record or config degrades to the module baseline, not an exception.
    return { applied: false, passthrough: true, reason: "no_engine", customer_price: baselineSell, warnings: [] };
  }
}

/**
 * Seam helper — engine-owned economics for a vinyl source record.
 * Returns null when no vinyl line carries pricing config (the caller then
 * keeps today's numbers byte-identically); when config resolves the engine
 * owns the sell side — including over a legacy saved customer_pricing
 * snapshot (parity with the F-23a channel wire).
 */
export function vinylEngineEconomics(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  const res = resolveVinylEngineSell(record, { baselineSell, internalCost, pricingContext, now });
  return res && res.applied === true
    ? { internalCost, customerPrice: res.customer_price, resolution: res }
    : null;
}

/**
 * Convenience — the customer-facing sell price for a vinyl source record.
 * Returns the engine total when config resolves, else `baselineSell` verbatim
 * (=== passthrough; the byte-identical zero-regression path).
 */
export function vinylEngineCustomerPrice(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  const res = resolveVinylEngineSell(record, { baselineSell, internalCost, pricingContext, now });
  return res && res.applied === true ? res.customer_price : baselineSell;
}

/**
 * Detection only — does any vinyl line on this record carry pricing-engine
 * config? Useful for badges/tests without running the full resolution.
 */
export function vinylHasEnginePricing(record) {
  try {
    return vinylConfigScan(record).configured === true;
  } catch {
    return false;
  }
}

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;

// ---------- strict priced-input resolution (pricing-availability hardening) --
// Finite number or null. Accepts real numbers and trimmed numeric strings;
// rejects "", "abc", Infinity, NaN, hex/octal strings, null, undefined, objects.
// `Number()` alone would accept "0x10" → 16 and launder it silently.
export const paintStrictNumber = (v) => {
  if (typeof v === "number") return Number.isFinite(v) ? v : null;
  if (typeof v === "string") {
    const t = v.trim();
    if (t === "") return null;
    if (!/^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(t)) return null;
    const n = Number(t);
    return Number.isFinite(n) ? n : null;
  }
  return null;
};

// A Settings value that was actually recorded — absent rows/blank text fall
// back to the module default by design (see moduleSettingDefaults).
export const paintSettingRecorded = (settings, key) => {
  const v = settings?.[key];
  return v !== undefined && v !== null && !(typeof v === "string" && v.trim() === "");
};

// Strict settings read: a recorded finite value is honored verbatim — an
// explicit 0 stays 0 where the key allows it (the old `num(x,d)||d` revived
// the default and made a deliberate $0 impossible). Absent/blank/malformed or
// out-of-range values resolve the fallback exactly like before; the
// availability layer flags every recorded-but-unusable value separately.
//   positive: true  → value must be > 0 (coverage, ratios that are the paint
//                     itself, waste multiplier, letter perimeter factor)
//   positive: false → value must be >= 0 (rates, multipliers, hours, floors,
//                     costs — an explicit 0 is a legitimate free/zero amount)
export const paintSettingNumber = (settings, key, fallback, { positive = false } = {}) => {
  if (!paintSettingRecorded(settings, key)) return fallback;
  const n = paintStrictNumber(settings[key]);
  if (n === null) return fallback;
  if (positive ? n <= 0 : n < 0) return fallback;
  return n;
};

export const PAINT_THICKNESSES = [
  "1/16", "1/8", "3/16", "1/4", "3/8", "1/2", "5/8", "3/4", "7/8", "1",
  "1-1/8", "1-1/4", "1-3/8", "1-1/2", "1-5/8", "1-3/4", "1-7/8", "2",
  "2-1/4", "2-1/2", "2-3/4", "3", "3-1/4", "3-1/2", "3-3/4", "4",
];

export function parseImperialFraction(value) {
  if (typeof value !== "string") return num(value);
  let text = value.trim();
  if (!text) return 0;
  let total = 0;
  const wholeAndFraction = text.split("-");
  if (wholeAndFraction.length === 2) {
    total += num(wholeAndFraction[0]);
    text = wholeAndFraction[1];
  } else {
    text = wholeAndFraction[0];
  }
  const parts = text.split("/");
  if (parts.length === 2) {
    const denominator = num(parts[1]);
    if (denominator) total += num(parts[0]) / denominator;
  } else {
    total += num(text);
  }
  return total;
}

// Strict sibling of parseImperialFraction — same grammar ("a", "a/b",
// "a-b/c"), but malformed text resolves null instead of silently 0 so the
// availability layer can flag it ("-1" laundered to +1 and "1/0" to 0 before).
export function paintThicknessNumber(value) {
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value !== "string") return null;
  let text = value.trim();
  if (!text) return null;
  let total = 0;
  const wholeAndFraction = text.split("-");
  if (wholeAndFraction.length === 2) {
    const whole = paintStrictNumber(wholeAndFraction[0]);
    if (whole === null) return null;
    total += whole;
    text = wholeAndFraction[1];
  } else if (wholeAndFraction.length > 2) {
    return null;
  } else {
    text = wholeAndFraction[0];
  }
  const parts = text.split("/");
  if (parts.length === 2) {
    const numerator = paintStrictNumber(parts[0]);
    const denominator = paintStrictNumber(parts[1]);
    if (numerator === null || denominator === null || denominator === 0) return null;
    total += numerator / denominator;
  } else if (parts.length === 1) {
    const n = paintStrictNumber(text);
    if (n === null) return null;
    total += n;
  } else {
    return null;
  }
  return Number.isFinite(total) ? total : null;
}

function parseTiers(raw) {
  if (Array.isArray(raw)) return raw;
  try {
    const parsed = JSON.parse(raw || "[]");
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function laborTierMultiplier(settings, itemType, quantity) {
  const settingKey = itemType === "panel"
    ? "panel_labor_tiers"
    : itemType === "complex_shapes"
      ? "complex_shapes_labor_tiers"
      : itemType === "lettering"
        ? "lettering_labor_tiers"
        : "";
  if (!settingKey) return 1;
  const tiers = parseTiers(settings?.[settingKey]);
  const qty = num(quantity, 1);
  const tier = tiers.find((row) => qty >= num(row.min_quantity) && qty <= num(row.max_quantity));
  return tier ? num(tier.labor_multiplier, 1) : 1;
}

function costPerGallon(cost, unit) {
  const unitFactors = { oz: 128, pint: 8, quart: 4, liter: 3.78541, gallon: 1 };
  const factor = unitFactors[unit];
  return factor ? num(cost) * factor : 0;
}

export function liquidPaintRatePerSqft(settings = {}) {
  const paintCost = costPerGallon(paintSettingNumber(settings, "paint_cost_per_unit", 0), settings.paint_unit);
  const hardenerCost = costPerGallon(paintSettingNumber(settings, "hardener_cost_per_unit", 0), settings.hardener_unit);
  const reducerCost = costPerGallon(paintSettingNumber(settings, "reducer_cost_per_unit", 0), settings.reducer_unit);
  const paintRatio = paintSettingNumber(settings, "paint_mix_ratio", 3, { positive: true });
  const hardenerRatio = paintSettingNumber(settings, "hardener_mix_ratio", 1);
  const reducerRatio = paintSettingNumber(settings, "reducer_mix_ratio", 1);
  const totalRatio = paintRatio + hardenerRatio + reducerRatio;
  const mixCost = totalRatio > 0
    ? (paintCost / totalRatio * paintRatio) + (hardenerCost / totalRatio * hardenerRatio) + (reducerCost / totalRatio * reducerRatio)
    : 0;
  // Coverage defaults to the canonical 350 sq ft/gal here too — the old ||1
  // fallback priced mixCost/1 (≈350x too high) when the setting was unset.
  const coverage = paintSettingNumber(settings, "mixed_paint_coverage_sqft_per_gallon", 350, { positive: true });
  return coverage > 0 ? mixCost / coverage : 0;
}

export function autoPaintMaskSqft(item = {}) {
  if (!(num(item.length) > 0 && num(item.width) > 0)) return 0;
  let faceArea = 0;
  if (item.item_type === "lettering") {
    const letterHeight = num(item.width);
    const letterCount = num(item.length);
    faceArea = (letterHeight ** 2 * 0.8 * letterCount) / 144;
  } else {
    faceArea = num(item.length) * num(item.width) / 144;
  }
  return item.paint_sides === "both_sides" ? faceArea * 2 : faceArea;
}

export function normalizePaintingItem(item = {}) {
  // Remote expressed the post-spread normalization as duplicate literal keys
  // (last wins). Post-construction assignment keeps the same semantics, the
  // same key order, and a warning-free bundle.
  const normalized = {
    item_type: "panel",
    description: "",
    thickness: "1/2",
    length: 0,
    width: 0,
    quantity: 1,
    edge_complexity_multiplier: 1,
    paint_sides: "one_side",
    paint_colors: [""],
    letter_size: "normal",
    paint_mask_sqft: 0,
    base_supplies_cost: 0,
    fixed_waste_gallons: 0,
    supplies_cost: 0,
    paint_cost: 0,
    paint_gallons: 0,
    labor_hours: 0,
    labor_cost: 0,
    ...item,
  };
  normalized.paint_colors = Array.isArray(item.paint_colors) ? item.paint_colors : [];
  normalized.paint_sides = item.paint_sides === "none" ? "one_side" : (item.paint_sides || "one_side");
  return normalized;
}

export function calculatePaintingItem(rawItem, settings = {}, liquidRate = 0, projectPaintSuppliesRate = 0) {
  const item = normalizePaintingItem(rawItem);
  const perimFactor = paintSettingNumber(settings, "letter_perimeter_factor", 3.5, { positive: true });
  const thickness = parseImperialFraction(item.thickness);
  let paintableSqFt = 0;

  if (item.item_type === "panel" && num(item.length) > 0 && num(item.width) > 0) {
    const faceArea = num(item.length) * num(item.width) / 144;
    const perimeterInches = 2 * (num(item.length) + num(item.width));
    const edgeArea = thickness > 0 ? perimeterInches * thickness / 144 : 0;
    paintableSqFt = item.paint_sides === "both_sides" ? faceArea * 2 + edgeArea : faceArea + edgeArea;
  } else if (item.item_type === "lettering" && num(item.width) > 0 && num(item.length) > 0 && thickness > 0) {
    const letterHeight = num(item.width);
    const letterCount = num(item.length);
    const faceArea = (letterHeight ** 2 * 0.8 * letterCount) / 144;
    const perimeterInches = letterHeight * perimFactor * letterCount;
    const edgeArea = perimeterInches * thickness / 144;
    paintableSqFt = item.paint_sides === "both_sides" ? faceArea * 2 + edgeArea : faceArea + edgeArea;
  } else if (item.item_type === "complex_shapes" && num(item.length) > 0 && num(item.width) > 0 && thickness > 0) {
    const faceArea = num(item.length) * num(item.width) / 144;
    const perimeterInches = 2 * (num(item.length) + num(item.width));
    const edgeArea = perimeterInches * thickness * num(item.edge_complexity_multiplier, 1) / 144;
    paintableSqFt = item.paint_sides === "both_sides" ? faceArea * 2 + edgeArea : faceArea + edgeArea;
  }

  const paintMaskMaterialRate = paintSettingNumber(settings, "paint_mask_rate_per_sqft", 0.75);
  const paintMaskMachineRate = paintSettingNumber(settings, "paint_mask_machine_cutting_rate_per_sqft", 0.10);
  // Preserve SignEstimate Pro behavior exactly: item cost math uses the stored
  // color-array length. Blank entries are only removed when the project is saved.
  const numColors = (item.paint_colors || []).length;
  let paintMaskCost = 0;
  if (numColors > 1 && num(item.paint_mask_sqft) > 0) {
    paintMaskCost = num(item.paint_mask_sqft) * (paintMaskMaterialRate + paintMaskMachineRate) * (numColors - 1);
  }

  let liquidPaintCost = 0;
  let paintApplicationSuppliesCost = 0;
  let paintGallons = 0;
  if (numColors > 0) {
    const wasteMultiplier = paintSettingNumber(settings, "paint_waste_multiplier", 1.25, { positive: true });
    const coverage = paintSettingNumber(settings, "mixed_paint_coverage_sqft_per_gallon", 350, { positive: true });
    paintApplicationSuppliesCost = paintableSqFt * num(projectPaintSuppliesRate) * numColors;
    if (liquidRate > 0) liquidPaintCost = paintableSqFt * liquidRate * wasteMultiplier * numColors;
    paintGallons = paintableSqFt * wasteMultiplier * numColors / coverage;
  }

  const itemFixedWasteGallons = num(item.fixed_waste_gallons);
  paintGallons += itemFixedWasteGallons;
  const coverage = paintSettingNumber(settings, "mixed_paint_coverage_sqft_per_gallon", 350, { positive: true });
  liquidPaintCost += itemFixedWasteGallons * liquidRate * coverage;
  const liquidPaintAndSuppliesCost = paintApplicationSuppliesCost + liquidPaintCost + num(item.base_supplies_cost);

  // Positive-required: the mask-labor terms below divide by this rate, so an
  // explicit 0 can never mean "free labor" here — it resolves the default and
  // the availability layer flags it.
  const laborRate = paintSettingNumber(settings, "default_labor_rate", 60, { positive: true });
  const baseHoursPerSqFt = paintSettingNumber(settings, "base_labor_hours_per_sqft", 0.05);
  const complexityMap = {
    extra_small: "complex",
    small: "complex",
    normal: "moderate",
    medium: "moderate",
    large: "simple",
    extra_large: "simple",
  };
  const itemComplexity = item.item_type === "lettering" ? complexityMap[item.letter_size] || "moderate" : "moderate";
  const complexityMultipliers = {
    simple: paintSettingNumber(settings, "simple_complexity_multiplier", 0.7),
    moderate: paintSettingNumber(settings, "moderate_complexity_multiplier", 1),
    complex: paintSettingNumber(settings, "complex_complexity_multiplier", 1.5),
  };
  const paintMultipliers = {
    one_side: paintSettingNumber(settings, "one_side_paint_multiplier", 0.8),
    both_sides: paintSettingNumber(settings, "both_sides_paint_multiplier", 1),
  };
  const additionalColorMultiplier = paintSettingNumber(settings, "additional_color_multiplier", 0.3);

  let baseHours = paintableSqFt * baseHoursPerSqFt * (complexityMultipliers[itemComplexity] || 1) * (paintMultipliers[item.paint_sides] || 1);
  if (numColors > 1) baseHours *= 1 + (numColors - 1) * additionalColorMultiplier;

  const maskApplicationLaborRate = paintSettingNumber(settings, "paint_mask_application_labor_rate_per_sqft", 0.25);
  const maskCuttingLaborRate = paintSettingNumber(settings, "paint_mask_cutting_labor_rate_per_sqft", 0.15);
  if (numColors > 1 && num(item.paint_mask_sqft) > 0) {
    baseHours += (num(item.paint_mask_sqft) * maskApplicationLaborRate * (numColors - 1) / laborRate)
      + (num(item.paint_mask_sqft) * maskCuttingLaborRate * (numColors - 1) / laborRate);
  }

  const qty = item.item_type === "lettering" ? 1 : Math.max(num(item.quantity, 1), 1);
  const discountedLaborHours = baseHours * laborTierMultiplier(settings, item.item_type, qty);
  const laborCost = discountedLaborHours * laborRate * qty;

  return {
    ...item,
    quantity: qty,
    supplies_cost: paintMaskCost * qty,
    paint_cost: liquidPaintAndSuppliesCost * qty,
    paint_gallons: paintGallons * qty,
    labor_hours: discountedLaborHours * qty,
    labor_cost: laborCost,
    paintable_sqft: paintableSqFt,
  };
}

export function calculatePaintingProject(project = {}, settings = {}) {
  const liquidRate = liquidPaintRatePerSqft(settings);
  const projectSuppliesRate = paintSettingNumber(
    project,
    "paint_supplies_per_sqft",
    paintSettingNumber(settings, "default_paint_supplies_per_sqft", 1.25)
  );
  const items = (project.items || []).map((item) => calculatePaintingItem(item, settings, liquidRate, projectSuppliesRate));

  const totalPaintMask = items.reduce((sum, item) => sum + num(item.supplies_cost), 0);
  let totalLiquidPaintAndSupplies = items.reduce((sum, item) => sum + num(item.paint_cost), 0);
  const totalItemLaborCost = items.reduce((sum, item) => sum + num(item.labor_cost), 0);
  let totalPaintGallons = items.reduce((sum, item) => sum + num(item.paint_gallons), 0);

  const globalFixedWasteGallons = paintSettingNumber(settings, "fixed_paint_waste_gallons", 0);
  totalPaintGallons += globalFixedWasteGallons;
  const coverage = paintSettingNumber(settings, "mixed_paint_coverage_sqft_per_gallon", 350, { positive: true });
  totalLiquidPaintAndSupplies += globalFixedWasteGallons * liquidRate * coverage;

  const itemFixedWaste = items.reduce((sum, item) => sum + num(item.fixed_waste_gallons), 0);
  const numberOfMixes = Math.ceil(totalPaintGallons);
  const mixingHours = numberOfMixes * paintSettingNumber(settings, "paint_mixing_labor_hours", 0.25);
  const setupHours = paintSettingNumber(settings, "setup_time_labor_hours", 0.5);

  const uniqueColors = new Set();
  items.forEach((item) => (item.paint_colors || []).forEach((color) => {
    const normalized = String(color || "").trim().toLowerCase();
    if (normalized) uniqueColors.add(normalized);
  }));
  const uniqueColorCount = uniqueColors.size;
  const totalColorChangeHours = uniqueColorCount > 1
    ? (uniqueColorCount - 1) * paintSettingNumber(settings, "color_change_setup_hours", 0.25)
    : 0;
  const totalPaintGunCleaningHours = uniqueColorCount > 0
    ? uniqueColorCount * paintSettingNumber(settings, "paint_gun_cleaning_hours", 0.15)
    : 0;
  const laborRate = paintSettingNumber(settings, "default_labor_rate", 60, { positive: true });
  const fixedLaborCost = (mixingHours + setupHours + totalColorChangeHours + totalPaintGunCleaningHours) * laborRate;
  let totalLabor = totalItemLaborCost + fixedLaborCost;
  const totalLaborHours = items.reduce((sum, item) => sum + num(item.labor_hours), 0)
    + mixingHours + setupHours + totalColorChangeHours + totalPaintGunCleaningHours;

  const minLaborHours = paintSettingNumber(settings, "min_labor_hours", 0);
  const minPaintCost = paintSettingNumber(settings, "min_paint_cost", 0);
  if (totalLaborHours > 0 && totalLaborHours < minLaborHours) totalLabor = minLaborHours * laborRate;
  if (totalLiquidPaintAndSupplies > 0 && totalLiquidPaintAndSupplies < minPaintCost) totalLiquidPaintAndSupplies = minPaintCost;

  const totalCost = totalPaintMask + totalLiquidPaintAndSupplies + totalLabor;
  return {
    items,
    liquidPaintRate: liquidRate,
    totals: {
      total_paint_mask_cost: totalPaintMask,
      total_liquid_paint_and_supplies_cost: totalLiquidPaintAndSupplies,
      total_labor_cost: totalLabor,
      total_labor_hours: totalLaborHours,
      total_paint_gallons: totalPaintGallons,
      number_of_mixes: numberOfMixes,
      mixing_hours: mixingHours,
      setup_hours: setupHours,
      unique_color_count: uniqueColorCount,
      color_change_hours: totalColorChangeHours,
      gun_cleaning_hours: totalPaintGunCleaningHours,
      fixed_waste_gallons: globalFixedWasteGallons + itemFixedWaste,
      total_cost: totalCost,
    },
  };
}

// Painting pricing-availability layer.
//
// Wraps calculatePaintingProject with strict finite-number input validation so
// a missing, malformed, or unusable pricing input can no longer silently
// become $0, a hidden default, or a dropped item edge. Mirrors the landed
// Foundation/Vinyl hardening convention:
//   - strict parsers (paintStrictNumber / paintSettingNumber / paintThicknessNumber,
//     owned by paintCalc so the calculator and the scanner resolve identically)
//   - structured issue records { kind, index, itemIndex, field, code, message, hold }
//   - Painting has no catalog entities — the shared Settings rows are the
//     priced surface, so settings issues are kind "paint_catalog" and hold the
//     whole project calc; authored item/project-field issues hold the affected
//     item's derived numbers and every aggregate those numbers feed.
//   - explicit 0 stays valid where the calculator treats it as a real
//     free/zero amount (rates, multipliers, hours, floors, costs); 0 is
//     invalid where the math divides or needs a real magnitude (coverage, the
//     paint mix ratio, the waste multiplier, the labor rate divisor, the
//     letter perimeter factor).
//   - raw rows are never mutated — the calculator reads the original records
//     exactly as PaintingEstimator has always passed them.
//
// Valid inputs take the exact same code path as before: the calc object the
// page receives for a clean project is bit-identical to today's result (plus
// __held / pricingUnavailable / issues metadata flags).

import {
  calculatePaintingProject,
  paintSettingNumber,
  paintSettingRecorded,
  paintStrictNumber,
  paintThicknessNumber,
} from "./paintCalc";

// ---------- issue records ----------
const issue = (kind, { index = null, itemIndex = null, field, code, message, hold }) => ({
  kind, index, itemIndex, field, code, message, hold,
});

// ---------- settings scan ----------
// Every Settings row the calculator prices from. [key, human, positive]
// positive: true  → recorded value must be > 0
// positive: false → recorded value must be finite and >= 0
const PRICED_SETTINGS = [
  ["default_labor_rate", "default labor rate ($/hr)", true],
  ["min_labor_hours", "minimum labor hours floor", false],
  ["min_paint_cost", "minimum paint cost floor", false],
  ["default_paint_supplies_per_sqft", "default paint supplies per sq ft", false],
  ["paint_cost_per_unit", "paint cost per unit", false],
  ["hardener_cost_per_unit", "hardener cost per unit", false],
  ["reducer_cost_per_unit", "reducer cost per unit", false],
  ["paint_mix_ratio", "paint mix ratio", true],
  ["hardener_mix_ratio", "hardener mix ratio", false],
  ["reducer_mix_ratio", "reducer mix ratio", false],
  ["mixed_paint_coverage_sqft_per_gallon", "mixed paint coverage (sq ft/gallon)", true],
  ["paint_waste_multiplier", "paint waste multiplier", true],
  ["fixed_paint_waste_gallons", "fixed paint waste (gallons)", false],
  ["paint_mask_rate_per_sqft", "paint mask material rate per sq ft", false],
  ["paint_mask_machine_cutting_rate_per_sqft", "paint mask machine cutting rate per sq ft", false],
  ["paint_mask_application_labor_rate_per_sqft", "paint mask application labor rate per sq ft", false],
  ["paint_mask_cutting_labor_rate_per_sqft", "paint mask cutting labor rate per sq ft", false],
  ["base_labor_hours_per_sqft", "base labor hours per sq ft", false],
  ["setup_time_labor_hours", "setup time (hours)", false],
  ["paint_mixing_labor_hours", "paint mixing labor hours per mix", false],
  ["color_change_setup_hours", "color change setup hours", false],
  ["paint_gun_cleaning_hours", "paint gun cleaning hours", false],
  ["one_side_paint_multiplier", "one-side paint multiplier", false],
  ["both_sides_paint_multiplier", "both-sides paint multiplier", false],
  ["additional_color_multiplier", "additional color multiplier", false],
  ["simple_complexity_multiplier", "simple complexity multiplier", false],
  ["moderate_complexity_multiplier", "moderate complexity multiplier", false],
  ["complex_complexity_multiplier", "complex complexity multiplier", false],
  ["letter_perimeter_factor", "letter perimeter factor", true],
];

const PAINT_UNITS = ["oz", "pint", "quart", "liter", "gallon"];
const TIER_SETTINGS = [
  ["panel_labor_tiers", "panel labor tiers"],
  ["complex_shapes_labor_tiers", "complex shape labor tiers"],
  ["lettering_labor_tiers", "lettering labor tiers"],
];

// Settings rows the calc prices from. Only recorded values can be broken —
// an absent row falls back to the documented module default by design, so it
// is never an issue. Every settings issue holds the whole project calc.
export function paintSettingIssues(settings = {}) {
  const issues = [];
  const add = (field, code, message) =>
    issues.push(issue("paint_catalog", { field, code, message, hold: "project" }));

  for (const [key, human, positive] of PRICED_SETTINGS) {
    if (!paintSettingRecorded(settings, key)) continue;
    const n = paintStrictNumber(settings[key]);
    if (n === null || (positive ? n <= 0 : n < 0)) {
      add(key, "paint_setting_unavailable",
        `Setting ${key}: record a finite, ${positive ? "positive" : "nonnegative"} ${human} in Painting Settings — the stored value cannot price this estimate`);
    }
  }

  // Liquid unit selectors — a recorded-but-unsupported unit resolves 0 in
  // costPerGallon (silently free); a missing unit next to a priced component
  // does the same.
  for (const [costKey, unitKey, human] of [
    ["paint_cost_per_unit", "paint_unit", "paint"],
    ["hardener_cost_per_unit", "hardener_unit", "hardener"],
    ["reducer_cost_per_unit", "reducer_unit", "reducer"],
  ]) {
    const unitRecorded = paintSettingRecorded(settings, unitKey);
    const unitValid = PAINT_UNITS.includes(settings?.[unitKey]);
    if (unitRecorded && !unitValid) {
      add(unitKey, "paint_liquid_unit_unavailable",
        `Setting ${unitKey}: select a supported ${human} unit (oz / pint / quart / liter / gallon) in Painting Settings`);
    } else if (!unitValid && (paintStrictNumber(settings?.[costKey]) ?? 0) > 0) {
      add(unitKey, "paint_liquid_unit_unavailable",
        `Setting ${unitKey}: set a ${human} unit — a recorded ${costKey} prices as $0 without one`);
    }
  }

  // Labor tier tables are JSON arrays of {min_quantity, max_quantity,
  // labor_multiplier}. Malformed JSON silently disables the whole table;
  // malformed row fields silently dead-window the tier or reprice it.
  for (const [key, human] of TIER_SETTINGS) {
    if (!paintSettingRecorded(settings, key)) continue;
    const raw = settings[key];
    let tiers = raw;
    if (!Array.isArray(tiers)) {
      try {
        const parsed = JSON.parse(raw || "[]");
        tiers = Array.isArray(parsed) ? parsed : null;
      } catch {
        tiers = null;
      }
    }
    if (tiers === null) {
      add(key, "paint_labor_tiers_unavailable",
        `Setting ${key}: the ${human} table is not a valid JSON array — repair it in Painting Settings or quantity discounts price as 1x`);
      continue;
    }
    tiers.forEach((row, rowIdx) => {
      const where = `Setting ${key} row ${rowIdx + 1}`;
      for (const [field, human2] of [["min_quantity", "minimum quantity"], ["max_quantity", "maximum quantity"]]) {
        if (row?.[field] !== undefined && row?.[field] !== null
          && (paintStrictNumber(row[field]) === null || paintStrictNumber(row[field]) < 0)) {
          add(key, "paint_labor_tier_row_unavailable",
            `${where}: record a finite, nonnegative ${human2} — the stored value dead-windows this tier`);
        }
      }
      if (row?.labor_multiplier !== undefined && row?.labor_multiplier !== null
        && (paintStrictNumber(row.labor_multiplier) === null || paintStrictNumber(row.labor_multiplier) < 0)) {
        add(key, "paint_labor_tier_row_unavailable",
          `${where}: record a finite, nonnegative labor multiplier — the stored value cannot price this tier`);
      }
    });
  }

  return issues;
}

// ---------- item-level scan ----------
// Consumed fields on each paint item. Issues hold the item's derived numbers
// (hold "item") — totals re-derive null because they sum held items.
const LETTER_SIZES = ["extra_small", "small", "normal", "medium", "large", "extra_large"];
const PRESENT = (v) => v !== undefined && v !== null;
// For this module a cleared stored value is malformed input, not an absent
// one: paintCalc's num("") launders to 0 / a clamp to 1 silently.
const nonnegField = (v) => paintStrictNumber(v) !== null && paintStrictNumber(v) >= 0;

export function paintItemIssues(rawItem = {}, index = 0) {
  const issues = [];
  const label = `Item ${index + 1}${rawItem?.description ? ` "${rawItem.description}"` : ""}`;
  const add = (field, code, message) =>
    issues.push(issue("paint", { index, itemIndex: index, field, code, message: `${label}: ${message}`, hold: "item" }));

  // item_type — every geometry branch keys on it; anything else prices a
  // silent $0 item.
  if (PRESENT(rawItem?.item_type) && !["panel", "lettering", "complex_shapes"].includes(rawItem.item_type)) {
    add("item_type", "paint_item_type_unavailable",
      "select Panel, Lettering, or Complex Shape — the stored type prices as $0 silently");
  }
  const effectiveType = rawItem?.item_type || "panel";

  // thickness — the strict imperial parse: malformed text used to vanish into
  // 0 (edge area silently dropped; "-1" even laundered to +1). Panel math has
  // an explicit edge-less branch so a real 0 is tolerated there; lettering
  // and complex shapes price nothing at all without a positive thickness.
  if (rawItem?.thickness !== undefined) {
    const t = paintThicknessNumber(rawItem.thickness);
    if (t === null || t < 0) {
      add("thickness", "paint_thickness_unavailable",
        "record a usable thickness (inches, e.g. 1/2 or 1-1/4) — the stored value silently drops edge pricing");
    } else if (t === 0 && effectiveType !== "panel") {
      add("thickness", "paint_thickness_unavailable",
        "record a positive thickness — lettering and complex shapes price nothing at 0\"");
    }
  }

  // length / width — every branch gates > 0; blank, zero, negative or
  // malformed dimensions silently collapse the item's paint and labor.
  for (const field of ["length", "width"]) {
    const n = paintStrictNumber(rawItem?.[field]);
    if (n === null || n <= 0) {
      add(field, "paint_dimension_unavailable",
        `record a positive, finite ${field === "length" ? (effectiveType === "lettering" ? "letter count" : "length") : (effectiveType === "lettering" ? "letter height" : "width")} (inches) — a blank or zero dimension prices the item as $0 silently`);
    }
  }

  // quantity — lettering forces 1 by design; other types clamp <1 to 1 in the
  // math, so a recorded 0/blank/malformed value silently repriced as one.
  if (effectiveType !== "lettering" && PRESENT(rawItem?.quantity)) {
    const q = paintStrictNumber(rawItem.quantity);
    if (q === null || q < 1) {
      add("quantity", "paint_quantity_unavailable",
        "record a quantity of 1 or more — a blank or malformed value prices as 1 silently");
    }
  }

  // paint_sides — the stored value chooses the multiplier branch; "none" is a
  // tolerated legacy alias for one_side.
  if (PRESENT(rawItem?.paint_sides) && rawItem.paint_sides !== ""
    && !["one_side", "both_sides", "none"].includes(rawItem.paint_sides)) {
    add("paint_sides", "paint_sides_unavailable",
      "choose One side or Both sides — the stored value silently prices as one side");
  }

  // edge complexity — complex-shape edge multiplier; negative values priced
  // negative edge area, malformed text repriced as 1x, blank as 0 edges.
  if (effectiveType === "complex_shapes" && PRESENT(rawItem?.edge_complexity_multiplier)
    && !nonnegField(rawItem.edge_complexity_multiplier)) {
    add("edge_complexity_multiplier", "paint_edge_complexity_unavailable",
      "record a finite, nonnegative edge complexity multiplier — the stored value cannot price edges");
  }

  // paint mask sq ft — consumed when more than one color is selected; blank
  // or malformed text silently priced as no mask.
  if (PRESENT(rawItem?.paint_mask_sqft) && !nonnegField(rawItem.paint_mask_sqft)) {
    add("paint_mask_sqft", "paint_mask_sqft_unavailable",
      "record a finite, nonnegative paint mask area (sq ft) — the stored value drops mask pricing");
  }

  // fixed waste gallons / base supplies — recorded junk silently became 0.
  for (const [field, human] of [["fixed_waste_gallons", "fixed waste (gallons)"], ["base_supplies_cost", "base supplies cost ($)"]]) {
    if (PRESENT(rawItem?.[field]) && !nonnegField(rawItem[field])) {
      add(field, field === "fixed_waste_gallons" ? "paint_fixed_waste_unavailable" : "paint_base_supplies_unavailable",
        `record a finite, nonnegative ${human} — the stored value silently became $0`);
    }
  }

  // letter_size — drives the complexity class for lettering only.
  if (effectiveType === "lettering" && PRESENT(rawItem?.letter_size) && rawItem.letter_size !== ""
    && !LETTER_SIZES.includes(rawItem.letter_size)) {
    add("letter_size", "paint_letter_size_unavailable",
      "the stored letter size is unsupported — it silently prices as moderate complexity");
  }

  // paint_colors — the math reads the array length verbatim (ported); a
  // non-array value normalized to [] silently bills no paint.
  if (PRESENT(rawItem?.paint_colors) && !Array.isArray(rawItem.paint_colors)) {
    add("paint_colors", "paint_colors_unavailable",
      "the stored color list is malformed — it silently bills $0 paint; re-add the colors");
  }

  return issues;
}

// ---------- project-level scan ----------
export function paintProjectInputIssues(project = {}) {
  const issues = [];
  const add = (field, code, message) =>
    issues.push(issue("paint", { field, code, message, hold: "project" }));

  // items must be an array — the calc maps it verbatim.
  if (project?.items !== undefined && !Array.isArray(project.items)) {
    add("items", "paint_items_unavailable",
      "the stored paint items are malformed — the project cannot be repriced");
  }

  // paint_supplies_per_sqft — blank/null laundered to $0 under num(); a
  // malformed string silently became the settings default. Explicit 0 stays a
  // legitimate free supplies rate.
  if (project?.paint_supplies_per_sqft !== undefined
    && (paintStrictNumber(project.paint_supplies_per_sqft) === null
      || paintStrictNumber(project.paint_supplies_per_sqft) < 0)) {
    add("paint_supplies_per_sqft", "paint_supplies_rate_unavailable",
      "record a finite, nonnegative supplies rate per sq ft — a blank or malformed value silently repriced supplies");
  }

  return issues;
}

// ---------- calc wrapper ----------
// Returns { calc, issues, held }. The calc keeps the real result shape; when
// held, every derived number a flagged input could have tainted is null —
// saved acknowledged totals on the record are the display fallback, never an
// invented $0. Raw rows are untouched.
const ITEM_HELD_FIELDS = ["supplies_cost", "paint_cost", "paint_gallons", "labor_hours", "labor_cost", "paintable_sqft"];

export function calcPaintingProject(project = {}, settings = {}) {
  const issues = [
    ...paintSettingIssues(settings),
    ...((Array.isArray(project?.items) ? project.items : [])
      .flatMap((item, index) => paintItemIssues(item, index))),
    ...paintProjectInputIssues(project),
  ];

  // A non-array items value is itself a project-level hold; hand the calc an
  // empty list so it still returns a real result shape (the input object is
  // never mutated — totals are nulled below regardless).
  const calcable = Array.isArray(project?.items) ? project : { ...project, items: [] };
  const calc = calculatePaintingProject(calcable, settings);
  const held = issues.length > 0;
  if (!held) {
    calc.__held = false;
    calc.pricingUnavailable = false;
    calc.issues = [];
    return { calc, issues, held };
  }

  const out = { ...calc, totals: { ...calc.totals } };
  const hasProjectHold = issues.some((i) => i.hold === "project");
  const itemHolds = new Set(issues.filter((i) => i.hold === "item").map((i) => i.itemIndex));

  // Held items keep their raw row but lose every derived number — the totals
  // sum those numbers so every aggregate is untrustworthy too.
  out.items = calc.items.map((item, index) => {
    if (!hasProjectHold && !itemHolds.has(index)) return item;
    const heldItem = { ...item };
    for (const field of ITEM_HELD_FIELDS) heldItem[field] = null;
    return heldItem;
  });
  for (const field of Object.keys(out.totals)) out.totals[field] = null;
  if (hasProjectHold) out.liquidPaintRate = null;

  out.__held = true;
  out.pricingUnavailable = true;
  out.issues = issues;
  return { calc: out, issues, held };
}

// ---------- UI helpers ----------
// Saved acknowledged pricing snapshot — only a real finite number counts.
// This is the gate for "Saved amounts (not current pricing)" display.
export const hasPaintCostSnapshot = (v) => typeof v === "number" && Number.isFinite(v);

// Blank-preserving input helper for number fields: "" stays "" so the input
// does not fight the user mid-typing; parseable text becomes a number;
// anything else stays raw so validation can flag it instead of laundering it
// into 0 (paintCalc's num("") silently read as 0 before).
export const paintDraftValue = (raw) => {
  if (raw === "") return "";
  const n = Number(raw);
  return Number.isFinite(n) ? n : raw;
};

// All issues attached to a single field (optionally a single item row).
export const issuesForField = (issues = [], field, itemIndex = null) =>
  issues.filter((i) => i.field === field && (itemIndex === null || i.itemIndex === itemIndex));
export const hasIssueFor = (issues = [], field, itemIndex = null) =>
  issuesForField(issues, field, itemIndex).length > 0;

// Painting sell-price engine wire (F-23g) — module-side glue.
//
// The shared wire (base44/shared/paintPricingWire.ts) is intentionally
// import-free; this file is the composition root that injects the real engine
// functions and merges caller-supplied registries with the record-embedded
// engine context. Wired into customerPricing.sourceProjectEconomics for
// module_key "painting" — when no paint line carries pricing-engine config
// the resolution is a passthrough and the module sell price is returned
// verbatim (zero regression).
//
// Registry context (`pricingContext`) is OPTIONAL today: config embedded on
// the record/items (item pricing fields, engine_pricing blocks, embedded
// templates/tier rules) resolves without any entity reads. Callers that have
// PricingTierMatrix / PricingTemplate / GlobalPricingTier / MarkupTier rows
// loaded may pass them as { tierRules|tier_rules, templates, tiers,
// customerTier|customer_tier, defaultMarkupPct|default_markup_pct, now } to
// unlock registry-backed tier/template references.

import { pricePart, matrixRowsToRules } from "../../../../base44/shared/pricingEngine.ts";
import { resolveTemplatePrice, templatePartDescriptor } from "../../../../base44/shared/pricingTemplateModel.ts";
import {
  resolvePaintSellPricing,
  paintConfigScan,
  paintPricingContextOf,
} from "../../../../base44/shared/paintPricingWire.ts";

const ENGINE = Object.freeze({ pricePart, resolveTemplatePrice, templatePartDescriptor });

/**
 * Full resolution — engine-priced sell for config-carrying paint lines.
 * Never throws: malformed input/config degrades to a passthrough result.
 *
 * @param {object} record       paint Project-like record
 * @param {object} opts
 * @param {number} opts.baselineSell  module sell price (total_paint_mask_cost
 *                                    + total_liquid_paint_and_supplies_cost
 *                                    + total_labor_cost)
 * @param {number} [opts.internalCost] module internal cost (same sum)
 * @param {object} [opts.pricingContext] caller-loaded registries (optional)
 * @param {*}      [opts.now]    effective-window override (tests)
 * @returns {object} resolvePaintSellPricing result ({applied, customer_price,
 *          passthrough, lines, chain, warnings, ...})
 */
export function resolvePaintEngineSell(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  try {
    const caller = pricingContext && typeof pricingContext === "object" ? { ...pricingContext } : {};
    // Normalize caller chart rows through the engine's entity adapter so
    // PricingTierMatrix spellings (unit_breaks aliases, status windows) resolve
    // exactly like the pricing admin path.
    const rawRules = caller.tierRules ?? caller.tier_rules ?? caller.tier_matrix;
    if (Array.isArray(rawRules) && rawRules.length) {
      caller.tierRules = matrixRowsToRules(rawRules, { now: caller.now ?? now });
    }
    const context = paintPricingContextOf(record, caller);
    return resolvePaintSellPricing({ record, baselineSell, internalCost, context, engine: ENGINE, now });
  } catch {
    // The sell-price seam must never break estimate rendering — a malformed
    // record or config degrades to the module baseline, not an exception.
    return { applied: false, passthrough: true, reason: "no_engine", customer_price: baselineSell, warnings: [] };
  }
}

/**
 * Seam helper — engine-owned economics for a paint source record.
 * Returns null when no paint line carries pricing config (the caller then
 * keeps today's numbers byte-identically); when config resolves the engine
 * owns the sell side — including over a legacy saved customer_pricing
 * snapshot (parity with the F-23a..F-23f channel/vinyl/brick/cnc/laser/metal
 * wires).
 */
export function paintEngineEconomics(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  const res = resolvePaintEngineSell(record, { baselineSell, internalCost, pricingContext, now });
  return res && res.applied === true
    ? { internalCost, customerPrice: res.customer_price, resolution: res }
    : null;
}

/**
 * Convenience — the customer-facing sell price for a paint source record.
 * Returns the engine total when config resolves, else `baselineSell` verbatim
 * (=== passthrough; the byte-identical zero-regression path).
 */
export function paintEngineCustomerPrice(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  const res = resolvePaintEngineSell(record, { baselineSell, internalCost, pricingContext, now });
  return res && res.applied === true ? res.customer_price : baselineSell;
}

/**
 * Detection only — does any paint line on this record carry pricing-engine
 * config? Useful for badges/tests without running the full resolution.
 */
export function paintHasEnginePricing(record) {
  try {
    return paintConfigScan(record).configured === true;
  } catch {
    return false;
  }
}

const num = (v, d = 0) => (Number.isFinite(Number(v)) ? Number(v) : d);

// Engraving items run on the engraving laser; cutting items run on the parameter laser.
// engrave_and_cut splits: engrave portion on the engraving laser, cut portion on the parameter laser.
export function calcLaserProject(project) {
  const cutMachine = num(project.machine_rate_per_hour, 100);
  const cutLabor = num(project.labor_rate, 75);
  const engMachine = num(project.engraving_machine_rate_per_hour, 80);
  const engLabor = num(project.engraving_labor_rate, 40);
  const cutHandlingPct = num(project.parameter_handling_time_percentage, 15);
  const engHandlingPct = num(project.engraving_handling_time_percentage, 20);

  const items = (project.items || []).map((raw) => {
    const item = { ...raw };
    const qty = num(item.quantity, 1);
    const type = item.item_type || "panel";
    const doesEngrave = type === "engraving" || type === "engrave_and_cut";
    const doesCut = type !== "engraving";

    const engSpeed = num(item.engrave_speed_sqipm, 5);
    const engHours = doesEngrave && engSpeed > 0 ? (num(item.engrave_area_sqin) / engSpeed / 60) * qty : 0;

    const cutSpeed = num(item.cut_speed_ipm, 20);
    const perimeter =
      num(item.total_cut_length_inches) ||
      (type === "lettering"
        ? num(item.num_letters) * num(item.letter_height) * 4
        : (num(item.length) + num(item.width)) * 2);
    const cutHours = doesCut && cutSpeed > 0 ? (perimeter / cutSpeed / 60) * qty : 0;

    item.engrave_hours = engHours;
    item.cut_hours = cutHours;
    item.machine_time_hours = engHours + cutHours;
    item.handling_time_hours =
      (engHours * engHandlingPct) / 100 + (cutHours * cutHandlingPct) / 100;
    item.machine_cost = engHours * engMachine + cutHours * cutMachine;
    item.labor_cost =
      ((engHours * engHandlingPct) / 100) * engLabor + ((cutHours * cutHandlingPct) / 100) * cutLabor;
    item.item_total_cost = item.machine_cost + item.labor_cost;
    return item;
  });

  const total_machine_hours = items.reduce((s, i) => s + i.machine_time_hours, 0);
  const total_handling_hours =
    items.reduce((s, i) => s + i.handling_time_hours, 0) + num(project.fixed_setup_hours);
  const total_machine_cost = items.reduce((s, i) => s + i.machine_cost, 0);
  const fixed_setup_cost = num(project.fixed_setup_hours) * cutLabor;
  const total_labor_cost = items.reduce((s, i) => s + i.labor_cost, 0) + fixed_setup_cost;
  const total_supplies_cost = num(project.fixed_material_setup_cost);

  return {
    items,
    totals: {
      total_machine_hours,
      total_handling_hours,
      total_machine_cost,
      fixed_setup_cost,
      total_labor_cost,
      total_supplies_cost,
      total_cost: total_machine_cost + total_labor_cost + total_supplies_cost,
    },
  };
}

// Laser pricing-availability layer.
//
// Wraps the LaserEstimator's inline calculateTotals (ported verbatim below as
// computeLaserTotals) with strict finite-number input validation so a missing,
// malformed, or unusable pricing input can no longer silently become $0, a
// hidden default, or a NaN that is laundered into the persisted totals.
// Mirrors the landed Foundation/Vinyl/Painting hardening convention:
//   - strict parsers (laserStrictNumber / laserSettingRecorded /
//     laserSeedNumber — the page seeds new-project defaults through the same
//     resolver so the scanner and the seed agree)
//   - structured issue records { kind, index, itemIndex, field, code, message,
//     hold } — kind "laser_catalog" for Settings rows (the priced surface —
//     Laser has no catalog entities), kind "laser" for project-field and item
//     issues; hold "project" holds the whole calc, hold "item" holds one row's
//     derived numbers plus every aggregate they feed
//   - explicit 0 stays valid where the math treats it as a real free/zero
//     amount (handling %, fixed setup hours, fixed material setup cost); 0 is
//     invalid where the math divides or needs a real magnitude (rates, speeds,
//     multipliers feeding a speed, perimeter factor, dimensions, counts)
//   - only CONSUMED values are validated: seed settings only while a new
//     project would seed from them (!project.id), item-derived settings only
//     when a project row actually consumes them, engrave-side rates only when
//     an engraving-type item exists
//   - raw rows are never mutated — the calculator reads the original records
//     exactly as the page has always passed them
//
// Valid inputs take the exact same code path as before: the result the page
// receives for a clean project is bit-identical to today's inline result (plus
// __held / pricingUnavailable / issues metadata flags).
//
// NOTE: src/components/estimator/laser/laserCalc.js is DEAD and DIVERGENT from
// the live math (different units, perimeter rule, and cost split) — it is not
// the source of truth; the ported inline body below is.

// ---------- strict parsers ----------
// Finite number or null. Accepts real numbers and trimmed numeric strings;
// rejects "", "abc", Infinity, NaN, hex/octal strings, null, undefined,
// objects. `Number()` alone would accept "0x10" → 16 and launder it silently.
export const laserStrictNumber = (v) => {
  if (typeof v === "number") return Number.isFinite(v) ? v : null;
  if (typeof v === "string") {
    const t = v.trim();
    if (t === "") return null;
    if (!/^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(t)) return null;
    const n = Number(t);
    return Number.isFinite(n) ? n : null;
  }
  return null;
};

// A Settings value that was actually recorded — absent rows/blank text fall
// back to the documented module default by design (see LASER_SETTINGS_DEFAULTS
// in moduleSettingDefaults).
export const laserSettingRecorded = (settings, key) => {
  const v = settings?.[key];
  return v !== undefined && v !== null && !(typeof v === "string" && v.trim() === "");
};

// Strict settings read used for NEW-project seeding: a recorded finite value
// is honored verbatim — an explicit 0 stays 0 where the key allows it (the old
// `parseFloat(x)||d` revived the default and made a deliberate 0 impossible).
// Absent/blank/malformed or out-of-range values resolve the fallback exactly
// like before; the availability layer flags every recorded-but-unusable value
// separately.
//   positive: true  → value must be > 0 (rates, speeds, multipliers, factors)
//   positive: false → value must be >= 0 (handling %, setup hours, fixed cost)
export const laserSeedNumber = (settings, key, fallback, { positive = false } = {}) => {
  if (!laserSettingRecorded(settings, key)) return fallback;
  const n = laserStrictNumber(settings[key]);
  if (n === null) return fallback;
  if (positive ? n <= 0 : n < 0) return fallback;
  return n;
};

// ---------- issue records ----------
const issue = (kind, { index = null, itemIndex = null, field, code, message, hold }) => ({
  kind, index, itemIndex, field, code, message, hold,
});

// ---------- consumption model ----------
const CUT_TYPES = new Set(["panel", "lettering", "engrave_and_cut"]);
const ENGRAVE_TYPES = new Set(["engraving", "engrave_and_cut"]);
const VALID_TYPES = new Set(["panel", "lettering", "engraving", "engrave_and_cut"]);
const IMPERIAL_SIZES = ["1/16", "1/8", "3/16", "1/4", "3/8", "1/2", "3/4"];
const MATERIALS = ["Acrylic", "Wood", "Leather"];

const PRESENT = (v) => v !== undefined && v !== null && v !== "";
const cutConsumed = (item) => CUT_TYPES.has(item?.item_type);
const engraveConsumed = (item) => ENGRAVE_TYPES.has(item?.item_type);

// ---------- settings scan ----------
// Seed keys consumed at load for a NEW project only — existing records carry
// their own (validated as project inputs). [key, human, positive]
const SEED_SETTINGS = [
  ["parameter_laser_machine_rate", "parameter laser machine rate ($/hr)", true],
  ["parameter_laser_labor_rate", "parameter laser labor rate ($/hr)", true],
  ["engraving_laser_machine_rate", "engraving laser machine rate ($/hr)", true],
  ["engraving_labor_rate", "engraving labor rate ($/hr)", true],
  ["parameter_handling_time_percentage", "parameter handling time %", false],
  ["engraving_handling_time_percentage", "engraving handling time %", false],
  ["min_parameter_laser_setup_hours", "minimum parameter laser setup hours", false],
  ["parameter_laser_fixed_material_setup_cost", "parameter laser fixed material setup cost", false],
];

// Item-derived settings (updateItem reads them on every field edit). Only the
// keys a project row actually consumes are validated — a malformed setting no
// item reads cannot silently reprice anything.
const thicknessSpeedKey = (t) => `cut_speed_${String(t || "").replace("/", "_")}`;
const cutMultiplierKey = (m) => `${String(m || "").toLowerCase()}_cut_multiplier`;
const engraveMultiplierKey = (m) => `${String(m || "").toLowerCase()}_engrave_multiplier`;

export function laserSettingIssues(project = {}, settings = {}) {
  const issues = [];
  const add = (field, message) =>
    issues.push(issue("laser_catalog", { field, code: "laser_setting_unavailable", message, hold: "project" }));
  const check = (key, human, positive) => {
    if (!laserSettingRecorded(settings, key)) return; // absent → documented module default by design
    const n = laserStrictNumber(settings[key]);
    if (n === null || (positive ? n <= 0 : n < 0)) {
      add(key, `Setting ${key}: record a finite, ${positive ? "positive" : "nonnegative"} ${human} in Laser Settings — the stored value cannot price this estimate`);
    }
  };

  // Seed keys — only while this project has no persisted id and would seed
  // from Settings at load.
  if (!project?.id) {
    for (const [key, human, positive] of SEED_SETTINGS) check(key, human, positive);
  }

  const items = Array.isArray(project?.items) ? project.items : [];
  const derivedKeys = new Map(); // key -> human (dedupe across items)
  for (const it of items) {
    if (cutConsumed(it)) {
      if (IMPERIAL_SIZES.includes(it?.material_thickness)) {
        derivedKeys.set(thicknessSpeedKey(it.material_thickness), `cut speed for ${it.material_thickness}" material (mm/sec)`);
      }
      if (MATERIALS.includes(it?.material_type)) {
        derivedKeys.set(cutMultiplierKey(it.material_type), `${it.material_type} cut multiplier`);
      }
      if (it?.item_type === "lettering") {
        derivedKeys.set("laser_letter_perimeter_factor", "letter perimeter factor");
      }
    }
    if (engraveConsumed(it)) {
      derivedKeys.set("laser_engrave_speed_sqipm", "engrave speed (sq mm/sec)");
      if (MATERIALS.includes(it?.material_type)) {
        derivedKeys.set(engraveMultiplierKey(it.material_type), `${it.material_type} engrave multiplier`);
      }
    }
  }
  for (const [key, human] of derivedKeys) check(key, human, true);

  return issues;
}

// ---------- item-level scan ----------
// Consumed fields on each laser item. Issues hold the item's derived numbers
// (hold "item") — totals re-derive null because they sum held items.
export function laserItemIssues(rawItem = {}, index = 0) {
  const issues = [];
  const label = `Item ${index + 1}${rawItem?.description ? ` "${rawItem.description}"` : ""}`;
  const add = (field, code, message) =>
    issues.push(issue("laser", { index, itemIndex: index, field, code, message: `${label}: ${message}`, hold: "item" }));

  // item_type — every cost branch keys on it; anything else prices a silent
  // $0 item.
  if (!VALID_TYPES.has(rawItem?.item_type)) {
    add("item_type", "laser_item_type_unavailable",
      "select Panel, Lettering, Engraving, or Engrave and Cut — the stored type prices as $0 silently");
  }
  const effectiveType = VALID_TYPES.has(rawItem?.item_type) ? rawItem.item_type : "panel";
  const cuts = cutConsumed({ item_type: effectiveType });
  const engraves = engraveConsumed({ item_type: effectiveType });

  // material_type — derives the *_cut_multiplier / *_engrave_multiplier
  // Settings keys; an unknown or missing material silently resolves 1×.
  if (!MATERIALS.includes(rawItem?.material_type)) {
    add("material_type", "laser_material_type_unavailable",
      "choose Acrylic, Wood, or Leather — the stored material silently prices at a 1.0× multiplier");
  }

  // material_thickness — keys the cut_speed_<t> Settings row for cutting
  // items; an unknown size reads a nonexistent setting → silent 20 mm/s.
  if (cuts && !IMPERIAL_SIZES.includes(rawItem?.material_thickness)) {
    add("material_thickness", "laser_thickness_unavailable",
      "choose a listed thickness — the stored size has no cut-speed setting and silently prices at 20 mm/sec");
  }

  // Dimensions — the derivation multiplies them verbatim.
  if (effectiveType === "lettering") {
    const h = laserStrictNumber(rawItem?.letter_height);
    if (h === null || h <= 0) {
      add("letter_height", "laser_dimension_unavailable",
        "record a positive, finite letter height (inches) — a blank or zero height prices the letters as $0 silently");
    }
    const n = laserStrictNumber(rawItem?.num_letters);
    if (n === null || n < 1) {
      add("num_letters", "laser_quantity_unavailable",
        "record a letter count of 1 or more — a blank or malformed count prices the letters as $0 silently");
    }
  } else {
    for (const field of ["length", "width"]) {
      const n = laserStrictNumber(rawItem?.[field]);
      if (cuts) {
        if (n === null || n <= 0) {
          add(field, "laser_dimension_unavailable",
            `record a positive, finite ${field} (inches) — a blank or zero dimension silently mis-prices the cut perimeter`);
        }
      } else if (PRESENT(rawItem?.[field]) && (n === null || n < 0)) {
        // engraving: dims only feed the engrave-area derivation on edit —
        // a recorded malformed value still poisons it; 0/absent is fine when
        // the area is hand-entered.
        add(field, "laser_dimension_unavailable",
          `record a finite, nonnegative ${field} (inches) or clear it — the stored value poisons the engrave area`);
      }
    }
  }

  // quantity — multiplied into engrave_area for every row and into every
  // cut-length derivation; blank/malformed silently zeroes or NaNs the row.
  {
    const q = laserStrictNumber(rawItem?.quantity);
    if (q === null || q < 1) {
      add("quantity", "laser_quantity_unavailable",
        "record a quantity of 1 or more — a blank or malformed value prices this row as $0 silently");
    }
  }

  // total_cut_length_inches — the calc multiplies it by MM_PER_IN verbatim:
  // a malformed or string value NaNs the row; for cutting items a nonpositive
  // value silently drops all machine time.
  {
    const n = laserStrictNumber(rawItem?.total_cut_length_inches);
    if (n === null || (cuts ? n <= 0 : n < 0)) {
      add("total_cut_length_inches", "laser_cut_length_unavailable",
        cuts
          ? "re-enter the dimensions — the derived cut length is unusable and would silently price $0 machine time"
          : "the stored cut length is malformed — it corrupts the row's machine time");
    }
  }

  // engrave_area_sqin — multiplied unconditionally; engraving types price
  // nothing at 0.
  {
    const n = laserStrictNumber(rawItem?.engrave_area_sqin);
    if (n === null || (engraves ? n <= 0 : n < 0)) {
      add("engrave_area_sqin", "laser_engrave_area_unavailable",
        engraves
          ? "record a positive, finite engraving area (sq in) — a blank or zero area prices the engraving as $0 silently"
          : "the stored engrave area is malformed — it corrupts the row's machine time");
    }
  }

  // cut_speed_ipm / engrave_speed_sqipm — unconditional divisors: a truthy
  // malformed string NaNs the row even when its own geometry is zero.
  {
    const n = laserStrictNumber(rawItem?.cut_speed_ipm);
    if (n === null || n <= 0) {
      add("cut_speed_ipm", "laser_cut_speed_unavailable",
        "re-pick the material and thickness — the derived cut speed is unusable and corrupts the row's machine time");
    }
    const e = laserStrictNumber(rawItem?.engrave_speed_sqipm);
    if (e === null || e <= 0) {
      add("engrave_speed_sqipm", "laser_engrave_speed_unavailable",
        "re-pick the material — the derived engrave speed is unusable and corrupts the row's machine time");
    }
  }

  return issues;
}

// ---------- project-level scan ----------
// Stored rate/setup fields the calc reads with `||` launders that pass truthy
// malformed values straight into NaN. Engrave-side rates validate only when an
// engraving-type item consumes them; cut-side rates only when a cutting item
// does; labor/setup fields are consumed unconditionally.
export function laserProjectInputIssues(project = {}) {
  const issues = [];
  const add = (field, code, message) =>
    issues.push(issue("laser", { field, code, message, hold: "project" }));

  if (project?.items !== undefined && !Array.isArray(project.items)) {
    add("items", "laser_items_unavailable",
      "the stored laser items are malformed — the project cannot be repriced");
  }

  const items = Array.isArray(project?.items) ? project.items : [];
  const anyCut = items.some(cutConsumed);
  const anyEngrave = items.some(engraveConsumed);

  const needPositive = (field, human, active) => {
    if (!active) return;
    const n = laserStrictNumber(project?.[field]);
    if (n === null || n <= 0) {
      add(field, "laser_rate_unavailable",
        `record a positive, finite ${human} — the stored value silently reprices this estimate`);
    }
  };
  const needNonNeg = (field, human, active) => {
    if (!active) return;
    const n = laserStrictNumber(project?.[field]);
    if (n === null || n < 0) {
      add(field, "laser_rate_unavailable",
        `record a finite, nonnegative ${human} — the stored value silently reprices this estimate`);
    }
  };

  needPositive("machine_rate_per_hour", "machine rate ($/hr)", anyCut);
  needPositive("labor_rate", "labor rate ($/hr)", true); // fixed setup consumes it always
  needPositive("engraving_machine_rate_per_hour", "engraving machine rate ($/hr)", anyEngrave);
  needPositive("engraving_labor_rate", "engraving labor rate ($/hr)", anyEngrave);
  needNonNeg("parameter_handling_time_percentage", "parameter handling %", anyCut);
  needNonNeg("engraving_handling_time_percentage", "engraving handling %", anyEngrave);
  needNonNeg("fixed_setup_hours", "fixed setup hours", true);
  needNonNeg("fixed_material_setup_cost", "fixed material setup cost ($)", true);

  return issues;
}

// ---------- live calculation (ported verbatim from LaserEstimator) ----------
// Byte-identical reproduction of the page's inline calculateTotals body —
// same formulas, same `||` launders, same iteration order. On a clean project
// it returns exactly the remote result; under issues its (possibly NaN)
// numbers are discarded by the held wrapper, never persisted.
export function computeLaserTotals(project = {}) {
  let totalMachineCost = 0;
  let totalLaborCost = 0;
  let totalSuppliesCost = 0;

  // Cut/engrave speeds are stored as mm/sec and mm²/sec.
  // Convert lengths/areas from inches to mm (1 in = 25.4 mm) before dividing.
  const MM_PER_IN = 25.4;
  const SQMM_PER_SQIN = 25.4 * 25.4;

  const updatedItems = project.items.map((item) => {
    const cutLengthMm = item.total_cut_length_inches * MM_PER_IN;
    const engraveAreaSqMm = item.engrave_area_sqin * item.quantity * SQMM_PER_SQIN;

    const cutTimeSeconds = cutLengthMm / (item.cut_speed_ipm || 20);
    const engraveTimeSeconds = engraveAreaSqMm / (item.engrave_speed_sqipm || 5);

    const cutTimeHours = cutTimeSeconds / 3600;
    const engraveTimeHours = engraveTimeSeconds / 3600;
    const machineTimeHours = cutTimeHours + engraveTimeHours;

    // Rates
    const paramMachineRate = project.machine_rate_per_hour || 100;
    const paramLaborRate = project.labor_rate || 75;
    const paramHandlingPct = (project.parameter_handling_time_percentage || 15) / 100;

    const engraveMachineRate = project.engraving_machine_rate_per_hour || 80;
    const engraveLaborRate = project.engraving_labor_rate || 40;
    const engraveHandlingPct = (project.engraving_handling_time_percentage || 20) / 100;

    let itemMachineCost = 0;
    let itemLaborCost = 0;
    let itemHandlingHours = 0;

    if (item.item_type === 'panel' || item.item_type === 'lettering') {
      // Parameter Only
      itemHandlingHours = machineTimeHours * paramHandlingPct;
      itemMachineCost = machineTimeHours * paramMachineRate;
      itemLaborCost = itemHandlingHours * paramLaborRate;
    } else if (item.item_type === 'engraving') {
      // Engraving Only
      itemHandlingHours = machineTimeHours * engraveHandlingPct;
      itemMachineCost = machineTimeHours * engraveMachineRate;
      itemLaborCost = itemHandlingHours * engraveLaborRate;
    } else if (item.item_type === 'engrave_and_cut') {
      // Mixed - Split costs
      const cutHandling = cutTimeHours * paramHandlingPct;
      const engraveHandling = engraveTimeHours * engraveHandlingPct;
      itemHandlingHours = cutHandling + engraveHandling;

      itemMachineCost = (cutTimeHours * paramMachineRate) + (engraveTimeHours * engraveMachineRate);
      itemLaborCost = (cutHandling * paramLaborRate) + (engraveHandling * engraveLaborRate);
    }

    totalMachineCost += itemMachineCost;
    totalLaborCost += itemLaborCost;

    return {
      ...item,
      machine_time_hours: machineTimeHours,
      handling_time_hours: itemHandlingHours,
      machine_cost: itemMachineCost,
      labor_cost: itemLaborCost
    };
  });

  // Add fixed setup time labor cost
  const fixedSetupLaborCost = project.fixed_setup_hours * project.labor_rate;
  totalLaborCost += fixedSetupLaborCost;

  // Add fixed material setup cost to supplies cost
  const fixedMaterialSetupCost = project.fixed_material_setup_cost || 0;
  totalSuppliesCost += fixedMaterialSetupCost; // Now goes to supplies cost

  return {
    items: updatedItems,
    total_machine_cost: totalMachineCost,
    total_labor_cost: totalLaborCost,
    total_supplies_cost: totalSuppliesCost
  };
}

// ---------- calc wrapper ----------
// Returns { calc, issues, held }. The calc keeps the real result shape
// ({ items, total_machine_cost, total_labor_cost, total_supplies_cost }); when
// held, every derived number a flagged input could have tainted is null — the
// saved acknowledged totals on the record are the display fallback, never an
// invented $0. Raw rows are untouched.
const ITEM_HELD_FIELDS = ["machine_time_hours", "handling_time_hours", "machine_cost", "labor_cost"];
const TOTAL_FIELDS = ["total_machine_cost", "total_labor_cost", "total_supplies_cost"];

export function calcLaserPricing(project = {}, settings = {}) {
  const issues = [
    ...laserSettingIssues(project, settings),
    ...laserProjectInputIssues(project),
    ...((Array.isArray(project?.items) ? project.items : [])
      .flatMap((item, index) => laserItemIssues(item, index))),
  ];

  // A non-array items value is itself a project-level hold; hand the calc an
  // empty list so it still returns a real result shape (the input object is
  // never mutated — totals are nulled below regardless).
  const calcable = Array.isArray(project?.items) ? project : { ...project, items: [] };
  const calc = computeLaserTotals(calcable);

  // Paranoid net: if any derived number still came out non-finite without a
  // named issue, hold rather than let a NaN reach the persisted totals.
  const leakedNaN =
    issues.length === 0 &&
    (!TOTAL_FIELDS.every((f) => Number.isFinite(calc[f])) ||
      calc.items.some((it) => ITEM_HELD_FIELDS.some((f) => !Number.isFinite(it[f]))));
  if (leakedNaN) {
    issues.push(issue("laser", {
      field: "total_cost",
      code: "laser_totals_unavailable",
      message: "Pricing produced a non-finite total — re-check the item values before saving",
      hold: "project",
    }));
  }

  const held = issues.length > 0;
  if (!held) {
    calc.__held = false;
    calc.pricingUnavailable = false;
    calc.issues = [];
    return { calc, issues, held };
  }

  const out = { ...calc, items: calc.items.slice() };
  const hasProjectHold = issues.some((i) => i.hold === "project");
  const itemHolds = new Set(issues.filter((i) => i.hold === "item").map((i) => i.itemIndex));

  // Held items keep their raw row but lose every derived number — the totals
  // sum those numbers so every aggregate is untrustworthy too.
  out.items = calc.items.map((item, index) => {
    if (!hasProjectHold && !itemHolds.has(index)) return item;
    const heldItem = { ...item };
    for (const field of ITEM_HELD_FIELDS) heldItem[field] = null;
    return heldItem;
  });
  for (const field of TOTAL_FIELDS) out[field] = null;

  out.__held = true;
  out.pricingUnavailable = true;
  out.issues = issues;
  return { calc: out, issues, held };
}

// ---------- UI helpers ----------
// Saved acknowledged pricing snapshot — only a real finite number counts.
// This is the gate for "Saved amounts (not current pricing)" display.
export const hasLaserCostSnapshot = (v) => typeof v === "number" && Number.isFinite(v);

// Sum that propagates null — for "total = machine + supplies + labor" cells.
export const laserSumOrNull = (...xs) =>
  xs.every((v) => Number.isFinite(v)) ? xs.reduce((s, v) => s + v, 0) : null;

// Blank-preserving input helper for number fields: "" stays "" so the input
// does not fight the user mid-typing; parseable text becomes a number;
// anything else stays raw so validation can flag it instead of laundering it
// into 0/1 (the old parseFloat||N silently read "" as the fallback).
export const laserDraftValue = (raw) => {
  if (raw === "") return "";
  const n = Number(raw);
  return Number.isFinite(n) ? n : raw;
};

// All issues attached to a single field (optionally a single item row).
export const issuesForField = (issues = [], field, itemIndex = null) =>
  issues.filter((i) => i.field === field && (itemIndex === null || i.itemIndex === itemIndex));
export const hasIssueFor = (issues = [], field, itemIndex = null) =>
  issuesForField(issues, field, itemIndex).length > 0;

// Laser sell-price engine wire (F-23e) — module-side glue.
//
// The shared wire (base44/shared/laserPricingWire.ts) is intentionally
// import-free; this file is the composition root that injects the real engine
// functions and merges caller-supplied registries with the record-embedded
// engine context. Wired into customerPricing.sourceProjectEconomics for
// module_key "laser" — when no laser line carries pricing-engine config the
// resolution is a passthrough and the module sell price is returned verbatim
// (zero regression).
//
// Registry context (`pricingContext`) is OPTIONAL today: config embedded on
// the record/items (item pricing fields, engine_pricing blocks, embedded
// templates/tier rules) resolves without any entity reads. Callers that have
// PricingTierMatrix / PricingTemplate / GlobalPricingTier / MarkupTier rows
// loaded may pass them as { tierRules|tier_rules, templates, tiers,
// customerTier|customer_tier, defaultMarkupPct|default_markup_pct, now } to
// unlock registry-backed tier/template references.

import { pricePart, matrixRowsToRules } from "../../../../base44/shared/pricingEngine.ts";
import { resolveTemplatePrice, templatePartDescriptor } from "../../../../base44/shared/pricingTemplateModel.ts";
import {
  resolveLaserSellPricing,
  laserConfigScan,
  laserPricingContextOf,
} from "../../../../base44/shared/laserPricingWire.ts";

const ENGINE = Object.freeze({ pricePart, resolveTemplatePrice, templatePartDescriptor });

/**
 * Full resolution — engine-priced sell for config-carrying laser lines.
 * Never throws: malformed input/config degrades to a passthrough result.
 *
 * @param {object} record       LaserProject-like record
 * @param {object} opts
 * @param {number} opts.baselineSell  module sell price (record.total_cost)
 * @param {number} [opts.internalCost] module internal cost (record.total_cost)
 * @param {object} [opts.pricingContext] caller-loaded registries (optional)
 * @param {*}      [opts.now]    effective-window override (tests)
 * @returns {object} resolveLaserSellPricing result ({applied, customer_price,
 *          passthrough, lines, chain, warnings, ...})
 */
export function resolveLaserEngineSell(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  try {
    const caller = pricingContext && typeof pricingContext === "object" ? { ...pricingContext } : {};
    // Normalize caller chart rows through the engine's entity adapter so
    // PricingTierMatrix spellings (unit_breaks aliases, status windows) resolve
    // exactly like the pricing admin path.
    const rawRules = caller.tierRules ?? caller.tier_rules ?? caller.tier_matrix;
    if (Array.isArray(rawRules) && rawRules.length) {
      caller.tierRules = matrixRowsToRules(rawRules, { now: caller.now ?? now });
    }
    const context = laserPricingContextOf(record, caller);
    return resolveLaserSellPricing({ record, baselineSell, internalCost, context, engine: ENGINE, now });
  } catch {
    // The sell-price seam must never break estimate rendering — a malformed
    // record or config degrades to the module baseline, not an exception.
    return { applied: false, passthrough: true, reason: "no_engine", customer_price: baselineSell, warnings: [] };
  }
}

/**
 * Seam helper — engine-owned economics for a laser source record.
 * Returns null when no laser line carries pricing config (the caller then
 * keeps today's numbers byte-identically); when config resolves the engine
 * owns the sell side — including over a legacy saved customer_pricing
 * snapshot (parity with the F-23a…F-23d channel/vinyl/brick/cnc wires).
 */
export function laserEngineEconomics(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  const res = resolveLaserEngineSell(record, { baselineSell, internalCost, pricingContext, now });
  return res && res.applied === true
    ? { internalCost, customerPrice: res.customer_price, resolution: res }
    : null;
}

/**
 * Convenience — the customer-facing sell price for a laser source record.
 * Returns the engine total when config resolves, else `baselineSell` verbatim
 * (=== passthrough; the byte-identical zero-regression path).
 */
export function laserEngineCustomerPrice(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  const res = resolveLaserEngineSell(record, { baselineSell, internalCost, pricingContext, now });
  return res && res.applied === true ? res.customer_price : baselineSell;
}

/**
 * Detection only — does any laser line on this record carry pricing-engine
 * config? Useful for badges/tests without running the full resolution.
 */
export function laserHasEnginePricing(record) {
  try {
    return laserConfigScan(record).configured === true;
  } catch {
    return false;
  }
}

const num = (v, d = 0) => (Number.isFinite(Number(v)) ? Number(v) : d);

// Hold-Down Advisor — decides whether the item needs enhanced workholding.
export function holdDownAdvice(item) {
  const reasons = [];
  const detail = num(item.smallest_detail_in);
  const cutter = num(item.cutter_diameter_in);
  const loose = item.item_type === "lettering" || item.creates_loose_pieces;
  const base = item.workholding_method || "none";

  if (loose) reasons.push("Cut releases loose pieces at cut-through");
  if (detail > 0 && cutter > 0 && detail < cutter * 2)
    reasons.push(`Fine detail (${detail}") is under 2× cutter diameter`);
  if (["none", "clamps", "screws"].includes(base) && loose)
    reasons.push(`Base workholding (${base.replace("_", " ")}) will not retain small pieces`);
  if (base === "vacuum_full" && detail > 0 && detail < 0.5)
    reasons.push("Vacuum alone loses grip on narrow strokes");

  const needed = item.force_enhanced || reasons.length > 0;
  return {
    needed,
    reasons,
    recommendation: needed
      ? loose
        ? "Add tape-and-glue or onion-skin tabs over the vacuum, and plan a manual release pass."
        : "Add supplemental tape/glue or zoned vacuum before the finish pass."
      : "Base workholding is sufficient.",
    extra_hours: needed ? 0.25 * num(item.quantity, 1) : 0,
  };
}

export function calcCNCProject(project) {
  const machineRate = num(project.machine_rate_per_hour, 75);
  const laborRate = num(project.labor_rate, 45);
  const setupPct = num(project.setup_time_percentage, 20);

  const items = (project.items || []).map((raw) => {
    const item = { ...raw };
    const qty = num(item.quantity, 1);

    let cutHours = 0;
    if (item.item_type === "3d_carving") {
      const rate = num(item.carve_speed_sqipm, 10);
      const passes = Math.max(1, Math.ceil(num(item.carve_depth) / 0.25));
      cutHours = rate > 0 ? (num(item.carve_area_sqin) * passes) / rate / 60 : 0;
    } else {
      const speed = num(item.cut_speed_ipm, 50);
      const perimeter =
        num(item.total_cut_length_inches) ||
        (item.item_type === "lettering"
          ? num(item.num_letters) * num(item.letter_height) * 4
          : (num(item.length) + num(item.width)) * 2);
      cutHours = speed > 0 ? perimeter / speed / 60 : 0;
    }

    const advice = holdDownAdvice(item);
    item.hold_down = advice;
    item.machine_time_hours = cutHours * qty;
    item.setup_time_hours = (item.machine_time_hours * setupPct) / 100 + advice.extra_hours;
    item.machine_cost = item.machine_time_hours * machineRate;
    item.labor_cost = item.setup_time_hours * laborRate;
    item.item_total_cost = item.machine_cost + item.labor_cost;
    return item;
  });

  const total_machine_hours = items.reduce((s, i) => s + i.machine_time_hours, 0);
  const total_machine_cost = items.reduce((s, i) => s + i.machine_cost, 0);
  const fixed_setup_cost = num(project.fixed_setup_hours) * laborRate;
  const total_labor_cost = items.reduce((s, i) => s + i.labor_cost, 0) + fixed_setup_cost;
  const total_setup_hours =
    items.reduce((s, i) => s + i.setup_time_hours, 0) + num(project.fixed_setup_hours);

  return {
    items,
    totals: {
      total_machine_hours,
      total_setup_hours,
      total_machine_cost,
      fixed_setup_cost,
      total_labor_cost,
      total_cost: total_machine_cost + total_labor_cost,
    },
  };
}

// CNC pricing-availability layer.
//
// The live CNC calculator is page-inline in CNCEstimator.jsx (updateItem +
// calculateTotals): item rows store derived snapshots (machine_time_hours,
// setup_time_hours, machine_cost, labor_cost) computed at edit time from the
// project's rates and the Settings rows. This module owns:
//   - strict parsers (cncStrictNumber / cncNonNegativeNumber /
//     cncPositiveNumber); numeric strings accepted, "", "abc", Infinity, NaN,
//     null, undefined rejected.
//   - structured issue records { kind, index, itemIndex, field, code, message,
//     hold } split into authored-input issues (kind "cnc") and settings-side
//     catalog issues (kind "cnc_catalog"). CNC has no catalog entities — the
//     shared Settings rows are the priced surface.
//   - a derived pricing pass (computeCncItemPricing / computeCncTotals) that
//     mirrors the page-inline math byte-identically on the valid path, so
//     totals are recomputed from the CURRENT raw inputs every render — the
//     remote reprice-staleness defect (project-rate edits left stored item
//     snapshots stale) cannot persist stale totals as current.
//   - calcCncPricing: one pass returning { items, totals, issues, held }.
//     Held items keep their raw row but lose every derived number; totals
//     re-derive null-propagating and the page falls back to the saved
//     acknowledged snapshot — never an invented $0.
//   - explicit 0 stays valid where the math treats it as a real free/zero
//     amount (rates, percentages, hour floors); 0 is invalid where the math
//     divides by it or the value silently cancels a priced leg (cut speed,
//     carve speed, letter perimeter factor, material cut multiplier, letter
//     count/height, quantity).
//   - raw rows are never mutated — the derived pass reads the original
//     records exactly as updateItem always consumed them.
//
// Settings consumption split (why some keys are project-scanned, not
// settings-scanned): four keys are copied INTO the project at load
// (cnc_machine_rate → machine_rate_per_hour, cnc_labor_rate → labor_rate,
// cnc_setup_time_percentage → setup_time_percentage, min_cnc_setup_hours →
// fixed_setup_hours) — the CONSUMED value is the project field, so those are
// validated there (also avoids double-flagging one root cause). The rest are
// read live from Settings on every calc and are settings-scanned here.

// ---------- strict parsers ----------
// Finite number or null. Accepts real numbers and trimmed numeric strings;
// rejects "", "abc", Infinity, NaN, null, undefined, objects.
export const cncStrictNumber = (v) => {
  if (typeof v === "number") return Number.isFinite(v) ? v : null;
  if (typeof v === "string") {
    const t = v.trim();
    if (t === "") return null;
    if (!/^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(t)) return null;
    const n = Number(t);
    return Number.isFinite(n) ? n : null;
  }
  return null;
};
export const cncNonNegativeNumber = (v) => {
  const n = cncStrictNumber(v);
  return n !== null && n >= 0 ? n : null;
};
export const cncPositiveNumber = (v) => {
  const n = cncStrictNumber(v);
  return n !== null && n > 0 ? n : null;
};

// A value that was actually recorded on the record — absent/blank/whitespace
// is "not recorded" (settings blank = falls back to the documented default).
const recorded = (v) => v !== undefined && v !== null && !(typeof v === "string" && v.trim() === "");
export const cncSettingRecorded = (settings, key) => recorded(settings?.[key]);
// Strict read of a Settings row: the finite number, or null when the recorded
// value is unusable (malformed/non-finite). Absent also reads null — callers
// distinguish via cncSettingRecorded.
export const cncSettingNumber = (settings, key) => cncStrictNumber(settings?.[key]);

// Saved acknowledged pricing snapshot — only a real finite number counts.
// This is the gate for "Saved amounts (not current pricing)" display.
export const hasCncCostSnapshot = (v) => typeof v === "number" && Number.isFinite(v);

// Blank-preserving input helper for number fields (paint/channel pattern):
// "" stays "" so the input does not fight the user mid-typing; parseable text
// becomes a number; anything else stays raw so validation can flag it instead
// of laundering it into 0 (remote parseFloat||0 silently read "" as 0).
export const cncDraftValue = (raw) => {
  if (raw === "") return "";
  const n = Number(raw);
  return Number.isFinite(n) ? n : raw;
};

// ---------- issue records ----------
const issue = (kind, { index = null, itemIndex = null, field, code, message, hold }) => ({
  kind, index, itemIndex, field, code, message, hold,
});

// ---------- constants mirrored from the page ----------
// These lists describe which keys/fields the page-inline calculator consumes;
// they are NOT new formulas — the formulas stay mirrored in
// computeCncItemPricing / computeCncTotals below.
const CNC_MATERIALS = ["Acrylic", "Wood", "MDF", "Plywood", "PVC", "HDPE", "Aluminum", "Corian"];
const CNC_ITEM_TYPES = ["panel", "lettering", "3d_carving"];
const IMPERIAL_SIZES = ["1/16", "1/8", "3/16", "1/4", "3/8", "1/2", "5/8", "3/4", "7/8", "1", "1-1/4", "1-1/2", "2", "2-1/2", "3", "3-1/2", "4"];
const CUT_SPEED_KEYS = IMPERIAL_SIZES.map((s) => `cnc_cut_speed_${s.replace("/", "_").replace("-", "_")}`);
const CUT_MULTIPLIER_KEYS = CNC_MATERIALS.map((m) => `${m.toLowerCase()}_cnc_cut_multiplier`);

// ---------- settings scan ----------
// Live-consumed Settings rows. Only recorded values can be broken — an absent
// row falls back to the documented module default by design, so it is never an
// issue. Every settings issue holds the whole project calc.
//   positive: true  → recorded value must be > 0 (divisors and factors where
//                     0 silently cancels a priced leg)
//   positive: false → recorded value must be finite and >= 0
const LIVE_SETTINGS = [
  ["cnc_letter_perimeter_factor", "letter perimeter factor", true],
  ["min_cnc_labor_hours", "minimum dynamic labor hours floor", false],
  ...CUT_SPEED_KEYS.map((k) => [k, "cut speed (in/min)", true]),
  ...CUT_MULTIPLIER_KEYS.map((k) => [k, "material cut multiplier", true]),
];

export function cncSettingIssues(settings = {}) {
  const issues = [];
  const add = (field, code, message) =>
    issues.push(issue("cnc_catalog", { field, code, message, hold: "project" }));
  for (const [key, human, positive] of LIVE_SETTINGS) {
    if (!cncSettingRecorded(settings, key)) continue;
    const n = cncStrictNumber(settings[key]);
    if (n === null || (positive ? n <= 0 : n < 0)) {
      add(key, "cnc_setting_unavailable",
        `Setting ${key}: record a finite, ${positive ? "positive" : "nonnegative"} ${human} in CNC Settings — the stored value cannot price this estimate`);
    }
  }
  return issues;
}

// ---------- item-level scan ----------
// Consumed fields on each CNC item. Issues hold the item's derived numbers
// (hold "item") — totals re-derive null because they sum held items.
export function cncItemIssues(rawItem = {}, index = 0) {
  const issues = [];
  const label = `Item ${index + 1}${rawItem?.description ? ` "${rawItem.description}"` : ""}`;
  const add = (field, code, message) =>
    issues.push(issue("cnc", { index, itemIndex: index, field, code, message: `${label}: ${message}`, hold: "item" }));

  // item_type — the cut leg keys on it; anything else silently prices the cut
  // leg as $0 (a stored carve leg can still bill — flagged regardless since
  // the row's type cannot be determined).
  const type = rawItem?.item_type;
  const typeKnown = CNC_ITEM_TYPES.includes(type);
  if (!typeKnown) {
    add("item_type", "cnc_item_type_unavailable",
      "select Panel Cut, Lettering Cut, or 3D Carving — the stored type silently prices the cut leg as $0");
  }
  const cutLeg = type === "panel" || type === "lettering";

  // quantity — consumed as a direct multiplier for every type except
  // lettering (lettering forces qty 1 by design — unconsumed there).
  // Absent/malformed laundered to NaN → silent $0 row in remote totals.
  if (type !== "lettering" && typeKnown) {
    const q = cncStrictNumber(rawItem?.quantity);
    if (q === null || q < 1) {
      add("quantity", "cnc_quantity_unavailable",
        "record a quantity of 1 or more — a blank or malformed value silently zeroes this item's machine time");
    }
  }

  // material_type — drives the <material>_cnc_cut_multiplier Settings key,
  // consumed only on the cut leg (panel/lettering). Unknown/missing resolves
  // to a silent 1× multiplier in remote (parseFloat(undefined)||1.0).
  if (cutLeg) {
    const mt = rawItem?.material_type;
    if (!recorded(mt) || !CNC_MATERIALS.map((m) => m.toLowerCase()).includes(String(mt).toLowerCase())) {
      add("material_type", "cnc_material_unavailable",
        "choose a known material — the stored value silently prices the cut multiplier as 1×");
    }
  }

  if (type === "panel") {
    // length / width — consumed (l + w) * 2. Each must be finite, nonnegative;
    // both at 0 silently prices a $0 panel (no cut perimeter).
    for (const [field, human] of [["length", "length"], ["width", "height"]]) {
      const n = cncStrictNumber(rawItem?.[field]);
      if (n === null || n < 0) {
        add(field, "cnc_dimension_unavailable",
          `record a finite, nonnegative ${human} (inches) — the stored value cannot price the cut perimeter`);
      }
    }
    const l = cncStrictNumber(rawItem?.length);
    const w = cncStrictNumber(rawItem?.width);
    if (l !== null && w !== null && l >= 0 && w >= 0 && l + w === 0) {
      add("length", "cnc_dimension_unavailable",
        "a 0 × 0 panel has no cut perimeter — it silently prices as $0");
    }
  }

  if (type === "lettering") {
    // letter_height × perimeter factor × num_letters — every factor must be
    // positive; a 0 or malformed leg silently prices the letters as $0.
    if (cncPositiveNumber(rawItem?.letter_height) === null) {
      add("letter_height", "cnc_dimension_unavailable",
        "record a positive, finite letter height (inches) — a blank or zero height silently prices the letters as $0");
    }
    if (cncPositiveNumber(rawItem?.num_letters) === null) {
      add("num_letters", "cnc_dimension_unavailable",
        "record a positive, finite letter count — a blank or zero count silently prices the letters as $0");
    }
  }

  // cut_speed_ipm — the divisor on the cut leg. Gated > 0 in remote math, so
  // a 0/blank/malformed stored speed silently drops cut pricing (the
  // thickness preset writes this from cnc_cut_speed_* Settings).
  if (cutLeg && cncPositiveNumber(rawItem?.cut_speed_ipm) === null) {
    add("cut_speed_ipm", "cnc_cut_speed_unavailable",
      "record a positive, finite cut speed (in/min) — a blank or zero speed silently drops cut pricing");
  }

  // carve leg — remote fires it for ANY type whenever carve_area_sqin > 0
  // (the gate is on the fields, not the item type).
  const carveArea = cncStrictNumber(rawItem?.carve_area_sqin);
  if (type === "3d_carving") {
    // For 3D items carving is the ONLY priced leg — both the gated area and
    // the divisor speed must be positive or the item silently prices as $0.
    if (cncPositiveNumber(rawItem?.carve_area_sqin) === null) {
      add("carve_area_sqin", "cnc_dimension_unavailable",
        "record a positive, finite carve area (in²) — a blank or zero area silently prices the carving as $0");
    }
    if (cncPositiveNumber(rawItem?.carve_speed_sqipm) === null) {
      add("carve_speed_sqipm", "cnc_carve_speed_unavailable",
        "record a positive, finite carve speed (in²/min) — a blank or zero speed silently drops carve pricing");
    }
  } else {
    // Non-3D: a recorded malformed/negative carve area is silently ignored by
    // the > 0 gate; an authored positive area still needs a positive speed.
    if (recorded(rawItem?.carve_area_sqin) && (carveArea === null || carveArea < 0)) {
      add("carve_area_sqin", "cnc_dimension_unavailable",
        "the stored carve area is malformed or negative — it is silently ignored; fix it or clear it");
    }
    if (carveArea !== null && carveArea > 0 && cncPositiveNumber(rawItem?.carve_speed_sqipm) === null) {
      add("carve_speed_sqipm", "cnc_carve_speed_unavailable",
        "a stored carve area is priced only with a positive, finite carve speed — the stored speed silently drops it");
    }
  }

  return issues;
}

// ---------- project-level scan ----------
// The four rate fields the calculator consumes from the project. They are
// seeded from CNC Settings at load (malformed settings land as null and flag
// here — one flag site per consumed value) and edited directly on the page.
// ≥0 throughout: an explicit 0 is a legitimate authored "no charge" rate.
export function cncProjectInputIssues(project = {}) {
  const issues = [];
  const add = (field, code, message) =>
    issues.push(issue("cnc", { field, code, message, hold: "project" }));

  // items must be an array — the derived pass maps it verbatim.
  if (project?.items !== undefined && !Array.isArray(project.items)) {
    add("items", "cnc_items_unavailable",
      "the stored CNC items are malformed — the project cannot be repriced");
  }

  for (const [field, human] of [
    ["machine_rate_per_hour", "machine rate ($/hr)"],
    ["labor_rate", "labor rate ($/hr)"],
    ["setup_time_percentage", "setup time percentage (%)"],
    ["fixed_setup_hours", "fixed setup hours"],
  ]) {
    if (cncNonNegativeNumber(project?.[field]) === null) {
      add(field, "cnc_project_rate_unavailable",
        `record a finite, nonnegative ${human} — fix the project value or the CNC Settings value it was seeded from; the stored value cannot price this estimate`);
    }
  }
  return issues;
}

// ---------- derived pricing (mirrors the page-inline math) ----------
// computeCncItemPricing reproduces updateItem's derived-field math exactly on
// the valid path — same formulas, strict-normalized reads. Malformed reads
// resolve to 0 here but are always flagged by the scanners above, so the
// derived output for a tainted row is discarded under the hold.
const num = (v) => cncStrictNumber(v) ?? 0;
// Live Settings read with documented fallback: absent → the module default;
// recorded-malformed → null-safe 0 internally (flagged by cncSettingIssues,
// discarded under the project hold).
const settingOr = (settings, key, dflt) =>
  cncSettingRecorded(settings, key) ? (cncSettingNumber(settings, key) ?? 0) : dflt;

export function computeCncItemPricing(item = {}, project = {}, settings = {}) {
  const letterPerimFactor = settingOr(settings, "cnc_letter_perimeter_factor", 3.5);

  let cutLength = 0;
  if (item?.item_type === "panel") {
    cutLength = (num(item.length) + num(item.width)) * 2;
  } else if (item?.item_type === "lettering") {
    cutLength = num(item.letter_height) * letterPerimFactor * num(item.num_letters);
  }

  // Remote derives the key via item.material_type.toLowerCase(); String()
  // keeps the same resolution without throwing on a missing material.
  const materialCutMultiplierKey = `${String(item?.material_type ?? "").toLowerCase()}_cnc_cut_multiplier`;
  const cutMultiplier = settingOr(settings, materialCutMultiplierKey, 1.0);

  const cutSpeed = num(item?.cut_speed_ipm);
  const carveArea = num(item?.carve_area_sqin);
  const carveSpeed = num(item?.carve_speed_sqipm);
  // Lettering forces qty 1 — "Number of Letters" IS the quantity.
  const qty = item?.item_type === "lettering" ? 1 : num(item?.quantity);

  const cutTimeMinutes = cutLength > 0 && cutSpeed > 0
    ? (cutLength / cutSpeed) * cutMultiplier : 0;
  const carveTimeMinutes = carveArea > 0 && carveSpeed > 0
    ? carveArea / carveSpeed : 0;
  const machineTimeHours = ((cutTimeMinutes + carveTimeMinutes) * qty) / 60;
  const setupTimeHours = machineTimeHours * (num(project?.setup_time_percentage) / 100);

  return {
    machine_time_hours: machineTimeHours,
    setup_time_hours: setupTimeHours,
    machine_cost: machineTimeHours * num(project?.machine_rate_per_hour),
    labor_cost: setupTimeHours * num(project?.labor_rate),
  };
}

// computeCncTotals reproduces the page-inline calculateTotals exactly on the
// valid path, over DERIVED item costs (fresh every render — stored snapshots
// can never go stale against the project rates).
export function computeCncTotals(derivedItems = [], project = {}, settings = {}) {
  const laborRate = num(project?.labor_rate);
  const totalMachineCost = derivedItems.reduce((sum, item) => sum + num(item.machine_cost), 0);
  const dynamicLaborFromItems = derivedItems.reduce((sum, item) => sum + num(item.labor_cost), 0);
  const totalSetupHours = derivedItems.reduce((sum, item) => sum + num(item.setup_time_hours), 0);
  const fixedSetupCost = num(project?.fixed_setup_hours) * laborRate;
  const minLaborHours = settingOr(settings, "min_cnc_labor_hours", 0);

  // Source behavior: minimum applies only to the dynamic item setup portion,
  // while fixed setup remains additive.
  const effectiveDynamicLabor = totalSetupHours > 0 && totalSetupHours < minLaborHours
    ? minLaborHours * laborRate
    : dynamicLaborFromItems;
  const minimumDynamicLaborAdjustment = effectiveDynamicLabor - dynamicLaborFromItems;
  const totalLaborCost = fixedSetupCost + effectiveDynamicLabor;

  return {
    totalMachine: totalMachineCost,
    totalLabor: totalLaborCost,
    totalSetupHours,
    dynamicLaborFromItems,
    fixedSetupCost,
    minLaborHours,
    minimumDynamicLaborAdjustment,
  };
}

// ---------- calc wrapper ----------
// Returns { items, totals, issues, held }. items = raw rows plus derived
// pricing fields (machine_time_hours, setup_time_hours, machine_cost,
// labor_cost). When held, every derived number a flagged input could have
// tainted is null — saved acknowledged totals on the record are the display
// fallback, never an invented $0. Raw rows are untouched.
const ITEM_HELD_FIELDS = ["machine_time_hours", "setup_time_hours", "machine_cost", "labor_cost"];
const NULL_TOTALS = {
  totalMachine: null,
  totalLabor: null,
  totalSetupHours: null,
  dynamicLaborFromItems: null,
  fixedSetupCost: null,
  minLaborHours: null,
  minimumDynamicLaborAdjustment: null,
};

export function calcCncPricing(project = {}, settings = {}) {
  const issues = [
    ...cncSettingIssues(settings),
    ...((Array.isArray(project?.items) ? project.items : [])
      .flatMap((item, index) => cncItemIssues(item, index))),
    ...cncProjectInputIssues(project),
  ];

  const held = issues.length > 0;
  const rawItems = Array.isArray(project?.items) ? project.items : [];
  const hasProjectHold = issues.some((i) => i.hold === "project");
  const itemHolds = new Set(issues.filter((i) => i.hold === "item").map((i) => i.itemIndex));

  const items = rawItems.map((item, index) => {
    if (hasProjectHold || itemHolds.has(index)) {
      const heldItem = { ...item };
      for (const field of ITEM_HELD_FIELDS) heldItem[field] = null;
      return heldItem;
    }
    return { ...item, ...computeCncItemPricing(item, project, settings) };
  });

  const totals = held ? { ...NULL_TOTALS } : computeCncTotals(items, project, settings);

  return {
    items,
    totals,
    issues,
    held,
    __held: held,
    pricingUnavailable: held,
  };
}

// ---------- UI helpers ----------
// All issues attached to a single field (optionally a single item row).
export const issuesForField = (issues = [], field, itemIndex = null) =>
  issues.filter((i) => i.field === field && (itemIndex === null || i.itemIndex === itemIndex));
export const hasIssueFor = (issues = [], field, itemIndex = null) =>
  issuesForField(issues, field, itemIndex).length > 0;

// CNC sell-price engine wire (F-23d) — module-side glue.
//
// The shared wire (base44/shared/cncPricingWire.ts) is intentionally
// import-free; this file is the composition root that injects the real engine
// functions and merges caller-supplied registries with the record-embedded
// engine context. Wired into customerPricing.sourceProjectEconomics for
// module_key "cnc" — when no CNC line carries pricing-engine config the
// resolution is a passthrough and the module sell price is returned verbatim
// (zero regression).
//
// Registry context (`pricingContext`) is OPTIONAL today: config embedded on
// the record/items (item pricing fields, engine_pricing blocks, embedded
// templates/tier rules) resolves without any entity reads. Callers that have
// PricingTierMatrix / PricingTemplate / GlobalPricingTier / MarkupTier rows
// loaded may pass them as { tierRules|tier_rules, templates, tiers,
// customerTier|customer_tier, defaultMarkupPct|default_markup_pct, now } to
// unlock registry-backed tier/template references.

import { pricePart, matrixRowsToRules } from "../../../../base44/shared/pricingEngine.ts";
import { resolveTemplatePrice, templatePartDescriptor } from "../../../../base44/shared/pricingTemplateModel.ts";
import {
  resolveCncSellPricing,
  cncConfigScan,
  cncPricingContextOf,
} from "../../../../base44/shared/cncPricingWire.ts";

const ENGINE = Object.freeze({ pricePart, resolveTemplatePrice, templatePartDescriptor });

/**
 * Full resolution — engine-priced sell for config-carrying CNC lines.
 * Never throws: malformed input/config degrades to a passthrough result.
 *
 * @param {object} record       CNCProject-like record
 * @param {object} opts
 * @param {number} opts.baselineSell  module sell price (record.total_cost)
 * @param {number} [opts.internalCost] module internal cost (record.total_cost)
 * @param {object} [opts.pricingContext] caller-loaded registries (optional)
 * @param {*}      [opts.now]    effective-window override (tests)
 * @returns {object} resolveCncSellPricing result ({applied, customer_price,
 *          passthrough, lines, chain, warnings, ...})
 */
export function resolveCncEngineSell(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  try {
    const caller = pricingContext && typeof pricingContext === "object" ? { ...pricingContext } : {};
    // Normalize caller chart rows through the engine's entity adapter so
    // PricingTierMatrix spellings (unit_breaks aliases, status windows) resolve
    // exactly like the pricing admin path.
    const rawRules = caller.tierRules ?? caller.tier_rules ?? caller.tier_matrix;
    if (Array.isArray(rawRules) && rawRules.length) {
      caller.tierRules = matrixRowsToRules(rawRules, { now: caller.now ?? now });
    }
    const context = cncPricingContextOf(record, caller);
    return resolveCncSellPricing({ record, baselineSell, internalCost, context, engine: ENGINE, now });
  } catch {
    // The sell-price seam must never break estimate rendering — a malformed
    // record or config degrades to the module baseline, not an exception.
    return { applied: false, passthrough: true, reason: "no_engine", customer_price: baselineSell, warnings: [] };
  }
}

/**
 * Seam helper — engine-owned economics for a CNC source record.
 * Returns null when no CNC line carries pricing config (the caller then
 * keeps today's numbers byte-identically); when config resolves the engine
 * owns the sell side — including over a legacy saved customer_pricing
 * snapshot (parity with the F-23a/F-23b channel+vinyl wires).
 */
export function cncEngineEconomics(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  const res = resolveCncEngineSell(record, { baselineSell, internalCost, pricingContext, now });
  return res && res.applied === true
    ? { internalCost, customerPrice: res.customer_price, resolution: res }
    : null;
}

/**
 * Convenience — the customer-facing sell price for a CNC source record.
 * Returns the engine total when config resolves, else `baselineSell` verbatim
 * (=== passthrough; the byte-identical zero-regression path).
 */
export function cncEngineCustomerPrice(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  const res = resolveCncEngineSell(record, { baselineSell, internalCost, pricingContext, now });
  return res && res.applied === true ? res.customer_price : baselineSell;
}

/**
 * Detection only — does any CNC line on this record carry pricing-engine
 * config? Useful for badges/tests without running the full resolution.
 */
export function cncHasEnginePricing(record) {
  try {
    return cncConfigScan(record).configured === true;
  } catch {
    return false;
  }
}

