export default function AddProductGrid({ counts = EMPTY_COUNTS, onAdd, onAddCustom, onAddQuickProduct, onAddKit, className = "" }) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState(() => {
    try { return new URLSearchParams(window.location.search).get("q") || ""; } catch { return ""; }
  });
  const [addingKey, setAddingKey] = useState(null);
  const [customNameOpen, setCustomNameOpen] = useState(false);
  const [customName, setCustomName] = useState("Custom Product");
  const [quickProducts, setQuickProducts] = useState([]);
  const [quickLoading, setQuickLoading] = useState(false);
  const [quickError, setQuickError] = useState("");
  const [kits, setKits] = useState([]);
  const [kitsError, setKitsError] = useState("");
  const [actionError, setActionError] = useState("");
  const searchRef = useRef(null);
  const actionRef = useRef(false);

  useEffect(() => {
    if (!open) {
      setQuery("");
      return;
    }
    const timer = setTimeout(() => searchRef.current?.focus(), 80);
    setQuickLoading(true);
    setQuickError("");
    setActionError("");
    setQuickProducts([]);
    listQuickProducts()
      .then((rows) => setQuickProducts(rows || []))
      .catch((error) => setQuickError(error?.message || "Quick Product Library could not be verified."))
      .finally(() => setQuickLoading(false));
    listInventoryKits()
      .then((rows) => setKits(rows || []))
      .catch(() => setKitsError("Inventory kits could not be loaded."));
    return () => clearTimeout(timer);
  }, [open]);

  const customMatches = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return true;
    const haystack = "blank custom product manual parts inventory build your own product";
    return q.split(/\s+/).every((term) => haystack.includes(term));
  }, [query]);

  const quickResults = useMemo(() => {
    const q = query.trim().toLowerCase();
    return quickProducts.filter((product) => {
      if (!q) return true;
      const haystack = [
        product.product_name,
        product.source_builder_name,
        product.source_module_key,
        product.product_category,
        product.production_product_type,
        ...(product.categories || []),
      ].filter(Boolean).join(" ").toLowerCase();
      return q.split(/\s+/).every((term) => haystack.includes(term));
    });
  }, [quickProducts, query]);

  const results = useMemo(() => {
    const q = query.trim().toLowerCase();
    const registryOrder = Object.fromEntries(ESTIMATOR_MODULES.map((m, i) => [m.key, i]));

    return ESTIMATOR_MODULES.filter((mod) => {
      if (!q) return true;
      const meta = getMeta(mod.key);
      const haystack = `${mod.label} ${mod.key} ${meta.blurb} ${meta.keywords}`.toLowerCase();
      return q.split(/\s+/).every((term) => haystack.includes(term));
    }).sort((a, b) => {
      if (q) return registryOrder[a.key] - registryOrder[b.key];
      const countDiff = Number(counts[b.key] || 0) - Number(counts[a.key] || 0);
      return countDiff || registryOrder[a.key] - registryOrder[b.key];
    });
  }, [query, counts]);

  const handleAdd = async (mod) => {
    if (!mod || actionRef.current) return;
    actionRef.current = true;
    setAddingKey(mod.key);
    setActionError("");
    try {
      await onAdd(mod);
      setOpen(false);
    } catch (error) {
      setActionError(error?.message || "Product could not be added.");
    } finally {
      actionRef.current = false;
      setAddingKey(null);
    }
  };

  const beginCustom = () => {
    if (addingKey) return;
    setOpen(false);
    setCustomName("Custom Product");
    setCustomNameOpen(true);
  };

  const handleAddCustom = async () => {
    if (actionRef.current) return;
    actionRef.current = true;
    setAddingKey("custom");
    setActionError("");
    try {
      await onAddCustom?.(customName.trim() || "Custom Product");
      setCustomNameOpen(false);
    } catch (error) {
      setActionError(error?.message || "Custom Product could not be created.");
    } finally {
      actionRef.current = false;
      setAddingKey(null);
    }
  };

  const handleAddQuick = async (quickProduct) => {
    if (!quickProduct?.id || quickError || actionRef.current) return;
    actionRef.current = true;
    setAddingKey(`quick:${quickProduct.id}`);
    setActionError("");
    try {
      await onAddQuickProduct?.(quickProduct);
      setOpen(false);
    } catch (error) {
      setActionError(error?.message || "Quick Product could not be added.");
    } finally {
      actionRef.current = false;
      setAddingKey(null);
    }
  };

  const kitResults = useMemo(() => {
    const q = query.trim().toLowerCase();
    return kits.filter((kit) => {
      if (!q) return true;
      const haystack = ["kit", kitLabel(kit), kit.supplier, kit.notes, kit.material_type, kit.product_type].filter(Boolean).join(" ").toLowerCase();
      return q.split(/\s+/).every((term) => haystack.includes(term));
    });
  }, [kits, query]);

  const handleAddKit = async (kit) => {
    if (!kit?.id || typeof onAddKit !== "function" || actionRef.current) return;
    actionRef.current = true;
    setAddingKey(`kit:${kit.id}`);
    setActionError("");
    try {
      await onAddKit(kit);
      setOpen(false);
    } catch (error) {
      setActionError(error?.message || "Kit could not be added.");
    } finally {
      actionRef.current = false;
      setAddingKey(null);
    }
  };

  const handleSearchKeyDown = (event) => {
    const totalMatches = results.length + quickResults.length + (customMatches ? 1 : 0);
    if (event.key !== "Enter" || totalMatches !== 1 || addingKey) return;
    event.preventDefault();
    if (customMatches) beginCustom();
    else if (results.length === 1) handleAdd(results[0]);
    else handleAddQuick(quickResults[0]);
  };

  const usedCount = ESTIMATOR_MODULES.filter((mod) => Number(counts[mod.key] || 0) > 0).length;

  return (
    <>
      <button
        type="button"
        onClick={() => setOpen(true)}
        className={`h-[32px] px-3 inline-flex items-center gap-1.5 rounded-sm border border-gray-700 bg-[#454545] text-white text-[12px] font-semibold shadow-sm hover:bg-[#353535] active:translate-y-px ${className}`}
      >
        <Plus className="w-3.5 h-3.5 text-lime-300" aria-hidden="true" />
        Add Product
      </button>

      <Dialog open={open} onOpenChange={(next) => !addingKey && setOpen(next)}>
        <DialogContent className="sm:max-w-[900px] p-0 overflow-hidden gap-0 border-gray-300 shadow-2xl">
          <DialogHeader className="px-5 pt-5 pb-4 bg-gradient-to-r from-slate-950 to-slate-800 text-white border-b border-slate-700">
            <div className="flex items-start gap-3 pr-8">
              <div className="w-10 h-10 rounded-md bg-lime-300 text-slate-950 flex items-center justify-center shadow-sm flex-shrink-0">
                <PackagePlus className="w-5 h-5" aria-hidden="true" />
              </div>
              <div className="min-w-0">
                <DialogTitle className="text-[18px] font-bold text-white leading-tight">Find a Product</DialogTitle>
                <p className="mt-1 text-[11px] text-slate-300 font-normal">
                  Search by product type, material, process or service. Select a result to build it directly inside this estimate.
                </p>
              </div>
            </div>

            <div className="relative mt-4">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" aria-hidden="true" />
              <input
                ref={searchRef}
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                onKeyDown={handleSearchKeyDown}
                aria-label="Search products"
                placeholder="Search products — try acrylic, graphics, masonry, service, letters..."
                className="w-full h-[42px] pl-10 pr-4 rounded-md bg-white text-[13px] text-gray-900 placeholder:text-gray-400 border border-white/20 shadow-inner outline-none focus:ring-2 focus:ring-lime-300"
              />
            </div>
          </DialogHeader>

          <div className="bg-white">
            <div className="px-5 py-2.5 border-b border-gray-100 flex items-center justify-between gap-3 bg-gray-50/80">
              <div className="flex items-center gap-2 min-w-0">
                <Sparkles className="w-3.5 h-3.5 text-lime-600 flex-shrink-0" aria-hidden="true" />
                <span className="text-[11px] font-semibold text-gray-700">
                  {query ? `${results.length + quickResults.length + (customMatches ? 1 : 0)} matching product${results.length + quickResults.length + (customMatches ? 1 : 0) === 1 ? "" : "s"}` : "Blank Products, Builders & Quick Products"}
                </span>
                {!query && usedCount > 0 && (
                  <span className="text-[10px] text-gray-400">• types already used on this estimate are shown first</span>
                )}
              </div>
              <span className="text-[10px] text-gray-400 whitespace-nowrap">{ESTIMATOR_MODULES.length} builders · {quickProducts.length} Quick Products</span>
            </div>

            <div className="p-3 max-h-[520px] overflow-y-auto">
              {actionError && <div role="alert" className="mb-3 rounded border border-red-200 bg-red-50 px-3 py-2 text-[10px] text-red-700">{actionError}</div>}
              {quickError && <div role="alert" className="mb-3 rounded border border-amber-200 bg-amber-50 px-3 py-2 text-[10px] text-amber-800"><strong>Quick Products unavailable.</strong> {quickError} Builders and Blank / Custom Product remain available.</div>}
              {!customMatches && results.length === 0 && quickResults.length === 0 && !quickLoading ? (
                <div className="py-14 px-6 text-center">
                  <div className="mx-auto w-11 h-11 rounded-full bg-gray-100 flex items-center justify-center mb-3">
                    <Search className="w-5 h-5 text-gray-400" aria-hidden="true" />
                  </div>
                  <div className="text-[13px] font-bold text-gray-800">No products found</div>
                  <p className="mt-1 text-[11px] text-gray-500">
                    Try a broader term such as "vinyl," "metal," "service," "letters," or "concrete."
                  </p>
                  <button
                    type="button"
                    onClick={() => setQuery("")}
                    className="mt-4 h-[30px] px-3 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-700 hover:bg-gray-50"
                  >
                    Clear search
                  </button>
                </div>
              ) : (
                <div className="space-y-3">
                  {customMatches && (
                    <button
                      type="button"
                      disabled={!!addingKey}
                      onClick={beginCustom}
                      className="w-full text-left border-2 border-lime-300 rounded-md p-4 bg-lime-50/70 hover:bg-lime-100/80 hover:border-lime-500 transition-all shadow-sm disabled:opacity-60 disabled:cursor-wait"
                    >
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-md bg-[#454545] text-lime-300 flex items-center justify-center"><PackagePlus className="w-5 h-5" aria-hidden="true" /></div>
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-2"><span className="text-[13px] font-extrabold text-gray-900">Blank / Custom Product</span><span className="text-[9px] px-2 py-0.5 rounded bg-lime-200 border border-lime-300 text-gray-700 font-bold">BUILD FROM PARTS</span></div>
                          <p className="mt-1 text-[10px] text-gray-600">Name the Product yourself and add any Parts directly from the Master Inventory. No dedicated Builder is attached.</p>
                          <div className="mt-2 text-[10px] font-bold text-gray-800 inline-flex items-center gap-1">{addingKey === "custom" ? "Creating product…" : "Create blank product"}{addingKey !== "custom" && <ArrowRight className="w-3 h-3" aria-hidden="true" />}</div>
                        </div>
                      </div>
                    </button>
                  )}
                  {results.length > 0 && (
                  <div>
                    <div className="text-[9px] font-extrabold tracking-widest text-gray-400 px-1 pb-1.5">BUILDERS</div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                  {results.map((mod) => {
                    const meta = getMeta(mod.key);
                    const Icon = meta.icon;
                    const count = Number(counts[mod.key] || 0);
                    const adding = addingKey === mod.key;

                    return (
                      <button
                        type="button"
                        key={mod.key}
                        disabled={!!addingKey}
                        onClick={() => handleAdd(mod)}
                        className={`group min-h-[92px] text-left border rounded-md p-3 transition-all shadow-sm hover:shadow-md disabled:opacity-60 disabled:cursor-wait ${meta.accent}`}
                      >
                        <div className="flex items-start gap-3 h-full">
                          <div className={`w-9 h-9 rounded-md flex items-center justify-center flex-shrink-0 ${meta.iconBg}`}>
                            <Icon className={`w-[18px] h-[18px] ${meta.color}`} aria-hidden="true" />
                          </div>

                          <div className="min-w-0 flex-1">
                            <div className="flex items-center gap-2">
                              <span className="text-[12px] font-bold text-gray-900 truncate">{mod.label}</span>
                              {count > 0 && (
                                <span className="px-1.5 py-0.5 rounded bg-white border border-gray-200 text-[9px] font-semibold text-gray-500 whitespace-nowrap">
                                  {count} in estimate
                                </span>
                              )}
                            </div>
                            <p className="mt-1 text-[10px] leading-[1.45] text-gray-500 line-clamp-2">{meta.blurb}</p>
                            <div className="mt-2 flex items-center gap-1 text-[10px] font-bold text-gray-700 group-hover:text-gray-950">
                              {adding ? "Adding product…" : "Add to estimate"}
                              {!adding && <ArrowRight className="w-3 h-3 transition-transform group-hover:translate-x-0.5" aria-hidden="true" />}
                            </div>
                          </div>
                        </div>
                      </button>
                    );
                  })}
                    </div>
                  </div>
                  )}

                  {!quickError && (quickLoading || quickResults.length > 0) && (
                    <div>
                      <div className="text-[9px] font-extrabold tracking-widest text-gray-400 px-1 pb-1.5 flex items-center justify-between">
                        <span>QUICK PRODUCTS</span>
                        <span className="font-medium normal-case tracking-normal">{quickLoading ? "Loading…" : `${quickResults.length} available`}</span>
                      </div>
                      {quickLoading ? (
                        <div role="status" className="rounded border border-gray-200 bg-gray-50 px-3 py-6 text-center text-[11px] text-gray-400">Loading Quick Products…</div>
                      ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                          {quickResults.map((product) => {
                            const adding = addingKey === `quick:${product.id}`;
                            const builderLabel = product.source_product_class === "builder"
                              ? (product.source_builder_name || "Builder Product")
                              : product.source_product_class === "legacy"
                                ? "Legacy Quick Product"
                                : "Custom Product";
                            const quickQuantity = Math.max(0, Number(product.product_quantity ?? 1) || 0);
                            const quickUnitPrice = Number(product.price_snapshot?.frozen_cost ?? 0);
                            const quickExtendedPrice = product.total_price !== undefined && product.total_price !== null
                              ? Number(product.total_price || 0)
                              : quickUnitPrice * quickQuantity;
                            return (
                              <button
                                type="button"
                                key={product.id}
                                disabled={!!addingKey}
                                onClick={() => handleAddQuick(product)}
                                className="group min-h-[86px] text-left border border-cyan-200 rounded-md p-3 bg-cyan-50/40 hover:border-cyan-400 hover:bg-cyan-50 transition-all shadow-sm hover:shadow-md disabled:opacity-60 disabled:cursor-wait"
                              >
                                <div className="flex items-start gap-3">
                                  <div className="w-9 h-9 rounded-md bg-cyan-100 text-cyan-700 flex items-center justify-center flex-shrink-0"><PackagePlus className="w-[18px] h-[18px]" aria-hidden="true" /></div>
                                  <div className="min-w-0 flex-1">
                                    <div className="flex items-center gap-2">
                                      <span className="text-[12px] font-bold text-gray-900 truncate">{product.product_name}</span>
                                      <span className="text-[9px] px-1.5 py-0.5 rounded border border-cyan-200 bg-white text-cyan-700 font-semibold">{product.product_group === "global" ? "GLOBAL" : "MY"}</span>
                                    </div>
                                    <div className="mt-1 text-[10px] text-gray-500 truncate">{builderLabel}{product.product_category ? ` · ${product.product_category}` : ""}{product.production_product_type ? ` · Production: ${product.production_product_type}` : ""}</div>
                                    <div className="mt-1 flex items-center justify-between gap-2">
                                      <span className="text-[9px] text-gray-400 truncate">{(product.categories || []).join(" · ") || "Uncategorized"}</span>
                                      <div className="text-right flex-shrink-0">
                                        <div className="text-[11px] font-bold text-gray-800">{money(quickExtendedPrice)}</div>
                                        {quickQuantity !== 1 && quickUnitPrice > 0 && <div className="text-[8px] text-gray-400">{quickQuantity} × {money(quickUnitPrice)}</div>}
                                      </div>
                                    </div>
                                    <div className="mt-1.5 flex items-center gap-1 text-[10px] font-bold text-gray-700 group-hover:text-gray-950">{adding ? "Adding Quick Product…" : "Add Quick Product"}{!adding && <ArrowRight className="w-3 h-3" aria-hidden="true" />}</div>
                                  </div>
                                </div>
                              </button>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              )}
              {typeof onAddKit === "function" && kitResults.length > 0 && (
                <div>
                  <div className="text-[9px] font-extrabold tracking-widest text-gray-400 px-1 pb-1.5 pt-3 flex items-center justify-between">
                    <span>INVENTORY KITS</span>
                    <span className="font-medium normal-case tracking-normal">{kitsError || `${kitResults.length} available`}</span>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                    {kitResults.map((kit) => {
                      const adding = addingKey === `kit:${kit.id}`;
                      const kitPrice = Number.isFinite(Number(kit.kit_price)) && Number(kit.kit_price) > 0 ? Number(kit.kit_price) : null;
                      return (
                        <button
                          type="button"
                          key={kit.id}
                          disabled={!!addingKey}
                          onClick={() => handleAddKit(kit)}
                          className="group min-h-[74px] text-left border border-violet-200 rounded-md p-3 bg-violet-50/40 hover:border-violet-400 hover:bg-violet-50 transition-all shadow-sm hover:shadow-md disabled:opacity-60 disabled:cursor-wait"
                        >
                          <div className="flex items-start gap-3">
                            <div className="w-9 h-9 rounded-md bg-violet-100 text-violet-700 flex items-center justify-center flex-shrink-0"><PackagePlus className="w-[18px] h-[18px]" aria-hidden="true" /></div>
                            <div className="min-w-0 flex-1">
                              <div className="flex items-center gap-2">
                                <span className="text-[12px] font-bold text-gray-900 truncate">{kitLabel(kit)}</span>
                                <span className="text-[9px] px-1.5 py-0.5 rounded border border-violet-200 bg-white text-violet-700 font-semibold">KIT</span>
                              </div>
                              <div className="mt-1 text-[10px] text-gray-500 truncate">{(kit.kit_items || []).length} component{(kit.kit_items || []).length === 1 ? "" : "s"} — expands into Parts on add</div>
                              <div className="mt-1.5 flex items-center justify-between gap-2">
                                <span className="flex items-center gap-1 text-[10px] font-bold text-gray-700 group-hover:text-gray-950">{adding ? "Adding kit…" : "Add kit"}{!adding && <ArrowRight className="w-3 h-3" aria-hidden="true" />}</span>
                                <span className="text-[11px] font-bold text-gray-800">{kitPrice !== null ? money(kitPrice) : "Σ parts"}</span>
                              </div>
                            </div>
                          </div>
                        </button>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>

            <div className="px-5 py-2.5 border-t border-gray-100 bg-gray-50 flex items-center justify-between gap-3">
              <span className="text-[10px] text-gray-400">Tip: when one search result remains, press Enter to add it.</span>
              <button
                type="button"
                disabled={!!addingKey}
                onClick={() => setOpen(false)}
                className="h-[28px] px-3 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-600 hover:bg-gray-100 disabled:opacity-50"
              >
                Cancel
              </button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      <Dialog open={customNameOpen} onOpenChange={(next) => !addingKey && setCustomNameOpen(next)}>
        <DialogContent className="sm:max-w-[520px] p-0 overflow-hidden border-gray-300 shadow-xl">
          <DialogHeader className="px-5 py-4 bg-[#424242] text-white border-b-4 border-lime-300">
            <DialogTitle className="text-white text-[16px] flex items-center gap-2"><PackagePlus className="w-5 h-5 text-lime-300" aria-hidden="true" /> Create Blank / Custom Product</DialogTitle>
            <p className="text-[11px] text-gray-300 mt-1">Give the Product its client-facing name. You can add and group Master Inventory Parts immediately afterward.</p>
          </DialogHeader>
          <form onSubmit={(event) => { event.preventDefault(); handleAddCustom(); }} className="p-5 bg-white space-y-4">
            <label className="text-[10px] font-bold tracking-wide text-gray-500 block">PRODUCT NAME
              <input autoFocus value={customName} onChange={(event) => setCustomName(event.target.value)} className="mt-1 w-full h-[36px] px-3 border border-gray-300 rounded text-[13px]" placeholder="e.g. Worship Center Circle Sign" />
            </label>
            <div className="rounded border border-lime-200 bg-lime-50 px-3 py-2 text-[10px] text-gray-700">This Product has no dedicated Builder. Its price is the sum of its Parts, with frozen Master Inventory snapshots and explicit Update Price control.</div>
            <div className="flex justify-end gap-2">
              <button type="button" disabled={!!addingKey} onClick={() => setCustomNameOpen(false)} className="h-[32px] px-4 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-600">Cancel</button>
              <button type="submit" disabled={!!addingKey || !customName.trim()} className="min-h-[44px] px-4 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 disabled:opacity-50">{addingKey === "custom" ? "Creating…" : "Create Product"}</button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { Layers, Link2, Save, RefreshCw, Copy, GitMerge, PencilLine } from "lucide-react";

export default function AioEstimateHeader({
  status = "draft",
  quoteTotal = 0,
  onSave,
  saving,
  title = "New All-In-One Estimate",
  subtitle = "One page, one set of project info, every estimator.",
  metaRight,
  readOnly = false,
  onEdit = null,
  editStarting = false,
  onDuplicate,
  duplicating = false,
  onMerge,
}) {
  return (
    <div className="bg-white border border-gray-200 rounded-md m-3 px-4 py-3 flex items-center justify-between">
      <div className="flex items-start gap-2">
        <Layers className="w-5 h-5 text-gray-700 mt-0.5" aria-hidden="true" />
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-[17px] font-bold text-gray-900">{title}</h1>
            <span className="text-[11px] px-2 py-0.5 rounded bg-gray-100 text-gray-600 border border-gray-200">
              {status}
            </span>
            <span className="w-2 h-2 rounded-full bg-yellow-400" aria-hidden="true" />
          </div>
          <p className="text-[11px] text-gray-400">
            {subtitle}
            {metaRight ? <span className="ml-1 text-gray-300">· {metaRight}</span> : null}
          </p>
        </div>
      </div>

      <div className="flex items-center gap-3">
        <div className="text-right">
          <div className="text-[9px] font-bold tracking-widest text-gray-400">QUOTE TOTAL</div>
          <div className="text-[20px] font-bold text-green-600">
            ${Number(quoteTotal || 0).toFixed(2)}
          </div>
        </div>
        <button type="button" aria-label="Refresh" title="Refresh" className="w-9 h-9 border border-gray-200 rounded flex items-center justify-center text-gray-500 hover:bg-gray-50">
          <RefreshCw className="w-4 h-4" aria-hidden="true" />
        </button>
        <button
          type="button"
          onClick={() => navigator.clipboard?.writeText(window.location.href)}
          title="Copy estimate link"
          aria-label="Copy estimate link"
          className="w-9 h-9 border border-gray-200 rounded flex items-center justify-center text-gray-500 hover:bg-gray-50"
        >
          <Link2 className="w-4 h-4" aria-hidden="true" />
        </button>
        {onMerge && !readOnly && (
          <button
            type="button"
            onClick={onMerge}
            title="Merge another draft estimate into this one"
            aria-label="Merge another estimate"
            className="w-9 h-9 border border-gray-200 rounded flex items-center justify-center text-gray-500 hover:bg-gray-50"
          >
            <GitMerge className="w-4 h-4" aria-hidden="true" />
          </button>
        )}
        {onDuplicate && (
          <button type="button"
            onClick={onDuplicate}
            disabled={duplicating}
            title="Duplicate this estimate as a new draft"
            aria-label="Duplicate this estimate as a new draft"
            className="w-9 h-9 border border-gray-200 rounded flex items-center justify-center text-gray-500 hover:bg-gray-50 disabled:opacity-50"
          >
            <Copy className="w-4 h-4" aria-hidden="true" />
          </button>
        )}
        {readOnly && onEdit ? (
          <button type="button"
            onClick={onEdit}
            disabled={editStarting}
            aria-busy={editStarting}
            aria-live="polite"
            title="Open a recorded revision and edit this estimate"
            className="h-9 px-4 rounded bg-amber-500 text-white text-[13px] font-semibold flex items-center gap-2 hover:bg-amber-600 disabled:opacity-60"
          >
            <PencilLine className="w-4 h-4" aria-hidden="true" /> {editStarting ? "Opening…" : "Edit"}
          </button>
        ) : (
          <button type="button"
            onClick={onSave}
            disabled={saving || readOnly}
            aria-busy={saving}
            aria-live="polite"
            className="h-9 px-4 rounded bg-gray-800 text-white text-[13px] font-semibold flex items-center gap-2 hover:bg-gray-900 disabled:opacity-60"
          >
            <Save className="w-4 h-4" aria-hidden="true" /> {readOnly ? "Protected" : saving ? "Saving…" : "Save"}
          </button>
        )}
      </div>
    </div>
  );
}

const SECTIONS = [
  { n: 1, key: "details", label: "Details", description: "Customer & job information" },
  { n: 2, key: "build", label: "Products & Parts", description: "Build, price & organize products" },
  { n: 3, key: "customer", label: "Pricing & Finalize", description: "Review, quote, approve & convert" },
];

export default function AioStepRail({
  activeStep = 1,
  onStepClick,
  estimateNumber,
  clientName,
  description,
  taxPercent = 0,
  summary,
  stepDone = {},
  onSaveProgress,
  saving,
  dirty,
  readOnly = false,
  onEdit = null,
  editStarting = false,
}) {
  const money = (n) => `$${Number(n || 0).toFixed(2)}`;
  const s = summary || {};

  const done = {
    1: stepDone.details ?? !!(clientName && description),
    2: stepDone.build ?? false,
    3: stepDone.customer ?? false,
  };

  return (
    <div className="w-60 flex-shrink-0 space-y-3">
      <div className="bg-white border border-slate-300 rounded-sm overflow-hidden">
        <div className="px-3 py-2 bg-slate-800 border-b border-slate-300">
          <p className="text-xs font-bold text-lime-400 uppercase tracking-wide truncate">
            Estimate{estimateNumber ? ` — ${estimateNumber}` : " — New"}
          </p>
        </div>
        {SECTIONS.map((section) => {
          const active = section.n === activeStep;
          return (
            <button type="button"
              key={section.key}
              onClick={() => onStepClick?.(section.n)}
              aria-current={active ? "step" : undefined}
              className={`w-full text-left px-3 py-2.5 border-b border-slate-200 last:border-b-0 transition-colors ${
                active
                  ? "bg-lime-100 border-l-4 border-l-lime-600"
                  : "bg-slate-50 hover:bg-slate-100 border-l-4 border-l-transparent"
              }`}
            >
              <div className="flex items-center justify-between gap-2">
                <p className={`text-[13px] font-bold ${active ? "text-slate-950" : "text-slate-800"}`}>
                  {section.label}
                </p>
                {done[section.n] && <span className="text-lime-700 text-xs" title="Section complete">✔</span>}
              </div>
              <p className="text-[10px] leading-4 text-slate-500 mt-0.5">{section.description}</p>
            </button>
          );
        })}
      </div>

      <div className="bg-white border border-slate-300 rounded-sm overflow-hidden text-xs">
        <div className="px-3 py-1.5 bg-zinc-700 text-white font-semibold text-sm">Order Summary</div>
        <div className="px-3 py-2 border-b border-slate-200">
          <p className="font-bold text-slate-900 truncate">{clientName || "No customer set"}</p>
          <p className="text-slate-500 truncate">Description: {description || "—"}</p>
        </div>
        <div className="px-3 py-2">
          {[
            ["Subtotal:", s.subtotal],
            ["Discount:", s.discount],
            ...(Number(s.contingency) > 0
              ? [[`Contingency${s.contingencyPct != null ? ` (${s.contingencyPct}%)` : ""}:`, s.contingency]]
              : []),
            ["Shipping:", s.shipping],
            ["Permits:", s.permits],
            ["New Subtotal:", s.newSubtotal],
            [`Tax (${Number(taxPercent || 0)}%):`, s.tax],
          ].map(([label, val]) => (
            <div key={label} className="flex justify-between gap-2 py-0.5 text-slate-700">
              <span>{label}</span>
              <span className="tabular-nums">{money(val)}</span>
            </div>
          ))}
          <div className="flex justify-between gap-2 py-0.5 font-bold text-slate-900 border-t border-slate-300 mt-1 pt-1.5">
            <span>Total:</span>
            <span className="tabular-nums">{money(s.total)}</span>
          </div>
          {s.deposit != null && Number(s.deposit) > 0 && (
            <div className="flex justify-between gap-2 py-0.5 text-slate-700">
              <span>Deposit{s.depositPct != null ? ` (${s.depositPct}%)` : ""}:</span>
              <span className="tabular-nums">{money(s.deposit)}</span>
            </div>
          )}
        </div>
      </div>

      <button type="button"
        onClick={readOnly && onEdit ? onEdit : onSaveProgress}
        disabled={saving || editStarting || (readOnly && !onEdit)}
        className="w-full bg-lime-200 hover:bg-lime-300 disabled:opacity-60 border border-lime-500 text-slate-900 font-semibold py-2 rounded-sm text-sm transition-colors"
      >
        {readOnly ? (onEdit ? (editStarting ? "Opening revision…" : "Edit — open a revision") : "Protected") : saving ? "Saving…" : `Save Estimate Progress${dirty ? " *" : ""}`}
      </button>
    </div>
  );
}

