function PartGroup({ group, parts, globalOffset, selectionMode, selectedIds, onSelect, onChanged, builderProductId, onEditBuilder, estimateId, expectedEstimateUpdatedAt = "", availableProducts = [], readOnly = false }) {
  const [open, setOpen] = useState(!group.is_collapsed);
  const [visibleParts, setVisibleParts] = useState(PART_ROW_PAGE);
  const [renaming, setRenaming] = useState(false);
  const [name, setName] = useState(group.group_name || "Part Group");
  const [copying, setCopying] = useState(false);
  const [copied, setCopied] = useState(false);
  const [cloning, setCloning] = useState(false);
  const [moveOpen, setMoveOpen] = useState(false);
  const [saveLibraryOpen, setSaveLibraryOpen] = useState(false);
  const structuralActionRef = useRef(false);
  const groupVersionRef = useRef(group.updated_date || "");
  useEffect(() => {
    groupVersionRef.current = group.updated_date || groupVersionRef.current;
  }, [group.updated_date]);
  const frozen = parts.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0);
  const canMove = parts.length > 0 && parts.every((part) => ["manual", "manual_addon"].includes(part.builder_sync_state));
  const moveTargets = (availableProducts || []).filter((line) => line.builder_product_id && line.builder_product_id !== builderProductId);

  const toggleOpen = async () => {
    const next = !open;
    setOpen(next);
    if (!readOnly) {
      const current = await base44.entities.BuilderPartGroup.get(group.id).catch(() => null);
      if (!current?.id || current.builder_product_id !== builderProductId) return;
      const collapsePatch = { is_collapsed: !next };
      const updated = await replaceBuilderEntityFieldsIfUnchanged({
        entity: base44.entities.BuilderPartGroup,
        id: group.id,
        expectedUpdatedAt: current.updated_date || "",
        expectedFields: expectedBuilderEntityFields(current, collapsePatch),
        nextFields: collapsePatch,
        guardFields: { builder_product_id: builderProductId },
        label: "Part Group collapsed state",
      }).catch(() => null);
      if (updated?.updated_date) groupVersionRef.current = updated.updated_date;
      else if (current?.updated_date) groupVersionRef.current = current.updated_date;
    }
  };

  const saveName = async () => {
    if (structuralActionRef.current) return;
    structuralActionRef.current = true;
    const nextName = name.trim() || "Part Group";
    setName(nextName);
    setRenaming(false);
    try {
      await renamePartGroup({
        builderProductId,
        groupId: group.id,
        groupName: nextName,
        expectedEstimateUpdatedAt,
        expectedGroupUpdatedAt: groupVersionRef.current,
      });
      await onChanged?.();
    } catch (error) {
      window.alert(error?.message || "Part Group could not be renamed.");
    } finally {
      structuralActionRef.current = false;
    }
  };

  const dissolve = async () => {
    if (structuralActionRef.current) return;
    if (!window.confirm(`Dissolve "${group.group_name || "Part Group"}"? The Parts will stay in this Product and keep all frozen pricing.`)) return;
    structuralActionRef.current = true;
    try {
      await dissolvePartGroup({
        builderProductId,
        groupId: group.id,
        expectedEstimateUpdatedAt,
        expectedGroupUpdatedAt: groupVersionRef.current,
        expectedPartVersions: Object.fromEntries(parts.map((part) => [part.id, part.updated_date || ""])),
      });
      await onChanged?.();
    } catch (error) {
      await Promise.resolve(onChanged?.()).catch(() => null);
      window.alert(`${error?.message || "Part Group could not be dissolved."}\n\nThe Product was refreshed. If the dissolve had already started, use Resume Group Dissolve to safely continue it.`);
    } finally {
      structuralActionRef.current = false;
    }
  };

  return (
    <div className="border border-gray-300 rounded-sm overflow-hidden bg-gray-50">
      <div className="w-full px-3 py-2 flex items-center gap-2 bg-gray-100 hover:bg-gray-200 text-left">
        <button type="button" onClick={toggleOpen} aria-expanded={open} className="flex items-center gap-2 min-w-0 flex-1 text-left">
        {open ? <ChevronDown className="w-3.5 h-3.5 text-gray-600" aria-hidden="true" /> : <ChevronRight className="w-3.5 h-3.5 text-gray-600" aria-hidden="true" />}
        <Layers3 className="w-4 h-4 text-gray-600" aria-hidden="true" />
          <span className="text-[9px] font-extrabold tracking-widest text-gray-500">PART GROUP</span>
          {renaming ? (
            <input
              autoFocus
              value={name}
              onChange={(event) => setName(event.target.value)}
              onClick={(event) => event.stopPropagation()}
              aria-label="Part Group name"
              onKeyDown={(event) => {
                if (event.key === "Enter") {
                  event.preventDefault();
                  saveName();
                }
                if (event.key === "Escape") {
                  setName(group.group_name || "Part Group");
                  setRenaming(false);
                }
              }}
              onBlur={saveName}
              className="h-[25px] px-2 border border-gray-300 rounded bg-white text-[12px] font-bold text-gray-900 flex-1 min-w-[120px]"
            />
          ) : (
            <span className="text-[12px] font-bold text-gray-900 truncate flex-1">{group.group_name || "Part Group"}</span>
          )}
          <span className="text-[10px] text-gray-500">{parts.length} parts</span>
          <span className="text-[11px] font-bold text-gray-800 w-[92px] text-right">{money(frozen)}</span>
        </button>
        {!selectionMode && (
          <div className="flex items-center gap-1 ml-1">
            {estimateId && (
              <button
                type="button"
                disabled={copying}
                onClick={async () => {
                  setCopying(true);
                  try {
                    await copyPartGroupToClipboard({ estimateId, builderProductId, group, parts });
                    setCopied(true);
                    setTimeout(() => setCopied(false), 1500);
                  } catch (error) {
                    window.alert(error?.message || "Part Group could not be copied to the estimator clipboard.");
                  } finally {
                    setCopying(false);
                  }
                }}
                className="h-[26px] px-2 rounded border border-gray-300 bg-white flex items-center gap-1 text-[10px] font-semibold text-gray-600 hover:bg-gray-50 disabled:opacity-50"
                title="Copy Part Group to 30-day Clipboard"
                aria-label={`Copy ${group.group_name || "Part Group"} to 30-day clipboard`}
              ><ClipboardCopy className="w-3 h-3" aria-hidden="true" /> {copied ? "Copied" : "Copy"}</button>
            )}
            <button
              type="button"
              onClick={() => setSaveLibraryOpen(true)}
              className="h-[26px] px-2 rounded border border-violet-200 bg-white flex items-center gap-1 text-[10px] font-semibold text-violet-700 hover:bg-violet-50"
              title="Save Part Group permanently to Part Library"
              aria-label={`Save ${group.group_name || "Part Group"} permanently to Part Library`}
            ><BookmarkPlus className="w-3 h-3" aria-hidden="true" /> Save</button>
            {!readOnly && <>
              <button
                type="button"
                disabled={cloning}
                onClick={async () => {
                  if (!window.confirm(`Clone "${group.group_name || "Part Group"}" and all ${parts.length} Part${parts.length === 1 ? "" : "s"}?`)) return;
                  if (structuralActionRef.current) return;
                  structuralActionRef.current = true;
                  setCloning(true);
                  try {
                    await clonePartGroupInProduct({
                      builderProductId,
                      groupId: group.id,
                      expectedEstimateUpdatedAt,
                      expectedGroupUpdatedAt: groupVersionRef.current,
                      expectedPartVersions: Object.fromEntries(parts.map((part) => [part.id, part.updated_date || ""])),
                    });
                    await onChanged?.();
                  } catch (error) {
                    await Promise.resolve(onChanged?.()).catch(() => null);
                    window.alert(`${error?.message || "Part Group could not be cloned."}\n\nThe Product was refreshed. If the clone had already started, use Resume Group Clone to safely continue it.`);
                  } finally {
                    structuralActionRef.current = false;
                    setCloning(false);
                  }
                }}
                className="h-[26px] px-2 rounded border border-gray-300 bg-white flex items-center gap-1 text-[10px] font-semibold text-gray-600 hover:bg-gray-50 disabled:opacity-50"
                title="Clone Part Group in this Product"
                aria-label={`Clone ${group.group_name || "Part Group"} in this Product`}
              ><CopyPlus className="w-3 h-3" aria-hidden="true" /> {cloning ? "Cloning…" : "Clone"}</button>
              <button
                type="button"
                disabled={!canMove || moveTargets.length === 0}
                onClick={() => setMoveOpen(true)}
                className="h-[26px] px-2 rounded border border-gray-300 bg-white flex items-center gap-1 text-[10px] font-semibold text-gray-600 hover:bg-gray-50 disabled:opacity-40"
                title={canMove ? "Move Part Group to another Product" : "Builder-owned Parts cannot move directly. Use Clone or Copy instead."}
                aria-label={canMove ? `Move ${group.group_name || "Part Group"} to another Product` : "Builder-owned Parts cannot move directly. Use Clone or Copy instead."}
              ><ArrowRightLeft className="w-3 h-3" aria-hidden="true" /> Move</button>
              <button
                type="button"
                onClick={() => setRenaming(true)}
                className="w-[26px] h-[26px] rounded border border-gray-300 bg-white flex items-center justify-center text-gray-600 hover:bg-gray-50"
                title="Rename Part Group"
                aria-label={`Rename ${group.group_name || "Part Group"}`}
              >
                <Pencil className="w-3 h-3" aria-hidden="true" />
              </button>
              <button
                type="button"
                onClick={dissolve}
                className="w-[26px] h-[26px] rounded border border-gray-300 bg-white flex items-center justify-center text-gray-500 hover:text-red-600 hover:bg-red-50"
                title="Dissolve Part Group"
                aria-label={`Dissolve ${group.group_name || "Part Group"}`}
              >
                <Unlink className="w-3 h-3" aria-hidden="true" />
              </button>
            </>}
          </div>
        )}
      </div>
      {open && (
        <div className="p-2 space-y-2 border-t border-gray-200">
          {parts.slice(0, visibleParts).map((part, index) => (
            <PartRow
              key={part.id}
              part={part}
              index={globalOffset + index}
              selectionMode={selectionMode}
              selected={selectedIds.has(part.id)}
              onSelect={onSelect}
              onChanged={onChanged}
              onEditBuilder={onEditBuilder}
              estimateId={estimateId}
              expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
              readOnly={readOnly}
            />
          ))}
          {parts.length > visibleParts && (
            <button
              type="button"
              onClick={() => setVisibleParts((value) => value + PART_ROW_PAGE)}
              className="w-full h-[28px] rounded border border-gray-300 bg-white text-[10px] font-bold text-gray-600 hover:bg-gray-50"
            >
              Show {Math.min(PART_ROW_PAGE, parts.length - visibleParts)} more parts ({parts.length - visibleParts} remaining)
            </button>
          )}
        </div>
      )}
      <MovePartGroupModal
        open={moveOpen}
        group={group}
        sourceBuilderProductId={builderProductId}
        products={moveTargets}
        onClose={() => setMoveOpen(false)}
        onMove={async (targetBuilderProductId) => {
          if (structuralActionRef.current) return;
          structuralActionRef.current = true;
          try {
            await moveIndependentPartGroup({
              sourceBuilderProductId: builderProductId,
              targetBuilderProductId,
              groupId: group.id,
              expectedEstimateUpdatedAt,
              expectedGroupUpdatedAt: groupVersionRef.current,
              expectedPartVersions: Object.fromEntries(parts.map((part) => [part.id, part.updated_date || ""])),
            });
            setMoveOpen(false);
            await onChanged?.();
          } catch (error) {
            await Promise.resolve(onChanged?.()).catch(() => null);
            throw new Error(`${error?.message || "Part Group could not be moved."}\n\nThe Products were refreshed. If the move had already started, use Resume Group Move to safely continue it.`);
          } finally {
            structuralActionRef.current = false;
          }
        }}
      />
      <SavePartTemplateModal
        open={saveLibraryOpen}
        itemType="part_group"
        group={group}
        parts={parts}
        estimateId={estimateId}
        builderProductId={builderProductId}
        onClose={() => setSaveLibraryOpen(false)}
      />
    </div>
  );
}

export default function BuilderPartsPanel({ builderProductId, refreshKey, onLoaded, onEditBuilder, onProductRefresh, allowAddParts = false, estimateId, expectedEstimateUpdatedAt = "", availableProducts = [], readOnly = false }) {
  const [loading, setLoading] = useState(!!builderProductId);
  const [parts, setParts] = useState([]);
  const [groups, setGroups] = useState([]);
  const [dragGroupIdx, setDragGroupIdx] = useState(null);
  const [dragOverIdx, setDragOverIdx] = useState(null);
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState(new Set());
  const [groupModalOpen, setGroupModalOpen] = useState(false);
  const [partPickerOpen, setPartPickerOpen] = useState(false);
  const [partLibraryOpen, setPartLibraryOpen] = useState(false);
  const [refreshNonce, setRefreshNonce] = useState(0);
  const [partSearch, setPartSearch] = useState("");
  const [ungroupedVisible, setUngroupedVisible] = useState(PART_ROW_PAGE);
  const [bulkRemoving, setBulkRemoving] = useState(false);
  const [bulkDetaching, setBulkDetaching] = useState(false);
  const groupCreateRef = useRef(false);

  useEffect(() => {
    let active = true;
    const load = async () => {
      if (!builderProductId) {
        setParts([]);
        setGroups([]);
        setLoading(false);
        onLoaded?.(0);
        return;
      }
      setLoading(true);
      try {
        const [partRows, groupRows] = await Promise.all([
          loadAllEntityRows({ entity: base44.entities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts panel Parts" }),
          loadAllEntityRows({ entity: base44.entities.BuilderPartGroup, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts panel Groups" }),
        ]);
        if (!active) return;
        const activeParts = (partRows || [])
          .filter((part) => part.is_active !== false)
          .sort((a, b) => num(a.sort_order) - num(b.sort_order));
        const activeGroups = (groupRows || [])
          .filter((group) => group.is_active !== false)
          .sort((a, b) => num(a.sort_order) - num(b.sort_order));
        setParts(activeParts);
        setGroups(activeGroups);
        onLoaded?.(activeParts.length);
      } finally {
        if (active) setLoading(false);
      }
    };
    load();
    return () => {
      active = false;
    };
  }, [builderProductId, refreshKey, refreshNonce]);

  const togglePartSelection = (partId, checked) => {
    setSelectedIds((current) => {
      const next = new Set(current);
      if (checked) next.add(partId);
      else next.delete(partId);
      return next;
    });
  };

  const cancelSelection = () => {
    setSelectionMode(false);
    setSelectedIds(new Set());
    setGroupModalOpen(false);
  };

  const removableSelected = parts.filter((part) => selectedIds.has(part.id) && ["manual", "manual_addon"].includes(part.builder_sync_state));

  const bulkRemoveSelected = async () => {
    if (!builderProductId || bulkRemoving || !removableSelected.length) return;
    const skipped = selectedIds.size - removableSelected.length;
    const message = skipped > 0
      ? `Remove ${removableSelected.length} independent Part${removableSelected.length === 1 ? "" : "s"}? ${skipped} Builder-linked Part${skipped === 1 ? "" : "s"} will be kept (remove those through the Builder).`
      : `Remove ${removableSelected.length} independent Part${removableSelected.length === 1 ? "" : "s"} from this Product?`;
    if (!window.confirm(message)) return;
    setBulkRemoving(true);
    const failures = [];
    try {
      for (const part of removableSelected) {
        try {
          await removeManualProductPart(part.id, { builderProductId, expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" });
        } catch (error) {
          failures.push(`${part.part_name || "Part"}: ${error?.message || "remove failed"}`);
        }
      }
      setSelectionMode(false);
      setSelectedIds(new Set());
      setRefreshNonce((value) => value + 1);
      await onProductRefresh?.();
      if (failures.length) {
        window.alert(`${failures.length} Part${failures.length === 1 ? "" : "s"} could not be removed:\n${failures.join("\n")}\n\nThe Product was refreshed. If a removal had already started, use Resume Part Remove to safely continue it.`);
      }
    } finally {
      setBulkRemoving(false);
    }
  };

  const detachableSelected = parts.filter((part) => selectedIds.has(part.id) && part.builder_sync_state === "linked");

  const bulkDetachSelected = async () => {
    if (!builderProductId || bulkDetaching || !detachableSelected.length) return;
    if (!window.confirm(`Detach ${detachableSelected.length} Builder-linked Part${detachableSelected.length === 1 ? "" : "s"} for independent override? Frozen pricing is retained; each Part stops syncing with the Builder.`)) return;
    setBulkDetaching(true);
    const failures = [];
    try {
      for (const part of detachableSelected) {
        try {
          await detachBuilderPartOverride(part.id, undefined, { expectedEstimateUpdatedAt, expectedPartUpdatedAt: part.updated_date || "" });
        } catch (error) {
          failures.push(`${part.part_name || "Part"}: ${error?.message || "detach failed"}`);
        }
      }
      setSelectionMode(false);
      setSelectedIds(new Set());
      setRefreshNonce((value) => value + 1);
      await onProductRefresh?.();
      if (failures.length) {
        window.alert(`${failures.length} Part${failures.length === 1 ? "" : "s"} could not be detached:\n${failures.join("\n")}\n\nThe Product was refreshed. If a detach had already started, use Resume Part Detach to safely continue it.`);
      }
    } finally {
      setBulkDetaching(false);
    }
  };

  const createGroup = async (groupName) => {
    const selectedParts = parts.filter((part) => selectedIds.has(part.id));
    if (!builderProductId || selectedParts.length < 2 || groupCreateRef.current) return;
    groupCreateRef.current = true;
    try {
      await createPartGroupInProduct({
        builderProductId,
        partIds: selectedParts.map((part) => part.id),
        groupName,
        expectedEstimateUpdatedAt,
        expectedPartVersions: Object.fromEntries(selectedParts.map((part) => [part.id, part.updated_date || ""])),
      });
      setGroupModalOpen(false);
      setSelectionMode(false);
      setSelectedIds(new Set());
      setRefreshNonce((value) => value + 1);
      await onProductRefresh?.();
    } catch (error) {
      setRefreshNonce((value) => value + 1);
      await Promise.resolve(onProductRefresh?.()).catch(() => null);
      window.alert(`${error?.message || "Part Group could not be created."}\n\nThe Product was refreshed. If creation had already started, use Resume Group Create to safely continue it.`);
    } finally {
      groupCreateRef.current = false;
    }
  };

  const partQuery = partSearch.trim().toLowerCase();
  const visibleParts = useMemo(() => {
    if (!partQuery) return parts;
    return parts.filter((part) =>
      [part.part_name, part.client_label, part.inventory_item_name, part.part_type, part.part_subtype]
        .filter(Boolean)
        .some((value) => String(value).toLowerCase().includes(partQuery))
    );
  }, [parts, partQuery]);

  const grouped = useMemo(() => {
    const byGroup = new Map();
    groups.forEach((group) => byGroup.set(group.id, []));
    const ungrouped = [];
    visibleParts.forEach((part) => {
      if (part.part_group_id && byGroup.has(part.part_group_id)) byGroup.get(part.part_group_id).push(part);
      else ungrouped.push(part);
    });
    return { byGroup, ungrouped };
  }, [visibleParts, groups]);

  if (!builderProductId) {
    return <div className="px-4 py-4 text-[11px] text-gray-400">This legacy Product does not have Builder Parts yet.</div>;
  }
  if (loading) {
    return <div role="status" className="px-4 py-4 text-[11px] text-gray-400">Loading Parts…</div>;
  }
  if (!parts.length) {
    return (
      <div className="px-4 py-5 text-center border-t border-gray-200 bg-gray-50">
        <div className="text-[11px] font-semibold text-gray-600">This Product does not have any Parts yet.</div>
        <div className="text-[10px] text-gray-400 mt-1">Add a Part from Master Inventory now. Builder-generated BOM Parts will also appear here after the Builder is saved; manually added Parts remain independent add-ons.</div>
        {allowAddParts && !readOnly && (
          <div className="mt-3 flex items-center justify-center gap-2">
            <button type="button" onClick={() => setPartPickerOpen(true)} className="h-[30px] px-3 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 inline-flex items-center gap-1.5"><Plus className="w-3.5 h-3.5" aria-hidden="true" /> Add Part</button>
            <button type="button" onClick={() => setPartLibraryOpen(true)} className="h-[30px] px-3 rounded border border-violet-200 bg-white text-[11px] font-bold text-violet-700 hover:bg-violet-50 inline-flex items-center gap-1.5"><BookmarkPlus className="w-3.5 h-3.5" aria-hidden="true" /> Add Saved Part</button>
            <CopyBomButton estimateId={estimateId} targetBuilderProductId={builderProductId} expectedEstimateUpdatedAt={expectedEstimateUpdatedAt} />
          </div>
        )}
        <MasterPartPickerModal
          open={partPickerOpen}
          onClose={() => setPartPickerOpen(false)}
          onAdd={async (item, quantity) => {
            await addCatalogPartToProduct({ builderProductId, catalogItem: item, quantity, expectedEstimateUpdatedAt });
            setRefreshNonce((value) => value + 1);
            await onProductRefresh?.();
          }}
        />
        <PartLibraryPickerModal
          open={partLibraryOpen}
          estimateId={estimateId}
          builderProductId={builderProductId}
          expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
          onClose={() => setPartLibraryOpen(false)}
          onAdded={async () => {
            setRefreshNonce((value) => value + 1);
            await onProductRefresh?.();
          }}
        />
      </div>
    );
  }

  let offset = 0;
  const partsFrozenTotal = parts.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0);
  const persistGroupOrder = async (nextGroups) => {
    for (let i = 0; i < nextGroups.length; i++) {
      const g = nextGroups[i];
      if (Number(g.sort_order) !== i) {
        await staffEntities.BuilderPartGroup.updateMany({ id: g.id }, { sort_order: i }).catch(() => null);
      }
    }
  };


  return (
    <div className="border-t border-gray-300 bg-[#f6f6f6] px-3 py-3 space-y-2">
      <div className="flex items-center justify-between gap-2 pb-1">
        <div className="flex items-center gap-2 min-w-0">
          <div className="text-[10px] font-bold tracking-widest text-gray-500 whitespace-nowrap">PRODUCT PARTS · {partQuery ? `${visibleParts.length}/${parts.length}` : parts.length}</div>
          {parts.length > 10 && (
            <div className="relative">
              <Search className="w-3 h-3 text-gray-400 absolute left-1.5 top-1/2 -translate-y-1/2 pointer-events-none" aria-hidden="true" />
              <input
                value={partSearch}
                onChange={(event) => setPartSearch(event.target.value)}
                placeholder="Search parts…"
                aria-label="Search parts in this product"
                className="h-[26px] w-[150px] pl-6 pr-1.5 border border-gray-300 rounded bg-white text-[11px] focus:outline-none focus:border-lime-400"
              />
            </div>
          )}
        </div>
        {selectionMode ? (
          <div className="flex items-center gap-2">
            <span className="text-[10px] text-gray-500">{selectedIds.size} selected</span>
            <button
              type="button"
              onClick={cancelSelection}
              className="h-[28px] px-3 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-600 hover:bg-gray-50"
            >
              Cancel
            </button>
            <button
              type="button"
              disabled={selectedIds.size < 2}
              onClick={() => setGroupModalOpen(true)}
              className="h-[28px] px-3 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 disabled:opacity-40"
            >
              Group Selected Parts
            </button>
            <button
              type="button"
              disabled={bulkDetaching || detachableSelected.length === 0}
              onClick={bulkDetachSelected}
              title={detachableSelected.length === 0 ? "Only Builder-linked Parts can be detached" : "Detach the selected Builder-linked Parts for independent override"}
              className="h-[28px] px-3 rounded border border-amber-300 bg-white text-[11px] font-bold text-amber-700 hover:bg-amber-50 disabled:opacity-40 inline-flex items-center gap-1"
            >
              <Unlink className="w-3.5 h-3.5" aria-hidden="true" /> {bulkDetaching ? "Detaching…" : `Detach Selected (${detachableSelected.length})`}
            </button>
            <button
              type="button"
              disabled={bulkRemoving || removableSelected.length === 0}
              onClick={bulkRemoveSelected}
              title={removableSelected.length === 0 ? "Only independent (non-Builder) Parts can be removed here" : "Remove the selected independent Parts"}
              className="h-[28px] px-3 rounded border border-red-300 bg-white text-[11px] font-bold text-red-600 hover:bg-red-50 disabled:opacity-40 inline-flex items-center gap-1"
            >
              <Trash2 className="w-3.5 h-3.5" aria-hidden="true" /> {bulkRemoving ? "Removing…" : `Delete Selected (${removableSelected.length})`}
            </button>
          </div>
        ) : (
          <div className="flex items-center gap-2">
            {allowAddParts && !readOnly && (
              <>
                <button type="button" onClick={() => setPartPickerOpen(true)} className="h-[28px] px-3 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 inline-flex items-center gap-1.5"><Plus className="w-3.5 h-3.5" aria-hidden="true" /> Add Part</button>
                <button type="button" onClick={() => setPartLibraryOpen(true)} className="h-[28px] px-3 rounded border border-violet-200 bg-white text-[11px] font-bold text-violet-700 hover:bg-violet-50 inline-flex items-center gap-1.5"><BookmarkPlus className="w-3.5 h-3.5" aria-hidden="true" /> Add Saved Part</button>
                <CopyBomButton estimateId={estimateId} targetBuilderProductId={builderProductId} expectedEstimateUpdatedAt={expectedEstimateUpdatedAt} />
              </>
            )}
            {!readOnly && <button
              type="button"
              onClick={() => setSelectionMode(true)}
              className="h-[28px] px-3 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-700 hover:bg-gray-100 inline-flex items-center gap-1.5"
            >
              <Layers3 className="w-3.5 h-3.5" aria-hidden="true" /> Group Parts
            </button>}
          </div>
        )}
      </div>

      {groups.map((group) => {
        const groupParts = grouped.byGroup.get(group.id) || [];
        if (!groupParts.length) return null;
        const node = (
          <PartGroup
            key={group.id}
            group={group}
            parts={groupParts}
            globalOffset={offset}
            selectionMode={selectionMode}
            selectedIds={selectedIds}
            onSelect={togglePartSelection}
            onChanged={async () => {
              setRefreshNonce((value) => value + 1);
              await onProductRefresh?.();
            }}
            builderProductId={builderProductId}
            onEditBuilder={onEditBuilder}
            estimateId={estimateId}
            expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
            availableProducts={availableProducts}
            readOnly={readOnly}
          />
        );
        offset += groupParts.length;
        return readOnly ? node : (
          <div
            key={group.id}
            draggable
            onDragStart={() => setDragGroupIdx(groups.indexOf(group))}
            onDragOver={(e) => { e.preventDefault(); setDragOverIdx(groups.indexOf(group)); }}
            onDragLeave={() => setDragOverIdx(null)}
            onDrop={async (e) => {
              e.preventDefault();
              if (dragGroupIdx === null) return;
              const target = groups.indexOf(group);
              const next = [...groups];
              const [moved] = next.splice(dragGroupIdx, 1);
              next.splice(target, 0, moved);
              setGroups(next);
              setDragGroupIdx(null);
              setDragOverIdx(null);
              await persistGroupOrder(next);
              setRefreshNonce((v) => v + 1);
            }}
            onDragEnd={() => { setDragGroupIdx(null); setDragOverIdx(null); }}
            className={`${dragOverIdx === groups.indexOf(group) ? "ring-2 ring-emerald-400 rounded" : ""}`}
          >
            {node}
          </div>
        );
      })}
      {grouped.ungrouped.slice(0, partQuery ? grouped.ungrouped.length : ungroupedVisible).map((part, index) => (
        <PartRow
          key={part.id}
          part={part}
          index={offset + index}
          selectionMode={selectionMode}
          selected={selectedIds.has(part.id)}
          onSelect={togglePartSelection}
          onChanged={async () => {
            setRefreshNonce((value) => value + 1);
            await onProductRefresh?.();
          }}
          onEditBuilder={onEditBuilder}
          estimateId={estimateId}
          expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
          readOnly={readOnly}
        />
      ))}
      {!partQuery && grouped.ungrouped.length > ungroupedVisible && (
        <button
          type="button"
          onClick={() => setUngroupedVisible((value) => value + PART_ROW_PAGE)}
          className="w-full h-[28px] rounded border border-gray-300 bg-white text-[10px] font-bold text-gray-600 hover:bg-gray-50"
        >
          Show {Math.min(PART_ROW_PAGE, grouped.ungrouped.length - ungroupedVisible)} more parts ({grouped.ungrouped.length - ungroupedVisible} remaining)
        </button>
      )}
      {partQuery && !visibleParts.length && (
        <div className="py-4 text-center text-[11px] text-gray-400">No Parts match "{partSearch}".</div>
      )}

      <div className="flex items-center justify-between gap-2 pt-2 border-t border-gray-200">
        <div className="text-[10px] font-bold tracking-widest text-gray-500">PARTS TOTAL</div>
        <div className="text-[11px] font-bold text-gray-800">{money(partsFrozenTotal)}</div>
      </div>

      <CreatePartGroupModal
        open={groupModalOpen}
        selectedCount={selectedIds.size}
        onClose={() => setGroupModalOpen(false)}
        onCreate={createGroup}
      />
      <MasterPartPickerModal
        open={partPickerOpen}
        onClose={() => setPartPickerOpen(false)}
        onAdd={async (item, quantity) => {
          await addCatalogPartToProduct({ builderProductId, catalogItem: item, quantity, expectedEstimateUpdatedAt });
          setRefreshNonce((value) => value + 1);
          await onProductRefresh?.();
        }}
      />
      <PartLibraryPickerModal
        open={partLibraryOpen}
        estimateId={estimateId}
        builderProductId={builderProductId}
        expectedEstimateUpdatedAt={expectedEstimateUpdatedAt}
        onClose={() => setPartLibraryOpen(false)}
        onAdded={async () => {
          setRefreshNonce((value) => value + 1);
          await onProductRefresh?.();
        }}
      />
    </div>
  );
}

import { useState, useEffect } from "react";
import { X } from "lucide-react";
import { useEscapeKey, useModalDialog } from "@/components/estimator/a11y";

const REASONS = [
  "Duplicate",
  "Chose another Sign Company - No reason given",
  "Error",
  "Customer hasn't responded - No reason given",
  "Cancelled Project - No reason given",
  "Chose another Sign Company - Our Price too High",
  "Cancelled Project - Our Price too High",
  "Other",
  "Multi Estimates - Chose another one",
  "Price Shoppers",
  "Chose another Sign Company - We took too long",
  "Custom...",
];

export default function CancelEstimateModal({ open, onClose, onConfirm }) {
  const [reason, setReason] = useState("");
  const [customReason, setCustomReason] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const { containerRef, dialogProps } = useModalDialog({ open, labelledBy: "cancel-estimate-title" });
  useEscapeKey(open, () => { if (!submitting) onClose?.(); });

  useEffect(() => {
    if (open) {
      setReason("");
      setCustomReason("");
      setSubmitting(false);
    }
  }, [open]);

  if (!open) return null;

  const isCustom = reason === "Custom...";
  const canSubmit = reason && (!isCustom || customReason.trim());

  const handleConfirm = async () => {
    if (!canSubmit || submitting) return;
    setSubmitting(true);
    const finalReason = isCustom ? customReason.trim() : reason;
    await onConfirm(finalReason);
    setSubmitting(false);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-black/50"
        onClick={onClose}
      />

      {/* Modal */}
      <div
        ref={containerRef}
        {...dialogProps}
        className="relative bg-white rounded-md shadow-2xl border border-gray-300 w-full max-w-md"
        style={{ boxShadow: "0 20px 60px rgba(0,0,0,0.3)" }}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-5 pt-4 pb-2">
          <h2
            id="cancel-estimate-title"
            className="text-lg font-bold tracking-wide"
            style={{ color: "#7a9a4b" }}
          >
            CANCEL ESTIMATE
          </h2>
          <button
            type="button"
            onClick={onClose}
            className="text-gray-500 hover:text-gray-800 transition-colors p-1"
            title="Close"
            aria-label="Close cancel estimate dialog"
          >
            <X className="w-4 h-4" aria-hidden="true" />
          </button>
        </div>

        {/* Body */}
        <div className="px-5 pb-2 space-y-2 text-sm text-gray-800">
          <p>
            Proceeding with this action will cancel the{" "}
            <strong>entire estimate</strong>. All product{" "}
            <strong>totals</strong> will remain as they currently are.
          </p>
          <p className="text-gray-600">
            To cancel an individual product, use the product status.
          </p>
          <p>
            <span className="font-bold text-red-600">Warning:</span>{" "}
            This action cannot be undone.
          </p>
        </div>

        {/* Reason dropdown */}
        <div className="px-5 py-3">
          <label htmlFor="cancel-reason" className="block text-sm font-medium text-gray-900 mb-1.5">
            Enter Reason for Cancelling
          </label>
          <select
            id="cancel-reason"
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            className="w-full h-9 px-2 border border-gray-400 rounded text-sm bg-white focus:outline-none focus:border-lime-600"
          >
            <option value="">-- Select reason --</option>
            {REASONS.map((r) => (
              <option key={r} value={r}>
                {r}
              </option>
            ))}
          </select>

          {isCustom && (
            <input
              type="text"
              value={customReason}
              onChange={(e) => setCustomReason(e.target.value)}
              placeholder="Enter custom reason…"
              aria-label="Custom cancellation reason"
              className="w-full h-9 px-2 mt-2 border border-gray-400 rounded text-sm focus:outline-none focus:border-lime-600"
              autoFocus
            />
          )}
        </div>

        {/* Footer */}
        <div className="flex justify-end px-5 pb-5 pt-1">
          <button
            type="button"
            onClick={handleConfirm}
            disabled={!canSubmit || submitting}
            className="px-5 py-2 min-h-[44px] rounded border border-gray-500 font-semibold text-sm text-gray-800 disabled:opacity-50 disabled:cursor-not-allowed transition-colors hover:brightness-95"
            style={{ backgroundColor: "#d9e7c5" }}
          >
            {submitting ? "Cancelling…" : "Cancel Estimate"}
          </button>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { ClipboardPaste, Package, Search, Trash2 } from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { listClipboardItems, pasteClipboardItem, removeClipboardItem } from "@/components/estimator/products/clipboardService";

const typeLabel = (type) => type === "part_group" ? "Part Group" : type === "part" ? "Part" : "Product";
const daysLeft = (date) => Math.max(0, Math.ceil((new Date(date).getTime() - Date.now()) / 86400000));

export default function ClipboardManagerModal({ open, estimateId, expectedEstimateUpdatedAt = "", lines = [], onClose, onPasted }) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [query, setQuery] = useState("");
  const [typeFilter, setTypeFilter] = useState("all");
  const [targetByItem, setTargetByItem] = useState({});
  const [busyId, setBusyId] = useState("");
  const [loadError, setLoadError] = useState("");
  const [error, setError] = useState("");
  const pasteRef = useRef(false);

  const load = async () => {
    setLoading(true);
    setLoadError("");
    setError("");
    setItems([]);
    try {
      setItems(await listClipboardItems());
    } catch (err) {
      setLoadError(err?.message || "Clipboard could not be loaded.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!open) return;
    setQuery("");
    setTypeFilter("all");
    setTargetByItem({});
    load();
  }, [open]);

  const targets = (lines || []).filter((line) => !!line.builder_product_id);
  const visible = useMemo(() => {
    const q = query.trim().toLowerCase();
    return items.filter((item) => {
      if (typeFilter !== "all" && item.item_type !== typeFilter) return false;
      if (!q) return true;
      const haystack = `${item.item_name || ""} ${item.search_text || ""} ${item.source_product_name || ""}`.toLowerCase();
      return q.split(/\s+/).every((term) => haystack.includes(term));
    });
  }, [items, query, typeFilter]);

  const paste = async (item) => {
    if (!item?.id || pasteRef.current) return;
    pasteRef.current = true;
    const targetBuilderProductId = item.item_type === "product" ? "" : (targetByItem[item.id] || targets[0]?.builder_product_id || "");
    if (item.item_type !== "product" && !targetBuilderProductId) {
      setError("Add or choose a target Product before pasting this Part or Part Group.");
      pasteRef.current = false;
      return;
    }
    setBusyId(item.id);
    setError("");
    try {
      await pasteClipboardItem({ estimateId, clipboardItem: item, targetBuilderProductId, expectedEstimateUpdatedAt });
      await onPasted?.();
    } catch (err) {
      setError(err?.message || "Clipboard item could not be pasted.");
    } finally {
      pasteRef.current = false;
      setBusyId("");
    }
  };

  const remove = async (item) => {
    if (!window.confirm(`Remove "${item.item_name}" from the clipboard?`)) return;
    await removeClipboardItem(item.id);
    setItems((current) => current.filter((row) => row.id !== item.id));
  };

  return (
    <Dialog open={open} onOpenChange={(next) => !next && !busyId && onClose?.()}>
      <DialogContent className="sm:max-w-[1050px] p-0 overflow-hidden gap-0 border-gray-300 shadow-2xl">
        <DialogHeader className="px-5 py-4 bg-[#3f3f3f] text-white border-b-4 border-lime-300">
          <DialogTitle className="text-white text-[17px] flex items-center gap-2"><ClipboardPaste className="w-5 h-5 text-lime-300" aria-hidden="true" /> Estimator Clipboard</DialogTitle>
          <p className="text-[11px] text-gray-300 mt-1">Database-backed copies stay available for 30 days. Product pastes create a new independent Product snapshot; Part and Part Group pastes target an existing Product.</p>
        </DialogHeader>

        <div className="bg-white min-h-[590px] flex flex-col">
          <div className="p-3 border-b border-gray-200 bg-gray-50 flex flex-col sm:flex-row gap-2">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" aria-hidden="true" />
              <input value={query} onChange={(event) => setQuery(event.target.value)} aria-label="Search clipboard" placeholder="Search clipboard by item, estimate, order, company or Product..." className="w-full h-[34px] pl-9 pr-3 border border-gray-300 rounded bg-white text-[12px]" />
            </div>
            <select value={typeFilter} onChange={(event) => setTypeFilter(event.target.value)} aria-label="Filter clipboard by item type" className="h-[34px] px-3 border border-gray-300 rounded bg-white text-[11px] text-gray-700">
              <option value="all">All clipboard items</option>
              <option value="product">Products</option>
              <option value="part_group">Part Groups</option>
              <option value="part">Parts</option>
            </select>
          </div>

          {(loadError || error) && <div role="alert" className="mx-3 mt-3 rounded border border-red-200 bg-red-50 px-3 py-2 text-[11px] text-red-700">{loadError || error}</div>}

          <div className="flex-1 overflow-y-auto max-h-[510px] p-3">
            {loading ? (
              <div role="status" className="py-20 text-center text-[12px] text-gray-400">Loading clipboard…</div>
            ) : loadError ? (
              <div className="py-20 text-center"><Package className="w-9 h-9 text-red-300 mx-auto mb-2" aria-hidden="true" /><div className="text-[12px] font-semibold text-red-700">Clipboard could not be verified.</div><div className="text-[10px] text-red-500 mt-1">Close and reopen the clipboard to retry.</div></div>
            ) : visible.length === 0 ? (
              <div className="py-20 text-center">
                <Package className="w-9 h-9 text-gray-300 mx-auto mb-2" aria-hidden="true" />
                <div className="text-[12px] font-semibold text-gray-600">No clipboard items found.</div>
                <div className="text-[10px] text-gray-400 mt-1">Use Copy on a Product, Part Group or Part to save it here for 30 days.</div>
              </div>
            ) : (
              <div className="space-y-2">
                {visible.map((item) => {
                  const isProduct = item.item_type === "product";
                  const selectedTarget = targetByItem[item.id] || targets[0]?.builder_product_id || "";
                  return (
                    <div key={item.id} className="rounded border border-gray-200 bg-white p-3 shadow-sm">
                      <div className="flex items-start gap-3">
                        <div className={`w-9 h-9 rounded flex items-center justify-center flex-shrink-0 ${isProduct ? "bg-cyan-100 text-cyan-700" : item.item_type === "part_group" ? "bg-violet-100 text-violet-700" : "bg-gray-100 text-gray-600"}`}><Package className="w-4 h-4" aria-hidden="true" /></div>
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className="text-[12px] font-bold text-gray-900">{item.item_name}</span>
                            <span className="text-[9px] font-bold px-2 py-0.5 rounded border border-gray-200 bg-gray-50 text-gray-600">{typeLabel(item.item_type).toUpperCase()}</span>
                            <span className="text-[9px] px-2 py-0.5 rounded border border-amber-200 bg-amber-50 text-amber-700">expires in {daysLeft(item.expires_at)}d</span>
                          </div>
                          <div className="mt-1 text-[10px] text-gray-500 flex flex-wrap gap-x-3 gap-y-1">
                            <span>Estimate: <strong>{item.source_estimate_number || "—"}</strong></span>
                            <span>Order: <strong>{item.source_order || "—"}</strong></span>
                            <span>Company: <strong>{item.source_company || "—"}</strong></span>
                            {item.source_product_name && <span>From Product: <strong>{item.source_product_name}</strong></span>}
                            <span>Copied: <strong>{item.copied_at ? new Date(item.copied_at).toLocaleDateString() : "—"}</strong></span>
                          </div>
                          {!isProduct && (
                            <div className="mt-2 flex items-center gap-2">
                              <span className="text-[9px] font-bold tracking-wide text-gray-400">PASTE INTO</span>
                              <select value={selectedTarget} onChange={(event) => setTargetByItem((current) => ({ ...current, [item.id]: event.target.value }))} aria-label={`Paste ${item.item_name || "item"} into Product`} className="h-[28px] max-w-[360px] flex-1 border border-gray-300 rounded bg-white px-2 text-[10px] text-gray-700">
                                {targets.length === 0 && <option value="">No Products available</option>}
                                {targets.map((line) => <option key={line.builder_product_id} value={line.builder_product_id}>{line.client_product_name || line.project_name || line.builder_name || "Product"}</option>)}
                              </select>
                            </div>
                          )}
                        </div>
                        <div className="flex items-center gap-1.5 flex-shrink-0">
                          <button type="button" disabled={busyId === item.id} onClick={() => paste(item)} className="h-[30px] px-3 rounded border border-lime-400 bg-lime-200 text-[10px] font-bold text-gray-900 hover:bg-lime-300 disabled:opacity-50 inline-flex items-center gap-1"><ClipboardPaste className="w-3.5 h-3.5" aria-hidden="true" /> {busyId === item.id ? "Pasting…" : "Paste"}</button>
                          <button type="button" disabled={!!busyId} onClick={() => remove(item)} className="w-[30px] h-[30px] rounded border border-red-200 bg-white text-red-500 hover:bg-red-50 flex items-center justify-center" title="Remove from clipboard" aria-label={`Remove ${item.item_name || "item"} from clipboard`}><Trash2 className="w-3.5 h-3.5" aria-hidden="true" /></button>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          <div className="px-4 py-3 border-t border-gray-200 bg-gray-50 flex items-center justify-between">
            <span className="text-[10px] text-gray-400">{items.length} active item{items.length === 1 ? "" : "s"} · expired items are removed automatically</span>
            <button type="button" disabled={!!busyId} onClick={onClose} className="h-[30px] px-4 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-600">Close</button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect, useState } from "react";
import { Layers3 } from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";

export default function CreatePartGroupModal({ open, selectedCount, onClose, onCreate }) {
  const [name, setName] = useState("Part Group");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!open) return;
    setName("Part Group");
    setSaving(false);
    setError("");
  }, [open]);

  const submit = async (event) => {
    event?.preventDefault?.();
    if (!name.trim() || saving) return;
    setSaving(true);
    setError("");
    try {
      await onCreate?.(name.trim());
    } catch (err) {
      setError(err?.message || "The Part Group could not be created.");
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(next) => !next && !saving && onClose?.()}>
      <DialogContent className="max-w-md p-0 overflow-hidden border border-gray-300 shadow-xl">
        <div className="bg-[#444] border-b-4 border-lime-300 px-5 py-4 text-white">
          <DialogHeader>
            <DialogTitle className="text-white flex items-center gap-2 text-[16px]">
              <Layers3 className="w-5 h-5 text-lime-300" aria-hidden="true" /> Create Part Group
            </DialogTitle>
          </DialogHeader>
          <p className="text-[11px] text-gray-200 mt-1">
            Group {selectedCount} selected Part{selectedCount === 1 ? "" : "s"} so they can be collapsed and later copied/moved as one unit.
          </p>
        </div>
        <form onSubmit={submit} className="p-5 bg-white">
          <label className="text-[10px] font-bold tracking-wider text-gray-500 block">
            PART GROUP NAME
            <input
              autoFocus
              value={name}
              onChange={(event) => setName(event.target.value)}
              className="mt-1 h-[34px] w-full rounded border border-gray-300 px-3 text-[12px] text-gray-900 focus:outline-none focus:ring-2 focus:ring-lime-300"
              placeholder="e.g. Installation, Face Components, Electrical"
            />
          </label>
          {error && <div role="alert" className="mt-3 rounded border border-red-200 bg-red-50 px-3 py-2 text-[11px] text-red-700">{error}</div>}
          <div className="mt-5 flex justify-end gap-2">
            <button
              type="button"
              onClick={onClose}
              disabled={saving}
              className="h-[32px] px-4 rounded border border-gray-300 bg-white text-[12px] font-semibold text-gray-700 hover:bg-gray-50 disabled:opacity-50"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={saving || !name.trim()}
              className="h-[32px] px-4 rounded border border-lime-400 bg-lime-200 text-[12px] font-bold text-gray-900 hover:bg-lime-300 disabled:opacity-50"
            >
              {saving ? "Grouping…" : "Create Part Group"}
            </button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { PackagePlus, Save } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { money } from "@/components/estimator/aioPricing";
import { acceptedCustomerUnitPrice } from "@/components/estimator/customerPricing";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";

export default function CreateQuickProductModal({ open, line, partCount = 0, onClose, onSave }) {
  const [name, setName] = useState("");
  const [productGroup, setProductGroup] = useState("my");
  const [categories, setCategories] = useState([]);
  const [availableCategories, setAvailableCategories] = useState([]);
  const [extraCategories, setExtraCategories] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const saveRef = useRef(false);

  useEffect(() => {
    if (!open) return;
    setName(line?.client_product_name || line?.project_name || "Quick Product");
    setProductGroup("my");
    setCategories(line?.product_category ? [line.product_category] : []);
    setExtraCategories("");
    setSaving(false);
    setError("");
    Promise.all([
      loadAllEntityRows({ entity: base44.entities.QuickProductCategory, sort: "category_name", label: "Quick Product categories" }).catch(() => []),
      base44.auth.me().catch(() => null),
    ]).then(([rows, me]) => setAvailableCategories((rows || [])
      .filter((row) => row.product_group === "global" || !row.created_by_id || (!!me?.id && row.created_by_id === me.id))
      .sort((a, b) => String(a.category_name || "").localeCompare(String(b.category_name || "")))))
      .catch(() => setAvailableCategories([]));
  }, [open, line?.line_id, line?.builder_product_id]);

  const visibleCategories = useMemo(
    () => availableCategories.filter((row) => (row.product_group || "my") === productGroup),
    [availableCategories, productGroup]
  );

  const toggleCategory = (categoryName) => {
    setCategories((current) => current.includes(categoryName)
      ? current.filter((name) => name !== categoryName)
      : [...current, categoryName]);
  };

  const submit = async (event) => {
    event.preventDefault();
    if (!name.trim() || saveRef.current) return;
    saveRef.current = true;
    const extra = extraCategories.split(",").map((item) => item.trim()).filter(Boolean);
    const finalCategories = [...new Set([...categories, ...extra])];
    setSaving(true);
    setError("");
    try {
      await onSave?.({ name: name.trim(), productGroup, categories: finalCategories });
      onClose?.();
    } catch (err) {
      setError(err?.message || "Quick Product could not be saved.");
    } finally {
      saveRef.current = false;
      setSaving(false);
    }
  };

  const frozenCost = Number(line?.total_snapshot || 0);
  const frozenCustomerPrice = acceptedCustomerUnitPrice(line);
  const isBuilder = line?.module_key !== "custom";

  return (
    <Dialog open={open} onOpenChange={(next) => !next && !saving && onClose?.()}>
      <DialogContent className="sm:max-w-[680px] p-0 overflow-hidden border-gray-300 shadow-2xl">
        <DialogHeader className="px-5 py-4 bg-[#3f3f3f] text-white border-b-4 border-lime-300">
          <DialogTitle className="text-white text-[17px] flex items-center gap-2">
            <PackagePlus className="w-5 h-5 text-lime-300" aria-hidden="true" /> Create Quick Product
          </DialogTitle>
          <p className="text-[11px] text-gray-300 mt-1">
            Saves the complete Product package — not just its price. Builder configuration, Parts, Part Groups, inventory snapshots, frozen pricing, overrides and notes are preserved.
          </p>
        </DialogHeader>

        <form onSubmit={submit} className="p-5 bg-white space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <label className="text-[10px] font-bold tracking-wide text-gray-500 sm:col-span-2">
              QUICK PRODUCT NAME
              <input autoFocus value={name} onChange={(event) => setName(event.target.value)} className="mt-1 w-full h-[36px] px-3 border border-gray-300 rounded text-[13px]" />
            </label>

            <div className="sm:col-span-2">
              <div className="text-[10px] font-bold tracking-wide text-gray-500 mb-1.5">AVAILABILITY</div>
              <div className="grid grid-cols-2 gap-2">
                <button type="button" onClick={() => setProductGroup("my")} className={`rounded border px-3 py-2 text-left ${productGroup === "my" ? "border-lime-400 bg-lime-50" : "border-gray-200 bg-white"}`}>
                  <div className="text-[11px] font-bold text-gray-900">My Quick Product</div>
                  <div className="text-[9px] text-gray-500 mt-0.5">Personal reusable template.</div>
                </button>
                <button type="button" onClick={() => setProductGroup("global")} className={`rounded border px-3 py-2 text-left ${productGroup === "global" ? "border-lime-400 bg-lime-50" : "border-gray-200 bg-white"}`}>
                  <div className="text-[11px] font-bold text-gray-900">Global Quick Product</div>
                  <div className="text-[9px] text-gray-500 mt-0.5">Shared company template.</div>
                </button>
              </div>
            </div>

            <div className="sm:col-span-2 rounded border border-gray-200 bg-gray-50 p-3">
              <div className="text-[9px] font-bold tracking-widest text-gray-400 mb-2">PRODUCT PACKAGE</div>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 text-[10px]">
                <div><span className="text-gray-500 block">Class</span><strong>{isBuilder ? "Builder Product" : "Custom Product"}</strong></div>
                <div><span className="text-gray-500 block">Builder</span><strong>{line?.builder_name || (isBuilder ? "Builder" : "None")}</strong></div>
                <div><span className="text-gray-500 block">Parts</span><strong>{partCount}</strong></div>
                <div><span className="text-gray-500 block">Internal Cost</span><strong>{money(frozenCost)}</strong></div>
                <div><span className="text-gray-500 block">Customer Price</span><strong>{money(frozenCustomerPrice)}</strong></div>
              </div>
              {line?.needs_reattach_review && <div className="mt-2 rounded border border-amber-200 bg-amber-50 px-2 py-1.5 text-[9px] text-amber-700">Detached/override Part state will be preserved exactly in the Quick Product.</div>}
            </div>

            <div className="sm:col-span-2">
              <div className="text-[10px] font-bold tracking-wide text-gray-500 mb-1.5">CATEGORIES</div>
              {visibleCategories.length > 0 && (
                <div className="flex flex-wrap gap-1.5 mb-2">
                  {visibleCategories.map((category) => {
                    const selected = categories.includes(category.category_name);
                    return (
                      <button key={category.id} type="button" onClick={() => toggleCategory(category.category_name)} aria-pressed={selected} className={`h-[26px] px-2.5 rounded-full border text-[10px] font-semibold ${selected ? "border-lime-400 bg-lime-100 text-gray-900" : "border-gray-300 bg-white text-gray-600"}`}>
                        {category.category_name}
                      </button>
                    );
                  })}
                </div>
              )}
              <input value={extraCategories} onChange={(event) => setExtraCategories(event.target.value)} aria-label="Add extra categories" placeholder="Add categories, comma separated..." className="w-full h-[34px] px-3 border border-gray-300 rounded text-[11px]" />
              <div className="text-[9px] text-gray-400 mt-1">Existing selected: {categories.length ? categories.join(", ") : "none"}</div>
            </div>
          </div>

          {error && <div role="alert" className="rounded border border-red-200 bg-red-50 px-3 py-2 text-[11px] text-red-700">{error}</div>}

          <div className="flex justify-end gap-2">
            <button type="button" disabled={saving} onClick={onClose} className="h-[32px] px-4 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-600">Cancel</button>
            <button type="submit" disabled={saving || !name.trim()} className="h-[32px] px-4 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 disabled:opacity-50 inline-flex items-center gap-1.5">
              <Save className="w-3.5 h-3.5" aria-hidden="true" /> {saving ? "Saving…" : "Save Quick Product"}
            </button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Search } from "lucide-react";

const RECENT_KEY = "ccs_recent_customers";
const RECENT_LIMIT = 5;

const STATUS_STYLES = {
  active: "bg-emerald-100 text-emerald-800",
  inactive: "bg-slate-100 text-slate-500",
  prospect: "bg-blue-100 text-blue-800",
};

const readRecentIds = () => {
  try {
    const ids = JSON.parse(localStorage.getItem(RECENT_KEY) || "[]");
    return Array.isArray(ids) ? ids.filter(Boolean).slice(0, RECENT_LIMIT) : [];
  } catch {
    return [];
  }
};

const rememberRecentId = (id) => {
  if (!id) return;
  try {
    const next = [id, ...readRecentIds().filter((r) => r !== id)].slice(0, RECENT_LIMIT);
    localStorage.setItem(RECENT_KEY, JSON.stringify(next));
  } catch {
    // localStorage unavailable (private mode, quota) — recents are best-effort.
  }
};

export default function CustomerSearchDialog({ open, onClose, customers = [], onSelect }) {
  const [query, setQuery] = useState("");
  const [recentIds, setRecentIds] = useState([]);

  useEffect(() => {
    if (!open) return;
    setQuery("");
    setRecentIds(readRecentIds());
  }, [open]);

  const q = query.trim().toLowerCase();
  const results = customers.filter((c) => {
    if (!q) return true;
    return [
      c.company_name,
      c.contact_email,
      c.company_phone,
      `${c.contact_first_name || ""} ${c.contact_last_name || ""}`,
      c.billing_city,
    ]
      .filter(Boolean)
      .some((v) => String(v).toLowerCase().includes(q));
  });

  const recentCustomers = recentIds
    .map((id) => customers.find((c) => c.id === id))
    .filter(Boolean);
  const recentIdSet = new Set(recentCustomers.map((c) => c.id));
  const visibleResults = q ? results : results.filter((c) => !recentIdSet.has(c.id));

  const sectionLabel = (text) => (
    <div className="px-3 py-1 bg-gray-50 text-[10px] font-semibold uppercase tracking-wide text-gray-400">
      {text}
    </div>
  );

  const renderCustomer = (c) => {
    const status = String(c.customer_status || "prospect").toLowerCase();
    return (
      <button
        type="button"
        role="option"
        aria-selected={false}
        key={c.id}
        onClick={() => {
          rememberRecentId(c.id);
          onSelect(c);
          onClose();
        }}
        className="w-full text-left px-3 py-2 hover:bg-gray-50"
      >
        <div className="text-[13px] font-semibold text-gray-800 flex items-center gap-1.5">
          <span className="truncate">{c.company_name}</span>
          <span
            className={`rounded-full px-2 py-0.5 text-[10px] font-semibold capitalize flex-shrink-0 ${STATUS_STYLES[status] || STATUS_STYLES.prospect}`}
          >
            {status}
          </span>
        </div>
        <div className="text-[11px] text-gray-500">
          {[
            `${c.contact_first_name || ""} ${c.contact_last_name || ""}`.trim(),
            c.contact_email,
            c.company_phone,
            c.billing_city,
          ]
            .filter(Boolean)
            .join(" · ") || "No contact details"}
        </div>
      </button>
    );
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="max-w-[560px]">
        <DialogHeader>
          <DialogTitle className="text-[15px]">Find a Customer</DialogTitle>
        </DialogHeader>

        <div className="relative">
          <Search className="w-4 h-4 text-gray-400 absolute left-2 top-1/2 -translate-y-1/2" aria-hidden="true" />
          <input
            autoFocus
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            aria-label="Search customers"
            placeholder="Search by company, contact, email, phone or city…"
            className="w-full h-[32px] pl-8 pr-2 border border-gray-300 rounded-sm text-[13px] focus:outline-none focus:border-red-400"
          />
        </div>

        <div
          role="listbox"
          aria-label="Customer results"
          className="max-h-[340px] overflow-y-auto border border-gray-200 rounded-sm divide-y divide-gray-100"
        >
          {results.length === 0 ? (
            <div className="py-8 text-center text-[12px] text-gray-400">No matching customers.</div>
          ) : (
            <>
              {!q && recentCustomers.length > 0 && (
                <>
                  {sectionLabel("Recent")}
                  {recentCustomers.map(renderCustomer)}
                  {visibleResults.length > 0 && sectionLabel("All customers")}
                </>
              )}
              {visibleResults.map(renderCustomer)}
            </>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { LockKeyhole, RotateCcw } from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { money } from "@/components/estimator/aioPricing";
import { typeEditFields } from "@/components/estimator/parts/partCatalog";

const displayValue = (value) => {
  if (Array.isArray(value)) return value.join(", ");
  if (value === true) return "Yes";
  if (value === false) return "No";
  if (value === undefined || value === null || value === "") return "—";
  return String(value).replace(/_/g, " ");
};

const inputValue = (field) => {
  if (field.kind === "list") return Array.isArray(field.value) ? field.value.join(", ") : (field.value || "");
  if (field.kind === "boolean") return field.value === true ? "true" : field.value === false ? "false" : "";
  return field.value ?? "";
};

export default function DetachedPartOverrideModal({ open, part, onClose, onSave, mode = "detached" }) {
  const [form, setForm] = useState({});
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const saveRef = useRef(false);

  useEffect(() => {
    if (!open || !part) return;
    setForm({
      part_name: part.part_name || "Part",
      client_label: part.client_label || "",
      quantity: Number(part.quantity || 1),
      unit: part.unit || "",
      frozen_unit_cost: Number(part.frozen_unit_cost || 0),
      manual_cost_override_reason: part.manual_cost_override_reason || "",
      notes: part.notes || "",
      detail_overrides: { ...(part.detail_overrides || {}) },
    });
    setSaving(false);
    setError("");
    saveRef.current = false;
  }, [open, part?.id]);

  const set = (key, value) => setForm((current) => ({ ...current, [key]: value }));
  const detailFields = useMemo(
    () => typeEditFields(part?.inventory_entity, part?.frozen_inventory_snapshot || {}, form.detail_overrides || {}),
    [part?.inventory_entity, part?.frozen_inventory_snapshot, form.detail_overrides]
  );
  const extended = Number(form.quantity || 0) * Number(form.frozen_unit_cost || 0);
  const isManual = mode === "manual";
  const overrideCount = Object.keys(form.detail_overrides || {}).length;

  const setDetail = (field, rawValue, kind) => {
    let value = rawValue;
    if (kind === "number") value = rawValue === "" ? "" : Number(rawValue);
    if (kind === "boolean") value = rawValue === "" ? "" : rawValue === "true";
    if (kind === "list") {
      value = String(rawValue || "")
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean);
    }
    setForm((current) => ({
      ...current,
      detail_overrides: { ...(current.detail_overrides || {}), [field]: value },
    }));
  };

  const resetDetail = (field) => {
    setForm((current) => {
      const next = { ...(current.detail_overrides || {}) };
      delete next[field];
      return { ...current, detail_overrides: next };
    });
  };

  const submit = async (event) => {
    event.preventDefault();
    if (saveRef.current) return;
    saveRef.current = true;
    setSaving(true);
    setError("");
    try {
      await onSave?.(form);
    } catch (err) {
      setError(err?.message || "The Part override could not be saved.");
      saveRef.current = false;
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(next) => !next && !saving && onClose?.()}>
      <DialogContent className="sm:max-w-[980px] p-0 overflow-hidden border border-gray-300 shadow-xl">
        <div className="bg-[#444] border-b-4 border-amber-300 px-5 py-4 text-white">
          <DialogHeader>
            <DialogTitle className="text-white flex items-center gap-2 text-[16px]">
              <LockKeyhole className="w-5 h-5 text-amber-300" aria-hidden="true" /> {isManual ? "Edit Independent Product Part" : "Detached Part Override"}
            </DialogTitle>
          </DialogHeader>
          <p className="text-[11px] text-gray-200 mt-1">
            {isManual
              ? "Edit the estimate-specific Part while retaining its frozen Master Inventory source and quote pricing history."
              : "This Part is frozen independently and will not be overwritten when the Builder is saved."}
          </p>
        </div>

        <form onSubmit={submit} className="p-5 bg-white space-y-4 max-h-[78vh] overflow-y-auto">
          <section className="rounded border border-gray-200 bg-white p-4">
            <div className="text-[9px] font-extrabold tracking-widest text-gray-500 mb-3">PART INFORMATION</div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
              <label className="text-[10px] font-bold tracking-wide text-gray-500 sm:col-span-2">PART NAME<input value={form.part_name || ""} onChange={(e) => set("part_name", e.target.value)} className="mt-1 h-[32px] w-full border border-gray-300 rounded px-2 text-[12px]" /></label>
              <label className="text-[10px] font-bold tracking-wide text-gray-500 sm:col-span-2">CLIENT LABEL<input value={form.client_label || ""} onChange={(e) => set("client_label", e.target.value)} className="mt-1 h-[32px] w-full border border-gray-300 rounded px-2 text-[12px]" /></label>
              <label className="text-[10px] font-bold tracking-wide text-gray-500">QUANTITY<input type="number" step="any" min="0" value={form.quantity ?? 0} onChange={(e) => set("quantity", Number(e.target.value))} className="mt-1 h-[32px] w-full border border-gray-300 rounded px-2 text-[12px]" /></label>
              <label className="text-[10px] font-bold tracking-wide text-gray-500">UNIT<input value={form.unit || ""} onChange={(e) => set("unit", e.target.value)} className="mt-1 h-[32px] w-full border border-gray-300 rounded px-2 text-[12px]" /></label>
              <label className="text-[10px] font-bold tracking-wide text-gray-500">FROZEN UNIT COST<input type="number" step="any" min="0" value={form.frozen_unit_cost ?? 0} onChange={(e) => set("frozen_unit_cost", Number(e.target.value))} className="mt-1 h-[32px] w-full border border-gray-300 rounded px-2 text-[12px]" /></label>
              <div className="rounded border border-gray-200 bg-gray-50 px-3 py-2"><div className="text-[9px] font-bold tracking-wide text-gray-400">NEW FROZEN EXTENDED</div><div className="text-[15px] font-bold text-gray-900 mt-1">{money(extended)}</div>{(Number(form.quantity) < 0 || Number(form.frozen_unit_cost) < 0) && <div className="text-[9px] font-semibold text-amber-600 mt-1">Negative quantity or cost reduces the frozen total.</div>}</div>
              {(part?.manual_cost_override || Number(form.frozen_unit_cost) !== Number(part?.frozen_unit_cost)) && (
                <label className="text-[10px] font-bold tracking-wide text-amber-700 sm:col-span-2 lg:col-span-4">COST OVERRIDE REASON
                  <input
                    value={form.manual_cost_override_reason || ""}
                    onChange={(e) => set("manual_cost_override_reason", e.target.value)}
                    placeholder="Why is this cost being overridden? (e.g. negotiated price, damaged stock credit)"
                    className="mt-1 h-[32px] w-full border border-amber-300 rounded px-2 text-[12px] bg-white"
                  />
                </label>
              )}
            </div>
          </section>

          {detailFields.length > 0 && (
            <section className="rounded border border-amber-200 bg-amber-50/30 p-4">
              <div className="flex items-center justify-between gap-3 mb-3">
                <div>
                  <div className="text-[9px] font-extrabold tracking-widest text-gray-600">TYPE-SPECIFIC PART DETAILS</div>
                  <div className="text-[10px] text-gray-500 mt-1">These values override this estimate Part only. The frozen Master Inventory snapshot is never rewritten.</div>
                </div>
                <button
                  type="button"
                  disabled={overrideCount === 0}
                  onClick={() => { if (!window.confirm(`Reset all ${overrideCount} type-specific override${overrideCount === 1 ? "" : "s"} back to the Master Inventory values?`)) return; set("detail_overrides", {}); }}
                  className="h-[28px] px-3 rounded border border-gray-300 bg-white text-[10px] font-semibold text-gray-600 hover:bg-gray-50 disabled:opacity-40 inline-flex items-center gap-1"
                ><RotateCcw className="w-3 h-3" aria-hidden="true" /> Reset All ({overrideCount})</button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                {detailFields.map((field) => (
                  <div key={field.field} className={`rounded border p-3 ${field.overridden ? "border-amber-300 bg-amber-50" : "border-gray-200 bg-white"}`}>
                    <div className="flex items-center justify-between gap-2 mb-1">
                      <label className="text-[10px] font-bold tracking-wide text-gray-600">{field.label}</label>
                      {field.overridden && (
                        <button type="button" onClick={() => resetDetail(field.field)} className="text-[9px] font-semibold text-amber-700 hover:underline">Reset</button>
                      )}
                    </div>
                    {field.kind === "boolean" ? (
                      <select value={inputValue(field)} onChange={(e) => setDetail(field.field, e.target.value, field.kind)} aria-label={field.label} className="h-[32px] w-full border border-gray-300 rounded px-2 text-[11px] bg-white">
                        <option value="">Use Master Inventory value</option>
                        <option value="true">Yes</option>
                        <option value="false">No</option>
                      </select>
                    ) : (
                      <input
                        type={field.kind === "number" ? "number" : "text"}
                        step={field.kind === "number" ? "any" : undefined}
                        value={inputValue(field)}
                        onChange={(e) => setDetail(field.field, e.target.value, field.kind)}
                        aria-label={field.label}
                        className="h-[32px] w-full border border-gray-300 rounded px-2 text-[11px] bg-white"
                        placeholder={field.kind === "list" ? "Comma-separated values" : ""}
                      />
                    )}
                    <div className="mt-1.5 text-[9px] text-gray-400">Master Inventory: <span className="font-medium text-gray-500">{displayValue(field.inherited)}</span></div>
                  </div>
                ))}
              </div>
            </section>
          )}

          <section className="rounded border border-gray-200 bg-white p-4">
            <label className="text-[10px] font-bold tracking-wide text-gray-500 block">PART NOTES<textarea value={form.notes || ""} onChange={(e) => set("notes", e.target.value)} rows={3} className="mt-1 w-full border border-gray-300 rounded px-2 py-2 text-[12px]" /></label>
          </section>

          <div className="rounded border border-amber-200 bg-amber-50 px-3 py-2 text-[10px] text-amber-800">
            {isManual
              ? "This is an explicit Product Part edit. Frozen cost changes are audited immediately; type-specific overrides remain estimate-only; future Master Inventory pricing remains separate until Update Price is accepted."
              : "Saving this override changes the Product frozen total only by this Part's cost difference. It does not update or recalculate the Builder. Type-specific overrides remain estimate-only until the Part is reattached."}
          </div>
          {error && <div role="alert" className="rounded border border-red-200 bg-red-50 px-3 py-2 text-[11px] text-red-700">{error}</div>}
          <div className="flex justify-end gap-2 sticky bottom-0 bg-white pt-2 border-t border-gray-100">
            <button type="button" disabled={saving} onClick={onClose} className="h-[32px] px-4 rounded border border-gray-300 bg-white text-[12px] font-semibold text-gray-700">Cancel</button>
            <button type="submit" disabled={saving || !String(form.part_name || "").trim()} className="h-[32px] px-4 rounded border border-amber-400 bg-amber-200 text-[12px] font-bold text-gray-900 hover:bg-amber-300 disabled:opacity-50">{saving ? "Saving…" : isManual ? "Save Part" : "Save Detached Override"}</button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from "react";
import { Plus, StickyNote } from "lucide-react";
import { useAuth } from "@/components/auth/EmailGate";

const fmt = (iso) => {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleString(undefined, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
};

// Append-only estimate note timeline. Entries are {text, by, at} objects on
// estimate.notes_log — the single `notes` field stays the freeform scratch
// pad. Entries are never edited or deleted so the timeline stays trustworthy.
export default function EstimateNotesTimeline({ estimate, onChange, readOnly = false }) {
  const { user } = useAuth();
  const [draft, setDraft] = useState("");
  const log = Array.isArray(estimate?.notes_log) ? estimate.notes_log : [];

  const add = () => {
    const text = draft.trim();
    if (!text || readOnly) return;
    const entry = { text, by: user?.email || user?.full_name || "unknown", at: new Date().toISOString() };
    onChange?.({ notes_log: [...log, entry] });
    setDraft("");
  };

  return (
    <div className="rounded border border-gray-200 bg-white">
      <div className="flex items-center gap-2 px-3 py-2 border-b border-gray-100">
        <StickyNote className="w-3.5 h-3.5 text-gray-400" aria-hidden="true" />
        <span className="text-[11px] font-bold uppercase tracking-wide text-gray-600">Notes timeline</span>
        <span className="text-[10px] text-gray-400">{log.length} {log.length === 1 ? "entry" : "entries"}</span>
      </div>
      {log.length > 0 && (
        <div className="max-h-44 overflow-y-auto px-3 py-2 space-y-1.5">
          {[...log].reverse().map((entry, index) => (
            <div key={`${entry.at}-${index}`} className="text-[11px] leading-snug">
              <span className="text-gray-800 whitespace-pre-wrap">{entry.text}</span>
              <span className="block text-[9px] text-gray-400">{entry.by || "unknown"} · {fmt(entry.at)}</span>
            </div>
          ))}
        </div>
      )}
      {!readOnly && (
        <div className="flex items-center gap-1.5 px-3 py-2 border-t border-gray-100">
          <input
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            aria-label="Add a note to the timeline"
            onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); add(); } }}
            placeholder="Add a note to the timeline…"
            className="flex-1 h-7 px-2 border border-gray-300 rounded text-[11px] focus:outline-none focus:border-emerald-500"
          />
          <button
            type="button"
            onClick={add}
            disabled={!draft.trim()}
            className="h-7 px-2.5 rounded bg-emerald-700 text-white text-[11px] font-bold hover:bg-emerald-800 disabled:opacity-40 flex items-center gap-1"
          >
            <Plus className="w-3 h-3" aria-hidden="true" /> Add
          </button>
        </div>
      )}
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { estimateLineSelectionKey } from "@/components/estimator/estimateCreationService";
import { Search } from "lucide-react";
import ProductRow from "./ProductRow";
import { ESTIMATOR_MODULES, getModuleLabel } from "@/components/estimator/moduleRegistry";
import { acceptedCustomerUnitPrice } from "@/components/estimator/customerPricing";
import { money } from "@/components/estimator/aioPricing";
import { loadProductionProductTypes } from "@/components/estimator/productionProductTypes";

// (#408) Long product lists render in chunks so a 200-line estimate doesn't
// mount every ProductRow at once. "Show more" grows the window; deep links
// expand it as needed to reach their target row.
const ROW_PAGE = 50;
const EMPTY_LINES = [];

export default function EstimateProductsList({ lines = EMPTY_LINES, rawTotal = 0, onChange, onRemove, onEdit, onUpdatePrice, onProductRefresh, onClone, onSaveNotes, onCreateQuickProduct, onPersistSettings, onSplit, readOnly = false }) {
  const [query, setQuery] = useState("");
  const [splitMode, setSplitMode] = useState(false);
  const [splitIds, setSplitIds] = useState(() => new Set());
  const [splitting, setSplitting] = useState(false);
  const [splitError, setSplitError] = useState("");
  const splittingRef = useRef(false);
  const selectionSnapshot = JSON.stringify(lines);
  useEffect(() => {
    setSplitIds(new Set());
    setSplitError("");
  }, [selectionSnapshot, readOnly]);

  const submitSplit = async () => {
    if (splittingRef.current || readOnly || !splitIds.size) return;
    splittingRef.current = true;
    setSplitting(true);
    setSplitError("");
    try {
      const success = await onSplit([...splitIds]);
      if (success === false) return;
      setSplitMode(false);
      setSplitIds(new Set());
    } catch (error) {
      setSplitError(error?.message || "The selected products could not be copied. Try again.");
    } finally {
      splittingRef.current = false;
      setSplitting(false);
    }
  };
  const toggleSplitId = (id) => setSplitIds((prev) => { const next = new Set(prev); if (next.has(id)) next.delete(id); else next.add(id); return next; });
  const [moduleFilter, setModuleFilter] = useState("all");
  const [productionProductTypes, setProductionProductTypes] = useState([]);
  const [rowWindow, setRowWindow] = useState(ROW_PAGE);
  useEffect(() => { setRowWindow(ROW_PAGE); }, [query, moduleFilter]);

  useEffect(() => {
    let active = true;
    loadProductionProductTypes().then((items) => active && setProductionProductTypes(items));
    return () => { active = false; };
  }, []);

  const complete = lines.filter((l) => l.section_status === "complete").length;

  const visible = lines
    .map((line, index) => ({ line, index }))
    .filter(({ line }) => {
      if (moduleFilter !== "all" && line.module_key !== moduleFilter) return false;
      if (!query.trim()) return true;
      const q = query.toLowerCase();
      return (
        (line.project_name || "").toLowerCase().includes(q) ||
        (line.client_product_name || "").toLowerCase().includes(q) ||
        (line.builder_name || "").toLowerCase().includes(q) ||
        (line.product_category || "").toLowerCase().includes(q) ||
        (line.production_product_type || "").toLowerCase().includes(q) ||
        getModuleLabel(line.module_key).toLowerCase().includes(q)
      );
    });

  const visibleSubtotal = visible.reduce((sum, { line }) => {
    const quantity = Math.max(0, Number(line.customer_quantity ?? 1) || 0);
    return sum + acceptedCustomerUnitPrice(line) * quantity * (1 + Number(line.adjustment_percent || 0) / 100);
  }, 0);

  // #311/#323 — ?open=<product_id> / ?line=<id> deep links: make the target
  // row visible (clearing search/module filters when they would hide it),
  // then scroll it into view with a highlight flash. `open` matches the
  // same id set EstimateDetail uses (project_id / id) plus line-level ids.
  const rowRefs = useRef({});
  const deepLinkedLineRef = useRef(false);
  useEffect(() => {
    if (deepLinkedLineRef.current || lines.length === 0) return;
    let wantOpen = "", wantLine = "";
    try {
      const sp = new URLSearchParams(window.location.search);
      wantOpen = sp.get("open") || "";
      wantLine = sp.get("line") || "";
    } catch {}
    if (!wantOpen && !wantLine) return;
    const matchIndex = lines.findIndex((line, index) => {
      const lineId = estimateLineSelectionKey(line, index);
      if (wantLine && (lineId === wantLine || line?.line_id === wantLine || line?.id === wantLine)) return true;
      if (wantOpen && [line?.project_id, line?.id, line?.line_id, line?.builder_product_id, line?.product_id, line?.quick_product_source_id].includes(wantOpen)) return true;
      return false;
    });
    if (matchIndex < 0) { deepLinkedLineRef.current = true; return; }
    const targetKey = estimateLineSelectionKey(lines[matchIndex], matchIndex);
    const isVisible = visible.some(({ line, index }) => estimateLineSelectionKey(line, index) === targetKey);
    if (!isVisible) {
      if (query) setQuery("");
      if (moduleFilter !== "all") setModuleFilter("all");
      return;
    }
    // The target may sit past the render window — expand the window first,
    // then let the effect re-run once the row is actually mounted.
    const visibleIndex = visible.findIndex(({ line, index }) => estimateLineSelectionKey(line, index) === targetKey);
    if (visibleIndex >= rowWindow) {
      setRowWindow(visibleIndex + 1);
      return;
    }
    deepLinkedLineRef.current = true;
    const el = rowRefs.current[targetKey];
    if (el) {
      window.setTimeout(() => {
        el.scrollIntoView({ behavior: "smooth", block: "center" });
        el.classList.add("ring-4", "ring-blue-400", "rounded-md");
        window.setTimeout(() => el.classList.remove("ring-4", "ring-blue-400", "rounded-md"), 3500);
      }, 150);
    }
  }, [lines, visible, query, moduleFilter, rowWindow]);

  return (
    <div className="bg-white border border-gray-200 rounded-md">
      <div className="px-4 py-2 border-b border-gray-200 flex items-center justify-between gap-2">
        <span className="text-[11px] font-bold tracking-wider text-red-600">
          ESTIMATE PRODUCTS ({lines.length})
        </span>
        <span className="text-[10px] px-2 py-0.5 rounded bg-green-50 text-green-700 border border-green-100">
          ⇄ Live-synced with source estimators
        </span>
      </div>

      <div className="px-4 py-2 flex flex-wrap items-center gap-2 border-b border-gray-100">
        <div className="flex-1 relative">
          <Search className="w-3.5 h-3.5 text-gray-400 absolute left-2 top-1/2 -translate-y-1/2" aria-hidden="true" />
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search products..."
            aria-label="Search products in this estimate"
            className="w-full h-[30px] pl-7 pr-2 border border-gray-200 rounded text-[12px]"
          />
        </div>
        <select
          value={moduleFilter}
          onChange={(e) => setModuleFilter(e.target.value)}
          aria-label="Filter by product type"
          className="h-[30px] px-2 border border-gray-200 rounded text-[12px] text-gray-600 bg-white"
        >
          <option value="all">All product types</option>
          <option value="custom">Custom Products</option>
          {ESTIMATOR_MODULES.map((m) => (
            <option key={m.key} value={m.key}>
              {m.label}
            </option>
          ))}
        </select>
        <span className="text-[10px] text-gray-400 whitespace-nowrap">
          {complete}/{lines.length} products complete
        </span>
        {typeof onSplit === "function" && !readOnly && (
          splitMode ? (
            <span className="flex items-center gap-1.5">
              <button type="button" onClick={submitSplit} disabled={splitting || splitIds.size === 0} aria-busy={splitting} className="h-[30px] px-2 rounded bg-indigo-600 text-white text-[11px] font-bold hover:bg-indigo-700 disabled:opacity-40">{splitting ? "Creating draft..." : `Copy ${splitIds.size || ""} to new draft`}</button>
              <button type="button" disabled={splitting} onClick={() => { setSplitMode(false); setSplitIds(new Set()); setSplitError(""); }} className="h-[30px] px-2 rounded border border-gray-300 bg-white text-[11px] text-gray-600">Cancel</button>
            </span>
          ) : (
            <button type="button" onClick={() => setSplitMode(true)} className="h-[30px] px-2 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-600 hover:border-indigo-300">Split…</button>
          )
        )}
      </div>

      {splitMode && !readOnly && (
        <p className="px-4 py-2 text-[11px] text-gray-600" role="status">
          Select products to copy into a new draft. This estimate stays unchanged.
        </p>
      )}
      {splitError && <p className="px-4 py-2 text-[12px] text-red-700" role="alert">{splitError}</p>}
      {visible.length === 0 ? (
        <div className="py-10 text-center text-[12px] text-gray-400">
          {lines.length === 0
            ? "No products yet — add one above to start pricing this estimate."
            : "No products match this search or filter."}
        </div>
      ) : (
        <div className="p-2 space-y-2 bg-gray-50">
          {visible.slice(0, rowWindow).map(({ line, index }) => {
            const lineId = estimateLineSelectionKey(line, index);
            return (
            <div key={lineId} data-line-id={lineId} ref={(el) => { if (el) rowRefs.current[lineId] = el; else delete rowRefs.current[lineId]; }} className="relative">
              {splitMode && !readOnly && (
                <label className="absolute left-1 top-1 z-10 flex items-center justify-center w-5 h-5 rounded border border-indigo-300 bg-white cursor-pointer">
                  <input type="checkbox" disabled={splitting} checked={splitIds.has(lineId)} onChange={() => toggleSplitId(lineId)} className="w-3.5 h-3.5 accent-indigo-600" aria-label={`Select ${line.client_product_name || line.project_name || line.description || `product ${index + 1}`} to split`} />
                </label>
              )}
            <ProductRow
              key={lineId}
              line={line}
              index={index}
              percentOfTotal={rawTotal > 0 ? ((acceptedCustomerUnitPrice(line) * Math.max(0, Number(line.customer_quantity ?? 1) || 0)) / rawTotal) * 100 : null}
              onChange={onChange}
              onRemove={onRemove}
              onEdit={onEdit}
              onUpdatePrice={onUpdatePrice}
              onProductRefresh={onProductRefresh}
              onClone={onClone}
              onSaveNotes={onSaveNotes}
              onCreateQuickProduct={onCreateQuickProduct}
              onPersistSettings={onPersistSettings}
              productionProductTypes={productionProductTypes}
              readOnly={readOnly}
              allLines={lines}
            />
            </div>
            );
          })}
          {visible.length > rowWindow && (
            <button
              type="button"
              onClick={() => setRowWindow((n) => n + ROW_PAGE)}
              className="w-full h-[30px] rounded border border-gray-300 bg-white text-[11px] font-bold text-gray-600 hover:bg-gray-50"
            >
              Show {Math.min(ROW_PAGE, visible.length - rowWindow)} more products ({visible.length - rowWindow} remaining)
            </button>
          )}
        </div>
      )}

      {visible.length > 0 && (
        <div className="px-4 py-2 border-t border-gray-200 flex items-center justify-between gap-2">
          <span className="text-[10px] text-gray-400 whitespace-nowrap">
            {visible.length === lines.length ? `${visible.length} products` : `${visible.length} of ${lines.length} products shown`}
          </span>
          <span className="text-[11px] font-semibold text-gray-600 whitespace-nowrap">
            Sections subtotal: <span className="font-bold text-gray-900 tabular-nums">{money(visibleSubtotal)}</span>
          </span>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";
import FoundationEstimator from "@/pages/FoundationEstimator";
import ChannelLetterEstimator from "@/pages/ChannelLetterEstimator";
import VinylEstimator from "@/pages/VinylEstimator";
import CNCEstimator from "@/pages/CNCEstimator";
import LaserEstimator from "@/pages/LaserEstimator";
import MetalEstimator from "@/pages/MetalEstimator";
import BrickStoneEstimator from "@/pages/BrickStoneEstimator";
import MaintenanceEstimator from "@/pages/MaintenanceEstimator";
import PaintingEstimator from "@/pages/PaintingEstimator";
import CustomItemsEstimator from "@/pages/CustomItemsEstimator";
import ReattachPartsModal from "@/components/estimator/builder/ReattachPartsModal";
import { getDetachedBuilderParts, reattachBuilderParts } from "@/components/estimator/builder/partSync";

const EDITORS = {
  foundation: FoundationEstimator,
  channel_letters: ChannelLetterEstimator,
  vinyl: VinylEstimator,
  cnc: CNCEstimator,
  laser: LaserEstimator,
  metal: MetalEstimator,
  brick_stone: BrickStoneEstimator,
  maintenance: MaintenanceEstimator,
  painting: PaintingEstimator,
  custom_items: CustomItemsEstimator,
};

export default function InlineProductEditor({ line, estimateId, expectedEstimateUpdatedAt = "", onClose, onSaved }) {
  const Editor = EDITORS[line?.module_key];
  const [checkingDetached, setCheckingDetached] = useState(!!line?.builder_product_id);
  const [detachedParts, setDetachedParts] = useState([]);
  const [reattachOpen, setReattachOpen] = useState(false);
  const [reviewHandled, setReviewHandled] = useState(!line?.builder_product_id);
  const [editorVersion, setEditorVersion] = useState(0);

  useEffect(() => {
    let active = true;
    const check = async () => {
      if (!line?.builder_product_id) {
        if (active) {
          setCheckingDetached(false);
          setReviewHandled(true);
        }
        return;
      }
      setCheckingDetached(true);
      setReviewHandled(false);
      try {
        const parts = await getDetachedBuilderParts(line.builder_product_id);
        if (!active) return;
        setDetachedParts(parts);
        setReattachOpen(parts.length > 0);
        setReviewHandled(parts.length === 0);
      } finally {
        if (active) setCheckingDetached(false);
      }
    };
    check();
    return () => {
      active = false;
    };
  }, [line?.builder_product_id, line?.project_id]);

  const keepDetached = () => {
    setReattachOpen(false);
    setReviewHandled(true);
  };

  const reattachSelected = async (partIds) => {
    const result = await reattachBuilderParts({
      builderProductId: line.builder_product_id,
      partIds,
      expectedEstimateUpdatedAt,
      expectedPartVersions: Object.fromEntries(detachedParts.map((part) => [part.id, part.updated_date || ""])),
    });
    setDetachedParts(result.remainingDetached || []);
    setReattachOpen(false);
    setReviewHandled(true);
    setEditorVersion((value) => value + 1);
  };

  if (!Editor || !line?.project_id) {
    return (
      <div className="bg-white border border-gray-200 rounded-md p-6 text-center text-[12px] text-gray-500 space-y-3">
        <div>
          This legacy product no longer has a source project record, so only its saved estimate snapshot is available.
        </div>
        <button
          type="button"
          onClick={onClose}
          className="h-[30px] px-4 rounded border border-gray-300 bg-white text-[12px] font-semibold text-gray-700 hover:bg-gray-50"
        >
          ← Back to Products
        </button>
      </div>
    );
  }

  if (checkingDetached && !reviewHandled) {
    return (
      <div role="status" className="bg-white border border-gray-200 rounded-md p-8 text-center text-[12px] text-gray-500">
        Checking Builder Part links…
      </div>
    );
  }

  return (
    <>
      {reviewHandled && (
        <Editor
          key={`${line.module_key}:${line.project_id}:${editorVersion}`}
          embedded
          embeddedProjectId={line.project_id}
          embeddedEstimateId={estimateId}
          onClose={onClose}
          onSaved={onSaved}
        />
      )}
      <ReattachPartsModal
        open={reattachOpen}
        parts={detachedParts}
        builderName={line.client_product_name || line.project_name || line.builder_name || "Builder"}
        onKeepDetached={keepDetached}
        onReattach={reattachSelected}
      />
    </>
  );
}

import { useState, useEffect, useMemo } from "react";
import { X, Loader2 } from "lucide-react";
import { staffEntities } from "@/components/staff/staffEntities";
import { estimateLineSelectionKey } from "@/components/estimator/estimateCreationService";
import { useEscapeKey, useModalDialog } from "@/components/estimator/a11y";

const lineLabel = (line, index) =>
  line?.client_product_name || line?.product_name || line?.name || `Section ${index + 1}`;

const lineTotal = (line) => {
  const total = Number(line?.total_snapshot ?? line?.quote_total ?? line?.total ?? 0);
  return Number.isFinite(total) && total > 0 ? `$${total.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : "";
};

export default function MergeEstimateDialog({ open, currentEstimateId, onClose, onMerge }) {
  const [candidates, setCandidates] = useState([]);
  const [loadingList, setLoadingList] = useState(false);
  const [listError, setListError] = useState("");
  const [secondary, setSecondary] = useState(null);
  const [loadingSecondary, setLoadingSecondary] = useState(false);
  const [selectedKeys, setSelectedKeys] = useState(new Set());
  const [submitting, setSubmitting] = useState(false);
  const { containerRef, dialogProps } = useModalDialog({ open, labelledBy: "merge-estimate-title" });
  useEscapeKey(open, () => { if (!submitting) onClose?.(); });

  useEffect(() => {
    if (!open) return;
    setSecondary(null);
    setSelectedKeys(new Set());
    setListError("");
    setLoadingList(true);
    (async () => {
      try {
        const rows = await staffEntities.AllInOneEstimate.filter(
          { deleted: { $ne: true } },
          "-updated_date",
          200
        );
        const list = (Array.isArray(rows) ? rows : []).filter(
          (e) => e?.id && e.id !== currentEstimateId && ["draft", "calculated"].includes(String(e.status || "draft"))
        );
        setCandidates(list);
      } catch (e) {
        setListError(e?.message || "Other estimates could not be loaded.");
      } finally {
        setLoadingList(false);
      }
    })();
  }, [open, currentEstimateId]);

  const secondaryLines = useMemo(
    () => (Array.isArray(secondary?.line_items) ? secondary.line_items : []),
    [secondary]
  );

  const pickSecondary = async (id) => {
    setLoadingSecondary(true);
    setSelectedKeys(new Set());
    try {
      const row = await staffEntities.AllInOneEstimate.get(id);
      setSecondary(row || null);
    } catch {
      setSecondary(null);
    } finally {
      setLoadingSecondary(false);
    }
  };

  const toggleLine = (key) => {
    setSelectedKeys((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key); else next.add(key);
      return next;
    });
  };

  const canSubmit = secondary?.id && selectedKeys.size > 0 && !submitting;

  const handleConfirm = async () => {
    if (!canSubmit) return;
    setSubmitting(true);
    try {
      await onMerge({ secondary, lineItemIds: [...selectedKeys] });
    } finally {
      setSubmitting(false);
    }
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/50" onClick={onClose} />
      <div
        ref={containerRef}
        {...dialogProps}
        className="relative bg-white rounded-md shadow-2xl border border-gray-300 w-full max-w-lg max-h-[85vh] flex flex-col"
        style={{ boxShadow: "0 20px 60px rgba(0,0,0,0.3)" }}
      >
        <div className="flex items-center justify-between px-5 pt-4 pb-2">
          <h2 id="merge-estimate-title" className="text-lg font-bold tracking-wide" style={{ color: "#7a9a4b" }}>
            MERGE AN ESTIMATE INTO THIS ONE
          </h2>
          <button type="button" onClick={onClose} className="text-gray-500 hover:text-gray-800 p-1" title="Close" aria-label="Close merge estimate dialog">
            <X className="w-4 h-4" aria-hidden="true" />
          </button>
        </div>

        <div className="px-5 pb-4 overflow-y-auto">
          <p className="text-xs text-gray-600 mb-3">
            Pick another draft estimate, choose the sections to move here. The other estimate is archived afterward with a note pointing back to this one.
          </p>

          {loadingList && <p role="status" className="text-xs text-gray-500 flex items-center gap-2"><Loader2 className="w-3.5 h-3.5 animate-spin" aria-hidden="true" /> Loading drafts…</p>}
          {listError && <p role="alert" className="text-xs text-red-600">{listError}</p>}
          {!loadingList && !listError && candidates.length === 0 && (
            <p className="text-xs text-gray-500">No other draft or calculated estimates to merge.</p>
          )}

          {candidates.length > 0 && (
            <div className="space-y-1 max-h-40 overflow-y-auto border border-gray-200 rounded p-1 mb-3">
              {candidates.map((e) => (
                <button type="button"
                  key={e.id}
                  onClick={() => pickSecondary(e.id)}
                  aria-pressed={secondary?.id === e.id}
                  className={`w-full text-left px-2 py-1.5 rounded text-xs flex items-center justify-between gap-2 ${secondary?.id === e.id ? "bg-emerald-50 border border-emerald-300" : "hover:bg-gray-50 border border-transparent"}`}
                >
                  <span className="min-w-0">
                    <span className="font-semibold">{e.estimate_number ? `#${e.estimate_number} ` : ""}{e.project_name || "Untitled estimate"}</span>
                    <span className="block text-[10px] text-gray-500 truncate">{e.client_name || "No client"} · {e.status || "draft"}</span>
                  </span>
                  {Number(e.quote_total || 0) > 0 && <span className="text-[10px] font-semibold text-gray-600">${Number(e.quote_total).toLocaleString()}</span>}
                </button>
              ))}
            </div>
          )}

          {loadingSecondary && <p role="status" className="text-xs text-gray-500 flex items-center gap-2"><Loader2 className="w-3.5 h-3.5 animate-spin" aria-hidden="true" /> Loading sections…</p>}

          {secondary && !loadingSecondary && (
            <div className="border border-gray-200 rounded p-2">
              <p className="text-[11px] font-semibold text-gray-700 mb-1">Sections to move ({selectedKeys.size} of {secondaryLines.length} selected):</p>
              {secondaryLines.length === 0 && <p className="text-xs text-gray-500">That estimate has no sections.</p>}
              <div className="space-y-1 max-h-48 overflow-y-auto">
                {secondaryLines.map((line, index) => {
                  const key = estimateLineSelectionKey(line, index);
                  return (
                    <label key={key} className="flex items-center gap-2 text-xs px-1.5 py-1 rounded hover:bg-gray-50 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={selectedKeys.has(key)}
                        onChange={() => toggleLine(key)}
                        className="w-3.5 h-3.5 accent-emerald-600"
                      />
                      <span className="flex-1 min-w-0 truncate">{lineLabel(line, index)}</span>
                      <span className="text-[10px] text-gray-500">{lineTotal(line)}</span>
                    </label>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        <div className="flex justify-end gap-2 px-5 pb-4">
          <button type="button" onClick={onClose} className="h-9 px-4 rounded border border-gray-300 text-sm font-semibold text-gray-600 hover:bg-gray-50">
            Cancel
          </button>
          <button
            type="button"
            onClick={handleConfirm}
            disabled={!canSubmit}
            className="h-9 px-4 rounded bg-emerald-700 text-white text-sm font-bold hover:bg-emerald-800 disabled:opacity-50"
          >
            {submitting ? "Merging…" : `Merge ${selectedKeys.size || ""} section${selectedKeys.size === 1 ? "" : "s"}`}
          </button>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import { ArrowRightLeft } from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";

const EMPTY_PRODUCTS = [];

export default function MovePartGroupModal({ open, group, sourceBuilderProductId, products = EMPTY_PRODUCTS, onClose, onMove }) {
  const targets = useMemo(
    () => (products || []).filter((line) => line.builder_product_id && line.builder_product_id !== sourceBuilderProductId),
    [products, sourceBuilderProductId]
  );
  const [targetId, setTargetId] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!open) return;
    setTargetId(targets[0]?.builder_product_id || "");
    setSaving(false);
    setError("");
  }, [open, targets.length]);

  const submit = async () => {
    if (!targetId) return;
    setSaving(true);
    setError("");
    try {
      await onMove?.(targetId);
    } catch (err) {
      setError(err?.message || "Part Group could not be moved.");
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(next) => !next && !saving && onClose?.()}>
      <DialogContent className="sm:max-w-[520px] p-0 overflow-hidden border border-gray-300 shadow-xl">
        <div className="bg-[#444] border-b-4 border-lime-300 px-5 py-4 text-white">
          <DialogHeader>
            <DialogTitle className="text-white flex items-center gap-2 text-[16px]"><ArrowRightLeft className="w-5 h-5 text-lime-300" aria-hidden="true" /> Move Part Group</DialogTitle>
          </DialogHeader>
          <p className="text-[11px] text-gray-200 mt-1">Moves the entire group and all child Parts as one unit. Frozen/current pricing moves with it.</p>
        </div>
        <div className="p-5 bg-white space-y-4">
          <div className="rounded border border-gray-200 bg-gray-50 px-3 py-2">
            <div className="text-[9px] font-bold tracking-widest text-gray-400">GROUP</div>
            <div className="text-[13px] font-bold text-gray-900 mt-1">{group?.group_name || "Part Group"}</div>
          </div>
          <label className="block text-[10px] font-bold tracking-wide text-gray-500">
            MOVE TO PRODUCT
            <select value={targetId} onChange={(event) => setTargetId(event.target.value)} className="mt-1 h-[34px] w-full border border-gray-300 rounded bg-white px-2 text-[12px] text-gray-800">
              {targets.length === 0 && <option value="">No other Products available</option>}
              {targets.map((line) => (
                <option key={line.builder_product_id} value={line.builder_product_id}>{line.client_product_name || line.project_name || line.builder_name || "Product"}</option>
              ))}
            </select>
          </label>
          <div className="rounded border border-blue-200 bg-blue-50 px-3 py-2 text-[10px] text-blue-800">Direct Move is available only for groups made entirely from independent/manual Parts. Builder-owned Parts must use Clone or Copy so the source Builder stays internally consistent.</div>
          {error && <div role="alert" className="rounded border border-red-200 bg-red-50 px-3 py-2 text-[11px] text-red-700">{error}</div>}
          <div className="flex justify-end gap-2">
            <button type="button" disabled={saving} onClick={onClose} className="h-[32px] px-4 rounded border border-gray-300 bg-white text-[12px] font-semibold text-gray-700">Cancel</button>
            <button type="button" disabled={saving || !targetId} onClick={submit} className="h-[32px] px-4 rounded border border-lime-400 bg-lime-200 text-[12px] font-bold text-gray-900 hover:bg-lime-300 disabled:opacity-50">{saving ? "Moving…" : "Move Group"}</button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect, useRef, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { ensureNewCustomer, newCustomerCreationKey } from "@/components/estimator/customerCreationService";
import { useAuth } from "@/components/auth/EmailGate";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { staffEntities } from "@/components/staff/staffEntities";

const FIELDS = [
  { key: "company_name", label: "Company name *" },
  { key: "company_phone", label: "Company phone" },
  { key: "contact_first_name", label: "Contact first name" },
