const priceMeta = (line) => {
  const frozen = Number(line.total_snapshot || 0);
  const live = Number(line.live_total_snapshot ?? frozen);
  const customer = acceptedCustomerUnitPrice(line);
  const liveCustomer = liveCustomerUnitPrice(line);
  const differs = Math.abs(live - frozen) > 0.005 || Math.abs(liveCustomer - customer) > 0.005;

  if (line.needs_reattach_review || line.price_state === "detached_parts") {
    return {
      label: "Parts need reattach",
      className: "bg-amber-50 text-amber-700 border-amber-200",
      icon: AlertTriangle,
      differs,
    };
  }
  if (line.price_recalc_required) {
    return {
      label: "Price changed · recalculate Builder",
      className: "bg-amber-50 text-amber-700 border-amber-200",
      icon: AlertTriangle,
      differs: true,
    };
  }
  if (line.price_state === "legacy_frozen") {
    return {
      label: differs ? "Legacy price frozen · update available" : "Legacy price frozen",
      className: "bg-slate-100 text-slate-600 border-slate-200",
      icon: LockKeyhole,
      differs,
    };
  }
  if (line.price_state === "manual") {
    return {
      label: differs ? "Manual sell price · Builder price differs" : "Manual sell price",
      className: "bg-blue-50 text-blue-700 border-blue-200",
      icon: Percent,
      differs,
    };
  }
  if (line.price_state === "changed" || differs) {
    return {
      label: "Price changed",
      className: "bg-amber-50 text-amber-700 border-amber-200",
      icon: AlertTriangle,
      differs: true,
    };
  }
  if (line.price_state === "unchecked") {
    return {
      label: "Not priced yet",
      className: "bg-gray-50 text-gray-500 border-gray-200",
      icon: LockKeyhole,
      differs: false,
    };
  }
  return {
    label: "Price current",
    className: "bg-green-50 text-green-700 border-green-200",
    icon: CheckCircle2,
    differs: false,
  };
};

export default function ProductRow({
  line,
  index,
  percentOfTotal,
  onChange,
  onRemove,
  onEdit,
  onUpdatePrice,
  onProductRefresh,
  onClone,
  onSaveNotes,
  onCreateQuickProduct,
  onPersistSettings,
  productionProductTypes = [],
  readOnly = false,
  allLines = [],
}) {
  const [open, setOpen] = useState(false);
  const [partsOpen, setPartsOpen] = useState(true);
  const [partCount, setPartCount] = useState(0);
  const [updatingPrice, setUpdatingPrice] = useState(false);
  const [cloning, setCloning] = useState(false);
  const [notesOpen, setNotesOpen] = useState(false);
  const [priceHistoryOpen, setPriceHistoryOpen] = useState(false);
  const [quickProductOpen, setQuickProductOpen] = useState(false);
  const [copyingClipboard, setCopyingClipboard] = useState(false);
  const [copiedClipboard, setCopiedClipboard] = useState(false);
  const [partPickerOpen, setPartPickerOpen] = useState(false);
  const set = (patch) => onChange(index, patch);
  const commit = (patch) => onPersistSettings?.(line, index, patch);
  const frozen = Number(line.total_snapshot || 0);
  const live = Number(line.live_total_snapshot ?? frozen);
  const customerPrice = acceptedCustomerUnitPrice(line);
  const liveCustomerPrice = liveCustomerUnitPrice(line);
  const productQuantity = Math.max(0, Number(line.customer_quantity ?? 1) || 0);
  const amount = customerPrice * productQuantity * (1 + Number(line.adjustment_percent || 0) / 100);
  const meta = priceMeta(line);
  const pendingPriceAcceptance = line.price_acceptance_pending?.key ? line.price_acceptance_pending : null;
  const priceAcceptancePending = !!pendingPriceAcceptance;
  const pendingStale = pendingBuilderMutationIsStale(line);
  const [costTrend, setCostTrend] = useState(null);
  const loadCostTrend = async () => {
    if (costTrend !== null || !line.builder_product_id) return;
    try {
      const rows = await loadAllEntityRows({ entity: base44.entities.BuilderPriceRevision, query: { builder_product_id: line.builder_product_id }, sort: "revision_number", label: "Product cost trend" });
      setCostTrend((rows || []).map((row) => Number(row.new_total_cost ?? row.total_cost ?? row.new_customer_price ?? 0)).filter((v) => Number.isFinite(v)));
    } catch {
      setCostTrend([]);
    }
  };
  const sparkPoints = (() => {
    if (!costTrend || costTrend.length < 2) return "";
    const min = Math.min(...costTrend), max = Math.max(...costTrend), span = max - min || 1;
    const w = 56, h = 14;
    return costTrend.map((v, i) => `${((i / (costTrend.length - 1)) * w).toFixed(1)},${(h - ((v - min) / span) * h).toFixed(1)}`).join(" ");
  })();
  const pendingPriceLabel = pendingPriceAcceptance?.kind === "builder_initial_freeze"
    ? "Resume Initial Price"
    : pendingPriceAcceptance?.kind === "builder_detach_override"
      ? "Resume Part Detach"
      : pendingPriceAcceptance?.kind === "builder_detached_override_update"
        ? "Resume Part Change"
        : pendingPriceAcceptance?.kind === "builder_reattach_parts"
          ? "Resume Reattach"
          : pendingPriceAcceptance?.kind === "builder_manual_part_add"
            ? "Resume Part Add"
            : pendingPriceAcceptance?.kind === "builder_manual_part_edit"
              ? "Resume Part Edit"
              : pendingPriceAcceptance?.kind === "builder_manual_part_switch"
                ? "Resume Part Switch"
                : pendingPriceAcceptance?.kind === "builder_manual_part_remove"
                  ? "Resume Part Remove"
                  : pendingPriceAcceptance?.kind === "builder_part_package_add"
                    ? "Resume Part Insert"
                    : pendingPriceAcceptance?.kind === "builder_manual_product_price"
                      ? "Resume Product Price"
                      : pendingPriceAcceptance?.kind === "builder_part_group_clone"
                        ? "Resume Group Clone"
                        : pendingPriceAcceptance?.kind === "builder_part_group_move"
                          ? "Resume Group Move"
                          : pendingPriceAcceptance?.kind === "builder_part_group_create"
                            ? "Resume Group Create"
                            : pendingPriceAcceptance?.kind === "builder_part_group_dissolve"
                              ? "Resume Group Dissolve"
                              : pendingPriceAcceptance?.kind === "builder_blank_product_insert"
                                ? "Resume Product Add"
                                : pendingPriceAcceptance?.kind === "builder_product_remove"
                                  ? "Resume Product Remove"
                                  : pendingPriceAcceptance?.kind === "builder_quick_product_insert"
                        ? pendingPriceAcceptance?.source_type === "product_clone" ? "Resume Product Clone" : "Resume Quick Product"
                        : "Resume Price Update";
  const isCustom = line.module_key === "custom";
  const StatusIcon = meta.icon;

  const handleUpdatePrice = async () => {
    if (readOnly || !onUpdatePrice || updatingPrice) return;
    setUpdatingPrice(true);
    try {
      await onUpdatePrice(line, index);
    } finally {
      setUpdatingPrice(false);
    }
  };

  const handleClone = async () => {
    if (readOnly || !onClone || cloning) return;
    const name = line.client_product_name || line.project_name || "Product";
    if (!window.confirm(`Clone "${name}"?\n\nThe copy will preserve its Builder configuration, Parts, Part Groups, detached overrides and frozen pricing as a new independent Product.`)) return;
    setCloning(true);
    try {
      await onClone(line, index);
    } finally {
      setCloning(false);
    }
  };

  return (
    <div className="border border-gray-300 rounded-sm overflow-hidden bg-white shadow-sm">
      <div className="px-3 py-2.5 flex items-center gap-2.5 bg-white border-l-[4px] border-lime-300 hover:bg-gray-50">
        <button
          type="button"
          onClick={() => setPartsOpen((value) => !value)}
          aria-expanded={partsOpen}
          aria-label={partsOpen ? `Collapse parts for ${line.client_product_name || line.project_name || "product"}` : `Expand parts for ${line.client_product_name || line.project_name || "product"}`}
          className="w-[26px] h-[26px] rounded border border-gray-200 bg-white flex items-center justify-center text-gray-600 hover:bg-gray-100 flex-shrink-0"
          title={partsOpen ? "Collapse Product Parts" : "Expand Product Parts"}
        >
          {partsOpen ? <ChevronDown className="w-4 h-4" aria-hidden="true" /> : <ChevronRight className="w-4 h-4" aria-hidden="true" />}
        </button>
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-[13px] font-bold text-gray-900 truncate">
              {line.client_product_name || line.project_name || getModuleLabel(line.module_key)}
            </span>
            {isCustom ? (
              <span className="text-[10px] px-2 py-0.5 rounded-sm bg-lime-100 text-gray-800 border border-lime-300 inline-flex items-center gap-1">
                <Layers3 className="w-3 h-3 text-lime-700" aria-hidden="true" /> CUSTOM PRODUCT
              </span>
            ) : (
              <span className="text-[10px] px-2 py-0.5 rounded-sm bg-[#454545] text-white border border-gray-700 inline-flex items-center gap-1">
                <Layers3 className="w-3 h-3 text-lime-300" aria-hidden="true" /> BUILDER · {line.builder_name || getModuleLabel(line.module_key)}
              </span>
            )}
            {line.owned && (
              <span className="text-[10px] px-2 py-0.5 rounded-full bg-blue-50 text-blue-600 border border-blue-100">
                ⚡ Built here
              </span>
            )}
            <span className={`text-[10px] px-2 py-0.5 rounded-full border inline-flex items-center gap-1 ${meta.className}`}>
              <StatusIcon className="w-3 h-3" aria-hidden="true" /> {meta.label}
            </span>
          </div>
          <div className="text-[10px] text-gray-400 mt-0.5">
            {line.project_name && line.project_name !== line.client_product_name ? `Source: ${line.project_name} · ` : ""}
            {line.section_status === "complete" ? "complete" : "in progress"}
            {line.product_category ? ` · ${line.product_category}` : ""}
            {line.production_product_type ? ` · Production: ${line.production_product_type}` : ""}
            {` · ${partCount} Part${partCount === 1 ? "" : "s"}`}
            {line.linked_date ? ` · added ${new Date(line.linked_date).toLocaleDateString()}` : ""}
          </div>
        </div>

        <div className="grid grid-cols-[62px_100px_112px] gap-1.5 flex-shrink-0 items-start">
          <QuickNumberField
            label="QTY"
            value={line.customer_quantity ?? 1}
            min="0.01"
            step="1"
            disabled={readOnly || priceAcceptancePending}
            title="Customer quantity"
            onChange={(e) => set({ customer_quantity: Math.max(0.01, parseFloat(e.target.value) || 1) })}
            onBlur={(e) => commit({ customer_quantity: Math.max(0.01, parseFloat(e.target.value) || 1) })}
          />
          <div className="min-w-0">
            <QuickNumberField
              label="UNIT SELL"
              value={customerPrice}
              prefix="$"
              step="0.01"
              disabled={readOnly || priceAcceptancePending}
              title="Accepted customer selling price per unit. Internal cost is not changed."
              onChange={(e) => set({ customer_price_snapshot: e.target.value })}
              onBlur={(e) => commit({ customer_price_snapshot: Math.max(0, parseFloat(e.target.value) || 0) })}
            />
            {meta.differs && (
              <div className="text-[8px] leading-3 text-amber-600 text-right truncate mt-0.5" title={`Current Builder customer price ${money(liveCustomerPrice)}`}>
                live {money(liveCustomerPrice)}
              </div>
            )}
          </div>
          <div className="min-w-0 text-right" onMouseEnter={loadCostTrend} onFocus={loadCostTrend}>
            <div className="text-[8px] leading-none font-extrabold tracking-wider text-gray-400 mb-1">TOTAL</div>
            <div className="h-[28px] px-2 rounded-sm border border-gray-200 bg-gray-50 flex items-center justify-end text-[12px] font-bold tabular-nums text-gray-900">
              {money(amount)}
            </div>
            {sparkPoints && (
              <svg width="56" height="14" viewBox="0 0 56 14" className="ml-auto mt-0.5" role="img" aria-label={`Part cost history across ${costTrend.length} revisions`} title={`Cost history (${costTrend.length} revisions): ${money(costTrend[0])} → ${money(costTrend[costTrend.length - 1])}`}>
                <polyline points={sparkPoints} fill="none" stroke="#f59e0b" strokeWidth="1.5" />
              </svg>
            )}
            <div className="text-[8px] leading-3 text-gray-400 mt-0.5 whitespace-nowrap">
              {Number(line.adjustment_percent || 0) !== 0 ? `${Number(line.adjustment_percent || 0) > 0 ? "+" : ""}${Number(line.adjustment_percent || 0)}% adj · ` : ""}
              {percentOfTotal != null ? `${percentOfTotal.toFixed(0)}% of estimate` : ""}
            </div>
          </div>
        </div>

        {(meta.differs || priceAcceptancePending) && (line.builder_product_id || ["builder_quick_product_insert", "builder_blank_product_insert", "builder_product_remove"].includes(pendingPriceAcceptance?.kind)) && (
          priceAcceptancePending ? (
            <button
              type="button"
              onClick={handleUpdatePrice}
              disabled={updatingPrice || readOnly}
              className={`h-[28px] px-3 border rounded flex items-center gap-1 text-[12px] font-semibold disabled:opacity-50 ${pendingStale ? "border-red-300 bg-red-50 text-red-800 hover:bg-red-100" : "border-orange-300 bg-orange-50 text-orange-800 hover:bg-orange-100"}`}
              title={pendingPriceAcceptance?.kind === "builder_initial_freeze"
                ? "Resume the previously started initial Builder price freeze from its saved recovery marker."
                : pendingPriceAcceptance?.kind === "builder_detach_override"
                  ? "Resume the previously started detached-Part operation from its saved recovery marker."
                  : pendingPriceAcceptance?.kind === "builder_detached_override_update"
                    ? "Resume the previously started detached-Part override change from its saved recovery marker."
                    : pendingPriceAcceptance?.kind === "builder_reattach_parts"
                      ? "Resume the previously started Part reattachment from its saved recovery marker."
                      : pendingPriceAcceptance?.kind === "builder_manual_part_add"
                        ? "Resume the previously started manual Part add from its saved recovery marker."
                        : pendingPriceAcceptance?.kind === "builder_manual_part_edit"
                          ? "Resume the previously started manual Part edit from its saved recovery marker."
                          : pendingPriceAcceptance?.kind === "builder_manual_part_switch"
                            ? "Resume the previously started manual Part switch from its saved recovery marker."
                            : pendingPriceAcceptance?.kind === "builder_manual_part_remove"
                              ? "Resume the previously started manual Part removal from its saved recovery marker."
                              : pendingPriceAcceptance?.kind === "builder_part_package_add"
                                ? "Resume the previously started Saved Part / clipboard insertion from its saved recovery marker."
                                : pendingPriceAcceptance?.kind === "builder_manual_product_price"
                                  ? "Resume the previously started manual Product customer-price adjustment from its saved recovery marker."
                                  : pendingPriceAcceptance?.kind === "builder_part_group_clone"
                                    ? "Resume the previously started Part Group clone from its saved recovery marker."
                                    : pendingPriceAcceptance?.kind === "builder_part_group_move"
                                      ? "Resume the previously started two-Product Part Group move from its saved recovery marker."
                                      : pendingPriceAcceptance?.kind === "builder_part_group_create"
                                        ? "Resume the previously started Part Group creation from its saved recovery marker."
                                        : pendingPriceAcceptance?.kind === "builder_part_group_dissolve"
                                          ? "Resume the previously started Part Group dissolve from its saved recovery marker."
                                          : pendingPriceAcceptance?.kind === "builder_blank_product_insert"
                                            ? "Resume the previously started blank Product creation from its saved recovery marker."
                                            : pendingPriceAcceptance?.kind === "builder_product_remove"
                                              ? "Resume the previously started Product removal from its saved recovery marker."
                                              : pendingPriceAcceptance?.kind === "builder_quick_product_insert"
                                    ? pendingPriceAcceptance?.source_type === "product_clone"
                                      ? "Resume the previously started Product clone from its saved recovery marker."
                                      : "Resume the previously started Quick Product insertion from its saved recovery marker."
                                    : "Resume the previously started Update Price operation from its saved recovery marker."}
            >
              <RefreshCw className={`w-3 h-3 ${updatingPrice ? "animate-spin" : ""}`} aria-hidden="true" />
              {updatingPrice ? "Recovering…" : pendingPriceLabel}{pendingStale ? " · stale >24h" : ""}
            </button>
          ) : line.needs_reattach_review || line.price_state === "detached_parts" ? (
            <button
              type="button"
              disabled
              className="h-[28px] px-3 border border-amber-300 bg-amber-50 rounded flex items-center gap-1 text-[12px] font-semibold text-amber-700 cursor-not-allowed"
              title="Resolve or reattach detached Parts before updating this product's price."
            >
              <AlertTriangle className="w-3 h-3" aria-hidden="true" />
              Resolve Parts First
            </button>
          ) : line.price_recalc_required ? (
            <button
              type="button"
              onClick={() => onEdit?.(line, index)}
              disabled={readOnly}
              className="h-[28px] px-3 border border-amber-300 bg-amber-50 rounded flex items-center gap-1 text-[12px] font-semibold text-amber-800 hover:bg-amber-100 disabled:opacity-50"
              title={line.price_recalc_reason || "Open this Builder, recalculate with current Master Inventory, then save it before accepting Update Price."}
            >
              <RefreshCw className="w-3 h-3" aria-hidden="true" />
              Recalculate Builder
            </button>
          ) : (
            <button
              type="button"
              onClick={handleUpdatePrice}
              disabled={updatingPrice || readOnly}
              className="h-[28px] px-3 border border-lime-400 bg-lime-200 rounded flex items-center gap-1 text-[12px] font-semibold text-gray-800 hover:bg-lime-300 disabled:opacity-50"
              title={`Accept current customer price ${money(liveCustomerPrice)} (internal cost ${money(live)})`}
            >
              <RefreshCw className={`w-3 h-3 ${updatingPrice ? "animate-spin" : ""}`} aria-hidden="true" />
              {updatingPrice ? "Updating…" : "Update Price"}
            </button>
          )
        )}

        <button
          type="button"
          onClick={() => isCustom ? setOpen((value) => !value) : onEdit?.(line, index)}
          disabled={readOnly && !isCustom}
          aria-expanded={isCustom ? open : undefined}
          className="h-[28px] px-3 border border-gray-200 rounded flex items-center gap-1 text-[12px] text-gray-700 hover:bg-gray-100 disabled:opacity-50"
        >
          <Pencil className="w-3 h-3" aria-hidden="true" /> {isCustom ? "Product Settings" : "Edit Product"}
        </button>
        {line.builder_product_id && (
          <button
            type="button"
            onClick={() => setPartPickerOpen(true)}
            disabled={readOnly}
            title={isCustom ? "Add Part from Master Inventory" : "Add independent Part from Master Inventory"}
            aria-label={isCustom ? "Add Part from Master Inventory" : "Add independent Part from Master Inventory"}
            className="h-[28px] px-2.5 border border-lime-300 bg-lime-50 rounded flex items-center justify-center gap-1 text-[11px] font-semibold text-gray-700 hover:bg-lime-100"
          >
            <Plus className="w-3.5 h-3.5 text-lime-700" aria-hidden="true" /><span className="hidden xl:inline">Add Part</span>
          </button>
        )}
        <button
          type="button"
          onClick={() => setNotesOpen(true)}
          disabled={readOnly}
          title="Manage Product Notes"
          aria-label="Manage Product Notes"
          className={`h-[28px] px-2.5 border rounded flex items-center justify-center gap-1 text-[11px] font-semibold ${line.product_notes ? "border-lime-300 text-lime-700 bg-lime-50" : "border-gray-200 text-gray-600 hover:bg-gray-100"}`}
        >
          <StickyNote className="w-3.5 h-3.5" aria-hidden="true" /><span className="hidden xl:inline">Notes</span>
        </button>
        {line.builder_product_id && (
          <button
            type="button"
            onClick={() => setPriceHistoryOpen(true)}
            title="View Product Price History"
            aria-label="View Product Price History"
            className="h-[28px] px-2.5 border border-gray-200 rounded flex items-center justify-center gap-1 text-[11px] font-semibold text-gray-600 hover:bg-gray-100"
          >
            <History className="w-3.5 h-3.5" aria-hidden="true" /><span className="hidden 2xl:inline">History</span>
          </button>
        )}
        <button
          type="button"
          onClick={() => setQuickProductOpen(true)}
          title="Create Quick Product"
          aria-label="Create Quick Product"
          className="h-[28px] px-2.5 border border-gray-200 rounded flex items-center justify-center gap-1 text-[11px] font-semibold text-gray-600 hover:bg-gray-100"
        >
          <PackagePlus className="w-3.5 h-3.5" aria-hidden="true" /><span className="hidden 2xl:inline">Quick Product</span>
        </button>
        <button
          type="button"
          disabled={copyingClipboard || !line.estimate_id}
          onClick={async () => {
            if (!line.estimate_id) return;
            setCopyingClipboard(true);
            try {
              await copyProductToClipboard({ estimateId: line.estimate_id, line });
              setCopiedClipboard(true);
              setTimeout(() => setCopiedClipboard(false), 1500);
            } catch (error) {
              window.alert(error?.message || "Product could not be copied to the estimator clipboard.");
            } finally {
              setCopyingClipboard(false);
            }
          }}
          title="Copy Product to 30-day Clipboard"
          aria-label="Copy Product to 30-day Clipboard"
          className="h-[28px] px-2.5 border border-gray-200 rounded flex items-center justify-center gap-1 text-[11px] font-semibold text-gray-600 hover:bg-gray-100 disabled:opacity-50"
        >
          <ClipboardCopy className="w-3.5 h-3.5" aria-hidden="true" /><span className="hidden xl:inline">{copiedClipboard ? "Copied" : "Copy"}</span>
        </button>
        <button
          type="button"
          onClick={handleClone}
          disabled={cloning || readOnly}
          title="Clone Product"
          aria-label="Clone Product"
          className="h-[28px] px-2.5 border border-gray-200 rounded flex items-center justify-center gap-1 text-[11px] font-semibold text-gray-600 hover:bg-gray-100 disabled:opacity-50"
        >
          <Copy className={`w-3.5 h-3.5 ${cloning ? "animate-pulse" : ""}`} aria-hidden="true" /><span className="hidden xl:inline">{cloning ? "Cloning…" : "Clone"}</span>
        </button>
        <button
          type="button"
          onClick={() => setOpen(!open)}
          aria-expanded={open}
          title="Product Settings & Pricing Options"
          aria-label="Product settings and pricing options"
          className={`h-[28px] px-2.5 border rounded flex items-center justify-center gap-1 text-[11px] font-semibold ${
            open ? "border-red-300 text-red-600 bg-red-50" : "border-gray-200 text-gray-600 hover:bg-gray-100"
          }`}
        >
          <Percent className="w-3 h-3" aria-hidden="true" /> Pricing
        </button>
        <button
          type="button"
          onClick={() => {
            const name = line.client_product_name || line.project_name || "Product";
            if (!window.confirm(`Remove "${name}" from this estimate?`)) return;
            onRemove(index);
          }}
          disabled={readOnly || priceAcceptancePending}
          title={priceAcceptancePending ? "Resume the pending Product operation before removing this Product." : "Remove product"}
          aria-label={priceAcceptancePending ? "Resume the pending Product operation before removing this Product." : `Remove ${line.client_product_name || line.project_name || "product"} from this estimate`}
          className="w-[28px] h-[28px] border border-gray-200 rounded flex items-center justify-center text-red-500 hover:bg-red-50 disabled:opacity-50"
        >
          <Trash2 className="w-3 h-3" aria-hidden="true" />
        </button>
      </div>

      {open && (
        <div className="px-4 pb-3 pt-2 bg-gray-50 border-t border-gray-200">
          <div className="mb-2 flex items-center justify-between gap-2">
            <div className="text-[9px] font-extrabold tracking-widest text-gray-500">PRODUCT SETTINGS & PRICING OPTIONS</div>
            <div className="text-[9px] text-gray-400">Changes save when you leave each field. Pricing adjustments affect the customer quote, not the frozen Builder cost.</div>
          </div>
          <fieldset disabled={readOnly} className="grid grid-cols-2 sm:grid-cols-4 gap-3 disabled:opacity-60">
          <Field
            label="CLIENT PRODUCT NAME"
            value={line.client_product_name || line.project_name || ""}
            onChange={(e) => set({ client_product_name: e.target.value })}
            onBlur={(e) => commit({ client_product_name: e.target.value })}
            className="col-span-2"
          />
          <Field
            label={isCustom ? "PRODUCT TYPE" : "BUILDER TYPE"}
            value={isCustom ? "Custom Product" : line.builder_name || getModuleLabel(line.module_key)}
            disabled
          />
          <Field
            label="PRODUCT CATEGORY"
            value={line.product_category || ""}
            onChange={(e) => set({ product_category: e.target.value })}
            onBlur={(e) => commit({ product_category: e.target.value })}
            placeholder="e.g. Interior Signage"
          />
          <label className="text-[10px] font-semibold tracking-wide text-gray-400 block">
            PRODUCTION PRODUCT TYPE
            <select
              value={line.production_product_type || ""}
              onChange={(e) => {
                const patch = { production_product_type: e.target.value };
                set(patch);
                commit(patch);
              }}
              className="mt-0.5 w-full h-[28px] px-2 border border-gray-200 rounded text-[12px] text-gray-800 bg-white"
              title="Used by Work Orders and SIP/production checklists. Leave blank when the Product does not match a configured production type."
            >
              <option value="">Unclassified</option>
              {line.production_product_type && !productionProductTypes.includes(line.production_product_type) && (
                <option value={line.production_product_type}>{line.production_product_type} (not in current SIP list)</option>
              )}
              {productionProductTypes.map((type) => <option key={type} value={type}>{type}</option>)}
            </select>
          </label>
          <Field
            label="FROZEN COST"
            type="number"
            value={frozen}
            disabled
          />
          <Field
            label="LIVE INTERNAL COST"
            type="number"
            value={live}
            disabled
          />
          <Field
            label="CUSTOMER BASE PRICE"
            type="number"
            min="0"
            step="0.01"
            value={customerPrice}
            onChange={(e) => set({ customer_price_snapshot: e.target.value })}
            onBlur={(e) => commit({ customer_price_snapshot: Math.max(0, parseFloat(e.target.value) || 0) })}
            title="Accepted unit selling price. Manual changes are revisioned and do not change internal cost."
          />
          <Field
            label="LIVE CUSTOMER PRICE"
            type="number"
            value={liveCustomerPrice}
            disabled
          />
          <div>
            <Field
              label="ADJUSTMENT %"
              type="number"
              value={line.adjustment_percent ?? 0}
              onChange={(e) => set({ adjustment_percent: parseFloat(e.target.value) || 0 })}
              onBlur={(e) => commit({ adjustment_percent: parseFloat(e.target.value) || 0 })}
            />
            {Number(line.adjustment_percent || 0) !== 0 && (
              <div className="mt-0.5 text-[9px] text-emerald-700 font-semibold">
                → {money(Number(customerPrice || 0) * (1 + Number(line.adjustment_percent || 0) / 100))} preview
              </div>
            )}
          </div>
          <Field
            label="QUANTITY"
            type="number"
            value={line.customer_quantity ?? 1}
            onChange={(e) => set({ customer_quantity: parseFloat(e.target.value) || 1 })}
            onBlur={(e) => commit({ customer_quantity: parseFloat(e.target.value) || 1 })}
          />
          <label className="text-[10px] font-semibold tracking-wide text-gray-400 block">
            QUOTE DISPLAY
            <select
              value={line.include_in_customer === false ? "bundled" : "listed"}
              onChange={(e) => {
                const patch = { include_in_customer: e.target.value !== "bundled" };
                set(patch);
                commit(patch);
              }}
              className="mt-0.5 w-full h-[28px] px-2 border border-gray-200 rounded text-[12px] text-gray-800 bg-white"
            >
              <option value="listed">List Product on quote</option>
              <option value="bundled">Bundle into additional scope</option>
            </select>
          </label>
          <label className="text-[10px] font-semibold tracking-wide text-gray-400 block">
            STATUS
            <select
              value={line.section_status || "in_progress"}
              onChange={(e) => {
                const patch = { section_status: e.target.value };
                set(patch);
                commit(patch);
              }}
              className="mt-0.5 w-full h-[28px] px-2 border border-gray-200 rounded text-[12px] text-gray-800 bg-white"
            >
              <option value="in_progress">In progress</option>
              <option value="complete">Complete</option>
            </select>
          </label>
          <div className="col-span-2 sm:col-span-4">
            <Field
              label="CUSTOMER DESCRIPTION"
              value={line.customer_description || ""}
              onChange={(e) => set({ customer_description: e.target.value })}
              onBlur={(e) => commit({ customer_description: e.target.value })}
              placeholder="Shown to the customer on the quote"
            />
          </div>
          </fieldset>
        </div>
      )}

      <MasterPartPickerModal
        open={partPickerOpen}
        onClose={() => setPartPickerOpen(false)}
        onAdd={async (item, quantity) => {
          try {
            await addCatalogPartToProduct({ builderProductId: line.builder_product_id, catalogItem: item, quantity, expectedEstimateUpdatedAt: line.estimate_updated_date || "" });
            setPartPickerOpen(false);
            await onProductRefresh?.();
          } catch (error) {
            window.alert(error?.message || "Part could not be added to this Product.");
          }
        }}
      />

      <CreateQuickProductModal
        open={quickProductOpen}
        line={line}
        partCount={partCount}
        onClose={() => setQuickProductOpen(false)}
        onSave={async (options) => {
          await onCreateQuickProduct?.(line, options, index);
        }}
      />

      <ProductNotesModal
        open={notesOpen}
        line={line}
        onClose={() => setNotesOpen(false)}
        onSave={async (notes) => {
          await onSaveNotes?.(line, notes, index);
        }}
      />

      <ProductPriceHistoryModal
        open={priceHistoryOpen}
        line={line}
        onClose={() => setPriceHistoryOpen(false)}
      />

      {partsOpen && (
        <BuilderPartsPanel
          builderProductId={line.builder_product_id}
          refreshKey={`${line.last_price_check_at || ""}:${line.last_price_update_at || ""}:${line.price_state || ""}`}
          onLoaded={setPartCount}
          onEditBuilder={() => onEdit?.(line, index)}
          onProductRefresh={onProductRefresh}
          allowAddParts={true}
          estimateId={line.estimate_id}
          expectedEstimateUpdatedAt={line.estimate_updated_date || ""}
          availableProducts={allLines}
          readOnly={readOnly}
        />
      )}
    </div>
  );
}

import React, { useEffect, useState } from "react";
import { Search, Plus, Sparkles } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { staffEntities } from "@/components/staff/staffEntities";
import CustomerSearchDialog from "./CustomerSearchDialog";
import NewCustomerDialog from "./NewCustomerDialog";

const Row = ({ label, hint, children }) => {
  const labelId = React.useId();
  let labelled = false;
  const controls = React.Children.map(children, (child) => {
    if (
      !labelled &&
      React.isValidElement(child) &&
      ["input", "select", "textarea"].includes(child.type) &&
      !child.props["aria-label"] &&
      !child.props["aria-labelledby"]
    ) {
      labelled = true;
      return React.cloneElement(child, { "aria-labelledby": labelId });
    }
    return child;
  });
  return (
    <div className="flex items-center gap-2 mb-2">
      <span id={labelId} className="w-36 text-right text-xs text-slate-700 flex-shrink-0">
        {label}: {hint && <span className="text-blue-500" aria-hidden="true">ⓘ</span>}
      </span>
      <div className="flex-1 flex items-center gap-1">{controls}</div>
    </div>
  );
};

const inputCls =
  "w-full h-8 px-2 border border-slate-300 bg-white rounded-sm text-sm focus:outline-none focus:border-lime-500";

const pickerCls =
  "w-[104px] h-8 px-1 border border-slate-300 bg-white rounded-sm text-[12px] flex-shrink-0 focus:outline-none focus:border-lime-500";

const joinAddress = (line1, line2, city, state, postal) =>
  [line1, line2, city, [state, postal].map((p) => String(p || "").trim()).filter(Boolean).join(" ")]
    .map((p) => String(p || "").trim())
    .filter(Boolean)
    .join(", ");

export default function Step1EstimateDetails({
  form,
  patch,
  customers,
  recentCustomers = [],
  onCustomerSelected,
  saveSiteAsLocation = false,
  onSaveSiteAsLocationChange,
  taxGroups,
  users,
  termsOptions,
  salesCenters,
  onGenerateNumber,
  generating,
  enteredBy,
  onCustomerCreated,
}) {
  const [searchOpen, setSearchOpen] = useState(false);
  const [newOpen, setNewOpen] = useState(false);
  const [entityLocations, setEntityLocations] = useState([]);
  const [entityContacts, setEntityContacts] = useState([]);
  const [entityFlags, setEntityFlags] = useState([]);

  const linkedCustomer = customers.find((c) => c.id === form.customer_id) || null;

  useEffect(() => {
    if (!form.customer_id) {
      setEntityLocations([]);
      setEntityContacts([]);
      return;
    }
    let active = true;
    const load = (entity) =>
      entity && typeof entity.filter === "function"
        ? entity.filter({ customer_id: form.customer_id }).catch(() => [])
        : Promise.resolve([]);
    Promise.all([load(base44.entities?.CustomerLocation), load(base44.entities?.CustomerContact), load(staffEntities?.CustomerNote)]).then(
      ([locations, contacts, notes]) => {
        if (!active) return;
        setEntityLocations(locations || []);
        setEntityContacts(contacts || []);
        setEntityFlags((notes || []).filter((n) => n?.kind === "flag" && n?.deleted !== true));
      }
    );
    return () => {
      active = false;
    };
  }, [form.customer_id]);

  const applyCustomer = (c) => {
    // #486 tax-source chain: the customer's own default wins; otherwise the
    // company default stamped from Quote Defaults (default_tax_group), then
    // the TaxGroup flagged is_default as a last resort.
    const taxGroupName = (g) => String(g?.group_name || g?.name || "").trim();
    const wantedTaxGroup =
      String(c?.default_tax_group || "").trim() ||
      String(form?.default_tax_group || "").trim() ||
      taxGroupName((taxGroups || []).find((g) => g?.is_default === true));
    const defaultTaxGroup = (taxGroups || []).find((group) => taxGroupName(group) === wantedTaxGroup);
    const defaultTaxPercent = Number(defaultTaxGroup?.tax_percent);
    const taxDefaults = defaultTaxGroup && Number.isFinite(defaultTaxPercent) && defaultTaxPercent >= 0 && defaultTaxPercent <= 100
      ? { tax_group: taxGroupName(defaultTaxGroup), tax_percent: defaultTaxPercent }
      : {};
    const customerValidDays = Number(c.quote_valid_days);
    const validDaysDefault = Number.isFinite(customerValidDays) && customerValidDays > 0
      ? { quote_valid_days: Math.floor(customerValidDays) }
      : {};
    patch({
      client_name: c.company_name || "",
      customer_id: c.id,
      contact_email: c.contact_email || form.contact_email,
      office_phone: c.contact_office_phone || c.company_phone || form.office_phone,
      office_phone_ext: c.contact_office_ext || form.office_phone_ext,
      terms: c.terms || form.terms,
      pricing_tier: Number(c.pricing_tier) || form.pricing_tier || 1,
      volume_discount_tiers: Array.isArray(c.volume_discount_tiers) ? c.volume_discount_tiers : (form.volume_discount_tiers || []),
      salesperson: c.salesperson || form.salesperson,
      ...taxDefaults,
      ...validDaysDefault,
      order_contact:
        `${c.contact_first_name || ""} ${c.contact_last_name || ""}`.trim() || form.order_contact,
    });
    onCustomerSelected?.(c);
  };

  const locationOptions = (() => {
    const options = [];
    const seen = new Set();
    const push = (label, value) => {
      const v = String(value || "").trim();
      if (!v || seen.has(v.toLowerCase())) return;
      seen.add(v.toLowerCase());
      options.push({ key: options.length, label: label ? `${label}: ${v}` : v, value: v });
    };
    if (linkedCustomer) {
      push(
        "Site",
        joinAddress(
          linkedCustomer.location_address_1,
          linkedCustomer.location_address_2,
          linkedCustomer.location_city,
          linkedCustomer.location_state,
          linkedCustomer.location_postal_code
        )
      );
      push(
        "Billing",
        joinAddress(
          linkedCustomer.billing_address_1,
          linkedCustomer.billing_address_2,
          linkedCustomer.billing_city,
          linkedCustomer.billing_state,
          [linkedCustomer.billing_postal_code, linkedCustomer.billing_postal_ext]
            .filter(Boolean)
            .join("-")
        )
      );
    }
    (entityLocations || []).forEach((l) => {
      if (l?.is_active === false) return;
      push(l?.label, joinAddress(l?.address_line_1, l?.address_line_2, l?.city, l?.state, l?.postal_code));
    });
    return options;
  })();

  const contactOptions = (() => {
    const options = [];
    const seen = new Set();
    const push = (c) => {
      const name = String(c?.name || "").trim();
      if (!name) return;
      const dedupeKey = `${name.toLowerCase()}|${String(c?.email || "").trim().toLowerCase()}`;
      if (seen.has(dedupeKey)) return;
      seen.add(dedupeKey);
      options.push({
        ...c,
        key: options.length,
        name,
        label: c?.position ? `${name} (${c.position})` : name,
      });
    };
    if (linkedCustomer) {
      push({
        name: `${linkedCustomer.contact_first_name || ""} ${linkedCustomer.contact_last_name || ""}`.trim(),
        email: linkedCustomer.contact_email,
        phone: linkedCustomer.contact_office_phone || linkedCustomer.contact_cell_phone,
        ext: linkedCustomer.contact_office_ext,
        position: linkedCustomer.contact_position,
      });
      (linkedCustomer.additional_contacts || []).forEach((ac) => {
        if (ac?.is_active === false) return;
        push({
          name: `${ac?.first_name || ""} ${ac?.last_name || ""}`.trim(),
          email: ac?.email,
          phone: ac?.office_phone || ac?.cell_phone,
          ext: ac?.office_ext,
          position: ac?.position,
        });
      });
    }
    (entityContacts || []).forEach((sc) => {
      if (sc?.is_active === false) return;
      push({
        name: sc.display_name || `${sc.first_name || ""} ${sc.last_name || ""}`.trim(),
        email: sc.email,
        phone: sc.phone || sc.mobile_phone,
        ext: sc.phone_ext,
        position: sc.position,
      });
    });
    return options;
  })();

  const applySavedLocation = (key) => {
    const option = locationOptions.find((o) => String(o.key) === key);
    if (option) patch({ site_address: option.value });
  };

  const applySavedContact = (key) => {
    const c = contactOptions.find((o) => String(o.key) === key);
    if (!c) return;
    patch({
      contact_name: c.name,
      order_contact: c.name,
      contact_email: c.email || form.contact_email,
      contact_phone: c.phone || form.contact_phone,
      office_phone: c.phone || form.office_phone,
      office_phone_ext: c.ext || form.office_phone_ext,
    });
  };

  return (
    <div className="flex-1 min-w-0">
      <div className="bg-white border border-gray-200 rounded-md px-4 py-2 flex items-center justify-between mb-1">
        <h2 className="text-[13px] font-bold text-gray-800">Step 1: Estimate Details</h2>
        <button type="button" className="h-[26px] px-3 rounded bg-lime-200 border border-lime-300 text-[12px] font-semibold text-gray-800">
          Next Step →
        </button>
      </div>
      <div className="text-right text-[11px] italic text-slate-500 mb-2">
        Entered by: {enteredBy || "—"}
      </div>

      <div className="bg-slate-100 border border-slate-300 rounded-sm p-4 mb-3 max-w-4xl">
        <Row label="Customer">
          <input
            list="aio-customers"
            value={form.client_name}
            onChange={(e) => patch({ client_name: e.target.value })}
            placeholder="Customer / company name"
            className={inputCls}
          />
          <datalist id="aio-customers">
            {customers.map((c) => (
              <option key={c.id} value={c.company_name} />
            ))}
          </datalist>
          <button
            type="button"
            onClick={() => setSearchOpen(true)}
            aria-label="Search customers"
            title="Search customers"
            className="flex-shrink-0 text-lime-600 hover:text-lime-700"
          >
            <Search className="w-4 h-4" aria-hidden="true" />
          </button>
          <button
            type="button"
            onClick={() => setNewOpen(true)}
            aria-label="New customer"
            title="New customer"
            className="flex-shrink-0 text-lime-600 hover:text-lime-700"
          >
            <Plus className="w-4 h-4" aria-hidden="true" />
          </button>
          {linkedCustomer?.credit_hold === true && (
            <span className="inline-flex items-center gap-1 rounded-full bg-red-100 px-2 py-0.5 text-[10px] font-bold text-red-700 border border-red-200">
              CREDIT HOLD — new work needs a deposit or manager override
            </span>
          )}
          {entityFlags.map((flag) => {
            const styles = {
              red: "bg-red-100 text-red-700 border-red-200",
              amber: "bg-amber-100 text-amber-800 border-amber-200",
              blue: "bg-blue-100 text-blue-700 border-blue-200",
              green: "bg-emerald-100 text-emerald-700 border-emerald-200",
            };
            return (
              <span key={flag.id || flag.text} className={`inline-flex items-center rounded-full px-2 py-0.5 text-[10px] font-bold border ${styles[flag.flag_color] || styles.amber}`}>
                {flag.text}
              </span>
            );
          })}
        </Row>
        {recentCustomers.length > 0 && (
          <div className="mb-2 flex flex-wrap items-center gap-1.5 text-[10px]" aria-label="Recent customers">
            <span className="mr-1 text-slate-500">Recent:</span>
            {recentCustomers.map((customer) => (
              <button
                key={customer.id}
                type="button"
                onClick={() => applyCustomer(customer)}
                aria-label={`Use recent customer ${customer.company_name}`}
                className="min-h-7 max-w-full truncate rounded-full border border-slate-300 bg-white px-2.5 font-medium text-slate-700 hover:border-lime-500 hover:bg-lime-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-lime-500"
              >
                {customer.company_name || customer.contact_email || "Customer"}
              </button>
            ))}
          </div>
        )}

        <Row label="Estimate Description" hint>
          <input
            value={form.project_name}
            onChange={(e) => patch({ project_name: e.target.value })}
            placeholder="What this estimate is for"
            className={inputCls}
          />
        </Row>

        <Row label="PO Number">
          <input
            value={form.po_number}
            onChange={(e) => patch({ po_number: e.target.value })}
            className={inputCls}
          />
        </Row>

        <Row label="Terms">
          <select
            value={form.terms}
            onChange={(e) => patch({ terms: e.target.value })}
            className={inputCls}
          >
            <option value="">select</option>
            {termsOptions.map((t) => (
              <option key={t} value={t}>
                {t}
              </option>
            ))}
          </select>
        </Row>

        <Row label="Estimate #">
          <input
            value={form.estimate_number}
            onChange={(e) => patch({ estimate_number: e.target.value })}
            className={inputCls}
          />
          <button type="button"
            onClick={onGenerateNumber}
            disabled={generating}
            className="h-[26px] px-2 border border-gray-300 rounded-sm text-[12px] flex items-center gap-1 whitespace-nowrap hover:bg-gray-50 disabled:opacity-60"
          >
            <Sparkles className="w-3 h-3" aria-hidden="true" /> Generate
          </button>
        </Row>
      </div>

      <div className="bg-slate-100 border border-slate-300 rounded-sm p-4 max-w-4xl grid grid-cols-1 md:grid-cols-2 gap-6 divide-y md:divide-y-0 md:divide-x divide-slate-300">
        <div className="md:pr-4">
          <Row label="Order Contact">
            <select
              value={form.order_contact}
              onChange={(e) => patch({ order_contact: e.target.value })}
              className={inputCls}
            >
              <option value="">select</option>
              {users.map((u) => (
                <option key={u.id} value={u.full_name || u.email}>
                  {u.full_name || u.email}
                </option>
              ))}
            </select>
            {contactOptions.length > 0 && (
              <select
                value=""
                onChange={(e) => applySavedContact(e.target.value)}
                title="Fill contact fields from a saved customer contact"
                className={pickerCls}
              >
                <option value="">Saved…</option>
                {contactOptions.map((c) => (
                  <option key={c.key} value={c.key}>
                    {c.label}
                  </option>
                ))}
              </select>
            )}
          </Row>
          <Row label="Contact Email">
            <input
              value={form.contact_email}
              onChange={(e) => patch({ contact_email: e.target.value })}
              className={inputCls}
            />
          </Row>
          <Row label="Office Phone">
            <input
              value={form.office_phone}
              onChange={(e) => patch({ office_phone: e.target.value })}
              className={inputCls}
            />
            <span className="text-[11px] text-gray-500">Ext.</span>
            <input
              aria-label="Phone extension"
              value={form.office_phone_ext}
              onChange={(e) => patch({ office_phone_ext: e.target.value })}
              className="w-[52px] h-[26px] px-2 border border-gray-300 rounded-sm text-[12px]"
            />
          </Row>
          <Row label="Site Address">
            <input
              value={form.site_address || ""}
              onChange={(e) => patch({ site_address: e.target.value })}
              placeholder="Install / job site address"
              className={inputCls}
            />
            {locationOptions.length > 0 && (
              <select
                value=""
                onChange={(e) => applySavedLocation(e.target.value)}
                aria-label="Fill site address from a saved customer location"
                title="Fill site address from a saved customer location"
                className={pickerCls}
              >
                <option value="">Saved…</option>
                {locationOptions.map((l) => (
                  <option key={l.key} value={l.key}>
                    {l.label}
                  </option>
                ))}
              </select>
            )}
          </Row>
          {form.customer_id && String(form.site_address || "").trim() && (
            <label className="mb-2 flex items-start gap-2 pl-0 text-[11px] text-slate-600 sm:pl-36">
              <input
                type="checkbox"
                checked={saveSiteAsLocation === true}
                onChange={(event) => onSaveSiteAsLocationChange?.(event.target.checked)}
                className="mt-0.5 accent-lime-600"
              />
              <span>Save this address to the customer's locations</span>
            </label>
          )}
        </div>

        <div className="md:pl-4 pt-4 md:pt-0">
          <Row label="Salesperson">
            <select
              value={form.salesperson}
              onChange={(e) => patch({ salesperson: e.target.value })}
              className={inputCls}
            >
              <option value="">select</option>
              {users.map((u) => (
                <option key={u.id} value={u.full_name || u.email}>
                  {u.full_name || u.email}
                </option>
              ))}
            </select>
          </Row>
          <Row label="Sales Center">
            <select
              value={form.sales_center}
              onChange={(e) => patch({ sales_center: e.target.value })}
              className={inputCls}
            >
              {salesCenters.map((s) => (
                <option key={s} value={s}>
                  {s}
                </option>
              ))}
            </select>
          </Row>
          <Row label="Tax Group">
            <select
              value={form.tax_group}
              onChange={(e) => {
                const g = taxGroups.find((t) => (t.group_name || t.name) === e.target.value);
                patch({ tax_group: e.target.value, tax_percent: g?.tax_percent || 0 });
              }}
              className={inputCls}
            >
              <option value="">select</option>
              {taxGroups.map((t, i) => {
                const gname = t.group_name || t.name || "";
                return (
                  <option key={t.id || `tax-group-${gname}-${i}`} value={gname}>
                    {gname} ({t.tax_percent}%)
                  </option>
                );
              })}
            </select>
          </Row>
          <p className="text-[10px] text-gray-400 text-center mt-1">
            Tax applied to this estimate: {Number(form.tax_percent || 0)}%
          </p>
          <label className="mt-1 flex items-start gap-2 text-[11px] text-slate-600">
            <input
              type="checkbox"
              checked={form.round_quote_total === true}
              onChange={(event) => patch({ round_quote_total: event.target.checked })}
              className="mt-0.5 accent-lime-600"
            />
            <span>Round the quote total to the nearest whole dollar</span>
          </label>
        </div>
      </div>

      <CustomerSearchDialog
        open={searchOpen}
        onClose={() => setSearchOpen(false)}
        customers={customers}
        onSelect={applyCustomer}
      />
      <NewCustomerDialog
        open={newOpen}
        onClose={() => setNewOpen(false)}
        onCreated={(c) => {
          onCustomerCreated?.(c);
          applyCustomer(c);
        }}
      />
    </div>
  );
}

import { Link } from "react-router-dom";
import { Clock, TrendingUp } from "lucide-react";
import { format } from "date-fns";
import { isQuoteExpired, localDateStamp, quoteExpirationDate } from "../quoteLifecycle";

export default function RecentActivity({ estimates }) {
  return (
    <div className="bg-white">
      <div className="flex items-center gap-2 px-4 py-3 border-b border-gray-100">
        <TrendingUp className="w-4 h-4 text-red-500" aria-hidden="true" />
        <h2 className="text-xs font-bold tracking-wide text-gray-600">RECENT ESTIMATE ACTIVITY</h2>
      </div>
      {estimates.length === 0 ? (
        <div className="px-4 py-8 text-center text-sm text-gray-400">No estimate activity yet.</div>
      ) : (
        <div className="divide-y divide-gray-100">
          {estimates.map((e) => (
            <Link
              key={e.id}
              to={`/EstimateDetail?id=${e.id}`}
              className="flex items-center gap-3 px-4 py-2.5 hover:bg-red-50/50"
            >
              <Clock className="w-4 h-4 text-amber-500 flex-shrink-0" aria-hidden="true" />
              <div className="min-w-0 flex-1">
                <div className="text-sm font-semibold text-gray-800 truncate">{e.project_name}</div>
                <div className="text-xs text-gray-500 truncate">
                  {e.client_name} · {e.status || "draft"}
                </div>
              </div>
              {e.status === "sent" && e.quote_issue_date ? (() => {
                const expires = quoteExpirationDate(e.quote_issue_date, e.quote_valid_days);
                const today = localDateStamp(new Date());
                if (!expires) return null;
                if (isQuoteExpired(e.quote_issue_date, e.quote_valid_days)) return <span className="text-[9px] font-bold px-1.5 py-0.5 rounded bg-red-50 text-red-600 flex-shrink-0">EXPIRED</span>;
                const daysLeft = Math.round((new Date(`${expires}T00:00:00`) - new Date(`${today}T00:00:00`)) / 86400000);
                if (daysLeft <= 7) return <span className="text-[9px] font-bold px-1.5 py-0.5 rounded bg-amber-50 text-amber-700 flex-shrink-0">EXPIRES {format(new Date(`${expires}T00:00:00`), "MMM d").toUpperCase()}</span>;
                return null;
              })() : null}
              <div className="text-xs text-gray-400 flex-shrink-0">
                {e.created_date ? format(new Date(e.created_date), "MMM d") : ""}
              </div>
            </Link>
          ))}
        </div>
      )}
    </div>
  );
}

