export default function MasterPartPickerModal({ open, onClose, onAdd, mode = "add", initialQuantity = 1, catalogFilter = null, suggestQuery = "" }) {
  const [loading, setLoading] = useState(false);
  const [items, setItems] = useState([]);
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("all");
  const [selectedId, setSelectedId] = useState("");
  const [quantity, setQuantity] = useState(1);
  const [adding, setAdding] = useState(false);
  const [loadError, setLoadError] = useState("");
  const [quickOpen, setQuickOpen] = useState(false);
  const [quickBusy, setQuickBusy] = useState(false);
  const [quickError, setQuickError] = useState("");
  const [quickForm, setQuickForm] = useState({ material_type: "", product_type: "", size: "", unit_type: "per_piece", cost_per_unit: "", supplier: "" });
  const addRef = useRef(false);

  useEffect(() => {
    if (!open) return;
    let active = true;
    setQuantity(initialQuantity);
    if (mode === "switch" && suggestQuery) setQuery(String(suggestQuery).trim());
    setLoading(true);
    setLoadError("");
    setItems([]);
    setSelectedId("");
    loadMasterPartCatalog()
      .then((rows) => {
        if (!active) return;
        const scopedRows = typeof catalogFilter === "function" ? rows.filter(catalogFilter) : rows;
        setItems(scopedRows);
        setSelectedId(scopedRows[0]?.id || "");
      })
      .catch((error) => active && setLoadError(error?.message || "Master Inventory could not be verified."))
      .finally(() => active && setLoading(false));
    return () => { active = false; };
  }, [open, initialQuantity, catalogFilter]);

  useEffect(() => {
    if (!open) {
      setQuery("");
      setCategory("all");
      setQuantity(1);
      setSelectedId("");
      setAdding(false);
      setLoadError("");
      setQuickOpen(false);
      setQuickBusy(false);
      setQuickError("");
      setQuickForm({ material_type: "", product_type: "", size: "", unit_type: "per_piece", cost_per_unit: "", supplier: "" });
      addRef.current = false;
    }
  }, [open]);

  const categories = useMemo(() => {
    const map = new Map();
    items.forEach((item) => (item.categories || [{ key: item.categoryKey, label: item.categoryLabel }]).forEach((entry) => map.set(entry.key, entry.label)));
    return [...map.entries()].map(([key, label]) => ({ key, label }));
  }, [items]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return items.filter((item) => {
      if (category !== "all" && !(item.categories || [{ key: item.categoryKey }]).some((entry) => entry.key === category)) return false;
      if (!q) return true;
      return q.split(/\s+/).every((term) => item.searchText.includes(term));
    });
  }, [items, query, category]);

  const selected = items.find((item) => item.id === selectedId) || filtered[0] || null;
  const details = selected ? typeDetails(selected.entity, selected.row) : [];
  const requestedQty = Math.max(0, Number(mode === "switch" ? initialQuantity : quantity || 0));
  const onHand = Number(selected?.row?.quantity_on_hand);
  const stockShortfall = mode !== "select" && Number.isFinite(onHand) && onHand >= 0 && requestedQty > onHand;

  const quickAddSave = async () => {
    const data = {
      material_type: String(quickForm.material_type || "").trim(),
      product_type: String(quickForm.product_type || "").trim(),
      size: String(quickForm.size || "").trim(),
      unit_type: String(quickForm.unit_type || "per_piece").trim(),
      cost_per_unit: Math.max(0, Number(quickForm.cost_per_unit) || 0),
      supplier: String(quickForm.supplier || "").trim(),
      quantity_on_hand: 0,
    };
    if (quickBusy || !data.material_type || !data.product_type || !data.size) {
      setQuickError("Material type, product type, and size are required.");
      return;
    }
    setQuickBusy(true);
    setQuickError("");
    try {
      const { record } = await createInventoryRecordWithRecovery({
        entity: base44.entities.Inventory,
        data,
        nameField: "size",
        label: "Quick-added inventory item",
      });
      const rows = await loadMasterPartCatalog();
      const scopedRows = typeof catalogFilter === "function" ? rows.filter(catalogFilter) : rows;
      setItems(scopedRows);
      const match = scopedRows.find((item) => item.entity === "Inventory" && item.row?.id === record?.id);
      if (match) setSelectedId(match.id);
      setQuickOpen(false);
      setQuery("");
      setCategory("all");
    } catch (err) {
      setQuickError(err?.message || "The item could not be created.");
    } finally {
      setQuickBusy(false);
    }
  };

  const add = async () => {
    if (!selected || loadError || addRef.current) return;
    addRef.current = true;
    setAdding(true);
    try {
      await onAdd?.(selected, mode === "switch" ? Math.max(0, Number(initialQuantity || 0)) : mode === "select" ? 1 : Math.max(0, Number(quantity || 0)));
      onClose?.();
    } finally {
      addRef.current = false;
      setAdding(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(next) => !next && !adding && onClose?.()}>
      <DialogContent className="sm:max-w-[1050px] p-0 overflow-hidden gap-0 border-gray-300 shadow-2xl">
        <DialogHeader className="px-5 pt-5 pb-4 bg-[#3f3f3f] text-white border-b-4 border-lime-300">
          <div className="flex items-center gap-3 pr-8">
            <div className="w-10 h-10 rounded bg-lime-300 text-gray-900 flex items-center justify-center"><Boxes className="w-5 h-5" aria-hidden="true" /></div>
            <div>
              <DialogTitle className="text-white text-[17px]">{mode === "switch" ? "Switch Part from Master Inventory" : mode === "select" ? "Select Master Inventory Resource" : "Add Part from Master Inventory"}</DialogTitle>
              <p className="text-[11px] text-gray-300 mt-1">{mode === "switch" ? "Choose the replacement inventory record. The current Part quantity is preserved while the inventory link and frozen inventory/pricing snapshot are explicitly replaced." : mode === "select" ? "Choose the authoritative Master Inventory resource. This selection creates a reference only; it does not copy or change the inventory record." : "Choose the exact inventory record. The complete Master Inventory row and current pricing are frozen into the estimate Part."}</p>
            </div>
          </div>
        </DialogHeader>

        <div className="grid grid-cols-1 lg:grid-cols-[1.35fr_0.8fr] min-h-[590px] bg-white">
          <section className="border-r border-gray-200 min-w-0 flex flex-col">
            <div className="p-3 border-b border-gray-200 space-y-2 bg-gray-50">
              <div className="relative">
                <Search className="w-4 h-4 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" aria-hidden="true" />
                <input value={query} onChange={(e) => setQuery(e.target.value)} aria-label="Search inventory" placeholder="Search inventory by name, type, supplier, size, manufacturer..." className="w-full h-[36px] pl-9 pr-3 border border-gray-300 rounded text-[12px] bg-white" />
              </div>
              <div className="flex gap-1.5 overflow-x-auto pb-1">
                <button type="button" onClick={() => setCategory("all")} aria-pressed={category === "all"} className={`h-[27px] px-2.5 rounded border text-[10px] font-semibold whitespace-nowrap ${category === "all" ? "bg-gray-800 text-white border-gray-800" : "bg-white text-gray-600 border-gray-300"}`}>All Parts</button>
                {categories.map((cat) => (
                  <button key={cat.key} type="button" onClick={() => setCategory(cat.key)} aria-pressed={category === cat.key} className={`h-[27px] px-2.5 rounded border text-[10px] font-semibold whitespace-nowrap ${category === cat.key ? "bg-gray-800 text-white border-gray-800" : "bg-white text-gray-600 border-gray-300"}`}>{cat.label}</button>
                ))}
              </div>
            </div>
            <div className="px-3 py-2 border-b border-gray-100 text-[10px] text-gray-500 flex items-center justify-between">
              <span>{filtered.length} matching Master Inventory Part{filtered.length === 1 ? "" : "s"}</span>
              <button type="button" onClick={() => { setQuickOpen(!quickOpen); setQuickError(""); }} aria-expanded={quickOpen} className="text-[10px] font-bold text-gray-600 hover:text-gray-900 underline">
                {quickOpen ? "Cancel quick add" : "+ Quick add item"}
              </button>
            </div>
            {quickOpen && (
              <div className="px-3 py-2 border-b border-gray-200 bg-white space-y-1.5">
                <div className="grid grid-cols-3 gap-1.5">
                  <input value={quickForm.material_type} onChange={(e) => setQuickForm((f) => ({ ...f, material_type: e.target.value }))} aria-label="Material type" placeholder="Material type *" className="h-[28px] px-2 border border-gray-300 rounded text-[11px]" />
                  <input value={quickForm.product_type} onChange={(e) => setQuickForm((f) => ({ ...f, product_type: e.target.value }))} aria-label="Product type" placeholder="Product type *" className="h-[28px] px-2 border border-gray-300 rounded text-[11px]" />
                  <input value={quickForm.size} onChange={(e) => setQuickForm((f) => ({ ...f, size: e.target.value }))} aria-label="Size" placeholder="Size *" className="h-[28px] px-2 border border-gray-300 rounded text-[11px]" />
                  <select value={quickForm.unit_type} onChange={(e) => setQuickForm((f) => ({ ...f, unit_type: e.target.value }))} aria-label="Unit type" className="h-[28px] px-1.5 border border-gray-300 rounded text-[11px] bg-white">
                    {["per_piece", "per_foot", "per_pound", "per_sqft"].map((u) => <option key={u} value={u}>{u.replace(/_/g, " ")}</option>)}
                  </select>
                  <input type="number" min="0" step="any" value={quickForm.cost_per_unit} onChange={(e) => setQuickForm((f) => ({ ...f, cost_per_unit: e.target.value }))} aria-label="Cost per unit" placeholder="Cost per unit" className="h-[28px] px-2 border border-gray-300 rounded text-[11px]" />
                  <input value={quickForm.supplier} onChange={(e) => setQuickForm((f) => ({ ...f, supplier: e.target.value }))} aria-label="Supplier" placeholder="Supplier" className="h-[28px] px-2 border border-gray-300 rounded text-[11px]" />
                </div>
                {quickError && <div role="alert" className="text-[10px] font-semibold text-red-600">{quickError}</div>}
                <div className="flex items-center justify-between">
                  <span className="text-[9px] text-gray-400">Creates a Master Inventory row (stock starts at 0), then selects it here.</span>
                  <button type="button" disabled={quickBusy} onClick={quickAddSave} className="h-[26px] px-3 rounded bg-lime-200 border border-lime-400 text-[10px] font-bold text-gray-900 hover:bg-lime-300 disabled:opacity-50 inline-flex items-center gap-1">
                    {quickBusy ? <Loader2 className="w-3 h-3 animate-spin" aria-hidden="true" /> : null}Create & select
                  </button>
                </div>
              </div>
            )}
            <div className="flex-1 overflow-y-auto max-h-[480px] p-2 space-y-1">
              {loading ? (
                <div className="py-16 flex items-center justify-center gap-2 text-[12px] text-gray-500"><Loader2 className="w-4 h-4 animate-spin" aria-hidden="true" /> Loading Master Inventory…</div>
              ) : loadError ? (
                <div className="py-16 text-center"><div className="text-[12px] font-semibold text-red-700">Master Inventory could not be verified.</div><div className="text-[10px] text-red-500 mt-1">{loadError}</div><div className="text-[10px] text-gray-400 mt-1">Close and reopen the picker to retry. No Part can be selected from a partial catalog.</div></div>
              ) : filtered.length === 0 ? (
                <div className="py-16 text-center text-[12px] text-gray-400">No inventory Parts match this search.</div>
              ) : filtered.map((item) => (
                <button key={item.id} type="button" onClick={() => setSelectedId(item.id)} aria-pressed={selected?.id === item.id} className={`w-full text-left p-3 rounded border transition-colors ${selected?.id === item.id ? "border-lime-400 bg-lime-50" : "border-gray-200 bg-white hover:bg-gray-50 hover:border-gray-300"}`}>
                  <div className="flex items-start justify-between gap-3">
                    <div className="min-w-0">
                      <div className="text-[12px] font-bold text-gray-900 truncate">{item.name}</div>
                      <div className="text-[10px] text-gray-500 mt-0.5">{item.categoryLabel} · {String(item.subtype || "").replace(/_/g, " ")}{item.supplier ? ` · ${item.supplier}` : ""}</div>
                      {Number.isFinite(Number(item.row?.quantity_on_hand)) && Number(item.row?.reorder_point) > 0 && Number(item.row.quantity_on_hand) <= Number(item.row.reorder_point) && (
                        <span className="mt-1 inline-block px-1.5 py-0.5 rounded bg-amber-100 text-amber-800 text-[9px] font-bold" title={`On-hand ${Number(item.row.quantity_on_hand)} is at or below reorder point ${Number(item.row.reorder_point)}`}>LOW STOCK · {Number(item.row.quantity_on_hand)} on hand</span>
                      )}
                    </div>
                    <div className="text-right flex-shrink-0"><div className="text-[11px] font-bold text-gray-800">{money(item.unitCost)}</div><div className="text-[9px] text-gray-400">per {item.unit}</div></div>
                  </div>
                </button>
              ))}
            </div>
          </section>

          <aside className="p-4 bg-gray-50 flex flex-col">
            {loadError ? (
              <div className="flex-1 flex items-center justify-center text-center px-5"><div><div className="text-[12px] font-semibold text-red-700">Inventory unavailable</div><div className="text-[10px] text-gray-500 mt-1">Part creation and switching are disabled until the complete Master Inventory catalog can be read.</div></div></div>
            ) : selected ? (
              <>
                <div className="text-[9px] font-bold tracking-widest text-gray-400">SELECTED PART</div>
                <div className="text-[16px] font-bold text-gray-900 mt-1">{selected.name}</div>
                <div className="text-[10px] text-gray-500 mt-1">{selected.categoryLabel} · {String(selected.subtype || "").replace(/_/g, " ")}</div>

                <div className="mt-4 rounded border border-gray-200 bg-white p-3">
                  <div className="text-[9px] font-bold tracking-widest text-gray-400 mb-2">PRICING INFORMATION</div>
                  <div className="space-y-1.5 text-[11px]">
                    <div className="flex justify-between gap-3"><span className="text-gray-500">Pricing mode</span><strong>{String(selected.pricingMode).replace(/_/g, " ")}</strong></div>
                    <div className="flex justify-between gap-3"><span className="text-gray-500">Master cost</span><strong>{money(selected.unitCost)} / {selected.unit}</strong></div>
                    {selected.supplier && <div className="flex justify-between gap-3"><span className="text-gray-500">Supplier</span><strong className="text-right">{selected.supplier}</strong></div>}
                  </div>
                </div>

                {details.length > 0 && (
                  <div className="mt-3 rounded border border-gray-200 bg-white p-3 max-h-[245px] overflow-y-auto">
                    <div className="text-[9px] font-bold tracking-widest text-gray-400 mb-2">PART DETAILS</div>
                    <div className="space-y-1.5 text-[11px]">
                      {details.map((detail) => <div key={detail.field} className="flex justify-between gap-3"><span className="text-gray-500">{detail.label}</span><strong className="text-right">{Array.isArray(detail.value) ? detail.value.join(", ") : String(detail.value).replace(/_/g, " ")}</strong></div>)}
                    </div>
                  </div>
                )}

                <div className="mt-auto pt-4 space-y-3">
                  {mode === "switch" ? (
                    <div className="rounded border border-gray-200 bg-white px-3 py-2 flex justify-between"><span className="text-[10px] font-bold text-gray-500">PRESERVED QUANTITY</span><strong className="text-[12px]">{Number(initialQuantity || 0).toLocaleString()}</strong></div>
                  ) : mode !== "select" ? (
                    <label className="text-[10px] font-bold tracking-wide text-gray-500 block">QUANTITY<input type="number" min="0" step="any" value={quantity} onChange={(e) => setQuantity(e.target.value)} className="mt-1 w-full h-[34px] px-2 border border-gray-300 rounded bg-white text-[12px]" /></label>
                  ) : null}
                  {mode !== "select" && <div className="rounded border border-lime-300 bg-lime-50 px-3 py-2 flex justify-between"><span className="text-[10px] font-bold text-gray-600">FROZEN EXTENDED COST</span><strong className="text-[13px]">{money(Number(mode === "switch" ? initialQuantity : quantity || 0) * selected.unitCost)}</strong></div>}
                  {stockShortfall && (
                    <div className="rounded border border-amber-300 bg-amber-50 px-3 py-2 text-[10px] font-semibold text-amber-800">
                      Requested {requestedQty.toLocaleString()} {selected.unit || "units"} but only {onHand.toLocaleString()} on hand in Master Inventory. The Part can still be added — purchasing must cover the difference.
                    </div>
                  )}
                  <div className="flex justify-end gap-2">
                    <button type="button" disabled={adding} onClick={onClose} className="h-[32px] px-4 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-600">Cancel</button>
                    <button type="button" disabled={adding} onClick={add} className="h-[32px] px-4 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 disabled:opacity-50 inline-flex items-center gap-1.5">{adding ? <Loader2 className="w-3.5 h-3.5 animate-spin" aria-hidden="true" /> : <Plus className="w-3.5 h-3.5" aria-hidden="true" />}{adding ? (mode === "switch" ? "Switching…" : mode === "select" ? "Selecting…" : "Adding…") : (mode === "switch" ? "Switch Part" : mode === "select" ? "Select Resource" : "Add Part")}</button>
                  </div>
                </div>
              </>
            ) : <div className="flex-1 flex items-center justify-center text-[12px] text-gray-400">Select an inventory Part.</div>}
          </aside>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { AlertTriangle, BookmarkPlus, Layers3, PackagePlus, Search, ShieldCheck, UserRound } from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { money } from "@/components/estimator/aioPricing";
import { instantiatePartTemplate, listPartTemplates } from "./partTemplateService";

export default function PartLibraryPickerModal({ open, estimateId, builderProductId, expectedEstimateUpdatedAt = "", onClose, onAdded }) {
  const [templates, setTemplates] = useState([]);
  const [loading, setLoading] = useState(false);
  const [query, setQuery] = useState("");
  const [scope, setScope] = useState("all");
  const [type, setType] = useState("all");
  const [addingId, setAddingId] = useState("");
  const [error, setError] = useState("");
  const addRef = useRef(false);

  useEffect(() => {
    if (!open) return;
    let active = true;
    setQuery("");
    setScope("all");
    setType("all");
    setError("");
    setTemplates([]);
    setLoading(true);
    listPartTemplates()
      .then((rows) => active && setTemplates(rows || []))
      .catch((err) => active && setError(err?.message || "Part Library could not be loaded."))
      .finally(() => active && setLoading(false));
    return () => { active = false; };
  }, [open]);

  const visible = useMemo(() => {
    const q = query.trim().toLowerCase();
    return templates.filter((template) => {
      const group = template.product_group === "global" ? "global" : "my";
      if (scope !== "all" && group !== scope) return false;
      if (type !== "all" && template.template_type !== type) return false;
      if (!q) return true;
      const haystack = [template.template_name, template.category, template.description, template.notes, template.source_module_key, template.source_part_type, template.source_part_subtype, template.search_text, ...(template.tags || [])].filter(Boolean).join(" ").toLowerCase();
      return q.split(/\s+/).every((term) => haystack.includes(term));
    });
  }, [templates, query, scope, type]);

  const add = async (template) => {
    if (!template?.id || addRef.current) return;
    addRef.current = true;
    setAddingId(template.id);
    setError("");
    try {
      await instantiatePartTemplate({ estimateId, targetBuilderProductId: builderProductId, template, expectedEstimateUpdatedAt });
      await onAdded?.();
      onClose?.();
    } catch (err) {
      setError(err?.message || "Saved Part could not be added to this Product.");
    } finally {
      addRef.current = false;
      setAddingId("");
    }
  };

  return (
    <Dialog open={open} onOpenChange={(next) => !next && !addingId && onClose?.()}>
      <DialogContent className="sm:max-w-[980px] p-0 overflow-hidden gap-0 border-gray-300 shadow-2xl">
        <DialogHeader className="px-5 py-4 bg-[#3f3f3f] text-white border-b-4 border-lime-300">
          <DialogTitle className="text-white text-[17px] flex items-center gap-2"><BookmarkPlus className="w-5 h-5 text-lime-300" aria-hidden="true" /> Add from Part Library</DialogTitle>
          <p className="text-[10px] text-gray-300 mt-1">Reusable Parts and Part Groups are separate from Master Inventory. The selected snapshot is copied into this Product as an independent component.</p>
        </DialogHeader>

        <div className="bg-white min-h-[560px] flex flex-col">
          <div className="p-3 border-b border-gray-200 bg-gray-50 flex flex-col md:flex-row gap-2">
            <div className="relative flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" aria-hidden="true" /><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} aria-label="Search saved parts" placeholder="Search saved Parts by name, category, tag, material, process..." className="w-full h-[34px] pl-9 pr-3 border border-gray-300 rounded bg-white text-[12px]" /></div>
            <select value={scope} onChange={(event) => setScope(event.target.value)} aria-label="Library scope filter" className="h-[34px] px-3 border border-gray-300 rounded bg-white text-[11px]"><option value="all">My + Global</option><option value="my">My Parts</option><option value="global">Global Parts</option></select>
            <select value={type} onChange={(event) => setType(event.target.value)} aria-label="Part type filter" className="h-[34px] px-3 border border-gray-300 rounded bg-white text-[11px]"><option value="all">Parts + Groups</option><option value="part">Single Parts</option><option value="part_group">Part Groups</option></select>
          </div>
          {error && <div role="alert" className="mx-3 mt-3 rounded border border-red-200 bg-red-50 px-3 py-2 text-[11px] text-red-700">{error}</div>}
          <div className="px-3 py-2 border-b border-gray-100 text-[10px] text-gray-500">{visible.length} matching saved component{visible.length === 1 ? "" : "s"}</div>

          <div className="flex-1 overflow-y-auto max-h-[470px] p-3">
            {loading ? <div role="status" className="py-20 text-center text-[11px] text-gray-400">Loading Part Library…</div> : error ? (
              <div className="py-20 text-center"><AlertTriangle className="w-9 h-9 text-red-300 mx-auto" aria-hidden="true" /><div className="mt-2 text-[12px] font-semibold text-red-700">Part Library could not be verified.</div><div className="mt-1 text-[10px] text-red-500">Close and reopen this picker to retry.</div></div>
            ) : visible.length === 0 ? (
              <div className="py-20 text-center"><BookmarkPlus className="w-9 h-9 text-gray-300 mx-auto" aria-hidden="true" /><div className="mt-2 text-[12px] font-semibold text-gray-600">No saved Parts found.</div><div className="mt-1 text-[10px] text-gray-400">Expand a Product Part or Part Group and use Save to Library.</div></div>
            ) : <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              {visible.map((template) => {
                const isGroup = template.template_type === "part_group";
                const global = template.product_group === "global";
                const changed = Math.abs(Number(template.current_cost || 0) - Number(template.frozen_cost || 0)) > 0.005;
                return <div key={template.id} className="rounded border border-gray-200 bg-white p-3 shadow-sm hover:border-gray-300">
                  <div className="flex items-start gap-3">
                    <div className={`w-9 h-9 rounded flex items-center justify-center flex-shrink-0 ${isGroup ? "bg-violet-100 text-violet-700" : "bg-gray-100 text-gray-700"}`}>{isGroup ? <Layers3 className="w-4 h-4" aria-hidden="true" /> : <BookmarkPlus className="w-4 h-4" aria-hidden="true" />}</div>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-1.5 flex-wrap"><span className="text-[12px] font-bold text-gray-900">{template.template_name}</span><span className={`inline-flex items-center gap-1 h-[20px] px-1.5 rounded border text-[8px] font-bold ${global ? "border-blue-200 bg-blue-50 text-blue-700" : "border-violet-200 bg-violet-50 text-violet-700"}`}>{global ? <ShieldCheck className="w-2.5 h-2.5" aria-hidden="true" /> : <UserRound className="w-2.5 h-2.5" aria-hidden="true" />}{global ? "GLOBAL" : "MY"}</span></div>
                      <div className="mt-0.5 text-[9px] text-gray-500">{isGroup ? `${template.part_count || 0} Part component assembly` : `${template.source_part_type || "Part"}${template.source_part_subtype ? ` · ${String(template.source_part_subtype).replaceAll("_", " ")}` : ""}`}{template.category ? ` · ${template.category}` : ""}</div>
                      {template.description && <div className="mt-1 text-[9px] text-gray-400 line-clamp-2">{template.description}</div>}
                      {(template.tags || []).length > 0 && <div className="mt-1 text-[8px] text-gray-400 truncate">{template.tags.join(" · ")}</div>}
                    </div>
                    <div className="text-right flex-shrink-0"><div className="text-[11px] font-bold text-gray-900">{money(template.frozen_cost)}</div>{changed && <div className="text-[8px] text-amber-600">saved current {money(template.current_cost)}</div>}</div>
                  </div>
                  {template.contains_detached_parts && <div className="mt-2 rounded border border-amber-200 bg-amber-50 px-2 py-1 text-[9px] text-amber-700 inline-flex items-center gap-1"><AlertTriangle className="w-3 h-3" aria-hidden="true" /> Contains a detached/override Part snapshot</div>}
                  <div className="mt-3 flex justify-end"><button type="button" disabled={!!addingId} onClick={() => add(template)} className="h-[29px] px-3 rounded border border-lime-400 bg-lime-200 text-[10px] font-bold text-gray-900 hover:bg-lime-300 disabled:opacity-50 inline-flex items-center gap-1"><PackagePlus className="w-3.5 h-3.5" aria-hidden="true" /> {addingId === template.id ? "Adding…" : "Add to Product"}</button></div>
                </div>;
              })}
            </div>}
          </div>
          <div className="px-4 py-3 border-t border-gray-200 bg-gray-50 flex items-center justify-between"><span className="text-[9px] text-gray-400">Saved prices are copied exactly; linked inventory can then be checked through normal Product pricing controls.</span><button type="button" disabled={!!addingId} onClick={onClose} className="h-[30px] px-4 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-600">Close</button></div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { BookmarkPlus, Layers3, Save } from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { money } from "@/components/estimator/aioPricing";
import { savePartGroupTemplate, savePartTemplate } from "./partTemplateService";

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
const EMPTY_PARTS = [];

export default function SavePartTemplateModal({
  open,
  itemType = "part",
  part = null,
  group = null,
  parts = EMPTY_PARTS,
  estimateId = "",
  builderProductId = "",
  onClose,
  onSaved,
}) {
  const [name, setName] = useState("");
  const [library, setLibrary] = useState("my");
  const [category, setCategory] = useState("");
  const [tags, setTags] = useState("");
  const [description, setDescription] = useState("");
  const [notes, setNotes] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const saveRef = useRef(false);

  const isGroup = itemType === "part_group";
  const activeParts = useMemo(() => (parts || []).filter((row) => row.is_active !== false), [parts]);
  const partCount = isGroup ? activeParts.length : (part ? 1 : 0);
  const frozenCost = isGroup
    ? activeParts.reduce((sum, row) => sum + num(row.frozen_extended_cost), 0)
    : num(part?.frozen_extended_cost);

  useEffect(() => {
    if (!open) return;
    setName(isGroup ? (group?.client_label || group?.group_name || "Saved Part Group") : (part?.client_label || part?.part_name || "Saved Part"));
    setLibrary("my");
    setCategory("");
    setTags("");
    setDescription(isGroup ? (group?.description || "") : "");
    setNotes("");
    setSaving(false);
    setError("");
  }, [open, isGroup, group?.id, part?.id]);

  const save = async (event) => {
    event.preventDefault();
    if (!name.trim() || saveRef.current) return;
    saveRef.current = true;
    setSaving(true);
    setError("");
    try {
      const options = {
        template_name: name.trim(),
        product_group: library,
        category: category.trim(),
        tags: tags.split(",").map((value) => value.trim()).filter(Boolean),
        description,
        notes,
      };
      const created = isGroup
        ? await savePartGroupTemplate({ estimateId, builderProductId, group, parts: activeParts, options })
        : await savePartTemplate({ estimateId, builderProductId, part, options });
      onSaved?.(created);
      onClose?.();
    } catch (err) {
      setError(err?.message || "Part could not be saved to the Part Library.");
    } finally {
      saveRef.current = false;
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(next) => !next && !saving && onClose?.()}>
      <DialogContent className="sm:max-w-[650px] p-0 overflow-hidden border-gray-300 shadow-2xl">
        <DialogHeader className="px-5 py-4 bg-[#3f3f3f] text-white border-b-4 border-lime-300">
          <DialogTitle className="text-white text-[17px] flex items-center gap-2"><BookmarkPlus className="w-5 h-5 text-lime-300" aria-hidden="true" /> Save to Part Library</DialogTitle>
          <p className="text-[10px] text-gray-300 mt-1">Creates a permanent reusable snapshot. Master Inventory records remain unchanged.</p>
        </DialogHeader>
        <form onSubmit={save} className="p-5 bg-white space-y-4">
          <div className="rounded border border-gray-200 bg-gray-50 px-3 py-2.5 flex items-center gap-3">
            <div className="w-8 h-8 rounded bg-white border border-gray-200 flex items-center justify-center text-gray-600"><Layers3 className="w-4 h-4" aria-hidden="true" /></div>
            <div className="min-w-0 flex-1"><div className="text-[11px] font-bold text-gray-800">{isGroup ? group?.group_name || "Part Group" : part?.part_name || "Part"}</div><div className="text-[9px] text-gray-500">{isGroup ? `${partCount} Parts saved together as one reusable component assembly` : `${part?.part_type || "Part"} · ${part?.inventory_item_name || "manual / Builder cost"}`}</div></div>
            <div className="text-right"><div className="text-[9px] text-gray-400">FROZEN COST</div><div className="text-[13px] font-bold text-gray-900">{money(frozenCost)}</div></div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <label className="sm:col-span-2 text-[10px] font-bold tracking-wide text-gray-500">SAVED PART NAME<input autoFocus value={name} onChange={(event) => setName(event.target.value)} className="mt-1 w-full h-[34px] px-3 border border-gray-300 rounded text-[12px]" /></label>
            <label className="text-[10px] font-bold tracking-wide text-gray-500">LIBRARY<select value={library} onChange={(event) => setLibrary(event.target.value)} className="mt-1 w-full h-[34px] px-2 border border-gray-300 rounded bg-white text-[12px]"><option value="my">My Parts</option><option value="global">Global Parts</option></select></label>
            <label className="text-[10px] font-bold tracking-wide text-gray-500">CATEGORY<input value={category} onChange={(event) => setCategory(event.target.value)} placeholder="e.g. Mounting, Electrical, Cabinet" className="mt-1 w-full h-[34px] px-3 border border-gray-300 rounded text-[12px]" /></label>
            <label className="sm:col-span-2 text-[10px] font-bold tracking-wide text-gray-500">SEARCH TAGS<input value={tags} onChange={(event) => setTags(event.target.value)} placeholder="stud mount, acrylic, hardware, install" className="mt-1 w-full h-[34px] px-3 border border-gray-300 rounded text-[12px]" /><span className="block mt-1 text-[9px] font-normal text-gray-400">Comma separated.</span></label>
            <label className="sm:col-span-2 text-[10px] font-bold tracking-wide text-gray-500">DESCRIPTION<textarea value={description} onChange={(event) => setDescription(event.target.value)} rows={2} className="mt-1 w-full px-3 py-2 border border-gray-300 rounded text-[12px] resize-y" /></label>
            <label className="sm:col-span-2 text-[10px] font-bold tracking-wide text-gray-500">INTERNAL NOTES<textarea value={notes} onChange={(event) => setNotes(event.target.value)} rows={2} className="mt-1 w-full px-3 py-2 border border-gray-300 rounded text-[12px] resize-y" /></label>
          </div>

          <div className="rounded border border-amber-200 bg-amber-50 px-3 py-2 text-[10px] text-amber-800">When reused, this snapshot becomes an independent Part{isGroup ? " Group" : ""} in the target Product. Builder recalculation will not overwrite the inserted copy. Existing Master Inventory links and frozen/current snapshots are preserved for traceability.</div>
          {error && <div role="alert" className="rounded border border-red-200 bg-red-50 px-3 py-2 text-[11px] text-red-700">{error}</div>}
          <div className="flex justify-end gap-2"><button type="button" disabled={saving} onClick={onClose} className="h-[32px] px-4 rounded border border-gray-300 bg-white text-[11px] font-semibold text-gray-600">Cancel</button><button type="submit" disabled={saving || !name.trim()} className="h-[32px] px-4 rounded border border-lime-400 bg-lime-200 text-[11px] font-bold text-gray-900 hover:bg-lime-300 disabled:opacity-50 inline-flex items-center gap-1.5"><Save className="w-3.5 h-3.5" aria-hidden="true" /> {saving ? "Saving…" : "Save Part"}</button></div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { base44 } from "@/api/base44Client";
import { ensureBuilderProductForLine } from "@/components/estimator/builder/builderService";
import { applyBuilderPartPriceAcceptancePlan, pricingSnapshot } from "@/components/estimator/builder/partSync";
import { inventoryRowName, inventoryUnitCost, loadMasterPartCatalog } from "./partCatalog";
import { liveCustomerUnitPrice } from "@/components/estimator/customerPricing";
import { assertEstimateProductMutationAllowed } from "@/components/estimator/estimateMutationGuard";
import { builderMutationHash, markBuilderMutationPending, pendingBuilderMutation, resumeBuilderMutation } from "@/components/estimator/builder/builderMutationRecovery";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { expectedEstimateFields, replaceEstimateFieldsIfUnchanged } from "@/components/estimator/estimatePersistence";
import { expectedBuilderEntityFields, replaceBuilderEntityFieldsIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";
import { staffEntities } from "@/components/staff/staffEntities";

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
const nowIso = () => new Date().toISOString();
const stable = (value) => JSON.stringify(value || {});

function estimateLineForBuilder(estimate, builderProductId) {
  return (estimate?.line_items || []).find((line) => line.builder_product_id === builderProductId) || null;
}

async function loadManualMutationContext(builderProductId, expectedEstimateUpdatedAt = "") {
  if (!builderProductId) throw new Error("Product is required.");
  const builder = await staffEntities.BuilderProduct.get(builderProductId);
  if (!builder?.id || !builder.estimate_id) throw new Error("The Product could not be verified against an estimate.");
  const estimate = await staffEntities.AllInOneEstimate.get(builder.estimate_id);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });
  const line = estimateLineForBuilder(estimate, builder.id);
  if (!line) throw new Error("This Product is no longer part of the estimate. Reload before changing its Parts.");
  return { builder, estimate, line };
}

async function loadRawManualMutationContext(builderProductId) {
  if (!builderProductId) throw new Error("Product is required.");
  const builder = await staffEntities.BuilderProduct.get(builderProductId);
  if (!builder?.id || !builder.estimate_id) throw new Error("The Product could not be verified against an estimate.");
  const estimate = await staffEntities.AllInOneEstimate.get(builder.estimate_id);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  const line = estimateLineForBuilder(estimate, builder.id);
  if (!line) throw new Error("This Product is no longer part of the estimate. Reload before changing its Parts.");
  return { builder, estimate, line, pending: pendingBuilderMutation(line) };
}

async function resumeStoredManualPartMutation({ builder, estimate, line, pending }) {
  const parts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
  if (!Array.isArray(parts)) throw new Error("Builder Parts could not be verified while resuming the manual Part mutation.");
  return resumeBuilderMutation({
    estimateId: estimate.id,
    estimate,
    builder,
    parts,
    line,
    pending,
    applyPartPlan: applyBuilderPartPriceAcceptancePlan,
  });
}

function manualPartChangesAlreadyApplied(part, changes = {}) {
  if (!part || !["manual", "manual_addon"].includes(part.builder_sync_state)) return false;
  if (changes.part_name !== undefined && String(part.part_name || "") !== String(changes.part_name || "Part")) return false;
  if (changes.client_label !== undefined && String(part.client_label || "") !== String(changes.client_label || "")) return false;
  if (changes.quantity !== undefined && Math.abs(num(part.quantity) - Math.max(0, num(changes.quantity))) > 0.000001) return false;
  if (changes.unit !== undefined && String(part.unit || "") !== String(changes.unit || "")) return false;
  if (changes.frozen_unit_cost !== undefined && Math.abs(num(part.frozen_unit_cost) - num(changes.frozen_unit_cost)) > 0.000001) return false;
  if (changes.detail_overrides !== undefined && stable(part.detail_overrides || {}) !== stable(changes.detail_overrides || {})) return false;
  if (changes.notes !== undefined && String(part.notes || "") !== String(changes.notes || "")) return false;
  if (changes.manual_cost_override_reason !== undefined && String(part.manual_cost_override_reason || "") !== String(changes.manual_cost_override_reason || "")) return false;
  return true;
}

function patchedEstimateLines(estimate, builderProductId, patch) {
  return (estimate.line_items || []).map((line) => {
    if (line.builder_product_id !== builderProductId) return line;
    const resolvedPatch = typeof patch === "function" ? patch(line) : patch;
    return { ...line, ...resolvedPatch };
  });
}

async function patchVerifiedEstimateLine(estimate, builder, patch) {
  const lineItems = patchedEstimateLines(estimate, builder.id, patch);
  const savedEstimate = await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId: estimate.id,
    expectedFields: expectedEstimateFields(estimate, { line_items: lineItems }),
    nextFields: { line_items: lineItems },
    label: "Custom Product Estimate line update",
  });
  const savedLines = savedEstimate.line_items || lineItems;
  return savedLines.find((line) => line.builder_product_id === builder.id) || null;
}

function assertLoadedPartVersion(part, expectedPartUpdatedAt = "") {
  const expected = String(expectedPartUpdatedAt || "").trim();
  const current = String(part?.updated_date || "").trim();
  if (expected && current !== expected) {
    throw new Error("This Part changed in another session. Reload the Product before changing it.");
  }
}

async function verifyCatalogItem(catalogItem) {
  if (!catalogItem?.entity || !catalogItem?.inventoryId) throw new Error("Select a Master Inventory Part.");
  const row = await base44.entities[catalogItem.entity].get(catalogItem.inventoryId);
  if (!row) throw new Error("This Master Inventory Part no longer exists. Reopen the picker to refresh the catalog.");
  const expected = String(catalogItem.row?.updated_date || "").trim();
  const current = String(row.updated_date || "").trim();
  if (expected && current !== expected) {
    throw new Error("This Master Inventory Part changed after the picker opened. Reopen the picker and review the latest cost/details before using it.");
  }
  return {
    ...catalogItem,
    name: inventoryRowName(catalogItem.entity, row),
    unitCost: inventoryUnitCost(catalogItem.entity, row),
    row,
    pricingSnapshot: pricingSnapshot(row),
  };
}

export async function createCustomProduct({ estimate, name = "Custom Product", expectedEstimateUpdatedAt = "" }) {
  if (!estimate?.id) throw new Error("Estimate is required.");
  const currentEstimate = await staffEntities.AllInOneEstimate.get(estimate.id);
  if (!currentEstimate) throw new Error("Estimate could not be loaded.");
  await assertEstimateProductMutationAllowed(currentEstimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });
  const provisionalLine = {
    module_key: "custom",
    project_id: "",
    project_name: name,
    builder_name: "Custom Product",
    client_product_name: name,
    product_category: "",
    client_name: currentEstimate.client_name,
    total_snapshot: 0,
    live_total_snapshot: 0,
    customer_price_snapshot: 0,
    live_customer_price_snapshot: 0,
    price_state: "current",
    adjustment_percent: 0,
    section_status: "in_progress",
    customer_quantity: 1,
    include_in_customer: true,
    owned: true,
    linked_date: nowIso(),
  };
  const result = await ensureBuilderProductForLine({ estimate: currentEstimate, line: provisionalLine, isNew: true });
  const customBuilderPatch = {
    module_key: "custom",
    builder_name: "Custom Product",
    client_product_name: name,
    product_category: "",
    price_state: "current",
    frozen_cost: 0,
    frozen_customer_price: 0,
    current_recalculated_cost: 0,
    notes: "Blank / Custom Product. Pricing is driven directly by its Parts rather than a dedicated estimator Builder.",
  };
  await replaceBuilderEntityFieldsIfUnchanged({
    entity: staffEntities.BuilderProduct,
    id: result.builderProduct.id,
    expectedUpdatedAt: result.builderProduct.updated_date || "",
    expectedFields: expectedBuilderEntityFields(result.builderProduct, customBuilderPatch),
    nextFields: customBuilderPatch,
    guardFields: { estimate_id: currentEstimate.id },
    label: "Custom Product Builder setup",
  });
  return { ...result, line: { ...result.line, price_state: "current" } };
}

export async function addCatalogPartToProduct({ builderProductId, catalogItem, quantity = 1, expectedEstimateUpdatedAt = "" }) {
  if (!builderProductId || !catalogItem?.inventoryId) throw new Error("Select a Master Inventory Part.");
  const context = await loadRawManualMutationContext(builderProductId);
  const { builder, estimate, line, pending } = context;
  if (pending) {
    if (pending.kind !== "builder_manual_part_add") {
      throw new Error("Another Builder mutation is still being recovered for this Product. Resume that operation before adding a Part.");
    }
    await resumeStoredManualPartMutation(context);
    const completedParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
    const completed = (completedParts || []).find((part) => part.part_key === pending.target_part_key);
    if (!completed) throw new Error("The recovered manual Part could not be verified after completion.");
    return completed;
  }

  const qty = Math.max(0, num(quantity, 1));
  const requestVersion = String(expectedEstimateUpdatedAt || estimate.updated_date || "");
  const requestHash = builderMutationHash({
    builder_product_id: builder.id,
    expected_estimate_updated_at: requestVersion,
    inventory_entity: catalogItem.entity,
    inventory_item_id: catalogItem.inventoryId,
    quantity: qty,
  });
  const partKey = `manual-${requestHash}`;
  const existingParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts" });
  if (!Array.isArray(existingParts) || existingParts.some((part) => part?.builder_product_id !== builder.id)) {
    throw new Error("Builder Parts could not be verified before adding this Part.");
  }
  const alreadyCreated = existingParts.find((part) => part.part_key === partKey);
  if (alreadyCreated) return alreadyCreated;

  const liveCatalogItem = await verifyCatalogItem(catalogItem);
  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });
  const unitCost = num(liveCatalogItem.unitCost);
  const extended = qty * unitCost;
  const timestamp = nowIso();
  const activeParts = existingParts.filter((part) => part.is_active !== false);
  const isCustomProduct = builder.module_key === "custom";
  const syncState = isCustomProduct ? "manual" : "manual_addon";
  const partData = {
    builder_product_id: builder.id,
    part_key: partKey,
    sort_order: activeParts.length,
    part_name: liveCatalogItem.name,
    part_type: liveCatalogItem.categoryKey,
    part_subtype: liveCatalogItem.subtype || liveCatalogItem.categoryKey,
    source_module_key: builder.module_key || "custom",
    source_path: "",
    builder_sync_state: syncState,
    inventory_entity: liveCatalogItem.entity,
    inventory_item_id: liveCatalogItem.inventoryId,
    original_inventory_item_id: liveCatalogItem.inventoryId,
    inventory_item_name: liveCatalogItem.name,
    inventory_link_state: "attached",
    frozen_inventory_snapshot: liveCatalogItem.row,
    current_inventory_snapshot: liveCatalogItem.row,
    detail_overrides: {},
    builder_data: { catalog_category: liveCatalogItem.categoryKey, catalog_category_label: liveCatalogItem.categoryLabel },
    calculation_snapshot: { quantity: qty, unit_cost: unitCost, extended_cost: extended },
    pricing_basis_snapshot: { pricing_mode: liveCatalogItem.pricingMode, inventory_pricing: liveCatalogItem.pricingSnapshot },
    quantity: qty,
    unit: liveCatalogItem.unit,
    frozen_unit_cost: unitCost,
    frozen_extended_cost: extended,
    current_unit_cost: unitCost,
    current_extended_cost: extended,
    price_state: "current",
    price_delta: 0,
    price_delta_percent: 0,
    inventory_updated_date_snapshot: liveCatalogItem.row?.updated_date || "",
    last_price_check_at: timestamp,
    last_price_update_at: timestamp,
    manual_cost_override: false,
    is_active: true,
  };
  const previousTotal = num(builder.frozen_cost);
  const previousCustomerPrice = num(builder.frozen_customer_price, previousTotal);
  const nextTotal = previousTotal + extended;
  const nextCustomerPrice = previousCustomerPrice + extended;
  const builderPatch = {
    frozen_cost: nextTotal,
    frozen_customer_price: nextCustomerPrice,
    current_recalculated_cost: num(builder.current_recalculated_cost, previousTotal) + extended,
    part_count: activeParts.length + 1,
    price_state: "current",
    price_delta: 0,
    price_delta_percent: 0,
    last_price_check_at: timestamp,
    last_price_update_at: timestamp,
    builder_version: num(builder.builder_version, 1) + 1,
  };
  const linePatch = {
    total_snapshot: nextTotal,
    live_total_snapshot: nextTotal,
    customer_price_snapshot: nextCustomerPrice,
    live_customer_price_snapshot: liveCustomerUnitPrice(line) + extended,
    price_state: "current",
    last_price_check_at: timestamp,
    last_price_update_at: timestamp,
  };
  const changedParts = [{ part_key: partKey, part_name: liveCatalogItem.name, action: "add_part", unit_cost: unitCost, quantity: qty, extended_cost: extended, inventory_entity: liveCatalogItem.entity, inventory_item_id: liveCatalogItem.inventoryId }];
  const recoveryMarker = {
    key: `builder_manual_part_add:${builder.id}:${requestHash}`,
    kind: "builder_manual_part_add",
    started_at: timestamp,
    estimate_id: estimate.id,
    estimate_line_id: line.line_id || builder.estimate_line_id || "",
    builder_product_id: builder.id,
    target_part_key: partKey,
    builder_updated_date_before: builder.updated_date || "",
    builder_version_before: num(builder.builder_version, 1),
    part_acceptance_plan: {
      timestamp,
      part_updates: [{ operation: "create", part_key: partKey, data: partData }],
      changed_parts: changedParts,
      active_part_count: activeParts.length + 1,
    },
    builder_patch: builderPatch,
    line_patch: linePatch,
    revision: {
      builder_product_id: builder.id,
      estimate_id: builder.estimate_id || "",
      reason: previousTotal === 0 && activeParts.length === 0 ? "initial_freeze" : "manual_adjustment",
      previous_total_cost: previousTotal,
      new_total_cost: nextTotal,
      previous_customer_price: previousCustomerPrice,
      new_customer_price: nextCustomerPrice,
      changed_parts: changedParts,
      builder_snapshot_before: builder.builder_snapshot || {},
      builder_snapshot_after: builder.builder_snapshot || {},
      price_snapshot_before: { total: previousTotal },
      price_snapshot_after: { total: nextTotal },
      notes: `${isCustomProduct ? "Added" : "Added independent add-on"} ${liveCatalogItem.name} from Master Inventory.`,
    },
  };

  const marked = await markBuilderMutationPending({ estimate, builder, pending: recoveryMarker });
  await resumeBuilderMutation({
    estimateId: estimate.id,
    estimate: marked.markedEstimate,
    builder: marked.currentBuilder,
    parts: marked.currentParts,
    line: marked.markedLine,
    pending: marked.canonicalPending,
    applyPartPlan: applyBuilderPartPriceAcceptancePlan,
  });
  const completedParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
  const completed = (completedParts || []).find((part) => part.part_key === partKey);
  if (!completed) throw new Error("The added manual Part could not be verified after completion.");
  return completed;
}

export async function updateManualProductPart(partId, changes = {}, { expectedEstimateUpdatedAt = "", expectedPartUpdatedAt = "" } = {}) {
  const part = await staffEntities.BuilderPart.get(partId);
  if (!part) throw new Error("Part not found.");
  if (!["manual", "manual_addon"].includes(part.builder_sync_state)) throw new Error("Only independent manual Parts can be edited directly here.");
  const context = await loadRawManualMutationContext(part.builder_product_id);
  const { builder, estimate, line, pending } = context;
  if (pending) {
    if (pending.kind !== "builder_manual_part_edit" || String(pending.target_part_id || "") !== String(part.id)) {
      throw new Error("Another Builder mutation is still being recovered for this Product. Resume that operation before editing this Part.");
    }
    await resumeStoredManualPartMutation(context);
    return staffEntities.BuilderPart.get(part.id);
  }
  if (manualPartChangesAlreadyApplied(part, changes)) return part;
  assertLoadedPartVersion(part, expectedPartUpdatedAt);
  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });

  const previousExtended = num(part.frozen_extended_cost);
  const quantity = changes.quantity !== undefined ? Math.max(0, num(changes.quantity)) : num(part.quantity, 1);
  const unitCost = changes.frozen_unit_cost !== undefined ? num(changes.frozen_unit_cost) : num(part.frozen_unit_cost);
  const extended = quantity * unitCost;
  const delta = extended - previousExtended;
  const timestamp = nowIso();
  const previousDetailOverrides = part.detail_overrides || {};
  const nextDetailOverrides = changes.detail_overrides !== undefined ? { ...(changes.detail_overrides || {}) } : previousDetailOverrides;
  const costWasManuallyChanged = changes.frozen_unit_cost !== undefined && Math.abs(unitCost - num(part.frozen_unit_cost)) > 0.000001;
  const partPatch = {
    part_name: changes.part_name !== undefined ? String(changes.part_name || "Part") : part.part_name,
    client_label: changes.client_label !== undefined ? String(changes.client_label || "") : part.client_label,
    quantity,
    unit: changes.unit !== undefined ? String(changes.unit || "") : part.unit,
    frozen_unit_cost: unitCost,
    frozen_extended_cost: extended,
    current_unit_cost: costWasManuallyChanged ? unitCost : num(part.current_unit_cost, unitCost),
    current_extended_cost: costWasManuallyChanged ? extended : num(part.current_unit_cost, unitCost) * quantity,
    manual_cost_override: part.manual_cost_override || costWasManuallyChanged,
    manual_cost: (part.manual_cost_override || costWasManuallyChanged) ? extended : undefined,
    manual_cost_override_reason: changes.manual_cost_override_reason !== undefined ? String(changes.manual_cost_override_reason || "") : String(part.manual_cost_override_reason || ""),
    detail_overrides: nextDetailOverrides,
    price_state: costWasManuallyChanged ? "manual" : part.price_state,
    notes: changes.notes !== undefined ? String(changes.notes || "") : part.notes,
    last_price_update_at: timestamp,
  };
  const previousTotal = num(builder.frozen_cost);
  const previousCustomerPrice = num(builder.frozen_customer_price, previousTotal);
  const nextTotal = previousTotal + delta;
  const nextCustomerPrice = previousCustomerPrice + delta;
  const currentTotal = num(builder.current_recalculated_cost, previousTotal) + delta;
  const priceState = Math.abs(currentTotal - nextTotal) > 0.005 ? "changed" : "current";
  const builderPatch = {
    frozen_cost: nextTotal,
    frozen_customer_price: nextCustomerPrice,
    current_recalculated_cost: currentTotal,
    price_state: priceState,
    price_delta: currentTotal - nextTotal,
    price_delta_percent: nextTotal ? ((currentTotal - nextTotal) / nextTotal) * 100 : 0,
    last_price_update_at: timestamp,
    builder_version: num(builder.builder_version, 1) + 1,
  };
  const linePatch = {
    total_snapshot: nextTotal,
    live_total_snapshot: currentTotal,
    customer_price_snapshot: nextCustomerPrice,
    live_customer_price_snapshot: liveCustomerUnitPrice(line) + delta,
    price_state: priceState,
    last_price_update_at: timestamp,
  };
  const changedParts = [{ part_id: part.id, part_name: partPatch.part_name, action: "edit_manual_part", previous_extended_cost: previousExtended, new_extended_cost: extended, delta, previous_detail_overrides: previousDetailOverrides, new_detail_overrides: nextDetailOverrides }];
  const requestHash = builderMutationHash({
    estimate_updated_date: expectedEstimateUpdatedAt || estimate.updated_date || "",
    part_id: part.id,
    part_updated_date: expectedPartUpdatedAt || part.updated_date || "",
    changes,
    part_patch: partPatch,
  });
  const recoveryMarker = {
    key: `builder_manual_part_edit:${builder.id}:${part.id}:${requestHash}`,
    kind: "builder_manual_part_edit",
    started_at: timestamp,
    estimate_id: estimate.id,
    estimate_line_id: line.line_id || builder.estimate_line_id || "",
    builder_product_id: builder.id,
    target_part_id: part.id,
    builder_updated_date_before: builder.updated_date || "",
    builder_version_before: num(builder.builder_version, 1),
    part_acceptance_plan: {
      timestamp,
      part_updates: [{ operation: "update", part_id: part.id, part_key: part.part_key, expected_updated_date: part.updated_date || "", patch: partPatch }],
      changed_parts: changedParts,
    },
    builder_patch: builderPatch,
    line_patch: linePatch,
    revision: {
      builder_product_id: builder.id,
      estimate_id: builder.estimate_id || "",
      reason: "manual_adjustment",
      previous_total_cost: previousTotal,
      new_total_cost: nextTotal,
      previous_customer_price: previousCustomerPrice,
      new_customer_price: nextCustomerPrice,
      changed_parts: changedParts,
      builder_snapshot_before: builder.builder_snapshot || {},
      builder_snapshot_after: builder.builder_snapshot || {},
      price_snapshot_before: { total: previousTotal },
      price_snapshot_after: { total: nextTotal },
      notes: "Manual / Custom Product Part edited.",
    },
  };
  const marked = await markBuilderMutationPending({ estimate, builder, pending: recoveryMarker });
  await resumeBuilderMutation({
    estimateId: estimate.id,
    estimate: marked.markedEstimate,
    builder: marked.currentBuilder,
    parts: marked.currentParts,
    line: marked.markedLine,
    pending: marked.canonicalPending,
    applyPartPlan: applyBuilderPartPriceAcceptancePlan,
  });
  return staffEntities.BuilderPart.get(part.id);
}

export async function switchManualProductPart(partId, catalogItem, { expectedEstimateUpdatedAt = "", expectedPartUpdatedAt = "" } = {}) {
  if (!partId || !catalogItem?.inventoryId) throw new Error("Select a replacement Master Inventory Part.");
  const part = await staffEntities.BuilderPart.get(partId);
  if (!part || !["manual", "manual_addon"].includes(part.builder_sync_state)) throw new Error("Only independent manual Parts can be switched directly.");
  const context = await loadRawManualMutationContext(part.builder_product_id);
  const { builder, estimate, line, pending } = context;
  if (pending) {
    if (pending.kind !== "builder_manual_part_switch" || String(pending.target_part_id || "") !== String(part.id)) {
      throw new Error("Another Builder mutation is still being recovered for this Product. Resume that operation before switching this Part.");
    }
    await resumeStoredManualPartMutation(context);
    return staffEntities.BuilderPart.get(part.id);
  }
  const targetInventoryMatches =
    String(part.inventory_entity || "") === String(catalogItem.entity || "") &&
    String(part.inventory_item_id || "") === String(catalogItem.inventoryId || "") &&
    part.manual_cost_override !== true;
  if (expectedPartUpdatedAt && String(part.updated_date || "") !== String(expectedPartUpdatedAt) && targetInventoryMatches) {
    return part;
  }
  const liveCatalogItem = await verifyCatalogItem(catalogItem);
  const unitCost = num(liveCatalogItem.unitCost);
  const alreadySwitched = targetInventoryMatches && Math.abs(num(part.frozen_unit_cost) - unitCost) <= 0.000001;
  if (alreadySwitched) return part;
  assertLoadedPartVersion(part, expectedPartUpdatedAt);
  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });

  const quantity = num(part.quantity, 1);
  const previousExtended = num(part.frozen_extended_cost);
  const nextExtended = quantity * unitCost;
  const delta = nextExtended - previousExtended;
  const timestamp = nowIso();
  const partPatch = {
    part_name: liveCatalogItem.name,
    part_type: liveCatalogItem.categoryKey,
    part_subtype: liveCatalogItem.subtype || liveCatalogItem.categoryKey,
    inventory_entity: liveCatalogItem.entity,
    inventory_item_id: liveCatalogItem.inventoryId,
    original_inventory_item_id: liveCatalogItem.inventoryId,
    inventory_item_name: liveCatalogItem.name,
    inventory_link_state: "attached",
    reattach_candidate_id: "",
    reattach_candidate_name: "",
    frozen_inventory_snapshot: liveCatalogItem.row,
    current_inventory_snapshot: liveCatalogItem.row,
    detail_overrides: {},
    builder_data: { ...(part.builder_data || {}), catalog_category: liveCatalogItem.categoryKey, catalog_category_label: catalogItem.categoryLabel },
    pricing_basis_snapshot: { pricing_mode: liveCatalogItem.pricingMode, inventory_pricing: liveCatalogItem.pricingSnapshot },
    unit: liveCatalogItem.unit,
    frozen_unit_cost: unitCost,
    frozen_extended_cost: nextExtended,
    current_unit_cost: unitCost,
    current_extended_cost: nextExtended,
    manual_cost_override: false,
    manual_cost: undefined,
    price_state: "current",
    price_delta: 0,
    price_delta_percent: 0,
    inventory_updated_date_snapshot: liveCatalogItem.row?.updated_date || "",
    last_price_check_at: timestamp,
    last_price_update_at: timestamp,
  };
  const previousTotal = num(builder.frozen_cost);
  const previousCustomerPrice = num(builder.frozen_customer_price, previousTotal);
  const nextTotal = previousTotal + delta;
  const nextCustomerPrice = previousCustomerPrice + delta;
  const currentTotal = num(builder.current_recalculated_cost, previousTotal) + delta;
  const priceState = Math.abs(currentTotal - nextTotal) > 0.005 ? "changed" : "current";
  const builderPatch = {
    frozen_cost: nextTotal,
    frozen_customer_price: nextCustomerPrice,
    current_recalculated_cost: currentTotal,
    price_state: priceState,
    price_delta: currentTotal - nextTotal,
    price_delta_percent: nextTotal ? ((currentTotal - nextTotal) / nextTotal) * 100 : 0,
    last_price_update_at: timestamp,
    last_price_check_at: timestamp,
    builder_version: num(builder.builder_version, 1) + 1,
  };
  const linePatch = {
    total_snapshot: nextTotal,
    live_total_snapshot: currentTotal,
    customer_price_snapshot: nextCustomerPrice,
    live_customer_price_snapshot: liveCustomerUnitPrice(line) + delta,
    price_state: priceState,
    last_price_update_at: timestamp,
    last_price_check_at: timestamp,
  };
  const changedParts = [{ part_id: part.id, action: "switch_part", previous_inventory_item_id: part.inventory_item_id, new_inventory_item_id: liveCatalogItem.inventoryId, previous_inventory_name: part.inventory_item_name, new_inventory_name: liveCatalogItem.name, previous_extended_cost: previousExtended, new_extended_cost: nextExtended, delta, cleared_detail_overrides: part.detail_overrides || {} }];
  const requestHash = builderMutationHash({
    estimate_updated_date: expectedEstimateUpdatedAt || estimate.updated_date || "",
    part_id: part.id,
    part_updated_date: expectedPartUpdatedAt || part.updated_date || "",
    new_inventory_entity: liveCatalogItem.entity,
    new_inventory_item_id: liveCatalogItem.inventoryId,
    part_patch: partPatch,
  });
  const recoveryMarker = {
    key: `builder_manual_part_switch:${builder.id}:${part.id}:${requestHash}`,
    kind: "builder_manual_part_switch",
    started_at: timestamp,
    estimate_id: estimate.id,
    estimate_line_id: line.line_id || builder.estimate_line_id || "",
    builder_product_id: builder.id,
    target_part_id: part.id,
    builder_updated_date_before: builder.updated_date || "",
    builder_version_before: num(builder.builder_version, 1),
    part_acceptance_plan: {
      timestamp,
      part_updates: [{ operation: "update", part_id: part.id, part_key: part.part_key, expected_updated_date: part.updated_date || "", patch: partPatch }],
      changed_parts: changedParts,
    },
    builder_patch: builderPatch,
    line_patch: linePatch,
    revision: {
      builder_product_id: builder.id,
      estimate_id: builder.estimate_id || "",
      reason: "manual_adjustment",
      previous_total_cost: previousTotal,
      new_total_cost: nextTotal,
      previous_customer_price: previousCustomerPrice,
      new_customer_price: nextCustomerPrice,
      changed_parts: changedParts,
      builder_snapshot_before: builder.builder_snapshot || {},
      builder_snapshot_after: builder.builder_snapshot || {},
      price_snapshot_before: { total: previousTotal },
      price_snapshot_after: { total: nextTotal },
      notes: `Switched independent Product Part to ${liveCatalogItem.name}.`,
    },
  };
  const marked = await markBuilderMutationPending({ estimate, builder, pending: recoveryMarker });
  await resumeBuilderMutation({
    estimateId: estimate.id,
    estimate: marked.markedEstimate,
    builder: marked.currentBuilder,
    parts: marked.currentParts,
    line: marked.markedLine,
    pending: marked.canonicalPending,
    applyPartPlan: applyBuilderPartPriceAcceptancePlan,
  });
  return staffEntities.BuilderPart.get(part.id);
}

export async function removeManualProductPart(partId, { builderProductId = "", expectedEstimateUpdatedAt = "", expectedPartUpdatedAt = "" } = {}) {
  if (!partId) throw new Error("Part is required.");
  const part = await staffEntities.BuilderPart.get(partId);
  const resolvedBuilderProductId = builderProductId || part?.builder_product_id || "";
  if (!resolvedBuilderProductId) {
    throw new Error("The Product for this Part could not be verified. Reload before removing it.");
  }
  const context = await loadRawManualMutationContext(resolvedBuilderProductId);
  const { builder, estimate, line, pending } = context;
  const requestEstimateVersion = String(expectedEstimateUpdatedAt || estimate.updated_date || "");
  const requestPartVersion = String(expectedPartUpdatedAt || part?.updated_date || "");
  const requestHash = builderMutationHash({
    builder_product_id: builder.id,
    part_id: partId,
    expected_estimate_updated_at: requestEstimateVersion,
    expected_part_updated_at: requestPartVersion,
  });
  const operationKey = `builder_manual_part_remove:${builder.id}:${partId}:${requestHash}`;

  if (pending) {
    if (pending.kind !== "builder_manual_part_remove" || String(pending.target_part_id || "") !== String(partId)) {
      throw new Error("Another Builder mutation is still being recovered for this Product. Resume that operation before removing this Part.");
    }
    await resumeStoredManualPartMutation(context);
    return { removed: true, recovered: true };
  }

  if (!part) {
    const revisions = await loadAllEntityRows({ entity: base44.entities.BuilderPriceRevision, query: { builder_product_id: builder.id }, sort: "revision_number", label: "Builder price revisions" });
    const completed = (revisions || []).find((revision) => String(revision.idempotency_key || "") === operationKey);
    if (completed) return { removed: true, alreadyCompleted: true };
    throw new Error("This Part is already missing. Reload the Product before continuing so its totals can be verified.");
  }
  if (String(part.builder_product_id || "") !== String(builder.id)) {
    throw new Error("This Part no longer belongs to the expected Product. Reload before removing it.");
  }
  if (!["manual", "manual_addon"].includes(part.builder_sync_state)) {
    throw new Error("Only independent manual Parts can be removed directly.");
  }
  assertLoadedPartVersion(part, expectedPartUpdatedAt);
  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });

  const [allParts, allGroups] = await Promise.all([
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" }),
    loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Part Groups" }),
  ]);
  if (!Array.isArray(allParts) || allParts.some((row) => row?.builder_product_id !== builder.id)) {
    throw new Error("Builder Parts could not be verified before removing this Part.");
  }
  if (!Array.isArray(allGroups) || allGroups.some((row) => row?.builder_product_id !== builder.id)) {
    throw new Error("Part Groups could not be verified before removing this Part.");
  }

  const previousExtended = num(part.frozen_extended_cost);
  const previousCurrent = num(part.current_extended_cost, previousExtended);
  const previousTotal = num(builder.frozen_cost);
  const previousCustomerPrice = num(builder.frozen_customer_price, previousTotal);
  const nextTotal = Math.max(0, previousTotal - previousExtended);
  const nextCustomerPrice = Math.max(0, previousCustomerPrice - previousExtended);
  const currentTotal = Math.max(0, num(builder.current_recalculated_cost, previousTotal) - previousCurrent);
  const timestamp = nowIso();
  const otherActiveParts = allParts.filter((row) => row.id !== part.id && row.is_active !== false);
  const activeGroups = allGroups.filter((row) => row.is_active !== false);
  const containingGroup = part.part_group_id
    ? activeGroups.find((group) => group.id === part.part_group_id) || null
    : null;
  const emptiedGroup = containingGroup && !otherActiveParts.some((row) => row.part_group_id === part.part_group_id)
    ? containingGroup
    : null;
  const groupCount = Math.max(0, activeGroups.length - (emptiedGroup ? 1 : 0));
  const priceState = Math.abs(currentTotal - nextTotal) > 0.005 ? "changed" : "current";
  const builderPatch = {
    frozen_cost: nextTotal,
    frozen_customer_price: nextCustomerPrice,
    current_recalculated_cost: currentTotal,
    part_count: otherActiveParts.length,
    group_count: groupCount,
    price_state: priceState,
    price_delta: currentTotal - nextTotal,
    price_delta_percent: nextTotal ? ((currentTotal - nextTotal) / nextTotal) * 100 : 0,
    last_price_update_at: timestamp,
    builder_version: num(builder.builder_version, 1) + 1,
  };
  const linePatch = {
    total_snapshot: nextTotal,
    live_total_snapshot: currentTotal,
    customer_price_snapshot: nextCustomerPrice,
    live_customer_price_snapshot: Math.max(0, liveCustomerUnitPrice(line) - previousCurrent),
    price_state: priceState,
    last_price_update_at: timestamp,
  };
  const changedParts = [{ part_id: part.id, part_name: part.part_name, action: "remove_part", previous_extended_cost: previousExtended }];
  const recoveryMarker = {
    key: operationKey,
    kind: "builder_manual_part_remove",
    started_at: timestamp,
    estimate_id: estimate.id,
    estimate_line_id: line.line_id || builder.estimate_line_id || "",
    builder_product_id: builder.id,
    target_part_id: part.id,
    builder_updated_date_before: builder.updated_date || "",
    builder_version_before: num(builder.builder_version, 1),
    delete_plan: {
      parts: [{ id: part.id, expected_updated_date: part.updated_date || "" }],
      groups: emptiedGroup ? [{ id: emptiedGroup.id, expected_updated_date: emptiedGroup.updated_date || "" }] : [],
    },
    part_acceptance_plan: { timestamp, part_updates: [], changed_parts: changedParts },
    builder_patch: builderPatch,
    line_patch: linePatch,
    revision: {
      builder_product_id: builder.id,
      estimate_id: builder.estimate_id || "",
      reason: "manual_adjustment",
      previous_total_cost: previousTotal,
      new_total_cost: nextTotal,
      previous_customer_price: previousCustomerPrice,
      new_customer_price: nextCustomerPrice,
      changed_parts: changedParts,
      builder_snapshot_before: builder.builder_snapshot || {},
      builder_snapshot_after: builder.builder_snapshot || {},
      price_snapshot_before: { total: previousTotal },
      price_snapshot_after: { total: nextTotal },
      notes: `Removed independent Product Part ${part.part_name}.`,
    },
  };
  const marked = await markBuilderMutationPending({ estimate, builder, pending: recoveryMarker });
  await resumeBuilderMutation({
    estimateId: estimate.id,
    estimate: marked.markedEstimate,
    builder: marked.currentBuilder,
    parts: marked.currentParts,
    line: marked.markedLine,
    pending: marked.canonicalPending,
    applyPartPlan: applyBuilderPartPriceAcceptancePlan,
  });
  return { removed: true };
}

export async function refreshManualProductPricing(builderProductId) {
  if (!builderProductId) return null;
  const [{ builder, estimate }, parts, catalog] = await Promise.all([
    loadManualMutationContext(builderProductId),
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts" }),
    loadMasterPartCatalog(),
  ]);
  const active = (parts || []).filter((part) => part.is_active !== false);
  const catalogByKey = new Map(catalog.map((item) => [`${item.entity}:${item.inventoryId}`, item]));
  let currentTotal = 0;
  let detachedCount = 0;
  let changedCount = 0;
  let partWrites = 0;
  const timestamp = nowIso();

  for (const part of active) {
    let currentUnit = num(part.frozen_unit_cost);
    let currentExtended = num(part.frozen_extended_cost);
    let state = part.price_state || "current";
    let linkState = part.inventory_link_state || "manual";
    let currentSnapshot = part.current_inventory_snapshot || {};
    let candidate = null;
    if (part.inventory_entity && part.inventory_item_id && !part.manual_cost_override) {
      const item = catalogByKey.get(`${part.inventory_entity}:${part.inventory_item_id}`);
      if (item) {
        currentUnit = inventoryUnitCost(item.entity, item.row);
        currentExtended = currentUnit * num(part.quantity, 1);
        currentSnapshot = item.row;
        linkState = "attached";
        const changed = Math.abs(currentExtended - num(part.frozen_extended_cost)) > 0.005 || stable(pricingSnapshot(item.row)) !== stable(pricingSnapshot(part.frozen_inventory_snapshot));
        state = changed ? "changed" : "current";
        if (changed) changedCount += 1;
      } else {
        const name = part.inventory_item_name || inventoryRowName(part.inventory_entity, part.frozen_inventory_snapshot || {});
        candidate = catalog.find((item) => item.entity === part.inventory_entity && item.name.trim().toLowerCase() === String(name || "").trim().toLowerCase()) || null;
        linkState = candidate ? "reattach_available" : "detached";
        state = "detached";
        detachedCount += 1;
      }
    }
    currentTotal += currentExtended;
    const nextCandidateId = candidate?.inventoryId || part.reattach_candidate_id || "";
    const nextCandidateName = candidate?.name || part.reattach_candidate_name || "";
    const nextDelta = currentExtended - num(part.frozen_extended_cost);
    const nextDeltaPercent = num(part.frozen_extended_cost) ? (nextDelta / num(part.frozen_extended_cost)) * 100 : 0;
    const changed =
      Math.abs(num(part.current_unit_cost, num(part.frozen_unit_cost)) - currentUnit) > 0.000001 ||
      Math.abs(num(part.current_extended_cost, num(part.frozen_extended_cost)) - currentExtended) > 0.005 ||
      stable(part.current_inventory_snapshot || {}) !== stable(currentSnapshot) ||
      String(part.inventory_link_state || "manual") !== String(linkState) ||
      String(part.reattach_candidate_id || "") !== String(nextCandidateId) ||
      String(part.reattach_candidate_name || "") !== String(nextCandidateName) ||
      String(part.price_state || "current") !== String(state) ||
      Math.abs(num(part.price_delta) - nextDelta) > 0.005 ||
      Math.abs(num(part.price_delta_percent) - nextDeltaPercent) > 0.0001;
    if (changed) {
      const partRefreshPatch = {
        current_unit_cost: currentUnit,
        current_extended_cost: currentExtended,
        current_inventory_snapshot: currentSnapshot,
        inventory_link_state: linkState,
        reattach_candidate_id: nextCandidateId,
        reattach_candidate_name: nextCandidateName,
        price_state: state,
        price_delta: nextDelta,
        price_delta_percent: nextDeltaPercent,
        last_price_check_at: timestamp,
      };
      await replaceBuilderEntityFieldsIfUnchanged({
        entity: staffEntities.BuilderPart,
        id: part.id,
        expectedUpdatedAt: part.updated_date || "",
        expectedFields: expectedBuilderEntityFields(part, partRefreshPatch),
        nextFields: partRefreshPatch,
        guardFields: { builder_product_id: builderProductId },
        label: `Custom Product Part “${part.part_name || "Part"}” refresh`,
      });
      partWrites += 1;
    }
  }

  const frozenTotal = active.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0);
  const priceState = detachedCount > 0 ? "detached_parts" : Math.abs(currentTotal - frozenTotal) > 0.005 || changedCount > 0 ? "changed" : "current";
  const builderChanged =
    Math.abs(num(builder.frozen_cost) - frozenTotal) > 0.005 ||
    Math.abs(num(builder.current_recalculated_cost, frozenTotal) - currentTotal) > 0.005 ||
    num(builder.part_count) !== active.length ||
    num(builder.detached_part_count) !== detachedCount ||
    !!builder.needs_reattach_review !== (detachedCount > 0) ||
    String(builder.price_state || "current") !== priceState ||
    Math.abs(num(builder.price_delta) - (currentTotal - frozenTotal)) > 0.005 ||
    Math.abs(num(builder.price_delta_percent) - (frozenTotal ? ((currentTotal - frozenTotal) / frozenTotal) * 100 : 0)) > 0.0001;
  if (builderChanged) {
    const builderRefreshPatch = {
      frozen_cost: frozenTotal,
      current_recalculated_cost: currentTotal,
      part_count: active.length,
      detached_part_count: detachedCount,
      needs_reattach_review: detachedCount > 0,
      price_state: priceState,
      price_delta: currentTotal - frozenTotal,
      price_delta_percent: frozenTotal ? ((currentTotal - frozenTotal) / frozenTotal) * 100 : 0,
      last_price_check_at: timestamp,
    };
    await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderProduct,
      id: builderProductId,
      expectedUpdatedAt: builder.updated_date || "",
      expectedFields: expectedBuilderEntityFields(builder, builderRefreshPatch),
      nextFields: builderRefreshPatch,
      guardFields: { estimate_id: estimate.id },
      label: "Custom Product Builder pricing refresh",
    });
  }

  const frozenCustomerPrice = num(builder.frozen_customer_price, frozenTotal);
  const currentLine = estimateLineForBuilder(estimate, builder.id);
  const linePatch = {
    total_snapshot: frozenTotal,
    live_total_snapshot: currentTotal,
    customer_price_snapshot: frozenCustomerPrice,
    live_customer_price_snapshot: frozenCustomerPrice + (currentTotal - frozenTotal),
    detached_part_count: detachedCount,
    needs_reattach_review: detachedCount > 0,
    price_state: priceState,
    last_price_check_at: timestamp,
  };
  const lineChanged = !!currentLine && (
    Math.abs(num(currentLine.total_snapshot) - linePatch.total_snapshot) > 0.005 ||
    Math.abs(num(currentLine.live_total_snapshot, linePatch.total_snapshot) - linePatch.live_total_snapshot) > 0.005 ||
    Math.abs(num(currentLine.customer_price_snapshot, linePatch.customer_price_snapshot) - linePatch.customer_price_snapshot) > 0.005 ||
    Math.abs(num(currentLine.live_customer_price_snapshot, linePatch.customer_price_snapshot) - linePatch.live_customer_price_snapshot) > 0.005 ||
    num(currentLine.detached_part_count) !== detachedCount ||
    !!currentLine.needs_reattach_review !== (detachedCount > 0) ||
    String(currentLine.price_state || "current") !== priceState
  );
  if (lineChanged) await patchVerifiedEstimateLine(estimate, builder, linePatch);

  return { frozenTotal, currentTotal, detachedCount, changedCount, priceState, partWrites, builderChanged, lineChanged };
}

