export async function dissolvePartGroup({ builderProductId, groupId, expectedEstimateUpdatedAt = "", expectedGroupUpdatedAt = "", expectedPartVersions = {} }) {
  if (!builderProductId || !groupId) throw new Error("Part Group is required.");
  const builder = await staffEntities.BuilderProduct.get(builderProductId);
  if (!builder?.id || !builder.estimate_id) throw new Error("The Product could not be verified against an estimate.");
  const estimate = await staffEntities.AllInOneEstimate.get(builder.estimate_id);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  const currentLine = estimateLine(estimate, builder.id);
  if (!currentLine) throw new Error("This Product is no longer part of the estimate. Reload before dissolving its Part Group.");

  const operationKey = `builder_part_group_dissolve:${builderMutationHash({
    estimate_id: estimate.id,
    builder_product_id: builder.id,
    group_id: groupId,
    expected_estimate_updated_at: expectedEstimateUpdatedAt || "",
    expected_group_updated_at: expectedGroupUpdatedAt || "",
    expected_part_versions: expectedPartVersions || {},
  })}`;
  const existingPending = pendingBuilderMutation(currentLine);
  if (existingPending) {
    if (existingPending.kind !== "builder_part_group_dissolve" || existingPending.key !== operationKey) {
      throw new Error("Another Builder mutation is still being recovered for this Product. Resume it before dissolving a Part Group.");
    }
    const parts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
    if (!Array.isArray(parts)) throw new Error("Part Group members could not be verified during dissolve recovery.");
    const recovered = await resumeBuilderMutation({ estimateId: estimate.id, estimate, builder, parts, line: currentLine, pending: existingPending, applyPartPlan: applyBuilderPartPriceAcceptancePlan });
    return { dissolved: groupId, partCount: (existingPending.target_part_ids || []).length, recovered: true, line: recovered?.line || currentLine };
  }

  if (currentLine.last_part_group_mutation_key === operationKey && currentLine.last_part_group_mutation_kind === "dissolve") {
    const [groupAfter, partsAfter] = await Promise.all([
      staffEntities.BuilderPartGroup.get(groupId),
      loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" }),
    ]);
    const targetIds = new Set(Object.keys(expectedPartVersions || {}));
    const complete = !groupAfter && Array.isArray(partsAfter) && partsAfter.filter((part) => targetIds.has(String(part.id)) && !part.part_group_id).length === targetIds.size;
    if (complete) return { dissolved: groupId, partCount: targetIds.size, alreadyCompleted: true };
    throw new Error("The Part Group dissolve receipt exists, but the completed membership no longer matches. Reload and review the Product.");
  }

  const [group, allParts, allGroups] = await Promise.all([
    staffEntities.BuilderPartGroup.get(groupId),
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" }),
    loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Part Groups" }),
  ]);
  if (!Array.isArray(allParts) || !Array.isArray(allGroups)) throw new Error("Part Group dissolve prerequisites could not be fully verified.");
  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });
  if (!group || group.builder_product_id !== builder.id) throw new Error("Part Group could not be loaded.");
  assertVersion(group, expectedGroupUpdatedAt, "Part Group");
  const members = allParts.filter((part) => part.is_active !== false && part.part_group_id === group.id);
  assertMemberVersions(members, expectedPartVersions);

  const timestamp = nowIso();
  const activeGroupCount = allGroups.filter((row) => row.is_active !== false).length;
  const pending = {
    key: operationKey,
    kind: "builder_part_group_dissolve",
    started_at: timestamp,
    estimate_id: estimate.id,
    estimate_line_id: currentLine.line_id || builder.estimate_line_id || "",
    builder_product_id: builder.id,
    builder_updated_date_before: builder.updated_date || "",
    target_group_id: group.id,
    target_part_ids: members.map((part) => part.id),
    precondition_plan: {
      groups: [{
        id: group.id,
        expected_updated_date: group.updated_date || "",
        expected_patch: { builder_product_id: builder.id, group_key: group.group_key || "" },
        allow_missing_if_applied: true,
      }],
      parts: members.map((part) => ({
        id: part.id,
        expected_updated_date: part.updated_date || "",
        expected_patch: { builder_product_id: builder.id, part_group_id: group.id, part_key: part.part_key || "" },
        target_patch: { part_group_id: "" },
      })),
    },
    part_acceptance_plan: {
      timestamp,
      part_updates: members.map((part) => ({ operation: "update", part_id: part.id, part_key: part.part_key, expected_updated_date: part.updated_date || "", patch: { part_group_id: "" } })),
      changed_parts: [],
    },
    post_part_delete_plan: { groups: [{ id: group.id, expected_updated_date: group.updated_date || "" }], parts: [] },
    builder_patch: { group_count: Math.max(0, activeGroupCount - 1) },
    line_patch: { last_part_group_mutation_key: operationKey, last_part_group_mutation_kind: "dissolve" },
    skip_revision: true,
  };
  const marked = await markBuilderMutationPending({ estimate, builder, pending });
  const recovered = await resumeBuilderMutation({ estimateId: estimate.id, estimate: marked.markedEstimate, builder: marked.currentBuilder, parts: marked.currentParts, line: marked.markedLine, pending: marked.canonicalPending, applyPartPlan: applyBuilderPartPriceAcceptancePlan });
  return { dissolved: group.id, partCount: members.length, recovered: true, line: recovered?.line || currentLine };
}

export async function clonePartGroupInProduct({ builderProductId, groupId, expectedEstimateUpdatedAt = "", expectedGroupUpdatedAt = "", expectedPartVersions = {} }) {
  if (!builderProductId || !groupId) throw new Error("Part Group is required.");

  const builder = await staffEntities.BuilderProduct.get(builderProductId);
  if (!builder?.id || !builder.estimate_id) throw new Error("The Product could not be verified against an estimate.");
  const estimate = await staffEntities.AllInOneEstimate.get(builder.estimate_id);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  const currentLine = estimateLine(estimate, builder.id);
  if (!currentLine) throw new Error("This Product is no longer part of the estimate. Reload before cloning its Part Group.");

  const operationKey = `builder_part_group_clone:${builderMutationHash({
    estimate_id: estimate.id,
    builder_product_id: builder.id,
    source_group_id: groupId,
    expected_estimate_updated_at: expectedEstimateUpdatedAt || "",
    expected_group_updated_at: expectedGroupUpdatedAt || "",
    expected_part_versions: expectedPartVersions || {},
  })}`;

  const [group, allParts, allGroups, revisions] = await Promise.all([
    staffEntities.BuilderPartGroup.get(groupId),
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts" }),
    loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Part Groups" }),
    loadAllEntityRows({ entity: base44.entities.BuilderPriceRevision, query: { builder_product_id: builderProductId }, sort: "revision_number", label: "Builder price revisions" }),
  ]);
  if (!Array.isArray(allParts) || !Array.isArray(allGroups) || !Array.isArray(revisions)) {
    throw new Error("Part Group clone prerequisites could not be fully verified.");
  }

  const existingPending = pendingBuilderMutation(currentLine);
  if (existingPending) {
    if (existingPending.kind !== "builder_part_group_clone" || existingPending.key !== operationKey) {
      throw new Error("Another Builder mutation is still being recovered for this Product. Resume it before cloning a Part Group.");
    }
    const recovered = await resumeBuilderMutation({
      estimateId: estimate.id,
      estimate,
      builder,
      parts: allParts,
      line: currentLine,
      pending: existingPending,
      applyPartPlan: applyBuilderPartPriceAcceptancePlan,
    });
    const [groupsAfter, partsAfter] = await Promise.all([
      loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Part Groups" }),
      loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" }),
    ]);
    const recoveredGroup = (groupsAfter || []).find((row) => row.group_key === existingPending.target_group_key) || null;
    const targetPartKeys = new Set(existingPending.target_part_keys || []);
    return { group: recoveredGroup, parts: (partsAfter || []).filter((part) => targetPartKeys.has(part.part_key)), recovered: true, line: recovered?.line || currentLine };
  }

  const completedRevision = revisions.find((row) => String(row.idempotency_key || "") === operationKey);
  if (completedRevision) {
    const targetGroupKey = `clone-group-${builderMutationHash({ operation_key: operationKey, source_group_id: groupId })}`;
    const completedGroup = allGroups.find((row) => row.group_key === targetGroupKey) || null;
    const completedPartKeys = new Set((completedRevision.changed_parts || []).map((part) => part.part_key).filter(Boolean));
    const completedParts = allParts.filter((part) => completedPartKeys.has(part.part_key));
    const targetMatches = completedGroup &&
      completedParts.length === completedPartKeys.size &&
      !recoveryPatchDiffers(builder, {
        frozen_cost: completedRevision.new_total_cost,
        frozen_customer_price: completedRevision.new_customer_price,
      }) &&
      !recoveryPatchDiffers(currentLine, {
        total_snapshot: completedRevision.new_total_cost,
        customer_price_snapshot: completedRevision.new_customer_price,
      });
    if (targetMatches) return { group: completedGroup, parts: completedParts, alreadyCompleted: true };
    throw new Error("The Part Group clone audit exists, but the Product no longer matches that completed clone. Reload and review the Product before continuing.");
  }

  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });
  if (!group || group.builder_product_id !== builderProductId) throw new Error("Part Group could not be loaded.");
  assertVersion(group, expectedGroupUpdatedAt, "Part Group");

  const sourceParts = allParts
    .filter((part) => part.is_active !== false && part.part_group_id === groupId)
    .sort((a, b) => num(a.sort_order) - num(b.sort_order));
  if (!sourceParts.length) throw new Error("This Part Group does not contain any active Parts.");
  assertMemberVersions(sourceParts, expectedPartVersions);

  const timestamp = nowIso();
  const isCustom = builder.module_key === "custom";
  const activeGroupCount = allGroups.filter((row) => row.is_active !== false).length;
  const activePartCount = allParts.filter((part) => part.is_active !== false).length;
  const targetGroupKey = `clone-group-${builderMutationHash({ operation_key: operationKey, source_group_id: group.id })}`;
  const groupData = {
    ...stripEntitySystemFields(group),
    builder_product_id: builder.id,
    group_key: targetGroupKey,
    group_name: `${group.group_name || "Part Group"} Copy`,
    sort_order: activeGroupCount,
    is_collapsed: false,
    is_active: true,
  };

  const partSteps = sourceParts.map((sourcePart, index) => {
    const partKey = `clone-part-${builderMutationHash({ operation_key: operationKey, source_part_id: sourcePart.id, index })}`;
    return {
      operation: "create",
      part_key: partKey,
      part_group_key_ref: targetGroupKey,
      data: {
        ...stripEntitySystemFields(sourcePart),
        builder_product_id: builder.id,
        part_group_id: "",
        part_key: partKey,
        sort_order: activePartCount + index,
        builder_sync_state: isCustom ? "manual" : "manual_addon",
        source_path: "",
        builder_detached_at: "",
        builder_detached_reason: isCustom ? "" : "Independent Part created by cloning a Part Group.",
        builder_detached_snapshot: {},
        reattach_candidate_id: "",
        reattach_candidate_name: "",
        last_price_check_at: timestamp,
        last_price_update_at: timestamp,
        is_active: true,
        notes: `${sourcePart.notes ? `${sourcePart.notes}\n` : ""}Cloned with Part Group “${group.group_name || "Part Group"}”.`,
      },
    };
  });

  const addedFrozen = sourceParts.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0);
  const addedCurrent = sourceParts.reduce((sum, part) => sum + num(part.current_extended_cost, num(part.frozen_extended_cost)), 0);
  const previousFrozen = num(builder.frozen_cost);
  const previousCurrent = num(builder.current_recalculated_cost, previousFrozen);
  const nextFrozen = previousFrozen + addedFrozen;
  const nextCurrent = previousCurrent + addedCurrent;
  const nextState = Math.abs(nextCurrent - nextFrozen) > 0.005 ? "changed" : "current";
  const previousCustomer = num(builder.frozen_customer_price, previousFrozen);
  const nextCustomer = previousCustomer + addedFrozen;
  const builderPatch = {
    frozen_cost: nextFrozen,
    frozen_customer_price: nextCustomer,
    current_recalculated_cost: nextCurrent,
    price_state: nextState,
    price_delta: nextCurrent - nextFrozen,
    price_delta_percent: nextFrozen ? ((nextCurrent - nextFrozen) / nextFrozen) * 100 : 0,
    part_count: activePartCount + sourceParts.length,
    group_count: activeGroupCount + 1,
    last_price_check_at: timestamp,
    last_price_update_at: timestamp,
    builder_version: num(builder.builder_version, 1) + 1,
  };
  const linePatch = {
    total_snapshot: nextFrozen,
    live_total_snapshot: nextCurrent,
    customer_price_snapshot: nextCustomer,
    live_customer_price_snapshot: liveCustomerUnitPrice(currentLine) + addedCurrent,
    price_state: nextState,
    last_price_check_at: timestamp,
    last_price_update_at: timestamp,
  };
  const changedParts = sourceParts.map((part, index) => ({
    source_part_id: part.id,
    part_key_ref: partSteps[index].part_key,
    part_name: part.part_name,
    action: "clone_part_group",
    source_group_id: group.id,
    new_group_key_ref: targetGroupKey,
    frozen_extended_cost: num(part.frozen_extended_cost),
  }));
  const pending = {
    key: operationKey,
    kind: "builder_part_group_clone",
    started_at: timestamp,
    estimate_id: estimate.id,
    estimate_line_id: currentLine.line_id || builder.estimate_line_id || "",
    builder_product_id: builder.id,
    builder_updated_date_before: builder.updated_date || "",
    builder_version_before: num(builder.builder_version, 1),
    source_group_id: group.id,
    target_group_key: targetGroupKey,
    target_part_keys: partSteps.map((step) => step.part_key),
    precondition_plan: {
      groups: [{
        id: group.id,
        expected_updated_date: group.updated_date || "",
        expected_patch: { builder_product_id: builder.id, group_key: group.group_key || "" },
      }],
      parts: sourceParts.map((part) => ({
        id: part.id,
        expected_updated_date: part.updated_date || "",
        expected_patch: { builder_product_id: builder.id, part_group_id: group.id, part_key: part.part_key || "" },
      })),
    },
    group_create_plan: { groups: [{ group_key: targetGroupKey, data: groupData }] },
    part_acceptance_plan: {
      timestamp,
      part_updates: partSteps,
      changed_parts: changedParts,
      active_part_count: activePartCount + sourceParts.length,
    },
    builder_patch: builderPatch,
    line_patch: linePatch,
    revision: {
      builder_product_id: builder.id,
      estimate_id: builder.estimate_id || "",
      reason: "manual_adjustment",
      previous_total_cost: previousFrozen,
      new_total_cost: nextFrozen,
      previous_customer_price: previousCustomer,
      new_customer_price: nextCustomer,
      changed_parts: changedParts,
      builder_snapshot_before: builder.builder_snapshot || {},
      builder_snapshot_after: builder.builder_snapshot || {},
      price_snapshot_before: { total: previousFrozen },
      price_snapshot_after: { total: nextFrozen },
      notes: `Cloned Part Group “${group.group_name || "Part Group"}” with ${sourceParts.length} Part${sourceParts.length === 1 ? "" : "s"}. Builder-linked source Parts were copied as independent add-ons so future Builder saves cannot overwrite the clone.`,
    },
  };

  const marked = await markBuilderMutationPending({ estimate, builder, pending });
  const recovered = await resumeBuilderMutation({
    estimateId: estimate.id,
    estimate: marked.markedEstimate,
    builder: marked.currentBuilder,
    parts: marked.currentParts,
    line: marked.markedLine,
    pending: marked.canonicalPending,
    applyPartPlan: applyBuilderPartPriceAcceptancePlan,
  });
  const [groupsAfter, partsAfter] = await Promise.all([
    loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Part Groups" }),
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" }),
  ]);
  const clonedGroup = (groupsAfter || []).find((row) => row.group_key === targetGroupKey) || null;
  const targetPartKeys = new Set(partSteps.map((step) => step.part_key));
  return { group: clonedGroup, parts: (partsAfter || []).filter((part) => targetPartKeys.has(part.part_key)), recovered: true, line: recovered?.line || currentLine };
}

function assertMoveBuilderState(builder, targetPatch, expectedUpdatedAt, label) {
  if (!builder?.id) throw new Error(`${label} could not be verified while recovering the Part Group move.`);
  if (!recoveryPatchDiffers(builder, targetPatch)) return false;
  const expected = String(expectedUpdatedAt || "").trim();
  const current = String(builder.updated_date || "").trim();
  if (expected && current && expected !== current) {
    throw new Error(`${label} changed while the Part Group move was pending. Recovery stopped before overwriting unrelated Product state.`);
  }
  return true;
}

function assertMoveRecordState(record, step, sourceBuilderProductId, label) {
  if (!record?.id) throw new Error(`${label} disappeared while the Part Group move was pending.`);
  if (!recoveryPatchDiffers(record, step.target_patch || {})) return false;
  if (String(record.builder_product_id || "") !== String(sourceBuilderProductId || "")) {
    throw new Error(`${label} changed ownership while the Part Group move was pending.`);
  }
  const expected = String(step.expected_updated_date || "").trim();
  const current = String(record.updated_date || "").trim();
  if (expected && current && expected !== current) {
    throw new Error(`${label} changed while the Part Group move was pending. No unrelated edit was overwritten.`);
  }
  if (step.expected_patch && recoveryPatchDiffers(record, step.expected_patch)) {
    throw new Error(`${label} no longer matches the stored move source. Recovery was stopped.`);
  }
  return true;
}

export async function resumeIndependentPartGroupMove({ estimateId, lineId = "" }) {
  if (!estimateId) throw new Error("Estimate is required to resume a Part Group move.");
  const estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  const sourceLine = lineId
    ? (estimate.line_items || []).find((line) => line.line_id === lineId)
    : (estimate.line_items || []).find((line) => line?.price_acceptance_pending?.kind === "builder_part_group_move");
  const pending = pendingBuilderMutation(sourceLine);
  if (!sourceLine || !pending || pending.kind !== "builder_part_group_move") {
    throw new Error("The pending Part Group move could not be found.");
  }
  if (pending.estimate_id !== estimateId || pending.builder_product_id !== sourceLine.builder_product_id) {
    throw new Error("The Part Group move recovery marker no longer matches its source Product.");
  }
  await assertEstimateProductMutationAllowed(estimate, { allowPriceAcceptanceKey: pending.key });

  const [sourceBuilder, targetBuilder, group, movingParts] = await Promise.all([
    staffEntities.BuilderProduct.get(pending.builder_product_id),
    staffEntities.BuilderProduct.get(pending.target_builder_product_id),
    staffEntities.BuilderPartGroup.get(pending.group_move_step?.id),
    Promise.all((pending.part_move_steps || []).map((step) => staffEntities.BuilderPart.get(step.id))),
  ]);
  if (!sourceBuilder?.id || !targetBuilder?.id || sourceBuilder.estimate_id !== estimateId || targetBuilder.estimate_id !== estimateId) {
    throw new Error("Both Products could not be verified in this estimate while recovering the Part Group move.");
  }

  let sourceBuilderNeedsWrite = assertMoveBuilderState(sourceBuilder, pending.source_builder_patch || {}, pending.source_builder_updated_date_before, "Source Product");
  let targetBuilderNeedsWrite = assertMoveBuilderState(targetBuilder, pending.target_builder_patch || {}, pending.target_builder_updated_date_before, "Target Product");
  const groupNeedsWrite = assertMoveRecordState(group, pending.group_move_step || {}, sourceBuilder.id, `Part Group “${group?.group_name || "Part Group"}”`);
  const partNeedsWrite = movingParts.map((part, index) => assertMoveRecordState(part, pending.part_move_steps[index], sourceBuilder.id, `Part “${part?.part_name || "Part"}”`));

  if (groupNeedsWrite) {
    await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderPartGroup,
      id: group.id,
      expectedUpdatedAt: group.updated_date || "",
      expectedFields: expectedBuilderEntityFields(group, pending.group_move_step.target_patch),
      nextFields: pending.group_move_step.target_patch,
      guardFields: { builder_product_id: sourceBuilder.id },
      label: `Part Group “${group.group_name || "Part Group"}” move`,
    });
  }
  for (let index = 0; index < movingParts.length; index += 1) {
    if (!partNeedsWrite[index]) continue;
    const part = movingParts[index];
    const targetPatch = pending.part_move_steps[index].target_patch;
    await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderPart,
      id: part.id,
      expectedUpdatedAt: part.updated_date || "",
      expectedFields: expectedBuilderEntityFields(part, targetPatch),
      nextFields: targetPatch,
      guardFields: { builder_product_id: sourceBuilder.id },
      label: `Part “${part.part_name || "Part"}” move`,
    });
  }

  const [sourceBeforePriceWrite, targetBeforePriceWrite] = await Promise.all([
    staffEntities.BuilderProduct.get(sourceBuilder.id),
    staffEntities.BuilderProduct.get(targetBuilder.id),
  ]);
  sourceBuilderNeedsWrite = assertMoveBuilderState(sourceBeforePriceWrite, pending.source_builder_patch || {}, pending.source_builder_updated_date_before, "Source Product");
  targetBuilderNeedsWrite = assertMoveBuilderState(targetBeforePriceWrite, pending.target_builder_patch || {}, pending.target_builder_updated_date_before, "Target Product");
  if (sourceBuilderNeedsWrite) {
    await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderProduct,
      id: sourceBuilder.id,
      expectedUpdatedAt: sourceBeforePriceWrite.updated_date || "",
      expectedFields: expectedBuilderEntityFields(sourceBeforePriceWrite, pending.source_builder_patch),
      nextFields: pending.source_builder_patch,
      guardFields: { estimate_id: estimateId },
      label: "Source Product Part Group move totals",
    });
  }
  if (targetBuilderNeedsWrite) {
    await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderProduct,
      id: targetBuilder.id,
      expectedUpdatedAt: targetBeforePriceWrite.updated_date || "",
      expectedFields: expectedBuilderEntityFields(targetBeforePriceWrite, pending.target_builder_patch),
      nextFields: pending.target_builder_patch,
      guardFields: { estimate_id: estimateId },
      label: "Target Product Part Group move totals",
    });
  }

  await ensureBuilderPriceRevision(pending.source_revision_key || `${pending.key}:source`, pending.source_revision || {});
  await ensureBuilderPriceRevision(pending.target_revision_key || `${pending.key}:target`, pending.target_revision || {});

  const latestEstimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!latestEstimate) throw new Error("Estimate could not be verified while completing the Part Group move.");
  const latestSourceLine = (latestEstimate.line_items || []).find((line) => line.builder_product_id === sourceBuilder.id);
  const latestTargetLine = (latestEstimate.line_items || []).find((line) => line.builder_product_id === targetBuilder.id);
  if (!latestSourceLine || !latestTargetLine) throw new Error("Both Product lines must remain on the estimate while completing the Part Group move.");
  const latestPending = pendingBuilderMutation(latestSourceLine);
  if (!latestPending) {
    if (!recoveryPatchDiffers(latestSourceLine, pending.source_line_patch || {}) && !recoveryPatchDiffers(latestTargetLine, pending.target_line_patch || {})) {
      return { recovered: true, alreadyCompleted: true, groupId: pending.group_move_step?.id, movedParts: (pending.part_move_steps || []).length };
    }
    throw new Error("The Part Group move marker disappeared before both Product line targets could be verified.");
  }
  if (latestPending.key !== pending.key) throw new Error("A different Builder mutation is now active on the source Product.");
  await assertEstimateProductMutationAllowed(latestEstimate, { allowPriceAcceptanceKey: pending.key });
  const lineItems = (latestEstimate.line_items || []).map((line) => {
    if (line.builder_product_id === sourceBuilder.id) return { ...line, ...(pending.source_line_patch || {}), price_acceptance_pending: {} };
    if (line.builder_product_id === targetBuilder.id) return { ...line, ...(pending.target_line_patch || {}) };
    return line;
  });
  await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId,
    expectedFields: expectedEstimateFields(latestEstimate, { line_items: lineItems }),
    nextFields: { line_items: lineItems },
    label: "Part Group move Estimate line completion",
  });
  return { recovered: true, groupId: pending.group_move_step?.id, movedParts: (pending.part_move_steps || []).length, sourceBuilderProductId: sourceBuilder.id, targetBuilderProductId: targetBuilder.id };
}

export async function moveIndependentPartGroup({ sourceBuilderProductId, targetBuilderProductId, groupId, expectedEstimateUpdatedAt = "", expectedGroupUpdatedAt = "", expectedPartVersions = {} }) {
  if (!sourceBuilderProductId || !targetBuilderProductId || !groupId) throw new Error("Source Product, target Product and Part Group are required.");
  if (sourceBuilderProductId === targetBuilderProductId) throw new Error("Choose a different target Product.");

  const [sourceBuilder, targetBuilder] = await Promise.all([
    staffEntities.BuilderProduct.get(sourceBuilderProductId),
    staffEntities.BuilderProduct.get(targetBuilderProductId),
  ]);
  if (!sourceBuilder?.id || !targetBuilder?.id || !sourceBuilder.estimate_id || sourceBuilder.estimate_id !== targetBuilder.estimate_id) {
    throw new Error("Direct Move is only available between Products in the same estimate. Use Copy/Paste for another estimate.");
  }
  const estimate = await staffEntities.AllInOneEstimate.get(sourceBuilder.estimate_id);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  const sourceLine = estimateLine(estimate, sourceBuilder.id);
  const targetLine = estimateLine(estimate, targetBuilder.id);
  if (!sourceLine || !targetLine) throw new Error("Both Products must still belong to this estimate. Reload before moving the Part Group.");

  const operationKey = `builder_part_group_move:${builderMutationHash({
    estimate_id: estimate.id,
    source_builder_product_id: sourceBuilder.id,
    target_builder_product_id: targetBuilder.id,
    group_id: groupId,
    expected_estimate_updated_at: expectedEstimateUpdatedAt || "",
    expected_group_updated_at: expectedGroupUpdatedAt || "",
    expected_part_versions: expectedPartVersions || {},
  })}`;
  const existingPending = pendingBuilderMutation(sourceLine);
  if (existingPending) {
    if (existingPending.kind !== "builder_part_group_move" || existingPending.key !== operationKey || existingPending.target_builder_product_id !== targetBuilder.id) {
      throw new Error("Another Builder mutation is still being recovered for the source Product. Resume it before moving this Part Group.");
    }
    return resumeIndependentPartGroupMove({ estimateId: estimate.id, lineId: sourceLine.line_id || "" });
  }

  const [group, sourceParts, sourceGroups, targetParts, targetGroups, sourceRevisions, targetRevisions] = await Promise.all([
    staffEntities.BuilderPartGroup.get(groupId),
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: sourceBuilder.id }, sort: "sort_order", label: "Source Builder Parts" }),
    loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: sourceBuilder.id }, sort: "sort_order", label: "Source Builder Part Groups" }),
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: targetBuilder.id }, sort: "sort_order", label: "Target Builder Parts" }),
    loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: targetBuilder.id }, sort: "sort_order", label: "Target Builder Part Groups" }),
    loadAllEntityRows({ entity: base44.entities.BuilderPriceRevision, query: { builder_product_id: sourceBuilder.id }, sort: "revision_number", label: "Source Builder price revisions" }),
    loadAllEntityRows({ entity: base44.entities.BuilderPriceRevision, query: { builder_product_id: targetBuilder.id }, sort: "revision_number", label: "Target Builder price revisions" }),
  ]);
  if (![sourceParts, sourceGroups, targetParts, targetGroups, sourceRevisions, targetRevisions].every(Array.isArray)) {
    throw new Error("Part Group move prerequisites could not be fully verified.");
  }

  const sourceRevisionKey = `${operationKey}:source`;
  const targetRevisionKey = `${operationKey}:target`;
  const completedSource = sourceRevisions.find((row) => row.idempotency_key === sourceRevisionKey);
  const completedTarget = targetRevisions.find((row) => row.idempotency_key === targetRevisionKey);
  if (completedSource || completedTarget) {
    if (!completedSource || !completedTarget) throw new Error("Only one side of the Part Group move audit exists. Recovery cannot be inferred without its durable marker.");
    const targetGroupKey = `move-group-${builderMutationHash({ operation_key: operationKey, group_id: groupId })}`;
    const movedIds = new Set((completedSource.changed_parts || []).map((part) => part.part_id));
    const movedParts = targetParts.filter((part) => movedIds.has(part.id));
    const complete = group?.builder_product_id === targetBuilder.id && group?.group_key === targetGroupKey && movedParts.length === movedIds.size &&
      !recoveryPatchDiffers(sourceBuilder, { frozen_cost: completedSource.new_total_cost, frozen_customer_price: completedSource.new_customer_price }) &&
      !recoveryPatchDiffers(targetBuilder, { frozen_cost: completedTarget.new_total_cost, frozen_customer_price: completedTarget.new_customer_price }) &&
      !recoveryPatchDiffers(sourceLine, { total_snapshot: completedSource.new_total_cost, customer_price_snapshot: completedSource.new_customer_price }) &&
      !recoveryPatchDiffers(targetLine, { total_snapshot: completedTarget.new_total_cost, customer_price_snapshot: completedTarget.new_customer_price });
    if (complete) return { groupId, movedParts: movedParts.length, sourceBuilderProductId, targetBuilderProductId, alreadyCompleted: true };
    throw new Error("The Part Group move audits exist, but the two Products no longer match the completed move target. Reload and review both Products.");
  }

  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });
  if (!group || group.builder_product_id !== sourceBuilder.id) throw new Error("Part Group could not be loaded from the source Product.");
  assertVersion(group, expectedGroupUpdatedAt, "Part Group");
  const movingParts = sourceParts.filter((part) => part.is_active !== false && part.part_group_id === groupId).sort((a, b) => num(a.sort_order) - num(b.sort_order));
  if (!movingParts.length) throw new Error("This Part Group does not contain any active Parts.");
  assertMemberVersions(movingParts, expectedPartVersions);
  if (movingParts.some((part) => !["manual", "manual_addon"].includes(part.builder_sync_state))) {
    throw new Error("This Part Group contains Builder-owned Parts and cannot be moved directly. Use Clone or Copy instead so the source Builder remains internally consistent.");
  }

  const timestamp = nowIso();
  const movedFrozen = movingParts.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0);
  const movedCurrent = movingParts.reduce((sum, part) => sum + num(part.current_extended_cost, num(part.frozen_extended_cost)), 0);
  const sourcePreviousFrozen = num(sourceBuilder.frozen_cost);
  const sourcePreviousCurrent = num(sourceBuilder.current_recalculated_cost, sourcePreviousFrozen);
  const targetPreviousFrozen = num(targetBuilder.frozen_cost);
  const targetPreviousCurrent = num(targetBuilder.current_recalculated_cost, targetPreviousFrozen);
  const sourceNextFrozen = Math.max(0, sourcePreviousFrozen - movedFrozen);
  const sourceNextCurrent = Math.max(0, sourcePreviousCurrent - movedCurrent);
  const targetNextFrozen = targetPreviousFrozen + movedFrozen;
  const targetNextCurrent = targetPreviousCurrent + movedCurrent;
  const sourcePreviousCustomer = num(sourceBuilder.frozen_customer_price, sourcePreviousFrozen);
  const targetPreviousCustomer = num(targetBuilder.frozen_customer_price, targetPreviousFrozen);
  const sourceNextCustomer = Math.max(0, sourcePreviousCustomer - movedFrozen);
  const targetNextCustomer = targetPreviousCustomer + movedFrozen;
  const targetSyncState = targetBuilder.module_key === "custom" ? "manual" : "manual_addon";
  const targetActivePartCount = targetParts.filter((part) => part.is_active !== false).length;
  const sourceActivePartCount = sourceParts.filter((part) => part.is_active !== false).length;
  const sourceActiveGroupCount = sourceGroups.filter((row) => row.is_active !== false).length;
  const targetActiveGroupCount = targetGroups.filter((row) => row.is_active !== false).length;
  const targetGroupKey = `move-group-${builderMutationHash({ operation_key: operationKey, group_id: group.id })}`;
  const groupTargetPatch = { builder_product_id: targetBuilder.id, group_key: targetGroupKey, sort_order: targetActiveGroupCount, is_collapsed: false };
  const partMoveSteps = movingParts.map((part, index) => ({
    id: part.id,
    expected_updated_date: part.updated_date || "",
    expected_patch: { builder_product_id: sourceBuilder.id, part_group_id: group.id, part_key: part.part_key || "" },
    target_patch: {
      builder_product_id: targetBuilder.id,
      source_module_key: targetBuilder.module_key || "custom",
      source_path: "",
      builder_sync_state: targetSyncState,
      builder_detached_at: "",
      builder_detached_reason: targetSyncState === "manual_addon" ? "Independent Part moved from another Product." : "",
      builder_detached_snapshot: {},
      reattach_candidate_id: "",
      reattach_candidate_name: "",
      sort_order: targetActivePartCount + index,
      last_price_check_at: timestamp,
      last_price_update_at: timestamp,
      is_active: true,
    },
  }));
  const sourceState = sourceBuilder.needs_reattach_review ? "detached_parts" : Math.abs(sourceNextCurrent - sourceNextFrozen) > 0.005 ? "changed" : "current";
  const targetState = targetBuilder.needs_reattach_review ? "detached_parts" : Math.abs(targetNextCurrent - targetNextFrozen) > 0.005 ? "changed" : "current";
  const sourceBuilderPatch = { frozen_cost: sourceNextFrozen, frozen_customer_price: sourceNextCustomer, current_recalculated_cost: sourceNextCurrent, price_state: sourceState, price_delta: sourceNextCurrent - sourceNextFrozen, price_delta_percent: sourceNextFrozen ? ((sourceNextCurrent - sourceNextFrozen) / sourceNextFrozen) * 100 : 0, part_count: Math.max(0, sourceActivePartCount - movingParts.length), group_count: Math.max(0, sourceActiveGroupCount - 1), last_price_check_at: timestamp, last_price_update_at: timestamp, builder_version: num(sourceBuilder.builder_version, 1) + 1 };
  const targetBuilderPatch = { frozen_cost: targetNextFrozen, frozen_customer_price: targetNextCustomer, current_recalculated_cost: targetNextCurrent, price_state: targetState, price_delta: targetNextCurrent - targetNextFrozen, price_delta_percent: targetNextFrozen ? ((targetNextCurrent - targetNextFrozen) / targetNextFrozen) * 100 : 0, part_count: targetActivePartCount + movingParts.length, group_count: targetActiveGroupCount + 1, last_price_check_at: timestamp, last_price_update_at: timestamp, builder_version: num(targetBuilder.builder_version, 1) + 1 };
  const sourceLinePatch = { total_snapshot: sourceNextFrozen, live_total_snapshot: sourceNextCurrent, customer_price_snapshot: sourceNextCustomer, live_customer_price_snapshot: Math.max(0, liveCustomerUnitPrice(sourceLine) - movedCurrent), price_state: sourceState, last_price_check_at: timestamp, last_price_update_at: timestamp };
  const targetLinePatch = { total_snapshot: targetNextFrozen, live_total_snapshot: targetNextCurrent, customer_price_snapshot: targetNextCustomer, live_customer_price_snapshot: liveCustomerUnitPrice(targetLine) + movedCurrent, price_state: targetState, last_price_check_at: timestamp, last_price_update_at: timestamp };
  const sourceChangedParts = movingParts.map((part) => ({ part_id: part.id, part_name: part.part_name, action: "move_part_group_out", group_id: group.id, target_builder_product_id: targetBuilder.id, frozen_extended_cost: num(part.frozen_extended_cost) }));
  const targetChangedParts = movingParts.map((part) => ({ part_id: part.id, part_name: part.part_name, action: "move_part_group_in", group_id: group.id, source_builder_product_id: sourceBuilder.id, frozen_extended_cost: num(part.frozen_extended_cost) }));
  const pending = {
    key: operationKey,
    kind: "builder_part_group_move",
    started_at: timestamp,
    estimate_id: estimate.id,
    estimate_line_id: sourceLine.line_id || sourceBuilder.estimate_line_id || "",
    builder_product_id: sourceBuilder.id,
    target_builder_product_id: targetBuilder.id,
    source_builder_updated_date_before: sourceBuilder.updated_date || "",
    target_builder_updated_date_before: targetBuilder.updated_date || "",
    group_move_step: { id: group.id, expected_updated_date: group.updated_date || "", expected_patch: { builder_product_id: sourceBuilder.id, group_key: group.group_key || "" }, target_patch: groupTargetPatch },
    part_move_steps: partMoveSteps,
    source_builder_patch: sourceBuilderPatch,
    target_builder_patch: targetBuilderPatch,
    source_line_patch: sourceLinePatch,
    target_line_patch: targetLinePatch,
    source_revision_key: sourceRevisionKey,
    target_revision_key: targetRevisionKey,
    source_revision: { builder_product_id: sourceBuilder.id, estimate_id: estimate.id, reason: "manual_adjustment", previous_total_cost: sourcePreviousFrozen, new_total_cost: sourceNextFrozen, previous_customer_price: sourcePreviousCustomer, new_customer_price: sourceNextCustomer, changed_parts: sourceChangedParts, builder_snapshot_before: sourceBuilder.builder_snapshot || {}, builder_snapshot_after: sourceBuilder.builder_snapshot || {}, price_snapshot_before: { total: sourcePreviousFrozen }, price_snapshot_after: { total: sourceNextFrozen }, notes: `Moved Part Group “${group.group_name || "Part Group"}” to Product “${targetBuilder.client_product_name || targetBuilder.builder_name || "Product"}”.` },
    target_revision: { builder_product_id: targetBuilder.id, estimate_id: estimate.id, reason: "manual_adjustment", previous_total_cost: targetPreviousFrozen, new_total_cost: targetNextFrozen, previous_customer_price: targetPreviousCustomer, new_customer_price: targetNextCustomer, changed_parts: targetChangedParts, builder_snapshot_before: targetBuilder.builder_snapshot || {}, builder_snapshot_after: targetBuilder.builder_snapshot || {}, price_snapshot_before: { total: targetPreviousFrozen }, price_snapshot_after: { total: targetNextFrozen }, notes: `Received Part Group “${group.group_name || "Part Group"}” from Product “${sourceBuilder.client_product_name || sourceBuilder.builder_name || "Product"}”.` },
  };
  await markBuilderMutationPending({ estimate, builder: sourceBuilder, pending });
  return resumeIndependentPartGroupMove({ estimateId: estimate.id, lineId: sourceLine.line_id || "" });
}

import { base44 } from "@/api/base44Client";
import { stripEntitySystemFields } from "@/components/estimator/products/snapshotUtils";
import { liveCustomerUnitPrice } from "@/components/estimator/customerPricing";
import { assertEstimateProductMutationAllowed } from "@/components/estimator/estimateMutationGuard";
import { applyBuilderPartPriceAcceptancePlan } from "@/components/estimator/builder/partSync";
import { builderMutationHash, markBuilderMutationPending, pendingBuilderMutation, resumeBuilderMutation } from "@/components/estimator/builder/builderMutationRecovery";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { staffEntities } from "@/components/staff/staffEntities";

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
const nowIso = () => new Date().toISOString();

function getEstimateLine(estimate, builderProductId) {
  return (estimate?.line_items || []).find((line) => line.builder_product_id === builderProductId) || null;
}

function packageResult({ parts, groups, partKeys, groupKey, line, recovered = false, alreadyCompleted = false }) {
  return {
    parts: (parts || []).filter((part) => partKeys.includes(part.part_key)),
    group: groupKey ? (groups || []).find((group) => group.group_key === groupKey) || null : null,
    line,
    recovered,
    alreadyCompleted,
  };
}

export async function addPartPackageToProduct({
  estimateId,
  targetBuilderProductId,
  itemType,
  itemName,
  payload,
  sourceType = "library",
  sourceId = "",
  sourceTemplate = null,
  expectedEstimateUpdatedAt = "",
}) {
  if (!estimateId || !targetBuilderProductId) throw new Error("Estimate and target Product are required.");
  if (!["part", "part_group"].includes(itemType)) throw new Error("A Part or Part Group package is required.");

  const [estimate, builder] = await Promise.all([
    staffEntities.AllInOneEstimate.get(estimateId),
    staffEntities.BuilderProduct.get(targetBuilderProductId),
  ]);
  if (!estimate || !builder) throw new Error("Target Product could not be loaded.");
  if (builder.estimate_id && builder.estimate_id !== estimateId) {
    throw new Error("This Product no longer belongs to the target estimate. Reload before adding saved Parts.");
  }
  const targetLine = getEstimateLine(estimate, targetBuilderProductId);
  if (!targetLine) throw new Error("Target Product is not part of this estimate.");

  const existingPending = pendingBuilderMutation(targetLine);
  if (existingPending) {
    if (
      existingPending.kind !== "builder_part_package_add" ||
      String(existingPending.builder_product_id || "") !== String(builder.id) ||
      (existingPending.source_type && existingPending.source_type !== sourceType) ||
      (existingPending.source_id && sourceId && existingPending.source_id !== sourceId)
    ) {
      throw new Error("Another Builder mutation is still being recovered for this Product. Resume that operation before adding saved Parts.");
    }
    const parts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Saved Part insertion Parts" });
    if (!Array.isArray(parts)) throw new Error("Builder Parts could not be verified while resuming the saved Part insertion.");
    const result = await resumeBuilderMutation({
      estimateId,
      estimate,
      builder,
      parts,
      line: targetLine,
      pending: existingPending,
      applyPartPlan: applyBuilderPartPriceAcceptancePlan,
    });
    const [completedParts, completedGroups] = await Promise.all([
      loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Saved Part insertion Parts" }),
      loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Saved Part insertion Part Groups" }),
    ]);
    return packageResult({
      parts: completedParts,
      groups: completedGroups,
      partKeys: existingPending.target_part_keys || [],
      groupKey: existingPending.target_group_key || "",
      line: result.line,
      recovered: true,
    });
  }

  const isCustom = targetLine.module_key === "custom";
  const payloadParts = itemType === "part_group" ? (payload?.parts || []) : [payload?.part].filter(Boolean);
  if (!payloadParts.length) throw new Error("This saved package does not contain any Parts.");

  const fingerprintPayload = {
    group: itemType === "part_group" ? stripEntitySystemFields(payload?.group || {}) : null,
    parts: payloadParts.map((part) => stripEntitySystemFields(part || {})),
  };
  const requestHash = builderMutationHash({
    builder_product_id: builder.id,
    expected_estimate_updated_at: expectedEstimateUpdatedAt || estimate.updated_date || "",
    item_type: itemType,
    source_type: sourceType,
    source_id: sourceId,
    payload: fingerprintPayload,
  });
  const operationKey = `builder_part_package_add:${builder.id}:${requestHash}`;
  const partKeys = payloadParts.map((_, index) => `package-part-${requestHash}-${index}`);
  const groupKey = itemType === "part_group" ? `package-group-${requestHash}` : "";

  // If the final Estimate write succeeded but its response was lost, the durable
  // marker is already gone. Reuse the idempotent revision + deterministic keys
  // so the same browser action resolves as completed instead of inserting again.
  const revisions = await loadAllEntityRows({ entity: base44.entities.BuilderPriceRevision, query: { builder_product_id: builder.id }, sort: "revision_number", label: "Saved Part insertion price revisions" });
  const completedRevision = (revisions || []).find((revision) => String(revision.idempotency_key || "") === operationKey);
  if (completedRevision) {
    const [completedParts, completedGroups] = await Promise.all([
      loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Saved Part insertion Parts" }),
      loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Saved Part insertion Part Groups" }),
    ]);
    const completePartCount = (completedParts || []).filter((part) => partKeys.includes(part.part_key)).length;
    const completeGroup = !groupKey || (completedGroups || []).some((group) => group.group_key === groupKey);
    if (completePartCount !== partKeys.length || !completeGroup) {
      throw new Error("The saved Part insertion audit exists, but its inserted records could not be fully verified. Reload before continuing.");
    }
    return packageResult({
      parts: completedParts,
      groups: completedGroups,
      partKeys,
      groupKey,
      line: targetLine,
      alreadyCompleted: true,
    });
  }

  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });

  const timestamp = nowIso();
  const [activeParts, activeGroups] = await Promise.all([
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Saved Part insertion Parts" }),
    loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Saved Part insertion Part Groups" }),
  ]);
  if (!Array.isArray(activeParts) || activeParts.some((part) => part?.builder_product_id !== builder.id)) {
    throw new Error("Builder Parts could not be verified before adding the saved package.");
  }
  if (!Array.isArray(activeGroups) || activeGroups.some((group) => group?.builder_product_id !== builder.id)) {
    throw new Error("Part Groups could not be verified before adding the saved package.");
  }
  const targetPartCount = activeParts.filter((part) => part.is_active !== false).length;
  const targetGroupCount = activeGroups.filter((group) => group.is_active !== false).length;

  let groupData = null;
  if (itemType === "part_group") {
    const group = payload?.group || {};
    groupData = stripEntitySystemFields(group);
    delete groupData.snapshot_source_group_id;
    groupData = {
      ...groupData,
      builder_product_id: builder.id,
      group_key: groupKey,
      group_name: group.group_name || itemName || "Part Group",
      parent_group_id: "",
      sort_order: targetGroupCount,
      is_collapsed: false,
      is_active: true,
    };
  }

  const sourceLabel = sourceType === "clipboard" ? "estimator clipboard" : "Part Library";
  const targetSyncState = isCustom ? "manual" : "manual_addon";
  const plannedParts = payloadParts.map((sourcePart, index) => {
    const partData = stripEntitySystemFields(sourcePart);
    const missingInventory = ["detached", "reattach_available"].includes(sourcePart.inventory_link_state);
    const frozenExtended = num(sourcePart.frozen_extended_cost);
    const currentExtended = num(sourcePart.current_extended_cost, frozenExtended);
    const normalizedPriceState = missingInventory
      ? "detached"
      : sourcePart.manual_cost_override || sourcePart.price_state === "manual"
        ? "manual"
        : Math.abs(currentExtended - frozenExtended) > 0.005 ? "changed" : "current";
    return {
      ...partData,
      builder_product_id: builder.id,
      part_group_id: "",
      part_key: partKeys[index],
      sort_order: targetPartCount + index,
      source_module_key: isCustom ? "custom" : targetLine.module_key,
      source_path: "",
      builder_sync_state: targetSyncState,
      builder_detached_at: "",
      builder_detached_reason: targetSyncState === "manual_addon" ? `Independent Part added from ${sourceLabel}.` : "",
      builder_detached_snapshot: {},
      inventory_link_state: sourcePart.inventory_link_state === "reattach_available" ? "detached" : (sourcePart.inventory_link_state || "manual"),
      reattach_candidate_id: "",
      reattach_candidate_name: "",
      price_state: normalizedPriceState,
      price_delta: currentExtended - frozenExtended,
      price_delta_percent: frozenExtended ? ((currentExtended - frozenExtended) / frozenExtended) * 100 : 0,
      last_price_check_at: timestamp,
      last_price_update_at: timestamp,
      is_active: true,
      ...(sourceType === "library" && sourceTemplate?.id ? {
        source_template_id: String(sourceTemplate.id),
        source_template_name: String(sourceTemplate.name || ""),
        source_template_version: Math.max(1, Number(sourceTemplate.version) || 1),
      } : {}),
    };
  });

  const addedFrozen = plannedParts.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0);
  const addedCurrent = plannedParts.reduce((sum, part) => sum + num(part.current_extended_cost, num(part.frozen_extended_cost)), 0);
  const previousFrozen = num(builder.frozen_cost, num(targetLine.total_snapshot));
  const previousCurrent = num(builder.current_recalculated_cost, num(targetLine.live_total_snapshot, previousFrozen));
  const previousCustomer = num(builder.frozen_customer_price, previousFrozen);
  const nextFrozen = previousFrozen + addedFrozen;
  const nextCurrent = previousCurrent + addedCurrent;
  const nextCustomer = previousCustomer + addedFrozen;
  const insertedDetachedCount = plannedParts.filter((part) => ["detached", "reattach_available"].includes(part.inventory_link_state) || part.price_state === "detached").length;
  const nextDetachedCount = num(builder.detached_part_count) + insertedDetachedCount;
  const nextNeedsReattachReview = !!builder.needs_reattach_review || insertedDetachedCount > 0;
  const nextState = nextNeedsReattachReview
    ? "detached_parts"
    : Math.abs(nextCurrent - nextFrozen) > 0.005 ? "changed" : "current";

  const builderPatch = {
    frozen_cost: nextFrozen,
    frozen_customer_price: nextCustomer,
    current_recalculated_cost: nextCurrent,
    price_state: nextState,
    price_delta: nextCurrent - nextFrozen,
    price_delta_percent: nextFrozen ? ((nextCurrent - nextFrozen) / nextFrozen) * 100 : 0,
    part_count: targetPartCount + plannedParts.length,
    group_count: targetGroupCount + (groupData ? 1 : 0),
    detached_part_count: nextDetachedCount,
    needs_reattach_review: nextNeedsReattachReview,
    last_price_check_at: timestamp,
    last_price_update_at: timestamp,
    builder_version: num(builder.builder_version, 1) + 1,
  };
  const linePatch = {
    total_snapshot: nextFrozen,
    live_total_snapshot: nextCurrent,
    customer_price_snapshot: nextCustomer,
    live_customer_price_snapshot: liveCustomerUnitPrice(targetLine) + addedCurrent,
    price_state: nextState,
    detached_part_count: nextDetachedCount,
    needs_reattach_review: nextNeedsReattachReview,
    last_price_check_at: timestamp,
    last_price_update_at: timestamp,
  };

  const auditSourceLabel = sourceType === "clipboard" ? "30-day estimator clipboard" : "Part Library";
  const sourceField = sourceType === "clipboard" ? "source_clipboard_id" : "source_part_template_id";
  const actionPrefix = sourceType === "clipboard" ? "paste" : "add_saved";
  const changedParts = plannedParts.map((part) => ({
    part_key: part.part_key,
    part_name: part.part_name,
    action: `${actionPrefix}_${itemType}`,
    frozen_extended_cost: num(part.frozen_extended_cost),
    [sourceField]: sourceId,
  }));

  const recoveryMarker = {
    key: operationKey,
    kind: "builder_part_package_add",
    started_at: timestamp,
    estimate_id: estimateId,
    estimate_line_id: targetLine.line_id || builder.estimate_line_id || "",
    builder_product_id: builder.id,
    builder_updated_date_before: builder.updated_date || "",
    builder_version_before: num(builder.builder_version, 1),
    source_type: sourceType,
    source_id: sourceId,
    item_type: itemType,
    target_part_keys: partKeys,
    target_group_key: groupKey,
    group_create_plan: groupData ? { groups: [{ group_key: groupKey, data: groupData }] } : { groups: [] },
    part_acceptance_plan: {
      timestamp,
      part_updates: plannedParts.map((part) => ({
        operation: "create",
        part_key: part.part_key,
        part_group_key_ref: groupKey,
        data: part,
      })),
      changed_parts: changedParts,
      active_part_count: targetPartCount + plannedParts.length,
    },
    builder_patch: builderPatch,
    line_patch: linePatch,
    revision: {
      builder_product_id: builder.id,
      estimate_id: estimateId,
      reason: "manual_adjustment",
      previous_total_cost: previousFrozen,
      new_total_cost: nextFrozen,
      previous_customer_price: previousCustomer,
      new_customer_price: nextCustomer,
      changed_parts: changedParts,
      builder_snapshot_before: builder.builder_snapshot || {},
      builder_snapshot_after: builder.builder_snapshot || {},
      price_snapshot_before: { total: previousFrozen },
      price_snapshot_after: { total: nextFrozen },
      notes: `${sourceType === "clipboard" ? "Pasted" : "Added"} ${itemType.replace("_", " ")} “${itemName || "Saved Part"}” from the ${auditSourceLabel}.`,
    },
  };

  const marked = await markBuilderMutationPending({ estimate, builder, pending: recoveryMarker });
  const result = await resumeBuilderMutation({
    estimateId,
    estimate: marked.markedEstimate,
    builder: marked.currentBuilder,
    parts: marked.currentParts,
    line: marked.markedLine,
    pending: marked.canonicalPending,
    applyPartPlan: applyBuilderPartPriceAcceptancePlan,
  });

  const [completedParts, completedGroups] = await Promise.all([
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Saved Part insertion Parts" }),
    loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Saved Part insertion Part Groups" }),
  ]);
  return packageResult({
    parts: completedParts,
    groups: completedGroups,
    partKeys,
    groupKey,
    line: result.line,
  });
}

export function requiresBuilderReattach(part) {
  if (!part || part.is_active === false) return false;
  if (part.builder_sync_state === "detached_override") return true;
  if (part.builder_sync_state === "manual_addon") return false;
  return ["detached", "reattach_available"].includes(part.inventory_link_state);
}

export function countBuilderReattachParts(parts = []) {
  return (parts || []).filter(requiresBuilderReattach).length;
}

import { base44 } from "@/api/base44Client";
import { cloneSnapshot } from "@/components/estimator/products/snapshotUtils";
import { addPartPackageToProduct } from "@/components/estimator/parts/partPackageService";
import { builderMutationHash } from "@/components/estimator/builder/builderMutationRecovery";
import { ensureReusableRecord } from "@/components/estimator/products/reusableSaveIdempotency";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { staffEntities } from "@/components/staff/staffEntities";

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
const detached = (part) => part?.builder_sync_state === "detached_override" || ["detached", "reattach_available"].includes(part?.inventory_link_state) || part?.price_state === "detached";

function normalizeOptions(options = {}) {
  const tags = [...new Set((options.tags || []).map((value) => String(value || "").trim()).filter(Boolean))];
  return {
    template_name: String(options.template_name || "Saved Part").trim() || "Saved Part",
    product_group: options.product_group === "global" ? "global" : "my",
    category: String(options.category || "").trim(),
    tags,
    description: String(options.description || ""),
    notes: String(options.notes || ""),
  };
}

function searchText(values) {
  return values.flat().filter(Boolean).join(" ").toLowerCase();
}

function templateFamilyKey({ templateType, sourceId, meta }) {
  return `part-template-family:${builderMutationHash({
    template_type: templateType,
    source_id: String(sourceId || ""),
    product_group: meta.product_group,
    template_name: String(meta.template_name || "").trim().toLowerCase(),
  })}`;
}

async function resolveTemplateVersion({ familyKey, idempotencyKey }) {
  const rows = await loadAllEntityRows({
    entity: staffEntities.PartTemplate,
    query: { template_family_key: familyKey },
    sort: "created_date",
    label: "Part Template versions",
  });
  if (!Array.isArray(rows)) throw new Error("Part Template version history could not be verified. Retry the save before overwriting anything.");
  const existing = rows.find((row) => String(row?.idempotency_key || "") === idempotencyKey);
  if (existing) return Math.max(1, Number(existing.template_version) || 1);
  const versions = rows.map((row) => Number(row?.template_version)).filter((v) => Number.isInteger(v) && v >= 1);
  return versions.length ? Math.max(...versions) + 1 : 1;
}

export async function savePartTemplate({ estimateId = "", builderProductId = "", part, options = {} }) {
  if (!part?.id) throw new Error("Part is required.");
  const livePart = await staffEntities.BuilderPart.get(part.id);
  if (!livePart) throw new Error("This Part no longer exists. Reload the Product before saving it to the Part Library.");
  if (part.updated_date && livePart.updated_date && part.updated_date !== livePart.updated_date) {
    throw new Error("This Part changed in another session. Reload the Product and review the latest Part before saving it to the Part Library.");
  }
  const meta = normalizeOptions({ template_name: livePart.client_label || livePart.part_name || "Saved Part", ...options });
  const idempotencyKey = `part_template_save:${builderMutationHash({
    template_type: "part",
    part_id: livePart.id,
    part_updated_date: livePart.updated_date || "",
    estimate_id: estimateId || "",
    builder_product_id: builderProductId || livePart.builder_product_id || "",
    meta,
  })}`;
  const familyKey = templateFamilyKey({ templateType: "part", sourceId: livePart.id, meta });
  const templateVersion = await resolveTemplateVersion({ familyKey, idempotencyKey });
  return ensureReusableRecord({
    entity: staffEntities.PartTemplate,
    idempotencyKey,
    label: "Saved Part",
    data: {
    ...meta,
    template_family_key: familyKey,
    template_version: templateVersion,
    template_type: "part",
    source_module_key: livePart.source_module_key || "",
    source_part_type: livePart.part_type || "",
    source_part_subtype: livePart.part_subtype || "",
    created_from_estimate_id: estimateId,
    created_from_product_id: builderProductId || livePart.builder_product_id || "",
    created_from_part_id: livePart.id,
    created_from_part_group_id: livePart.part_group_id || "",
    part_snapshot: cloneSnapshot(livePart),
    group_snapshot: {},
    parts_snapshot: [],
    part_count: 1,
    frozen_cost: num(livePart.frozen_extended_cost),
    current_cost: num(livePart.current_extended_cost, num(livePart.frozen_extended_cost)),
    contains_detached_parts: detached(livePart),
    search_text: searchText([meta.template_name, meta.category, meta.tags, livePart.part_name, livePart.client_label, livePart.part_type, livePart.part_subtype, livePart.inventory_item_name, livePart.source_module_key]),
    is_active: true,
    },
  });
}

export async function savePartGroupTemplate({ estimateId = "", builderProductId = "", group, parts = [], options = {} }) {
  if (!group?.id) throw new Error("Part Group is required.");
  const loadedActiveParts = (parts || []).filter((part) => part.is_active !== false).sort((a, b) => num(a.sort_order) - num(b.sort_order));
  if (!loadedActiveParts.length) throw new Error("Part Group does not contain any active Parts.");

  const [liveGroup, liveRows] = await Promise.all([
    staffEntities.BuilderPartGroup.get(group.id),
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { part_group_id: group.id }, sort: "sort_order", label: "Saved Part Group members" }),
  ]);
  if (!liveGroup) throw new Error("This Part Group no longer exists. Reload the Product before saving it to the Part Library.");
  if (group.updated_date && liveGroup.updated_date && group.updated_date !== liveGroup.updated_date) {
    throw new Error("This Part Group changed in another session. Reload the Product before saving it to the Part Library.");
  }
  const activeParts = (liveRows || []).filter((part) => part.is_active !== false).sort((a, b) => num(a.sort_order) - num(b.sort_order));
  const loadedById = new Map(loadedActiveParts.map((part) => [part.id, part]));
  const membershipChanged = activeParts.length !== loadedActiveParts.length || activeParts.some((part) => !loadedById.has(part.id));
  const memberVersionChanged = activeParts.some((livePart) => {
    const loaded = loadedById.get(livePart.id);
    return !!(loaded?.updated_date && livePart.updated_date && loaded.updated_date !== livePart.updated_date);
  });
  if (membershipChanged || memberVersionChanged) {
    throw new Error("One or more Parts in this Part Group changed in another session. Reload the Product and review the current group before saving it to the Part Library.");
  }

  const meta = normalizeOptions({ template_name: liveGroup.client_label || liveGroup.group_name || "Saved Part Group", ...options });
  const first = activeParts[0] || {};
  const idempotencyKey = `part_group_template_save:${builderMutationHash({
    template_type: "part_group",
    group_id: liveGroup.id,
    group_updated_date: liveGroup.updated_date || "",
    parts: activeParts.map((part) => [part.id, part.updated_date || ""]),
    estimate_id: estimateId || "",
    builder_product_id: builderProductId || liveGroup.builder_product_id || "",
    meta,
  })}`;
  const familyKey = templateFamilyKey({ templateType: "part_group", sourceId: liveGroup.id, meta });
  const templateVersion = await resolveTemplateVersion({ familyKey, idempotencyKey });
  return ensureReusableRecord({
    entity: staffEntities.PartTemplate,
    idempotencyKey,
    label: "Saved Part Group",
    data: {
    ...meta,
    template_family_key: familyKey,
    template_version: templateVersion,
    template_type: "part_group",
    source_module_key: first.source_module_key || "",
    source_part_type: "part_group",
    source_part_subtype: "",
    created_from_estimate_id: estimateId,
    created_from_product_id: builderProductId || liveGroup.builder_product_id || "",
    created_from_part_group_id: liveGroup.id,
    created_from_part_id: "",
    part_snapshot: {},
    group_snapshot: { ...cloneSnapshot(liveGroup), snapshot_source_group_id: liveGroup.id },
    parts_snapshot: activeParts.map(cloneSnapshot),
    part_count: activeParts.length,
    frozen_cost: activeParts.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0),
    current_cost: activeParts.reduce((sum, part) => sum + num(part.current_extended_cost, num(part.frozen_extended_cost)), 0),
    contains_detached_parts: activeParts.some(detached),
    search_text: searchText([meta.template_name, meta.category, meta.tags, liveGroup.group_name, liveGroup.client_label, liveGroup.description, first.source_module_key, activeParts.map((part) => [part.part_name, part.client_label, part.part_type, part.part_subtype, part.inventory_item_name])]),
    is_active: true,
    },
  });
}

export async function listPartTemplates({ includeInactive = false } = {}) {
  const [rows, me] = await Promise.all([
    loadAllEntityRows({ entity: staffEntities.PartTemplate, sort: "template_name", label: "Part Library" }),
    base44.auth.me().catch(() => null),
  ]);
  return (rows || [])
    .filter((row) => {
      if (!includeInactive && row.is_active === false) return false;
      if (row.product_group === "global") return true;
      return !row.created_by_id || (!!me?.id && row.created_by_id === me.id);
    })
    .sort((a, b) => String(a.template_name || "").localeCompare(String(b.template_name || "")));
}

export async function instantiatePartTemplate({ estimateId, targetBuilderProductId, template, expectedEstimateUpdatedAt = "" }) {
  if (!template?.id) throw new Error("Saved Part is required.");
  const [liveTemplate, me] = await Promise.all([
    staffEntities.PartTemplate.get(template.id),
    base44.auth.me().catch(() => null),
  ]);
  if (!liveTemplate) throw new Error("This Saved Part no longer exists. Reopen the Part Library to refresh it.");
  if (liveTemplate.is_active === false) throw new Error("This Saved Part is now inactive and cannot be added. Reopen the Part Library to refresh it.");
  const accessible = liveTemplate.product_group === "global" || !liveTemplate.created_by_id || (!!me?.id && liveTemplate.created_by_id === me.id);
  if (!accessible) throw new Error("This Saved Part is no longer available to your account.");
  if (template.updated_date && liveTemplate.updated_date && template.updated_date !== liveTemplate.updated_date) {
    throw new Error("This Saved Part changed after the Part Library opened. Reopen the library and review the latest reusable snapshot before adding it.");
  }
  const isGroup = liveTemplate.template_type === "part_group";
  return addPartPackageToProduct({
    estimateId,
    targetBuilderProductId,
    itemType: isGroup ? "part_group" : "part",
    itemName: liveTemplate.template_name || (isGroup ? "Saved Part Group" : "Saved Part"),
    payload: isGroup
      ? { group: cloneSnapshot(liveTemplate.group_snapshot || {}), parts: (liveTemplate.parts_snapshot || []).map(cloneSnapshot) }
      : { part: cloneSnapshot(liveTemplate.part_snapshot || {}) },
    sourceType: "library",
    sourceId: liveTemplate.id,
    sourceTemplate: {
      id: liveTemplate.id,
      name: liveTemplate.template_name || "",
      version: Math.max(1, Number(liveTemplate.template_version) || 1),
    },
    expectedEstimateUpdatedAt,
  });
}

import { base44 } from "@/api/base44Client";
import { ensureBuilderProductForLine } from "@/components/estimator/builder/builderService";
import { builderMutationHash, pendingBuilderMutation, recoveryPatchDiffers } from "@/components/estimator/builder/builderMutationRecovery";
import { assertEstimateProductMutationAllowed } from "@/components/estimator/estimateMutationGuard";
import { expectedEstimateFields, replaceEstimateFieldsIfUnchanged } from "@/components/estimator/estimatePersistence";
import { expectedBuilderEntityFields, expectedEntityFields, replaceBuilderEntityFieldsIfUnchanged, replaceEntityFieldsIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";
import { staffEntities } from "@/components/staff/staffEntities";

const nowIso = () => new Date().toISOString();

function findLine(estimate, lineId) {
  return (estimate?.line_items || []).find((line) => line.line_id === lineId) || null;
}

function insertionIdentity({ estimateId, moduleKey, sourceEntity, productName, builderName, isCustom, expectedEstimateUpdatedAt }) {
  const key = `builder_blank_product_insert:${builderMutationHash({
    estimate_id: estimateId,
    module_key: moduleKey,
    source_entity: sourceEntity || "",
    product_name: productName,
    builder_name: builderName,
    is_custom: !!isCustom,
    expected_estimate_updated_at: expectedEstimateUpdatedAt || "",
  })}`;
  return {
    key,
    lineId: `line-add-${builderMutationHash({ operation_key: key })}`,
    sourceTag: `sep-insert-${builderMutationHash({ operation_key: key, source: sourceEntity || "custom" })}`,
  };
}

function completedInsertion(line, key) {
  return !!line && line.blank_product_insert_key === key && ["builder", "custom"].includes(line.blank_product_insert_kind);
}

async function persistSourceAnchor({ estimateId, lineId, pending, sourceId }) {
  const estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!estimate) throw new Error("Estimate could not be verified while anchoring the new Product source.");
  const line = findLine(estimate, lineId);
  const currentPending = pendingBuilderMutation(line);
  if (!line || !currentPending || currentPending.key !== pending.key) {
    throw new Error("The new Product recovery marker changed before its source could be anchored.");
  }
  await assertEstimateProductMutationAllowed(estimate, { allowPriceAcceptanceKey: pending.key });
  if (currentPending.source_project_id === sourceId && line.project_id === sourceId) return { estimate, line, pending: currentPending };

  const promotedPending = { ...currentPending, source_project_id: sourceId };
  const lineItems = (estimate.line_items || []).map((item) =>
    item.line_id === lineId
      ? { ...item, project_id: sourceId, price_acceptance_pending: promotedPending }
      : item
  );
  await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId,
    expectedFields: expectedEstimateFields(estimate, { line_items: lineItems }),
    nextFields: { line_items: lineItems },
    label: "Blank Product source anchor",
  });
  const anchored = await staffEntities.AllInOneEstimate.get(estimateId);
  const anchoredLine = findLine(anchored, lineId);
  const anchoredPending = pendingBuilderMutation(anchoredLine);
  if (!anchoredLine || !anchoredPending || anchoredPending.key !== pending.key || anchoredPending.source_project_id !== sourceId) {
    throw new Error("The new Product source anchor could not be verified after it was written.");
  }
  return { estimate: anchored, line: anchoredLine, pending: anchoredPending };
}

async function resolveSourceProject({ estimateId, lineId, pending }) {
  if (pending.is_custom) return { source: null, estimate: await staffEntities.AllInOneEstimate.get(estimateId), line: null, pending };
  const entityName = String(pending.source_entity || "").trim();
  if (!entityName) throw new Error("The Builder source entity is missing from the new Product recovery marker.");
  const entity = base44.entities[entityName];
  if (!entity?.get || !entity?.filter || !entity?.create || !entity?.update) {
    throw new Error("The Builder source entity needed to recover this Product is unavailable.");
  }

  let source = null;
  if (pending.source_project_id) {
    source = await entity.get(pending.source_project_id);
    if (!source) throw new Error("The anchored Builder source record disappeared while Product creation was pending.");
  } else {
    const readMatches = async () => {
      const rows = await entity.filter({ notes: pending.source_recovery_tag });
      if (!Array.isArray(rows)) throw new Error("The Builder source recovery token could not be verified.");
      return rows;
    };
    const verifySingle = (rows) => {
      if (rows.length > 1) throw new Error("Multiple Builder source records share this Product recovery token. Recovery stopped before linking either record.");
      return rows[0] || null;
    };

    source = verifySingle(await readMatches());
    if (!source) {
      let createdSource = null;
      let createError = null;
      try {
        createdSource = await entity.create({ ...(pending.source_create_data || {}), notes: pending.source_recovery_tag });
      } catch (error) {
        createError = error;
      }

      // One create attempt only. Re-read the deterministic source token before
      // anchoring it into the Estimate so response loss and simultaneous creates
      // cannot silently create or select a second source record.
      await new Promise((resolve) => setTimeout(resolve, 50));
      let after;
      try {
        after = await readMatches();
      } catch (verificationError) {
        if (createdSource?.id) {
          source = createdSource;
        } else {
          throw new Error(
            `Builder source create response was unavailable and its recovery lookup also failed. ` +
            `Do not retry blindly; reload the Estimate first. ${verificationError?.message || ""}`.trim()
          );
        }
      }

      if (!source) {
        const recovered = verifySingle(after);
        if (recovered) {
          if (createdSource?.id && recovered.id !== createdSource.id) {
            throw new Error("Builder source returned a create receipt, but a different record owns the Product recovery token. No source was anchored; reload before continuing.");
          }
          source = recovered;
        } else if (createdSource?.id) {
          source = createdSource;
        } else if (createError) {
          throw new Error(`${createError?.message || "Builder source could not be created."} No matching recovery-token source was visible after recovery. Reload the Estimate before retrying.`);
        } else {
          throw new Error("The Builder source record could not be verified after creation. Reload the Estimate before retrying.");
        }
      }
    }
  }

  const anchored = await persistSourceAnchor({ estimateId, lineId, pending, sourceId: source.id });
  const currentSource = await entity.get(source.id);
  if (!currentSource) throw new Error("The Builder source record disappeared while Product creation was pending.");
  if (String(currentSource.notes || "") === pending.source_recovery_tag) {
    const notesPatch = { notes: pending.source_original_notes || "" };
    source = await replaceEntityFieldsIfUnchanged({
      entity,
      id: source.id,
      expectedUpdatedAt: currentSource.updated_date || "",
      expectedFields: expectedEntityFields(currentSource, notesPatch),
      nextFields: notesPatch,
      label: "Blank Product source recovery token cleanup",
    });
  } else if (String(currentSource.notes || "") === String(pending.source_original_notes || "")) {
    source = currentSource;
  } else {
    throw new Error("The new Builder source record changed while Product creation was pending. Recovery retained the Estimate marker and did not overwrite the source edit.");
  }
  return { source, ...anchored };
}

export async function resumeBlankProductInsertion({ estimateId, lineId = "" }) {
  if (!estimateId) throw new Error("Estimate is required to resume Product creation.");
  let estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  let line = lineId
    ? findLine(estimate, lineId)
    : (estimate.line_items || []).find((item) => item?.price_acceptance_pending?.kind === "builder_blank_product_insert") || null;
  let pending = pendingBuilderMutation(line);
  if (!line || !pending || pending.kind !== "builder_blank_product_insert") {
    throw new Error("The pending Product creation could not be found.");
  }
  if (pending.estimate_id !== estimateId || pending.estimate_line_id !== line.line_id) {
    throw new Error("The Product creation recovery marker no longer matches this Estimate line.");
  }
  await assertEstimateProductMutationAllowed(estimate, { allowPriceAcceptanceKey: pending.key });

  let source = null;
  if (!pending.is_custom) {
    const resolved = await resolveSourceProject({ estimateId, lineId: line.line_id, pending });
    source = resolved.source;
    estimate = resolved.estimate;
    line = resolved.line || findLine(estimate, line.line_id);
    pending = resolved.pending;
  }

  const builderInputLine = {
    ...line,
    project_id: source?.id || "",
    project_name: pending.product_name,
    builder_name: pending.builder_name,
    client_product_name: pending.product_name,
    price_acceptance_pending: {},
  };
  const builderResult = await ensureBuilderProductForLine({
    estimate,
    line: builderInputLine,
    isNew: true,
    sourceProjectOverride: source,
  });
  if (!builderResult?.builderProduct?.id) throw new Error("The new Product's Builder record could not be verified.");

  let builderProduct = builderResult.builderProduct;
  let completedLine = builderResult.line;
  if (pending.is_custom) {
    const customPatch = {
      module_key: "custom",
      builder_name: "Custom Product",
      client_product_name: pending.product_name,
      product_category: "",
      price_state: "current",
      frozen_cost: 0,
      frozen_customer_price: 0,
      current_recalculated_cost: 0,
      notes: "Blank / Custom Product. Pricing is driven directly by its Parts rather than a dedicated estimator Builder.",
    };
    const currentBuilder = await staffEntities.BuilderProduct.get(builderProduct.id);
    if (!currentBuilder?.id || (currentBuilder.estimate_id && currentBuilder.estimate_id !== estimateId)) {
      throw new Error("The Custom Product Builder record changed ownership while creation was pending.");
    }
    if (recoveryPatchDiffers(currentBuilder, customPatch)) {
      builderProduct = await replaceBuilderEntityFieldsIfUnchanged({
        entity: staffEntities.BuilderProduct,
        id: builderProduct.id,
        expectedUpdatedAt: currentBuilder.updated_date || "",
        expectedFields: expectedBuilderEntityFields(currentBuilder, customPatch),
        nextFields: customPatch,
        guardFields: { estimate_id: estimateId },
        label: "Blank Product custom Builder setup",
      });
    } else {
      builderProduct = currentBuilder;
    }
    completedLine = { ...completedLine, price_state: "current" };
  }

  const latestEstimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!latestEstimate) throw new Error("Estimate could not be verified while completing Product creation.");
  const latestLine = findLine(latestEstimate, line.line_id);
  if (!latestLine) throw new Error("The provisional Product line disappeared before creation could complete.");
  const latestPending = pendingBuilderMutation(latestLine);
  if (!latestPending) {
    if (completedInsertion(latestLine, pending.key) && latestLine.builder_product_id === builderProduct.id) {
      return { line: latestLine, builderProduct, sourceProject: source, alreadyCompleted: true };
    }
    throw new Error("The Product creation marker disappeared before the completed Product line could be verified.");
  }
  if (latestPending.key !== pending.key) throw new Error("A different Product creation recovery marker is now active on this line.");
  await assertEstimateProductMutationAllowed(latestEstimate, { allowPriceAcceptanceKey: pending.key });

  const finalLine = {
    ...latestLine,
    ...completedLine,
    line_id: latestLine.line_id,
    project_id: source?.id || "",
    project_name: pending.product_name,
    builder_name: pending.builder_name,
    client_product_name: pending.product_name,
    linked_date: pending.started_at || latestLine.linked_date,
    blank_product_insert_key: pending.key,
    blank_product_insert_kind: pending.is_custom ? "custom" : "builder",
    price_acceptance_pending: {},
  };
  const lineItems = (latestEstimate.line_items || []).map((item) => item.line_id === latestLine.line_id ? finalLine : item);
  const updateResult = await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId,
    expectedFields: expectedEstimateFields(latestEstimate, { line_items: lineItems }),
    nextFields: { line_items: lineItems },
    label: "Blank Product insertion completion",
  });
  const persistedLine = (updateResult?.line_items || lineItems).find((item) => item.line_id === latestLine.line_id) || finalLine;
  return { line: persistedLine, builderProduct, sourceProject: source };
}

export async function addBlankProduct({
  estimateId,
  moduleKey,
  sourceEntity = "",
  productName,
  builderName,
  isCustom = false,
  expectedEstimateUpdatedAt = "",
}) {
  if (!estimateId || !moduleKey || !productName || !builderName) throw new Error("Estimate, Product type, and Product name are required.");
  const current = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!current) throw new Error("Estimate could not be loaded.");
  const requestVersion = expectedEstimateUpdatedAt || current.updated_date || "";
  const identity = insertionIdentity({
    estimateId,
    moduleKey,
    sourceEntity,
    productName,
    builderName,
    isCustom,
    expectedEstimateUpdatedAt: requestVersion,
  });
  const existingLine = findLine(current, identity.lineId);
  if (existingLine) {
    const existingPending = pendingBuilderMutation(existingLine);
    if (existingPending?.kind === "builder_blank_product_insert" && existingPending.key === identity.key) {
      return resumeBlankProductInsertion({ estimateId, lineId: identity.lineId });
    }
    if (completedInsertion(existingLine, identity.key)) {
      const builderProduct = existingLine.builder_product_id
        ? await staffEntities.BuilderProduct.get(existingLine.builder_product_id)
        : null;
      if (!builderProduct?.id) throw new Error("The completed Product insertion receipt exists, but its Builder Product is missing.");
      return { line: existingLine, builderProduct, alreadyCompleted: true };
    }
    throw new Error("A Product already occupies the deterministic insertion line for this request. Reload before trying again.");
  }

  await assertEstimateProductMutationAllowed(current, { expectedUpdatedAt: expectedEstimateUpdatedAt });
  const startedAt = nowIso();
  const pending = {
    key: identity.key,
    kind: "builder_blank_product_insert",
    started_at: startedAt,
    estimate_id: estimateId,
    estimate_line_id: identity.lineId,
    module_key: moduleKey,
    source_entity: isCustom ? "" : sourceEntity,
    source_project_id: "",
    source_recovery_tag: identity.sourceTag,
    source_original_notes: "",
    source_create_data: isCustom ? {} : {
      project_name: productName,
      client_name: current.client_name,
      customer_id: current.customer_id,
      estimate_number: current.estimate_number,
    },
    product_name: productName,
    builder_name: builderName,
    is_custom: !!isCustom,
  };
  const provisionalLine = {
    line_id: identity.lineId,
    module_key: moduleKey,
    project_id: "",
    project_name: productName,
    builder_name: builderName,
    client_product_name: productName,
    client_name: current.client_name,
    total_snapshot: 0,
    live_total_snapshot: 0,
    customer_price_snapshot: 0,
    live_customer_price_snapshot: 0,
    price_state: isCustom ? "current" : "unchecked",
    adjustment_percent: 0,
    section_status: "in_progress",
    customer_quantity: 1,
    include_in_customer: true,
    owned: true,
    linked_date: startedAt,
    price_acceptance_pending: pending,
  };
  const lineItems = [...(current.line_items || []), provisionalLine];
  await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId,
    expectedFields: expectedEstimateFields(current, { line_items: lineItems }),
    nextFields: { line_items: lineItems },
    label: "Blank Product insertion recovery marker",
  });
  return resumeBlankProductInsertion({ estimateId, lineId: identity.lineId });
}

import { snapshotHash } from "@/components/estimator/builder/builderService";
