}

export async function cloneProductInEstimate({ estimateId, line, expectedEstimateUpdatedAt = "" }) {
  if (!estimateId || !line?.builder_product_id) throw new Error("This Product does not have a persistent Product record to clone.");
  const [estimate, builder, parts, groups] = await Promise.all([
    staffEntities.AllInOneEstimate.get(estimateId),
    staffEntities.BuilderProduct.get(line.builder_product_id),
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: line.builder_product_id }, sort: "sort_order", label: "Product clone Builder Parts" }),
    loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: line.builder_product_id }, sort: "sort_order", label: "Product clone Part Groups" }),
  ]);
  if (!estimate || !builder || !Array.isArray(parts) || !Array.isArray(groups)) throw new Error("The Product could not be fully loaded for cloning.");
  const currentLine = (estimate.line_items || []).find((item) =>
    item.builder_product_id === builder.id || (line.line_id && item.line_id === line.line_id)
  );
  if (!currentLine) throw new Error("This Product is no longer part of the estimate. Reload before cloning it.");
  if (parts.some((part) => part?.builder_product_id !== builder.id) || groups.some((group) => group?.builder_product_id !== builder.id)) {
    throw new Error("This Product's Parts or Part Groups changed ownership. Reload before cloning it.");
  }

  let sourceProject = null;
  if (builder.source_entity && builder.source_project_id && currentLine.module_key !== "custom") {
    sourceProject = await base44.entities[builder.source_entity].get(builder.source_project_id);
    if (!sourceProject) throw new Error("The source Builder record could not be verified for this Product clone.");
  }

  const originalName = currentLine.client_product_name || builder.client_product_name || currentLine.project_name || "Product";
  const copyName = `${originalName} — Copy`;
  const activeParts = parts.filter((part) => part.is_active !== false).sort((a, b) => num(a.sort_order) - num(b.sort_order));
  const activeGroups = groups.filter((group) => group.is_active !== false).sort((a, b) => num(a.sort_order) - num(b.sort_order));
  const frozenTotal = num(builder.frozen_cost, num(currentLine.total_snapshot));
  const currentTotal = num(builder.current_recalculated_cost, num(currentLine.live_total_snapshot, frozenTotal));
  const frozenCustomer = num(builder.frozen_customer_price, acceptedCustomerUnitPrice(currentLine));
  const liveCustomer = liveCustomerUnitPrice(currentLine);
  const sourceSnapshot = cloneSnapshot(sourceProject || builder.builder_snapshot || {});

  const clonePayload = {
    product_name: copyName,
    template_version: 2,
    source_product_class: currentLine.module_key === "custom" ? "custom" : "builder",
    source_module_key: currentLine.module_key || builder.module_key || "custom",
    source_entity: currentLine.module_key === "custom" ? "" : (builder.source_entity || ""),
    source_builder_name: builder.builder_name || currentLine.builder_name || "Custom Product",
    product_category: currentLine.product_category || builder.product_category || "",
    production_product_type: currentLine.production_product_type ?? builder.production_product_type ?? "",
    product_quantity: num(currentLine.customer_quantity, num(builder.quantity, 1)),
    product_notes: currentLine.product_notes ?? builder.product_notes ?? "",
    client_description: currentLine.customer_description ?? builder.client_description ?? "",
    product_snapshot: {
      line: cloneSnapshot(currentLine),
      builder_product: cloneSnapshot(builder),
    },
    builder_snapshot: sourceSnapshot,
    parts_snapshot: activeParts.map(cloneSnapshot),
    part_groups_snapshot: activeGroups.map((group) => ({
      ...cloneSnapshot(group),
      snapshot_source_group_id: group.id,
    })),
    price_snapshot: {
      frozen_cost: frozenTotal,
      frozen_customer_price: frozenCustomer,
      current_recalculated_cost: currentTotal,
      current_recalculated_customer_price: liveCustomer,
      price_state: builder.price_state || currentLine.price_state || "current",
      price_delta: num(builder.price_delta, currentTotal - frozenTotal),
      price_delta_percent: num(builder.price_delta_percent, frozenTotal ? ((currentTotal - frozenTotal) / frozenTotal) * 100 : 0),
      price_recalc_required: !!(builder.price_recalc_required || currentLine.price_recalc_required),
      price_recalc_reason: builder.price_recalc_reason || currentLine.price_recalc_reason || "",
    },
    detached_part_count: num(builder.detached_part_count),
    needs_reattach_review: !!builder.needs_reattach_review,
  };

  return instantiateProductSnapshot({
    estimateId,
    productSnapshot: clonePayload,
    expectedEstimateUpdatedAt,
    sourceId: builder.id,
    sourceType: "product_clone",
  });
}

export async function saveProductSettings({ estimateId, line, patch = {}, expectedEstimateUpdatedAt = "" }) {
  if (!estimateId || !line) return null;
  const estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  const matches = (item) =>
    (line.line_id && item.line_id === line.line_id) ||
    (line.builder_product_id && item.builder_product_id === line.builder_product_id) ||
    (line.project_id && item.project_id === line.project_id);
  const currentLine = (estimate.line_items || []).find(matches);
  if (!currentLine) throw new Error("This Product is no longer part of the estimate. Reload before changing its settings.");

  const builderProductId = currentLine.builder_product_id || line.builder_product_id || "";
  const operationKey = builderProductId
    ? manualProductPriceOperationKey({
        estimateId,
        builderProductId,
        lineId: currentLine.line_id || line.line_id || "",
        expectedEstimateUpdatedAt: expectedEstimateUpdatedAt || estimate.updated_date || "",
        patch,
      })
    : "";
  const pending = pendingBuilderMutation(currentLine);
  if (pending) {
    if (pending.kind !== "builder_manual_product_price" || pending.key !== operationKey) {
      throw new Error("Another Builder mutation is still being recovered for this Product. Resume that operation before changing Product settings.");
    }
    const [builder, parts] = await Promise.all([
      staffEntities.BuilderProduct.get(builderProductId),
      loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Product price Builder Parts" }),
    ]);
    if (!builder?.id || !Array.isArray(parts)) throw new Error("The pending Product price adjustment could not verify its Builder Product or Parts.");
    const recovered = await resumeBuilderMutation({
      estimateId,
      estimate,
      builder,
      parts,
      line: currentLine,
      pending,
      applyPartPlan: applyBuilderPartPriceAcceptancePlan,
    });
    return recovered?.line || currentLine;
  }

  let builder = null;
  if (builderProductId) {
    builder = await staffEntities.BuilderProduct.get(builderProductId);
    if (!builder?.id || (builder.estimate_id && builder.estimate_id !== estimateId)) {
      throw new Error("This Product's Builder record could not be verified. Reload before changing Product settings.");
    }
  }

  // A lost response after the final Estimate write leaves no recovery marker.
  // The immutable idempotent pricing revision is completion evidence for the
  // exact browser request, so verify the requested line/Builder targets before
  // treating a stale retry as already completed.
  if (builder && patch.customer_price_snapshot !== undefined && operationKey) {
    const revisions = await loadAllEntityRows({ entity: base44.entities.BuilderPriceRevision, query: { builder_product_id: builder.id }, sort: "revision_number", label: "Product price revisions" });
    if (!Array.isArray(revisions)) throw new Error("Product price history could not be verified before changing Product settings.");
    const completedRevision = revisions.find((row) => String(row.idempotency_key || "") === operationKey);
    if (completedRevision) {
      const completedCustomerPrice = Math.max(0, num(completedRevision.new_customer_price));
      const expectedLinePatch = { ...patch, customer_price_snapshot: completedCustomerPrice };
      const expectedBuilderPatch = {
        ...productSettingsBuilderPatch(patch),
        frozen_customer_price: completedCustomerPrice,
      };
      if (!recoveryPatchDiffers(currentLine, expectedLinePatch) && !recoveryPatchDiffers(builder, expectedBuilderPatch)) {
        return currentLine;
      }
      throw new Error("The Product price-adjustment audit exists, but the Product no longer matches its completed target. Reload and review the Product before continuing.");
    }
  }

  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });
  const nextPatch = { ...patch };
  const timestamp = nowIso();
  let builderPatch = builder ? productSettingsBuilderPatch(patch) : {};

  if (builder && patch.customer_price_snapshot !== undefined) {
    const previousCustomerPrice = acceptedCustomerUnitPrice(currentLine);
    const nextCustomerPrice = Math.max(0, num(patch.customer_price_snapshot, previousCustomerPrice));
    nextPatch.customer_price_snapshot = nextCustomerPrice;

    if (Math.abs(nextCustomerPrice - previousCustomerPrice) > 0.005) {
      const frozenCost = num(builder.frozen_cost, num(currentLine.total_snapshot));
      const currentCost = num(builder.current_recalculated_cost, num(currentLine.live_total_snapshot, frozenCost));
      const liveCustomerPrice = liveCustomerUnitPrice(currentLine);
      const nextState = manualCustomerPriceState({
        frozenCost,
        currentCost,
        acceptedCustomerPrice: nextCustomerPrice,
        liveCustomerPrice,
        detached: !!builder.needs_reattach_review || currentLine.price_state === "detached_parts",
        recalcRequired: !!builder.price_recalc_required || !!currentLine.price_recalc_required,
      });
      builderPatch = {
        ...builderPatch,
        frozen_customer_price: nextCustomerPrice,
        price_state: nextState,
        price_delta: currentCost - frozenCost,
        price_delta_percent: frozenCost ? ((currentCost - frozenCost) / frozenCost) * 100 : 0,
        last_price_update_at: timestamp,
        last_price_update_note: "Customer base price manually adjusted. Internal frozen cost unchanged.",
        last_price_check_at: timestamp,
        builder_version: num(builder.builder_version, 1) + 1,
      };
      nextPatch.price_state = nextState;
      nextPatch.last_price_update_at = timestamp;
      nextPatch.last_price_check_at = timestamp;

      const revision = {
        builder_product_id: builder.id,
        estimate_id: estimateId,
        reason: "manual_adjustment",
        previous_total_cost: frozenCost,
        new_total_cost: frozenCost,
        previous_customer_price: previousCustomerPrice,
        new_customer_price: nextCustomerPrice,
        changed_parts: [],
        builder_snapshot_before: builder.builder_snapshot || {},
        builder_snapshot_after: builder.builder_snapshot || {},
        price_snapshot_before: { total: frozenCost, customer_price: previousCustomerPrice },
        price_snapshot_after: { total: frozenCost, customer_price: nextCustomerPrice },
        notes: "Customer base price manually adjusted from the estimate Product. Internal frozen cost was not changed.",
      };
      const recoveryMarker = {
        key: operationKey,
        kind: "builder_manual_product_price",
        started_at: timestamp,
        estimate_id: estimateId,
        estimate_line_id: currentLine.line_id || builder.estimate_line_id || "",
        builder_product_id: builder.id,
        builder_updated_date_before: builder.updated_date || "",
        builder_version_before: num(builder.builder_version, 1),
        part_acceptance_plan: { timestamp, part_updates: [], changed_parts: [] },
        builder_patch: builderPatch,
        line_patch: nextPatch,
        revision,
      };
      const marked = await markBuilderMutationPending({ estimate, builder, pending: recoveryMarker });
      const recovered = await resumeBuilderMutation({
        estimateId,
        estimate: marked.markedEstimate,
        builder: marked.currentBuilder,
        parts: marked.currentParts,
        line: marked.markedLine,
        pending: marked.canonicalPending,
        applyPartPlan: applyBuilderPartPriceAcceptancePlan,
      });
      return recovered?.line || { ...currentLine, ...nextPatch };
    }
  }

  // The Estimate line is the authoritative Product metadata record. Commit it
  // before the mirrored BuilderProduct fields so a lost/failing second write is
  // self-healing on the next strict reconciliation instead of leaving Builder
  // metadata ahead of an unchanged Estimate line.
  const lineItems = (estimate.line_items || []).map((item) => matches(item) ? { ...item, ...nextPatch } : item);
  const savedEstimate = await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId,
    expectedFields: expectedEstimateFields(estimate, { line_items: lineItems }),
    nextFields: { line_items: lineItems },
    label: "Product metadata Estimate line update",
  });
  if (builder && Object.keys(builderPatch).length) {
    await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderProduct,
      id: builder.id,
      expectedUpdatedAt: builder.updated_date || "",
      expectedFields: expectedBuilderEntityFields(builder, builderPatch),
      nextFields: builderPatch,
      guardFields: { estimate_id: estimateId },
      label: "Product metadata Builder mirror",
    });
  }
  const savedLines = savedEstimate.line_items || lineItems;
  return savedLines.find(matches) || { ...line, ...nextPatch };
}

export async function saveProductNotes({ estimateId, line, notes, expectedEstimateUpdatedAt = "" }) {
  if (!estimateId || !line) return;
  const estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });
  const exists = (estimate.line_items || []).some((item) =>
    (item.line_id && item.line_id === line.line_id) || (item.builder_product_id && item.builder_product_id === line.builder_product_id)
  );
  if (!exists) throw new Error("This Product is no longer part of the estimate. Reload before changing its notes.");
  const lineItems = (estimate.line_items || []).map((item) =>
    (item.line_id && item.line_id === line.line_id) || (item.builder_product_id && item.builder_product_id === line.builder_product_id)
      ? { ...item, product_notes: notes }
      : item
  );
  const savedEstimate = await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId,
    expectedFields: expectedEstimateFields(estimate, { line_items: lineItems }),
    nextFields: { line_items: lineItems },
    label: "Product notes Estimate line update",
  });
  if (line.builder_product_id) {
    const currentBuilder = await staffEntities.BuilderProduct.get(line.builder_product_id);
    if (!currentBuilder?.id || String(currentBuilder.estimate_id || "") !== String(estimateId)) {
      throw new Error("The Product Builder changed ownership before its notes could be mirrored.");
    }
    const builderNotesPatch = { product_notes: notes };
    await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderProduct,
      id: currentBuilder.id,
      expectedUpdatedAt: currentBuilder.updated_date || "",
      expectedFields: expectedBuilderEntityFields(currentBuilder, builderNotesPatch),
      nextFields: builderNotesPatch,
      guardFields: { estimate_id: estimateId },
      label: "Product notes Builder mirror",
    });
  }
  const savedLines = savedEstimate.line_items || lineItems;
  return savedLines.find((item) => item.builder_product_id === line.builder_product_id || item.line_id === line.line_id) || null;
}

import { base44 } from "@/api/base44Client";
import { getModule } from "@/components/estimator/moduleRegistry";
import { builderMutationHash, pendingBuilderMutation } from "@/components/estimator/builder/builderMutationRecovery";
import { assertEstimateProductMutationAllowed } from "@/components/estimator/estimateMutationGuard";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { expectedEstimateFields, replaceEstimateFieldsIfUnchanged } from "@/components/estimator/estimatePersistence";
import { deleteEntityIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";
import { staffEntities } from "@/components/staff/staffEntities";

const nowIso = () => new Date().toISOString();

function findMatchingLine(estimate, line) {
  return (estimate?.line_items || []).find((item) =>
    (line?.line_id && item.line_id === line.line_id) ||
    (line?.builder_product_id && item.builder_product_id === line.builder_product_id) ||
    (line?.project_id && item.project_id === line.project_id)
  ) || null;
}

function removalLineId(estimateId, line) {
  if (line?.line_id) return String(line.line_id);
  return `line-remove-${builderMutationHash({
    estimate_id: estimateId,
    builder_product_id: line?.builder_product_id || "",
    project_id: line?.project_id || "",
    module_key: line?.module_key || "",
    project_name: line?.project_name || "",
    client_product_name: line?.client_product_name || "",
  })}`;
}

function operationKeyFor({ estimateId, line, expectedEstimateUpdatedAt }) {
  return `builder_product_remove:${builderMutationHash({
    estimate_id: estimateId,
    line_id: removalLineId(estimateId, line),
    builder_product_id: line?.builder_product_id || "",
    project_id: line?.project_id || "",
    expected_estimate_updated_at: expectedEstimateUpdatedAt || "",
  })}`;
}

function rowVersion(row) {
  return String(row?.updated_date || row?.created_date || "");
}

function plannedStep(row, extra = {}) {
  return row?.id ? { id: row.id, expected_updated_date: rowVersion(row), ...extra } : null;
}

async function loadRemovalPlan(line) {
  const builderProductId = String(line?.builder_product_id || "").trim();
  const mod = getModule(line?.module_key);
  let source = null;
  if (line?.owned && mod?.entity && line?.project_id) {
    source = await base44.entities[mod.entity].get(line.project_id);
  }

  let builder = null;
  let parts = [];
  let groups = [];
  let revisions = [];
  if (builderProductId) {
    [builder, parts, groups, revisions] = await Promise.all([
      staffEntities.BuilderProduct.get(builderProductId),
      loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Product removal Builder Parts" }),
      loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Product removal Part Groups" }),
      loadAllEntityRows({ entity: base44.entities.BuilderPriceRevision, query: { builder_product_id: builderProductId }, sort: "revision_number", label: "Product removal price revisions" }),
    ]);
    if (![parts, groups, revisions].every(Array.isArray)) {
      throw new Error("Product removal could not verify all Builder child records before starting.");
    }
    if (parts.some((row) => row?.builder_product_id !== builderProductId) || groups.some((row) => row?.builder_product_id !== builderProductId) || revisions.some((row) => row?.builder_product_id !== builderProductId)) {
      throw new Error("Product removal found a Builder child record with unexpected ownership. Reload before removing the Product.");
    }
  }

  return {
    source: line?.owned && mod?.entity && line?.project_id
      ? { entity: mod.entity, id: line.project_id, expected_updated_date: source ? rowVersion(source) : "", expected_missing: !source }
      : null,
    builder: builderProductId
      ? { id: builderProductId, expected_updated_date: builder ? rowVersion(builder) : "", expected_missing: !builder }
      : null,
    parts: parts.map((row) => plannedStep(row, { builder_product_id: builderProductId })),
    groups: groups.map((row) => plannedStep(row, { builder_product_id: builderProductId })),
    revisions: revisions.map((row) => plannedStep(row, { builder_product_id: builderProductId })),
  };
}

function assertExpectedRecord(record, step, label, builderProductId = "") {
  if (!record) {
    if (step?.expected_missing) return;
    return;
  }
  if (step?.expected_missing) throw new Error(`${label} appeared while Product removal was pending. Recovery stopped before deleting it.`);
  if (builderProductId && String(record.builder_product_id || "") !== String(builderProductId)) {
    throw new Error(`${label} changed ownership while Product removal was pending.`);
  }
  const expected = String(step?.expected_updated_date || "").trim();
  const current = rowVersion(record);
  if (expected && current && expected !== current) {
    throw new Error(`${label} changed while Product removal was pending. Recovery stopped before deleting unrelated edits.`);
  }
}

async function preflightChildren(plan, builderProductId) {
  if (!builderProductId) return;
  const [parts, groups, revisions] = await Promise.all([
    loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Product removal Builder Parts" }),
    loadAllEntityRows({ entity: staffEntities.BuilderPartGroup, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Product removal Part Groups" }),
    loadAllEntityRows({ entity: base44.entities.BuilderPriceRevision, query: { builder_product_id: builderProductId }, sort: "revision_number", label: "Product removal price revisions" }),
  ]);
  if (![parts, groups, revisions].every(Array.isArray)) throw new Error("Builder child records could not be verified while Product removal was pending.");

  const check = (currentRows, steps, label) => {
    const planned = new Map((steps || []).map((step) => [step.id, step]));
    for (const row of currentRows) {
      const step = planned.get(row.id);
      if (!step) throw new Error(`A new ${label} appeared while Product removal was pending. Recovery stopped before deleting it.`);
      assertExpectedRecord(row, step, label, builderProductId);
    }
  };
  check(parts, plan.parts, "Builder Part");
  check(groups, plan.groups, "Part Group");
  check(revisions, plan.revisions, "pricing revision");
}

async function verifyRemovalPlan(plan) {
  if (plan.source) {
    const entity = base44.entities[plan.source.entity];
    if (!entity?.get || !entity?.deleteMany) throw new Error("The owned Builder source entity needed for Product removal is unavailable.");
    const source = await entity.get(plan.source.id);
    assertExpectedRecord(source, plan.source, "Owned Builder source");
  }

  const builderProductId = plan.builder?.id || "";
  if (builderProductId) {
    const builder = await staffEntities.BuilderProduct.get(builderProductId);
    assertExpectedRecord(builder, plan.builder, "Builder Product");
    await preflightChildren(plan, builderProductId);
  }
}

async function deleteVerified(entity, step, label, builderProductId = "") {
  if (!step?.id) return;
  const record = await entity.get(step.id);
  if (!record) return;
  assertExpectedRecord(record, step, label, builderProductId);
  await deleteEntityIfUnchanged({
    entity,
    record,
    guardFields: builderProductId ? { builder_product_id: builderProductId } : {},
    label,
  });
}

async function applyRemovalPlan(plan) {
  await verifyRemovalPlan(plan);

  if (plan.source) {
    const entity = base44.entities[plan.source.entity];
    await deleteVerified(entity, plan.source, "Owned Builder source");
  }

  const builderProductId = plan.builder?.id || "";
  for (const step of plan.parts || []) await deleteVerified(staffEntities.BuilderPart, step, "Builder Part", builderProductId);
  for (const step of plan.groups || []) await deleteVerified(staffEntities.BuilderPartGroup, step, "Part Group", builderProductId);
  for (const step of plan.revisions || []) await deleteVerified(base44.entities.BuilderPriceRevision, step, "pricing revision", builderProductId);

  if (builderProductId) {
    // Catch a child record created after the initial full preflight before the
    // parent Builder Product is removed.
    await preflightChildren(plan, builderProductId);
    await deleteVerified(staffEntities.BuilderProduct, plan.builder, "Builder Product");
  }
}

export async function resumeProductRemoval({ estimateId, lineId = "" }) {
  if (!estimateId) throw new Error("Estimate is required to resume Product removal.");
  let estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  let line = lineId
    ? (estimate.line_items || []).find((item) => item.line_id === lineId) || null
    : (estimate.line_items || []).find((item) => item?.price_acceptance_pending?.kind === "builder_product_remove") || null;
  if (!line) {
    if (estimate.last_product_removal_line_id === lineId && estimate.last_product_removal_key) {
      return { removed: true, alreadyCompleted: true, lineId };
    }
    throw new Error("The pending Product removal could not be found.");
  }
  const pending = pendingBuilderMutation(line);
  if (!pending || pending.kind !== "builder_product_remove" || pending.estimate_id !== estimateId || pending.estimate_line_id !== line.line_id) {
    throw new Error("The Product removal recovery marker no longer matches this Estimate line.");
  }
  await assertEstimateProductMutationAllowed(estimate, { allowPriceAcceptanceKey: pending.key });
  await applyRemovalPlan(pending.delete_plan || {});

  estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!estimate) throw new Error("Estimate could not be verified while completing Product removal.");
  line = (estimate.line_items || []).find((item) => item.line_id === pending.estimate_line_id) || null;
  if (!line) {
    if (estimate.last_product_removal_key === pending.key && estimate.last_product_removal_line_id === pending.estimate_line_id) {
      return { removed: true, alreadyCompleted: true, lineId: pending.estimate_line_id };
    }
    throw new Error("The Product line disappeared before its removal receipt could be verified.");
  }
  const latestPending = pendingBuilderMutation(line);
  if (!latestPending || latestPending.key !== pending.key) throw new Error("The Product removal marker changed before the final Estimate update.");
  await assertEstimateProductMutationAllowed(estimate, { allowPriceAcceptanceKey: pending.key });

  const lineItems = (estimate.line_items || []).filter((item) => item.line_id !== pending.estimate_line_id);
  const nextFields = {
    line_items: lineItems,
    last_product_removal_key: pending.key,
    last_product_removal_line_id: pending.estimate_line_id,
    last_product_removal_at: nowIso(),
  };
  await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId,
    expectedFields: expectedEstimateFields(estimate, nextFields),
    nextFields,
    label: "Product removal Estimate completion",
  });
  return { removed: true, lineId: pending.estimate_line_id };
}

export async function removeProductFromEstimate({ estimateId, line, expectedEstimateUpdatedAt = "" }) {
  if (!estimateId || !line) throw new Error("Estimate and Product are required for removal.");
  const estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  const currentLine = findMatchingLine(estimate, line);
  const identityLine = currentLine || line;
  const effectiveLineId = removalLineId(estimateId, identityLine);
  const normalizedLine = { ...identityLine, line_id: effectiveLineId };
  const key = operationKeyFor({ estimateId, line: normalizedLine, expectedEstimateUpdatedAt: expectedEstimateUpdatedAt || estimate.updated_date || "" });
  if (!currentLine) {
    if (estimate.last_product_removal_key === key && estimate.last_product_removal_line_id === effectiveLineId) {
      return { removed: true, alreadyCompleted: true, lineId: effectiveLineId };
    }
    throw new Error("This Product is no longer part of the estimate. Reload before removing it.");
  }

  const existingPending = pendingBuilderMutation(currentLine);
  if (existingPending) {
    if (existingPending.kind !== "builder_product_remove" || existingPending.key !== key) {
      throw new Error("Another Builder mutation is still being recovered for this Product. Resume it before removing the Product.");
    }
    return resumeProductRemoval({ estimateId, lineId: currentLine.line_id });
  }

  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });
  const deletePlan = await loadRemovalPlan(currentLine);
  const pending = {
    key,
    kind: "builder_product_remove",
    started_at: nowIso(),
    estimate_id: estimateId,
    estimate_line_id: effectiveLineId,
    builder_product_id: currentLine.builder_product_id || "",
    project_id: currentLine.project_id || "",
    product_name: currentLine.client_product_name || currentLine.project_name || "Product",
    delete_plan: deletePlan,
  };

  // Re-read immediately before the marker so preflight reads cannot hide a
  // concurrent Estimate edit behind the deletion plan.
  const latestEstimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!latestEstimate) throw new Error("Estimate could not be verified before starting Product removal.");
  if (estimate.updated_date && latestEstimate.updated_date && estimate.updated_date !== latestEstimate.updated_date) {
    throw new Error("This estimate changed while Product removal was being prepared. No source, Builder, Part, or Product line was deleted.");
  }
  const latestLine = findMatchingLine(latestEstimate, currentLine);
  if (!latestLine) throw new Error("This Product disappeared before removal could start.");
  const targetIndex = (latestEstimate.line_items || []).indexOf(latestLine);
  if (targetIndex < 0) throw new Error("The Product line could not be identified exactly before removal started.");
  const lineItems = (latestEstimate.line_items || []).map((item, index) => index === targetIndex
    ? { ...item, line_id: effectiveLineId, price_acceptance_pending: pending }
    : item);
  await replaceEstimateFieldsIfUnchanged({
    entity: staffEntities.AllInOneEstimate,
    estimateId,
    expectedFields: expectedEstimateFields(latestEstimate, { line_items: lineItems }),
    nextFields: { line_items: lineItems },
    label: "Product removal recovery marker",
  });
  return resumeProductRemoval({ estimateId, lineId: effectiveLineId });
}

import { base44 } from "@/api/base44Client";
import { snapshotHash } from "@/components/estimator/builder/builderService";
import { cloneSnapshot, stripEntitySystemFields } from "@/components/estimator/products/snapshotUtils";
import { countBuilderReattachParts } from "@/components/estimator/parts/partState";
import { acceptedCustomerUnitPrice, liveCustomerUnitPrice } from "@/components/estimator/customerPricing";
import { assertEstimateProductMutationAllowed } from "@/components/estimator/estimateMutationGuard";
import { applyBuilderPartPriceAcceptancePlan } from "@/components/estimator/builder/partSync";
import { builderMutationHash, pendingBuilderMutation, recoveryPatchDiffers, resumeBuilderMutation } from "@/components/estimator/builder/builderMutationRecovery";
import { ensureReusableRecord } from "@/components/estimator/products/reusableSaveIdempotency";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
