const ENTITY_SYSTEM_FIELDS = new Set([
  "id",
  "created_date",
  "updated_date",
  "created_by",
  "created_by_id",
  "is_sample",
]);

export function cloneSnapshot(value) {
  if (Array.isArray(value)) return value.map(cloneSnapshot);
  if (!value || typeof value !== "object") return value;
  const out = {};
  Object.entries(value).forEach(([key, item]) => {
    out[key] = cloneSnapshot(item);
  });
  return out;
}

export function stripEntitySystemFields(value) {
  const cloned = cloneSnapshot(value);
  if (!cloned || typeof cloned !== "object" || Array.isArray(cloned)) return cloned;
  ENTITY_SYSTEM_FIELDS.forEach((key) => delete cloned[key]);
  return cloned;
}

import React from "react";
import { ACTIONS, ACTION_GROUPS } from "./constants";
import { Check } from "lucide-react";

// `enabledActions` is an array of action ids that the user has enabled for this
// sign type in Settings. When omitted, every action is shown (backward compat).
export default function ActionPicker({ signType, selected, onToggle, enabledActions }) {
  if (!signType) {
    return <div className="text-xs text-slate-400 italic">Pick a sign type first to see applicable maintenance actions.</div>;
  }

  const allowed = enabledActions || ACTIONS.map(a => a.id);
  const grouped = ACTION_GROUPS.map(group => ({
    group,
    actions: ACTIONS.filter(a => a.group === group && allowed.includes(a.id)),
  })).filter(g => g.actions.length > 0);

  if (grouped.length === 0) {
    return (
      <div className="text-xs text-slate-500 italic bg-amber-50 border border-amber-200 rounded-md p-2">
        No actions are enabled for this sign type. Enable them in Sign Maintenance Settings → Service Items.
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {grouped.map(g => (
        <div key={g.group}>
          <div className="text-[10px] font-semibold text-slate-500 uppercase tracking-wider mb-1.5">{g.group}</div>
          <div className="flex flex-wrap gap-1.5">
            {g.actions.map(a => {
              const on = selected.includes(a.id);
              return (
                <button type="button"
                  key={a.id}
                  type="button"
                  onClick={() => onToggle(a.id)}
                  className={`text-xs px-2.5 py-1 rounded-full border transition-all flex items-center gap-1 ${
                    on
                      ? "bg-cyan-600 text-white border-cyan-600 shadow-sm"
                      : "bg-white text-slate-700 border-slate-200 hover:border-cyan-300"
                  }`}
                >
                  {on && <Check className="w-3 h-3" />}
                  {a.label}
                </button>
              );
            })}
          </div>
        </div>
      ))}
    </div>
  );
}

// Single (sign_type × action) rate card with an enable/disable toggle.
// Extracted from RatesBySignTypeTab so each card lives in its own focused file.

import React from "react";
import { motion } from "framer-motion";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Clock, Sparkles, Lightbulb, Zap, Wrench } from "lucide-react";
import { LETTER_SIZES, CABINET_SIZES, sizeAxisFor } from "./constants";
import { SIZE_FIELD } from "./defaults";

const GROUP_THEMES = {
  "Cosmetic":   { Icon: Sparkles,  bar: "from-pink-400 to-rose-500",     text: "text-rose-700",   bg: "bg-rose-50",   border: "border-rose-200" },
  "LED / Lamp": { Icon: Lightbulb, bar: "from-amber-400 to-orange-500",  text: "text-amber-700",  bg: "bg-amber-50",  border: "border-amber-200" },
  "Electrical": { Icon: Zap,       bar: "from-yellow-400 to-amber-500",  text: "text-yellow-700", bg: "bg-yellow-50", border: "border-yellow-200" },
  "Component":  { Icon: Wrench,    bar: "from-violet-400 to-purple-500", text: "text-violet-700", bg: "bg-violet-50", border: "border-violet-200" },
};

export default function ActionRateCard({ action, signType, rate, isLocked, onChange }) {
  const isCabinet = sizeAxisFor(signType.id) === "cabinet";
  const sizes = isCabinet ? CABINET_SIZES : LETTER_SIZES;
  const basis = rate.rate_basis || (isCabinet ? "per_cabinet" : "per_letter");
  const isFlat = basis === "flat";
  const theme = GROUP_THEMES[action.group] || GROUP_THEMES["Component"];
  const Icon = theme.Icon;
  const enabled = rate.is_enabled !== false; // default true

  return (
    <motion.div
      whileHover={{ y: -2, scale: 1.01 }}
      transition={{ type: "spring", stiffness: 300, damping: 20 }}
      className={`border ${theme.border} rounded-xl bg-white hover:shadow-md transition-shadow overflow-hidden ${!enabled ? "opacity-60" : ""}`}
    >
      <div className={`h-1 bg-gradient-to-r ${theme.bar}`} />
      <div className={`px-4 py-3 ${theme.bg}`}>
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-2 min-w-0">
            <div className={`w-7 h-7 rounded-lg bg-gradient-to-br ${theme.bar} flex items-center justify-center shadow-sm flex-shrink-0`}>
              <Icon className="w-3.5 h-3.5 text-white" />
            </div>
            <div className="min-w-0">
              <div className={`text-sm font-semibold ${theme.text} truncate`}>{action.label}</div>
              <div className="text-[11px] text-slate-500">
                {isFlat ? "Flat per service item" : `Per ${isCabinet ? "cabinet" : "letter"}`}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Switch
              checked={enabled}
              disabled={isLocked}
              onCheckedChange={(v) => onChange({ is_enabled: !!v })}
              aria-label={`Enable ${action.label} for ${signType.label}`}
            />
          </div>
        </div>
      </div>

      <div className={`p-4 space-y-3 ${!enabled ? "pointer-events-none" : ""}`}>
        <div>
          <Label className="text-[10px] uppercase tracking-wider text-slate-500 font-semibold">Rate Basis</Label>
          <select
            className="h-9 w-full rounded-md border border-slate-200 text-xs bg-white px-2 mt-1 disabled:bg-slate-50 focus:outline-none focus:ring-2 focus:border-transparent"
            value={basis}
            disabled={isLocked || !enabled}
            onChange={(e) => onChange({ rate_basis: e.target.value })}
          >
            <option value={isCabinet ? "per_cabinet" : "per_letter"}>{isCabinet ? "Per cabinet" : "Per letter"}</option>
            <option value="flat">Flat per service item</option>
          </select>
        </div>

        {isFlat ? (
          <div>
            <Label className="text-[10px] uppercase tracking-wider text-slate-500 font-semibold flex items-center gap-1">
              <Clock className="w-3 h-3" /> Minutes (flat)
            </Label>
            <Input
              type="number" min="0" step="1"
              value={rate.base_minutes_flat ?? 0}
              disabled={isLocked || !enabled}
              onChange={(e) => onChange({ base_minutes_flat: parseFloat(e.target.value) || 0 })}
              className="h-9 text-sm tabular-nums mt-1"
            />
          </div>
        ) : (
          <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
            {sizes.map(sz => {
              const field = SIZE_FIELD[sz.id];
              return (
                <div key={sz.id}>
                  <Label className={`text-[10px] font-semibold ${theme.text}`}>{sz.label}</Label>
                  <Input
                    type="number" min="0" step="1"
                    value={rate[field] ?? 0}
                    disabled={isLocked || !enabled}
                    onChange={(e) => onChange({ [field]: parseFloat(e.target.value) || 0 })}
                    className="h-9 text-sm tabular-nums mt-1"
                  />
                </div>
              );
            })}
          </div>
        )}
      </div>
    </motion.div>
  );
}

// Sub-panel rendered inside RepaintMonumentPanel ONLY when the
// "Dimensional Letters" face-feature is checked. Lets the user opt-in to
// painting the dimensional letters, with optional 2nd-color paint mask.
//
// All rates come from the existing Paint Estimator settings — no new settings
// are introduced here. See dimLetterPaintCalculator.js for the math.

import React from "react";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Type, Palette, Scissors } from "lucide-react";
import { computeDimLetterPaint } from "./dimLetterPaintCalculator";
import { hasIssueFor, maintenanceDraftValue } from "./maintenancePricingAvailability";

const DEFAULT_DL = {
  enabled: false,
  qty: 6,
  avg_height_in: 12,
  thickness_in: 1,
  second_color_mask: "none",
};

export default function DimLetterPaintSubPanel({ cfg, settings, onChange, issues = [], issueBoxId }) {
  const dl = { ...DEFAULT_DL, ...(cfg.dim_letter_paint || {}) };
  const setDL = (patch) => onChange({ dim_letter_paint: { ...dl, ...patch } });
  const invalid = (field) => hasIssueFor(issues, `dim_letter_paint.${field}`)
    ? { "aria-invalid": "true", "aria-describedby": issueBoxId }
    : {};
  // Held while any dim-letter input/setting is unavailable — never show a
  // sub-calc derived from unavailable pricing.
  const dimHeld = (issues || []).some(i =>
    typeof i.field === "string" && (i.field === "dim_letter_paint" || i.field.startsWith("dim_letter_paint.")));

  const calc = dl.enabled ? computeDimLetterPaint({ ...cfg, dim_letter_paint: dl }, settings) : null;

  return (
    <div className="bg-white border border-blue-200 rounded-lg p-3 space-y-3">
      <label className={`flex items-center gap-2 cursor-pointer rounded-md p-2 transition-colors ${dl.enabled ? "bg-blue-50" : "hover:bg-slate-50"}`}>
        <Checkbox
          checked={dl.enabled}
          onCheckedChange={(v) => setDL({ enabled: !!v })}
        />
        <Type className="w-4 h-4 text-blue-600" />
        <div className="flex-1">
          <div className="text-sm font-semibold text-slate-800">Paint the Dimensional Letters too?</div>
          <div className="text-[11px] text-slate-500">Uses Paint Estimator rates (mix, coverage, mask, labor).</div>
        </div>
      </label>

      {dl.enabled && (
        <>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
            <div>
              <Label className="text-[11px] uppercase tracking-wide text-slate-500"># of Letters</Label>
              <Input
                type="number" min="0" step="1"
                value={dl.qty ?? ""}
                onChange={(e) => setDL({ qty: maintenanceDraftValue(e.target.value) })}
                className="h-8 mt-1 text-sm tabular-nums"
                {...invalid("qty")}
              />
            </div>
            <div>
              <Label className="text-[11px] uppercase tracking-wide text-slate-500">Avg Height (in)</Label>
              <Input
                type="number" min="1" step="0.5"
                value={dl.avg_height_in ?? ""}
                onChange={(e) => setDL({ avg_height_in: maintenanceDraftValue(e.target.value) })}
                className="h-8 mt-1 text-sm tabular-nums"
                {...invalid("avg_height_in")}
              />
            </div>
            <div>
              <Label className="text-[11px] uppercase tracking-wide text-slate-500">Thickness (in)</Label>
              <Input
                type="number" min="0" step="0.25"
                value={dl.thickness_in ?? ""}
                onChange={(e) => setDL({ thickness_in: maintenanceDraftValue(e.target.value) })}
                className="h-8 mt-1 text-sm tabular-nums"
                {...invalid("thickness_in")}
              />
            </div>
          </div>

          <div>
            <Label className="text-[11px] uppercase tracking-wide text-slate-500 flex items-center gap-1">
              <Palette className="w-3 h-3" /> Second Color / Accent
            </Label>
            <Select
              value={dl.second_color_mask || "none"}
              onValueChange={(v) => setDL({ second_color_mask: v })}
            >
              <SelectTrigger className="h-9 mt-1 text-sm" {...invalid("second_color_mask")}><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="none">Single Color — No Mask Needed</SelectItem>
                <SelectItem value="paint_mask">Second Color — Requires Paint Mask</SelectItem>
              </SelectContent>
            </Select>
            <div className="text-[11px] text-slate-500 mt-1">
              Paint Mask uses your Paint Estimator's mask rates (material + plotter + weed + apply labor).
            </div>
          </div>

          {calc && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-2 pt-2 border-t border-blue-100">
              <Stat label="Letter Face SqFt"  value={dimHeld ? "—" : calc.letters_face_sqft.toFixed(2)} />
              <Stat label="Letter Return SqFt" value={dimHeld ? "—" : calc.letters_returns_sqft.toFixed(2)} />
              <Stat label="Letter Paint Cost"  value={dimHeld ? "—" : `$${calc.letters_paint_cost.toFixed(2)}`} accent />
              <Stat label="Letter Labor"       value={dimHeld ? "—" : `${calc.letters_labor_hours.toFixed(2)} hr`} />
              {dl.second_color_mask === "paint_mask" && (
                <>
                  <Stat label="Mask SqFt"      value={dimHeld ? "—" : calc.mask_sqft.toFixed(2)} icon={<Scissors className="w-3 h-3" />} />
                  <Stat label="Mask Material"  value={dimHeld ? "—" : `$${calc.mask_material_cost.toFixed(2)}`} />
                  <Stat label="Mask Labor"     value={dimHeld ? "—" : `$${(calc.mask_weed_labor_cost + calc.mask_apply_labor_cost).toFixed(2)}`} />
                  <Stat label="Mask Total"     value={dimHeld ? "—" : `$${calc.mask_total_cost.toFixed(2)}`} accent />
                </>
              )}
            </div>
          )}
        </>
      )}
    </div>
  );
}

function Stat({ label, value, accent, icon }) {
  return (
    <div className={`rounded-md px-2 py-1.5 border ${accent ? "bg-blue-100 border-blue-300" : "bg-slate-50 border-slate-200"}`}>
      <div className="text-[9px] uppercase tracking-wider text-slate-500 flex items-center gap-1">{icon}{label}</div>
      <div className={`text-sm font-bold tabular-nums ${accent ? "text-blue-800" : "text-slate-800"}`}>{value}</div>
    </div>
  );
}

