              <Label className="text-xs">Pricing Mode</Label>
              <Select value={item.pricing_mode || "per_letter_flat"} onValueChange={(v) => update({ pricing_mode: v })}>
                <SelectTrigger className="h-9 mt-1"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {PRICING_MODES.map(m => <SelectItem key={m.value} value={m.value}>{m.label}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="md:col-span-8">
              {item.pricing_mode === "per_letter_flat" && (
                <div><Label className="text-xs">Cost / Letter ($)</Label><Input type="number" step="0.01" value={item.cost_per_letter || 0} onChange={(e) => update({ cost_per_letter: parseFloat(e.target.value) || 0 })} className="h-9 mt-1 max-w-[200px]" /></div>
              )}
              {item.pricing_mode === "per_cabinet_flat" && (
                <div><Label className="text-xs">Cost / Cabinet ($)</Label><Input type="number" step="0.01" value={item.cost_per_cabinet || 0} onChange={(e) => update({ cost_per_cabinet: parseFloat(e.target.value) || 0 })} className="h-9 mt-1 max-w-[200px]" /></div>
              )}
              {item.pricing_mode === "per_linear_foot" && (
                <div><Label className="text-xs">Cost / Linear Foot ($)</Label><Input type="number" step="0.01" value={item.cost_per_foot || 0} onChange={(e) => update({ cost_per_foot: parseFloat(e.target.value) || 0 })} className="h-9 mt-1 max-w-[200px]" /></div>
              )}
              {item.pricing_mode === "per_sqft" && (
                <div><Label className="text-xs">Cost / Sq Ft ($)</Label><Input type="number" step="0.01" value={item.cost_per_sqft || 0} onChange={(e) => update({ cost_per_sqft: parseFloat(e.target.value) || 0 })} className="h-9 mt-1 max-w-[200px]" /></div>
              )}
              {item.pricing_mode === "per_project_flat" && (
                <div><Label className="text-xs">Flat Cost / Service Item ($)</Label><Input type="number" step="0.01" value={item.cost_flat || 0} onChange={(e) => update({ cost_flat: parseFloat(e.target.value) || 0 })} className="h-9 mt-1 max-w-[200px]" /></div>
              )}
              {(item.pricing_mode === "per_letter_by_size" || item.pricing_mode === "per_cabinet_by_size") && (
                <div className="text-xs text-slate-500 mt-1 italic">Size-based pricing matrix (advanced) — edit via Master Inventory.</div>
              )}
            </div>
          </div>

          <div>
            <Label className="text-xs">Notes</Label>
            <Input value={item.notes || ""} onChange={(e) => update({ notes: e.target.value })} className="h-9 mt-1" />
          </div>
        </div>
      )}
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { AlertTriangle, Boxes, Edit3, Link2, Plus, Save, ShieldCheck } from "lucide-react";
import { MaintenanceInventory } from "@/api/gatedEntities";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import MasterPartPickerModal from "@/components/estimator/parts/MasterPartPickerModal";
import { money } from "@/components/estimator/aioPricing";
import { SIGN_TYPES, ACTIONS } from "./constants";
import { expectedEntityFields, replaceEntityFieldsIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";
import { createMaintenanceMaterialRuleIfAbsent } from "./maintenanceMaterialRulePersistence";
import {
  isMaintenanceMaterialCatalogItem,
  legacyPricingModeForUsageBasis,
  loadMaintenanceMaterialRules,
  suggestedUsageBasis,
  suggestedUsageMultiplier,
} from "./maintenanceMaterialRules";

const SIZE_OPTIONS = [
  ["extra_small", "XS Letters"], ["small", "Small Letters"], ["medium", "Medium Letters"],
  ["large", "Large Letters"], ["extra_large", "XL Letters"], ["extra_extra_large", "XXL Letters"],
  ["cab_small", "Small Cabinet"], ["cab_medium", "Medium Cabinet"], ["cab_large", "Large Cabinet"], ["cab_extra_large", "XL Cabinet"],
];
const BASIS_OPTIONS = [
  ["per_letter", "Per letter"], ["per_cabinet", "Per cabinet"], ["per_linear_foot", "Per linear foot"],
  ["per_sqft", "Per square foot"], ["per_service_item", "Per service item"],
];

const emptyDraft = () => ({
  item_name: "",
  inventory_entity: "",
  inventory_item_id: "",
  inventory_item_name: "",
  usage_basis: "per_service_item",
  usage_multiplier: 1,
  usage_rounding: "none",
  applies_to_item_types: [],
  applies_to_sizes: [],
  applies_to_actions: [],
  pricing_mode: "per_project_flat",
  is_default: true,
  is_active: true,
  sort_order: 0,
  notes: "",
});

function toggle(list, value) {
  return list.includes(value) ? list.filter((item) => item !== value) : [...list, value];
}

function RuleEditor({ open, rule, catalog, onClose, onSaved }) {
  const [draft, setDraft] = useState(emptyDraft());
  const [pickerOpen, setPickerOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const saveRef = useRef(false);

  useEffect(() => {
    if (!open) return;
    setDraft({ ...emptyDraft(), ...(rule || {}) });
    setSaving(false);
    setError("");
  }, [open, rule?.id, rule?.updated_date]);

  const linked = catalog.find((item) => item.entity === draft.inventory_entity && item.inventoryId === draft.inventory_item_id) || null;
  const patch = (changes) => setDraft((current) => ({ ...current, ...changes }));

  const save = async () => {
    if (!draft.inventory_entity || !draft.inventory_item_id || !draft.item_name.trim() || saveRef.current) return;
    saveRef.current = true;
    setSaving(true);
    setError("");
    try {
      const payload = {
        item_name: draft.item_name.trim(),
        inventory_entity: draft.inventory_entity,
        inventory_item_id: draft.inventory_item_id,
        inventory_item_name: draft.inventory_item_name || linked?.name || draft.item_name.trim(),
        usage_basis: draft.usage_basis,
        usage_multiplier: Math.max(0, Number(draft.usage_multiplier || 0)),
        usage_rounding: draft.usage_rounding === "ceil_whole" ? "ceil_whole" : "none",
        applies_to_item_types: draft.applies_to_item_types || [],
        applies_to_sizes: draft.applies_to_sizes || [],
        applies_to_actions: draft.applies_to_actions || [],
        pricing_mode: legacyPricingModeForUsageBasis(draft.usage_basis),
        is_default: draft.is_default !== false,
        is_active: draft.is_active !== false,
        sort_order: Number(draft.sort_order || 0),
        notes: draft.notes || "",
      };
      if (rule?.id) {
        await replaceEntityFieldsIfUnchanged({
          entity: MaintenanceInventory,
          id: rule.id,
          expectedUpdatedAt: rule.updated_date || "",
          expectedFields: expectedEntityFields(rule, payload),
          nextFields: payload,
          label: `Maintenance material rule “${rule.item_name || payload.item_name || "Rule"}”`,
        });
      } else {
        const result = await createMaintenanceMaterialRuleIfAbsent({
          entity: MaintenanceInventory,
          data: payload,
          label: `Maintenance material rule “${payload.item_name || "Rule"}”`,
        });
        if (result.status === "existing" || result.status === "concurrent_duplicate_discarded") {
          throw new Error("An equivalent Maintenance material rule already exists for this Master Inventory resource, usage, and applicability. The existing rule was kept.");
        }
      }
      await onSaved?.();
      onClose?.();
    } catch (err) {
      if (rule?.id) {
        const latest = await MaintenanceInventory.get(rule.id).catch(() => null);
        if (latest?.id) setDraft({ ...emptyDraft(), ...latest });
      }
      setError(err?.message || "Maintenance material rule could not be saved.");
    } finally {
      saveRef.current = false;
      setSaving(false);
    }
  };

  return (
    <>
      <Dialog open={open} onOpenChange={(next) => !next && !saving && onClose?.()}>
        <DialogContent className="sm:max-w-[920px] p-0 overflow-hidden border-gray-300 shadow-2xl">
          <DialogHeader className="px-5 py-4 bg-[#3f3f3f] text-white border-b-4 border-lime-300">
            <DialogTitle className="text-white text-[17px] flex items-center gap-2"><Link2 className="w-5 h-5 text-lime-300" /> {rule?.id ? "Edit" : "Add"} Maintenance Material Rule</DialogTitle>
            <p className="text-[10px] text-gray-300 mt-1">Master Inventory owns the resource and cost. This rule only controls when and how much Maintenance uses.</p>
          </DialogHeader>
          <div className="p-5 bg-white space-y-4 max-h-[78vh] overflow-y-auto">
            <section className="rounded border border-gray-200 bg-gray-50 p-3">
              <div className="flex items-center justify-between gap-3">
                <div className="min-w-0">
                  <div className="text-[9px] font-bold tracking-widest text-gray-400">MASTER INVENTORY RESOURCE</div>
                  <div className="text-[12px] font-bold text-gray-900 mt-1">{linked?.name || draft.inventory_item_name || "No resource selected"}</div>
                  {linked && <div className="text-[9px] text-gray-500 mt-0.5">{linked.categoryLabel} · {String(linked.subtype || "").replaceAll("_", " ")} · {money(linked.unitCost)} / {linked.unit}</div>}
                </div>
                <Button type="button" variant="outline" className="h-[30px] text-[10px]" onClick={() => setPickerOpen(true)}><Boxes className="w-3.5 h-3.5 mr-1.5" /> {linked ? "Change Resource" : "Select Resource"}</Button>
              </div>
            </section>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
              <label className="md:col-span-2 text-[10px] font-bold tracking-wide text-gray-500">RULE NAME<Input value={draft.item_name} onChange={(e) => patch({ item_name: e.target.value })} className="mt-1 h-[33px] text-[11px]" placeholder="e.g. LED modules — medium channel letters" /></label>
              <label className="text-[10px] font-bold tracking-wide text-gray-500">USAGE BASIS<select value={draft.usage_basis} onChange={(e) => patch({ usage_basis: e.target.value })} className="mt-1 w-full h-[33px] border border-gray-300 rounded px-2 bg-white text-[11px]">{BASIS_OPTIONS.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>
              <label className="text-[10px] font-bold tracking-wide text-gray-500">MASTER UNITS / BASIS UNIT<Input type="number" min="0" step="any" value={draft.usage_multiplier} onChange={(e) => patch({ usage_multiplier: e.target.value })} className="mt-1 h-[33px] text-[11px]" /></label>
              <label className="text-[10px] font-bold tracking-wide text-gray-500">QUANTITY ROUNDING<select value={draft.usage_rounding} onChange={(e) => patch({ usage_rounding: e.target.value })} className="mt-1 w-full h-[33px] border border-gray-300 rounded px-2 bg-white text-[11px]"><option value="none">No rounding</option><option value="ceil_whole">Round up to whole Master unit</option></select></label>
              <div className="rounded border border-lime-200 bg-lime-50 px-3 py-2 self-end"><div className="text-[9px] text-gray-500">CURRENT RESOURCE RATE</div><div className="text-[12px] font-bold text-gray-900">{linked ? `${money(linked.unitCost)} / ${linked.unit}` : "Select a resource"}</div></div>
            </div>

            <section className="rounded border border-gray-200 p-3 space-y-3">
              <div><div className="text-[10px] font-bold text-gray-700">Applies to Sign Types</div><div className="text-[9px] text-gray-400">Leave all unchecked to apply to every sign type.</div></div>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-1.5">{SIGN_TYPES.map((item) => <label key={item.id} className="flex items-center gap-2 rounded border border-gray-200 px-2 py-1.5 text-[10px] bg-gray-50"><input type="checkbox" checked={(draft.applies_to_item_types || []).includes(item.id)} onChange={() => patch({ applies_to_item_types: toggle(draft.applies_to_item_types || [], item.id) })} className="accent-lime-600" /> {item.label}</label>)}</div>
            </section>

            <section className="rounded border border-gray-200 p-3 space-y-3">
              <div><div className="text-[10px] font-bold text-gray-700">Applies to Maintenance Actions</div><div className="text-[9px] text-gray-400">Leave all unchecked to apply to every action.</div></div>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-1.5 max-h-[190px] overflow-y-auto">{ACTIONS.map((item) => <label key={item.id} className="flex items-center gap-2 rounded border border-gray-200 px-2 py-1.5 text-[10px] bg-gray-50"><input type="checkbox" checked={(draft.applies_to_actions || []).includes(item.id)} onChange={() => patch({ applies_to_actions: toggle(draft.applies_to_actions || [], item.id) })} className="accent-lime-600" /> {item.label}</label>)}</div>
            </section>

            <section className="rounded border border-gray-200 p-3 space-y-3">
              <div><div className="text-[10px] font-bold text-gray-700">Applies to Sizes</div><div className="text-[9px] text-gray-400">Leave all unchecked for every size. Separate rules may reference the same Master item when usage changes by size.</div></div>
              <div className="grid grid-cols-2 md:grid-cols-5 gap-1.5">{SIZE_OPTIONS.map(([value, label]) => <label key={value} className="flex items-center gap-2 rounded border border-gray-200 px-2 py-1.5 text-[10px] bg-gray-50"><input type="checkbox" checked={(draft.applies_to_sizes || []).includes(value)} onChange={() => patch({ applies_to_sizes: toggle(draft.applies_to_sizes || [], value) })} className="accent-lime-600" /> {label}</label>)}</div>
            </section>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
              <label className="flex items-center justify-between gap-3 rounded border border-gray-200 px-3 py-2"><span><span className="block text-[10px] font-bold text-gray-700">Automatic Default</span><span className="block text-[9px] text-gray-400">Auto-add when applicability matches.</span></span><input type="checkbox" checked={draft.is_default !== false} onChange={(e) => patch({ is_default: e.target.checked })} className="w-4 h-4 accent-lime-600" /></label>
              <label className="flex items-center justify-between gap-3 rounded border border-gray-200 px-3 py-2"><span><span className="block text-[10px] font-bold text-gray-700">Active Rule</span><span className="block text-[9px] text-gray-400">Inactive rules stay preserved.</span></span><input type="checkbox" checked={draft.is_active !== false} onChange={(e) => patch({ is_active: e.target.checked })} className="w-4 h-4 accent-lime-600" /></label>
              <label className="text-[10px] font-bold tracking-wide text-gray-500">SORT ORDER<Input type="number" value={draft.sort_order || 0} onChange={(e) => patch({ sort_order: e.target.value })} className="mt-1 h-[33px] text-[11px]" /></label>
            </div>
            <label className="text-[10px] font-bold tracking-wide text-gray-500 block">INTERNAL NOTES<textarea rows={2} value={draft.notes || ""} onChange={(e) => patch({ notes: e.target.value })} className="mt-1 w-full border border-gray-300 rounded px-3 py-2 text-[11px]" /></label>
            {error && <div className="rounded border border-red-200 bg-red-50 px-3 py-2 text-[11px] text-red-700">{error}</div>}
            <div className="flex justify-end gap-2"><Button type="button" variant="outline" className="h-[31px] text-[10px]" disabled={saving} onClick={onClose}>Cancel</Button><Button type="button" className="h-[31px] text-[10px] bg-lime-300 text-gray-900 hover:bg-lime-400" disabled={saving || !draft.inventory_item_id || !draft.item_name.trim()} onClick={save}><Save className="w-3.5 h-3.5 mr-1.5" /> {saving ? "Saving…" : "Save Rule"}</Button></div>
          </div>
        </DialogContent>
      </Dialog>
      <MasterPartPickerModal
        open={pickerOpen}
        mode="select"
        catalogFilter={isMaintenanceMaterialCatalogItem}
        onClose={() => setPickerOpen(false)}
        onAdd={(item) => {
          const basis = suggestedUsageBasis(item);
          patch({
            inventory_entity: item.entity,
            inventory_item_id: item.inventoryId,
            inventory_item_name: item.name,
            item_name: draft.item_name || item.name,
            usage_basis: basis,
            usage_multiplier: suggestedUsageMultiplier(item, basis),
            pricing_mode: legacyPricingModeForUsageBasis(basis),
          });
        }}
      />
    </>
  );
}

export default function MaintenanceMaterialRulesTab() {
  const [rules, setRules] = useState([]);
  const [catalog, setCatalog] = useState([]);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(null);
  const [open, setOpen] = useState(false);
  const [error, setError] = useState("");

  const load = async () => {
    setLoading(true);
    setError("");
    try {
      const data = await loadMaintenanceMaterialRules({ includeInactive: true });
      setRules(data.rules || []);
      setCatalog(data.catalog || []);
    } catch (err) {
      setError(err?.message || "Maintenance material rules could not be loaded.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const sorted = useMemo(() => [...rules].sort((a, b) => Number(a.sort_order || 0) - Number(b.sort_order || 0) || String(a._display_name || a.item_name || "").localeCompare(String(b._display_name || b.item_name || ""))), [rules]);
  const setActive = async (rule, next) => {
    try {
      await replaceEntityFieldsIfUnchanged({
        entity: MaintenanceInventory,
        id: rule.id,
        expectedFields: { is_active: rule.is_active },
        nextFields: { is_active: next },
        label: `Maintenance material rule status “${rule.item_name || "Rule"}”`,
      });
      await load();
    } catch (err) { setError(err?.message || "Rule status could not be changed."); }
  };

  const scopeSummary = (rule) => {
    const signs = rule.applies_to_item_types?.length ? `${rule.applies_to_item_types.length} sign type${rule.applies_to_item_types.length === 1 ? "" : "s"}` : "all sign types";
    const actions = rule.applies_to_actions?.length ? `${rule.applies_to_actions.length} action${rule.applies_to_actions.length === 1 ? "" : "s"}` : "all actions";
    const sizes = rule.applies_to_sizes?.length ? `${rule.applies_to_sizes.length} size${rule.applies_to_sizes.length === 1 ? "" : "s"}` : "all sizes";
    return `${signs} · ${actions} · ${sizes}`;
  };

  return (
    <section className="bg-white border border-gray-200 rounded-xl overflow-hidden">
      <div className="px-4 py-3 bg-gray-50 border-b border-gray-200 flex items-center justify-between gap-3">
        <div><div className="text-[11px] font-bold uppercase tracking-wide text-gray-700">Maintenance Material Rules</div><div className="text-[10px] text-gray-500 mt-0.5">References Master Inventory for cost. Rules only define applicability and usage quantity.</div></div>
        <Button className="h-[30px] bg-lime-300 hover:bg-lime-400 text-gray-900 text-[10px] font-bold" onClick={() => { setEditing(null); setOpen(true); }}><Plus className="w-3.5 h-3.5 mr-1.5" /> Add Rule</Button>
      </div>
      {error && <div className="m-3 rounded border border-red-200 bg-red-50 px-3 py-2 text-[10px] text-red-700">{error}</div>}
      {loading ? <div className="py-14 text-center text-[11px] text-gray-400">Loading Maintenance material rules…</div> : sorted.length === 0 ? (
        <div className="py-14 text-center"><Boxes className="w-9 h-9 text-gray-300 mx-auto" /><div className="mt-2 text-[12px] font-bold text-gray-700">No Maintenance material rules yet</div><div className="mt-1 text-[10px] text-gray-400">Create rules that reference existing Master Inventory resources. No resource prices are copied here.</div></div>
      ) : (
        <div className="overflow-x-auto"><table className="w-full text-left"><thead className="bg-gray-50 border-b border-gray-200"><tr className="text-[9px] text-gray-500"><th className="px-4 py-2">RESOURCE / RULE</th><th className="px-3 py-2">APPLIES TO</th><th className="px-3 py-2">USAGE</th><th className="px-3 py-2 text-right">CURRENT COST</th><th className="px-3 py-2">DEFAULT</th><th className="px-3 py-2">STATUS</th><th className="px-4 py-2 text-right">ACTIONS</th></tr></thead><tbody className="divide-y divide-gray-100">{sorted.map((rule) => <tr key={rule.id} className="hover:bg-gray-50"><td className="px-4 py-2.5 min-w-[250px]"><div className="text-[11px] font-bold text-gray-900">{rule.item_name}</div><div className="text-[9px] text-gray-500 flex items-center gap-1 mt-0.5">{rule._master_missing ? <><AlertTriangle className="w-3 h-3 text-amber-600" /><span className="text-amber-700">Master Inventory link missing</span></> : rule._master_item ? <><ShieldCheck className="w-3 h-3 text-emerald-600" /> {rule._master_item.name}</> : <>Legacy manual pricing</>}</div></td><td className="px-3 py-2.5 text-[9px] text-gray-500 min-w-[210px]">{scopeSummary(rule)}</td><td className="px-3 py-2.5 text-[10px] text-gray-700 whitespace-nowrap">{String(rule.usage_basis || "legacy").replaceAll("_", " ")} × {Number(rule.usage_multiplier ?? 1).toLocaleString()}{rule.usage_rounding === "ceil_whole" ? " · round up" : ""}</td><td className="px-3 py-2.5 text-right whitespace-nowrap"><div className="text-[11px] font-bold text-gray-900">{rule._master_item ? money(rule._master_unit_cost) : "Legacy"}</div>{rule._master_item && <div className="text-[8px] text-gray-400">per {rule._master_unit}</div>}</td><td className="px-3 py-2.5 text-[9px] font-semibold">{rule.is_default === false ? "Optional" : "Auto"}</td><td className="px-3 py-2.5 text-[9px] font-semibold"><span className={rule.is_active === false ? "text-gray-400" : "text-emerald-700"}>{rule.is_active === false ? "Inactive" : "Active"}</span></td><td className="px-4 py-2.5"><div className="flex justify-end gap-1"><button type="button" onClick={() => { setEditing(rule); setOpen(true); }} className="h-[27px] px-2 rounded border border-gray-300 bg-white text-[9px] font-bold text-gray-700"><Edit3 className="w-3 h-3 inline mr-1" />Edit</button><button type="button" onClick={() => setActive(rule, rule.is_active === false)} className="h-[27px] px-2 rounded border border-gray-300 bg-white text-[9px] font-bold text-gray-600">{rule.is_active === false ? "Activate" : "Deactivate"}</button></div></td></tr>)}</tbody></table></div>
      )}
      <div className="px-4 py-2.5 border-t border-gray-200 bg-gray-50 text-[9px] text-gray-400"><Link2 className="w-3 h-3 inline mr-1" /> Master Inventory remains authoritative. Deactivating a rule does not delete the resource or historical estimate snapshots.</div>
      <RuleEditor open={open} rule={editing} catalog={catalog} onClose={() => { setOpen(false); setEditing(null); }} onSaved={load} />
    </section>
  );
}

// Maintenance Materials editor — generic by "axis".
//   axis="sign_type" → filters by applies_to_item_types (the 8 main service item types)
//   axis="action"    → filters by applies_to_actions (the 20 maintenance actions)
//
// Items are stored in the MaintenanceInventory entity; the same row can carry
// both axes' tags simultaneously (so a single inventory item can apply to
// specific sign types AND specific actions).

import React, { useEffect, useMemo, useState, useCallback } from "react";
import { MaintenanceInventory } from "@/api/gatedEntities";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Card, CardContent } from "@/components/ui/card";
import { useToast } from "@/components/ui/use-toast";
import { Plus, Save, Trash2, Search, ChevronDown, Package2 } from "lucide-react";
import { SIGN_TYPES, ACTIONS, ACTION_GROUPS } from "./constants";

const PRICING_MODES = [
  { value: "per_letter_flat",    label: "Per Letter (Flat)" },
  { value: "per_letter_by_size", label: "Per Letter (By Size)" },
  { value: "per_cabinet_flat",   label: "Per Cabinet (Flat)" },
  { value: "per_cabinet_by_size",label: "Per Cabinet (By Size)" },
  { value: "per_linear_foot",    label: "Per Linear Foot" },
  { value: "per_sqft",           label: "Per Sq. Ft." },
  { value: "per_project_flat",   label: "Per Sign (Flat)" },
];

const summarizeCost = (it) => {
  const n = (v) => `$${(parseFloat(v) || 0).toFixed(2)}`;
  switch (it.pricing_mode) {
    case "per_letter_flat":    return `${n(it.cost_per_letter)} / letter`;
    case "per_letter_by_size": return "By letter size";
    case "per_cabinet_flat":   return `${n(it.cost_per_cabinet)} / cabinet`;
    case "per_cabinet_by_size":return "By cabinet size";
    case "per_linear_foot":    return `${n(it.cost_per_foot)} / ft`;
    case "per_sqft":            return `${n(it.cost_per_sqft)} / sqft`;
    case "per_project_flat":   return `${n(it.cost_flat)} / sign`;
    default: return "";
  }
};

// Multi-select dropdown rendered as a popover with checkboxes.
function MultiSelectDropdown({ options, value, onChange, placeholder = "All" }) {
  const list = Array.isArray(value) ? value : [];
  const toggle = (v) => {
    if (list.includes(v)) onChange(list.filter(x => x !== v));
    else onChange([...list, v]);
  };
  const summary = list.length === 0
    ? placeholder
    : list.length <= 2
      ? list.map(v => options.find(o => o.value === v)?.label || v).join(", ")
      : `${list.length} selected`;

  // Allow grouped options (with .group field)
  const grouped = useMemo(() => {
    const hasGroups = options.some(o => o.group);
    if (!hasGroups) return [{ group: null, items: options }];
    const map = new Map();
    for (const o of options) {
      const g = o.group || "";
      if (!map.has(g)) map.set(g, []);
      map.get(g).push(o);
    }
    return Array.from(map.entries()).map(([group, items]) => ({ group, items }));
  }, [options]);

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button variant="outline" className="h-8 w-full justify-between font-normal text-xs px-2">
          <span className="truncate">{summary}</span>
          <ChevronDown className="w-3.5 h-3.5 opacity-60 flex-shrink-0" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-72 p-2 max-h-[60vh] overflow-y-auto" align="start">
        <div className="space-y-3">
          {grouped.map(({ group, items }) => (
            <div key={group || "_"}>
              {group && (
                <div className="text-[10px] uppercase tracking-wider text-slate-500 font-semibold px-2 pb-1">
                  {group}
                </div>
              )}
              <div className="space-y-0.5">
                {items.map(opt => (
                  <label
                    key={opt.value}
                    className="flex items-center gap-2 px-2 py-1.5 rounded hover:bg-slate-50 cursor-pointer text-sm"
                  >
                    <Checkbox
                      checked={list.includes(opt.value)}
                      onCheckedChange={() => toggle(opt.value)}
                    />
                    <span>{opt.label}</span>
                  </label>
                ))}
              </div>
            </div>
          ))}
          <div className="border-t pt-1 mt-1">
            <button
              type="button"
              onClick={() => onChange([])}
              className="text-xs text-slate-500 hover:text-slate-700 px-2 py-1"
            >
              Clear (apply to all)
            </button>
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
}

const emptyItem = () => ({
  item_name: "",
  applies_to_item_types: [],
  applies_to_sizes: [],
  applies_to_actions: [],
  pricing_mode: "per_letter_flat",
  cost_per_letter: 0,
  cost_per_cabinet: 0,
  cost_per_foot: 0,
  cost_per_sqft: 0,
  cost_flat: 0,
  unit: "ea",
  supplier: "",
  notes: "",
  is_default: true,
  sort_order: 0,
});

// `axis` controls what the "Applies To" multi-select shows (sign types vs actions)
// and how items are grouped on screen. Both fields are persisted regardless,
// so an item can be tagged on both axes.
export default function MaintenanceMaterialsByAxis({ axis }) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState("");
  const [dirtyIds, setDirtyIds] = useState(new Set());
  const { toast } = useToast();

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const data = await MaintenanceInventory.list("sort_order");
      setItems(data);
      setDirtyIds(new Set());
    } catch (e) { console.error(e); }
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const markDirty = (idx) => {
    setDirtyIds(prev => { const n = new Set(prev); n.add(idx); return n; });
  };

  const update = (idx, patch) => {
    setItems(prev => {
      const next = [...prev];
      next[idx] = { ...next[idx], ...patch };
      return next;
    });
    markDirty(idx);
  };

  const addItem = () => {
    setItems(prev => {
      const next = [...prev, { ...emptyItem(), _localKey: `new-${Date.now()}`, _new: true }];
      markDirty(next.length - 1);
      return next;
    });
  };

  const removeItem = async (idx) => {
    const it = items[idx];
    if (!confirm(`Delete "${it.item_name || "this item"}"?`)) return;
    if (it.id) {
      try { await MaintenanceInventory.delete(it.id); }
      catch (e) { toast({ variant: "destructive", description: "Delete failed: " + e.message }); return; }
    }
    setItems(prev => prev.filter((_, i) => i !== idx));
  };

  const saveAll = async () => {
    setSaving(true);
    try {
      const toSave = [...dirtyIds].map(i => items[i]).filter(Boolean);
      const ops = toSave.map(it => {
        const { _new, _localKey, id, ...payload } = it;
        if (id) return () => MaintenanceInventory.update(id, payload);
        return () => MaintenanceInventory.create(payload);
      });
      // Batch to respect rate limits
      const BATCH = 5;
      for (let i = 0; i < ops.length; i += BATCH) {
        await Promise.all(ops.slice(i, i + BATCH).map(fn => fn()));
        if (i + BATCH < ops.length) await new Promise(r => setTimeout(r, 250));
      }
      toast({ description: `Saved ${ops.length} item${ops.length !== 1 ? "s" : ""}` });
      load();
    } catch (e) {
      toast({ variant: "destructive", description: "Save failed: " + e.message });
    }
    setSaving(false);
  };

  // Build "Applies To" options based on the current axis
  const axisField = axis === "sign_type" ? "applies_to_item_types" : "applies_to_actions";
  const axisOptions = useMemo(() => {
    if (axis === "sign_type") {
      return SIGN_TYPES.map(s => ({ value: s.id, label: s.label }));
    }
    return ACTIONS.map(a => ({ value: a.id, label: a.label, group: a.group }));
  }, [axis]);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    return items
      .map((it, idx) => ({ it, idx }))
      .filter(({ it }) => {
        if (!q) return true;
        return `${it.item_name || ""} ${it.supplier || ""}`.toLowerCase().includes(q);
      });
  }, [items, search]);

  // Group rows by the current axis (each unique value gets its own section).
  // Items can appear under multiple groups when tagged with multiple values.
  // Items with empty list appear under "Applies to all".
  const grouped = useMemo(() => {
    const buckets = new Map();
    const ALL_KEY = "__all__";
    for (const { it, idx } of filtered) {
      const list = Array.isArray(it[axisField]) ? it[axisField] : [];
      const keys = list.length === 0 ? [ALL_KEY] : list;
      for (const k of keys) {
        if (!buckets.has(k)) buckets.set(k, []);
        buckets.get(k).push({ it, idx });
      }
    }
    const ordered = [];
    if (buckets.has(ALL_KEY)) {
      ordered.push({ key: ALL_KEY, label: "Applies to all", rows: buckets.get(ALL_KEY), accent: "bg-slate-100 text-slate-700 border-slate-200" });
    }
    if (axis === "sign_type") {
      for (const st of SIGN_TYPES) {
        if (buckets.has(st.id)) {
          ordered.push({ key: st.id, label: st.label, rows: buckets.get(st.id), accent: "bg-cyan-50 text-cyan-700 border-cyan-200" });
        }
      }
    } else {
      // Group actions by their action-group for visual organization
      for (const g of ACTION_GROUPS) {
        for (const a of ACTIONS.filter(x => x.group === g)) {
          if (buckets.has(a.id)) {
            ordered.push({ key: a.id, label: a.label, rows: buckets.get(a.id), accent: "bg-violet-50 text-violet-700 border-violet-200", group: g });
          }
        }
      }
    }
    return ordered;
  }, [filtered, axis, axisField]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20 text-slate-500">
        <div className="w-6 h-6 border-2 border-slate-300 border-t-cyan-600 rounded-full animate-spin mr-3" />
        Loading…
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="sticky top-0 z-30 bg-slate-50 -mx-2 px-2 pt-2 pb-1">
        <div className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm flex flex-wrap items-center gap-3">
          <div className="flex-1 min-w-[200px] relative">
            <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <Input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search by name or supplier…"
              className="pl-9 h-10"
            />
          </div>
          <Button onClick={addItem} variant="outline" className="h-10">
            <Plus className="w-4 h-4 mr-1" /> Add Material
          </Button>
          <Button
            onClick={saveAll}
            disabled={saving || dirtyIds.size === 0}
            className="bg-cyan-600 hover:bg-cyan-700 text-white h-10"
          >
            <Save className="w-4 h-4 mr-1" />
            {saving ? "Saving…" : dirtyIds.size > 0 ? `Save ${dirtyIds.size}` : "Saved"}
          </Button>
        </div>
      </div>

      {items.length === 0 ? (
        <div className="bg-white border border-dashed border-slate-300 rounded-xl py-16 text-center">
          <Package2 className="w-12 h-12 text-slate-300 mx-auto mb-3" />
          <h3 className="font-semibold text-slate-700 mb-1">No maintenance materials yet</h3>
          <p className="text-sm text-slate-500 mb-4">Add your first material to start tagging it to sign types and actions.</p>
          <Button onClick={addItem} className="bg-cyan-600 hover:bg-cyan-700 text-white">
            <Plus className="w-4 h-4 mr-1" /> Add First Material
          </Button>
        </div>
      ) : (
        <div className="space-y-6">
          {grouped.map(({ key, label, rows, accent }) => (
            <div key={key}>
              <div className="flex items-center gap-2 mb-2 px-1">
                <Badge variant="outline" className={`${accent} text-xs`}>{label}</Badge>
                <span className="text-xs text-slate-400">{rows.length} item{rows.length !== 1 ? "s" : ""}</span>
              </div>
              <div className="space-y-2">
                {rows.map(({ it, idx }) => (
                  <Card key={it.id || it._localKey || idx} className={it._new ? "border-emerald-300 bg-emerald-50/30" : ""}>
                    <CardContent className="p-3 space-y-2">
                      <div className="flex items-center gap-2 flex-wrap">
                        <Badge variant="outline" className="bg-slate-50 text-xs">{summarizeCost(it)}</Badge>
                        {dirtyIds.has(idx) && (
                          <Badge variant="outline" className="bg-amber-50 text-amber-700 border-amber-200 text-[10px]">Unsaved</Badge>
                        )}
                        <Button variant="ghost" size="icon" className="h-7 w-7 ml-auto text-red-500" onClick={() => removeItem(idx)}>
                          <Trash2 className="w-3.5 h-3.5" />
                        </Button>
                      </div>

                      <div className="grid grid-cols-2 md:grid-cols-6 gap-2">
                        <div className="md:col-span-2">
                          <Label className="text-xs">Item Name</Label>
                          <Input value={it.item_name || ""} onChange={(e) => update(idx, { item_name: e.target.value })} className="h-8 mt-1" />
                        </div>
                        <div className="md:col-span-2">
                          <Label className="text-xs">Applies To {axis === "sign_type" ? "Sign Types" : "Actions"}</Label>
                          <MultiSelectDropdown
                            options={axisOptions}
                            value={it[axisField] || []}
                            onChange={(v) => update(idx, { [axisField]: v })}
                            placeholder="All"
                          />
                        </div>
                        <div>
                          <Label className="text-xs">Pricing Mode</Label>
                          <Select value={it.pricing_mode} onValueChange={(v) => update(idx, { pricing_mode: v })}>
                            <SelectTrigger className="h-8 mt-1 text-xs"><SelectValue /></SelectTrigger>
                            <SelectContent>
                              {PRICING_MODES.map(p => <SelectItem key={p.value} value={p.value}>{p.label}</SelectItem>)}
                            </SelectContent>
                          </Select>
                        </div>
                        <div>
                          <Label className="text-xs">Supplier</Label>
                          <Input value={it.supplier || ""} onChange={(e) => update(idx, { supplier: e.target.value })} className="h-8 mt-1" />
                        </div>
                      </div>

                      {/* Cost field — only the relevant one for the selected pricing mode */}
                      <div className="grid grid-cols-2 md:grid-cols-6 gap-2">
                        {it.pricing_mode === "per_letter_flat" && (
                          <div>
                            <Label className="text-xs">$ / Letter</Label>
                            <Input type="number" step="0.01" value={it.cost_per_letter || 0} onChange={(e) => update(idx, { cost_per_letter: parseFloat(e.target.value) || 0 })} className="h-8 mt-1 tabular-nums" />
                          </div>
                        )}
                        {it.pricing_mode === "per_cabinet_flat" && (
                          <div>
                            <Label className="text-xs">$ / Cabinet</Label>
                            <Input type="number" step="0.01" value={it.cost_per_cabinet || 0} onChange={(e) => update(idx, { cost_per_cabinet: parseFloat(e.target.value) || 0 })} className="h-8 mt-1 tabular-nums" />
                          </div>
                        )}
                        {it.pricing_mode === "per_linear_foot" && (
                          <div>
                            <Label className="text-xs">$ / Foot</Label>
                            <Input type="number" step="0.01" value={it.cost_per_foot || 0} onChange={(e) => update(idx, { cost_per_foot: parseFloat(e.target.value) || 0 })} className="h-8 mt-1 tabular-nums" />
                          </div>
                        )}
                        {it.pricing_mode === "per_sqft" && (
                          <div>
                            <Label className="text-xs">$ / Sq. Ft.</Label>
                            <Input type="number" step="0.01" value={it.cost_per_sqft || 0} onChange={(e) => update(idx, { cost_per_sqft: parseFloat(e.target.value) || 0 })} className="h-8 mt-1 tabular-nums" />
                          </div>
                        )}
                        {it.pricing_mode === "per_project_flat" && (
                          <div>
                            <Label className="text-xs">$ / Sign (Flat)</Label>
                            <Input type="number" step="0.01" value={it.cost_flat || 0} onChange={(e) => update(idx, { cost_flat: parseFloat(e.target.value) || 0 })} className="h-8 mt-1 tabular-nums" />
                          </div>
                        )}
                        {(it.pricing_mode === "per_letter_by_size" || it.pricing_mode === "per_cabinet_by_size") && (
                          <div className="md:col-span-6 text-xs text-slate-500 italic">
                            By-size pricing: edit per-size rates from the line item on an estimate.
                          </div>
                        )}
                        <div className="md:col-span-2">
                          <Label className="text-xs">Notes</Label>
                          <Input value={it.notes || ""} onChange={(e) => update(idx, { notes: e.target.value })} className="h-8 mt-1" />
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// Sign Maintenance — Maintenance Materials tab.
