import React from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Gauge } from "lucide-react";
import { SIGN_TYPES } from "./constants";
import { DEFAULT_MIN_HOURS } from "./defaults";
import SectionCard, { AnimatedGrid } from "./SectionCard";

// Minimum billable hours per sign type. When a service item's calculated
// labor hours come in BELOW this floor, the estimator bumps it up.
export const minimumSettingKey = (signTypeId) => `maintenance_min_hours_${signTypeId}`;

// Map sign-type color → tailwind utility classes for the per-card accent.
const COLOR_CLASSES = {
  blue:    { dot: "bg-blue-500",    focus: "focus:border-blue-400 focus:ring-blue-100",    label: "text-blue-600" },
  amber:   { dot: "bg-amber-500",   focus: "focus:border-amber-400 focus:ring-amber-100",  label: "text-amber-600" },
  purple:  { dot: "bg-purple-500",  focus: "focus:border-purple-400 focus:ring-purple-100",label: "text-purple-600" },
  teal:    { dot: "bg-teal-500",    focus: "focus:border-teal-400 focus:ring-teal-100",    label: "text-teal-600" },
  indigo:  { dot: "bg-indigo-500",  focus: "focus:border-indigo-400 focus:ring-indigo-100",label: "text-indigo-600" },
  stone:   { dot: "bg-stone-500",   focus: "focus:border-stone-400 focus:ring-stone-100",  label: "text-stone-600" },
  slate:   { dot: "bg-slate-500",   focus: "focus:border-slate-400 focus:ring-slate-100",  label: "text-slate-600" },
  emerald: { dot: "bg-emerald-500", focus: "focus:border-emerald-400 focus:ring-emerald-100",label: "text-emerald-600" },
};

export default function MinimumsTab({ globalSettings, setGlobalSettings, isLocked }) {
  return (
    <SectionCard
      icon={Gauge}
      theme="violet"
      title="Minimum Rates by Sign Type"
      description="Minimum billable labor hours per service item. If the calculated labor for a service item comes in below this floor, the estimator bumps it up."
    >
      <AnimatedGrid className="grid sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {SIGN_TYPES.map(st => {
          const key = minimumSettingKey(st.id);
          const val = globalSettings[key] ?? String(DEFAULT_MIN_HOURS[st.id] ?? 2);
          const c = COLOR_CLASSES[st.color] || COLOR_CLASSES.slate;
          return (
            <div key={st.id} className="group p-3 rounded-xl border border-slate-100 bg-gradient-to-br from-white to-slate-50/40 hover:from-white hover:to-slate-50 hover:shadow-sm transition-all">
              <div className="flex items-baseline justify-between mb-1.5 gap-2">
                <Label htmlFor={key} className="text-sm font-medium text-slate-800 flex items-center gap-2 truncate">
                  <span className={`w-2 h-2 rounded-full ${c.dot} shadow-sm`} />
                  <span className="truncate">{st.label}</span>
                </Label>
                <span className={`text-[10px] uppercase tracking-wider font-semibold ${c.label}`}>hrs (min)</span>
              </div>
              <Input
                id={key}
                type="number" min="0" step="0.25"
                value={val}
                disabled={isLocked}
                onChange={(e) => setGlobalSettings(prev => ({ ...prev, [key]: e.target.value }))}
                className={`h-10 bg-white text-sm tabular-nums font-medium border-slate-200 focus:ring-2 transition-all ${c.focus}`}
              />
              <p className="mt-1.5 text-[11px] text-slate-500 leading-tight">{st.description}</p>
            </div>
          );
        })}
      </AnimatedGrid>
    </SectionCard>
  );
}

// Rates / Service Items tab.
// Layout: [Sign Type tabs] → [Action tabs within that sign type] → rate card
// + (optional) action-specific settings panel (e.g. Repaint settings).
//
// Show only the action combinations supported by the current Maintenance data model.
// The persisted MaintenanceActionRate matrix contains exactly these applicable
// combinations, so do not manufacture unsupported sign-type/action rows in the UI.

import React from "react";
import { motion } from "framer-motion";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Ruler, Sparkles, Lightbulb, Zap, Wrench, CheckCircle2, MinusCircle } from "lucide-react";
import { SIGN_TYPES, ACTIONS, ACTIONS_FOR_SIGN_TYPE } from "./constants";
import SectionCard from "./SectionCard";
import ActionRateCard from "./ActionRateCard";
import RepaintSettingsTab from "./RepaintSettingsTab";

const GROUP_ICON = {
  "Cosmetic":   Sparkles,
  "LED / Lamp": Lightbulb,
  "Electrical": Zap,
  "Component":  Wrench,
};

const SIGN_TYPE_ACTIVE_BG = {
  blue:    "data-[state=active]:bg-gradient-to-br data-[state=active]:from-blue-500    data-[state=active]:to-blue-700",
  amber:   "data-[state=active]:bg-gradient-to-br data-[state=active]:from-amber-500   data-[state=active]:to-orange-600",
  purple:  "data-[state=active]:bg-gradient-to-br data-[state=active]:from-purple-500  data-[state=active]:to-purple-700",
  teal:    "data-[state=active]:bg-gradient-to-br data-[state=active]:from-teal-500    data-[state=active]:to-teal-700",
  indigo:  "data-[state=active]:bg-gradient-to-br data-[state=active]:from-indigo-500  data-[state=active]:to-indigo-700",
  stone:   "data-[state=active]:bg-gradient-to-br data-[state=active]:from-stone-500   data-[state=active]:to-stone-700",
  slate:   "data-[state=active]:bg-gradient-to-br data-[state=active]:from-slate-500   data-[state=active]:to-slate-700",
  emerald: "data-[state=active]:bg-gradient-to-br data-[state=active]:from-emerald-500 data-[state=active]:to-emerald-700",
};

// Map of action id → component that renders that action's settings.
// Sub-panels must accept { globalSettings, setGlobalSettings, isLocked }.
const ACTION_SETTINGS_PANELS = {
  repaint: RepaintSettingsTab,
};

function ActionPane({ signType, action, rate, isLocked, onChange, globalSettings, setGlobalSettings }) {
  const enabled = rate?.is_enabled !== false;
  const SettingsPanel = ACTION_SETTINGS_PANELS[action.id];
  return (
    <div className="space-y-5">
      <ActionRateCard
        action={action}
        signType={signType}
        rate={rate || {}}
        isLocked={isLocked}
        onChange={(patch) => onChange(signType.id, action.id, patch)}
      />
      {enabled && SettingsPanel && (
        <div className="pt-2 border-t border-slate-200">
          <div className="text-[11px] uppercase tracking-wider text-slate-500 font-semibold mb-3">
            {action.label} — Detailed Settings
          </div>
          <SettingsPanel
            globalSettings={globalSettings}
            setGlobalSettings={setGlobalSettings}
            isLocked={isLocked}
          />
        </div>
      )}
    </div>
  );
}

function SignTypePane({ signType, rateMap, isLocked, onChangeRate, globalSettings, setGlobalSettings }) {
  const applicableIds = ACTIONS_FOR_SIGN_TYPE[signType.id] || [];
  const applicableActions = ACTIONS.filter((action) => applicableIds.includes(action.id));
  const firstEnabled = applicableActions.find(a => {
    const r = rateMap.get(`${signType.id}|${a.id}`);
    return !r || r.is_enabled !== false;
  }) || applicableActions[0];

  return (
    <div className="space-y-4">
      <motion.p
        initial={{ opacity: 0, y: -4 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3 }}
        className="text-xs text-slate-600 italic bg-slate-50 border-l-2 border-cyan-400 px-3 py-2 rounded-r-lg"
      >
        {signType.description}. Toggle each action on or off for this sign type using the switch on each card.
      </motion.p>

      <Tabs defaultValue={firstEnabled.id} className="w-full">
